function escapeGlobalCategoryText(value)
{
	return String(value ?? "").replace(/[&<>"']/g, (char) => ({
		"&": "&amp;",
		"<": "&lt;",
		">": "&gt;",
		'"': "&quot;",
		"'": "&#39;"
	}[char]));
}

function closePartTimeDetailPanel()
{
	const panel = document.getElementById("partTimeDetailPanel");
	const content = document.getElementById("partTimeDetailContent");
	const editBtn = document.getElementById("partTimeDetailEditBtn");
	const shareBtn = document.getElementById("partTimeDetailShareBtn");
	if (typeof window.closeDetailShareMenu === "function") window.closeDetailShareMenu();
	if (panel && typeof window.realjejuReleaseFocusBeforeAriaHidden === "function") {
		window.realjejuReleaseFocusBeforeAriaHidden(
			panel,
			document.getElementById("partTimeSearchInput") || document.querySelector(".topbar-menu-item.active") || document.body
		);
	} else if (panel && panel.contains(document.activeElement) && typeof document.activeElement.blur === "function") {
		document.activeElement.blur();
	}
	if (document.body) document.body.classList.remove("part-time-detail-open");
	if (panel) {
		panel.setAttribute("inert", "");
		panel.setAttribute("aria-hidden", "true");
		delete panel.dataset.jobId;
	}
	if (content) content.innerHTML = "";
	if (editBtn) {
		editBtn.hidden = true;
		delete editBtn.dataset.partTimeEditId;
	}
	if (shareBtn) delete shareBtn.dataset.partTimeShareId;
	if (typeof window.realjejuSyncGlobalDetailSurfaceState === "function") {
		window.realjejuSyncGlobalDetailSurfaceState();
	}
}

