function isGlobalRealestateCategory(category)
{
	return !category || category === "realestate";
}

function getCurrentRealjejuGlobalCategoryKey()
{
	const bodyCategory = String(document.body && document.body.dataset ? document.body.dataset.globalCategory || "" : "").trim();
	if (bodyCategory) return bodyCategory;
	const pathname = String(window.location && window.location.pathname || "/").replace(/\/+$/, "") || "/";
	if (pathname === "/parcels") return "parcel";

	if (pathname === "/ev-chargers") return "ev-charger";

	if (pathname === "/companies") return "local-business";
	if (pathname === "/jobs") return "part-time";
	if (pathname === "/cars") return "car";
	if (pathname === "/used") return "used-market";
	if (pathname === "/meetups") return "meetup";
	return "realestate";
}

function shouldLoadRealjejuRemotePageData(kind = "")
{
	const pathname = String(window.location && window.location.pathname || "/").replace(/\/+$/, "") || "/";
	if (/^\/(?:properties|admin|mypage|notices)(?:\/|$)/i.test(pathname)) return true;
	if (document.body && [
		"admin-page-open",
		"operator-page-open",
		"broker-home-page-open",
		"my-suite-page-open",
		"notice-page-open",
		"property-register-page-open",
		"detail-page-panel-open",
		"myinfo-page-open",
		"profile-edit-page-open",
		"broker-office-info-page-open",
		"broker-office-apply-page-open",
		"broker-office-edit-page-open"
	].some((className) => document.body.classList.contains(className))) return true;
	const category = getCurrentRealjejuGlobalCategoryKey();
	if (!isGlobalRealestateCategory(category)) return false;
	return true;
}

function shouldLoadBrokerOfficeMapDataForCurrentPage()
{
	const category = getCurrentRealjejuGlobalCategoryKey();
	if (category === "local-business" || isGlobalRealestateCategory(category)) return true;
	return typeof shouldLoadRealjejuRemotePageData === "function" && shouldLoadRealjejuRemotePageData("broker-office-map");
}

const REALJEJU_ADMIN_ONLY_GLOBAL_CATEGORIES = new Set(["used-market", "car", "meetup"]);

const REALJEJU_BLANK_MAP_GLOBAL_CATEGORIES = new Set(["used-market", "car", "meetup"]);

const REALJEJU_HIDE_FILTER_MENU_GLOBAL_CATEGORIES = new Set(["parcel", "local-business", "ev-charger", "used-market", "car", "meetup"]);

function isRealjejuAdminForGlobalCategoryAccess()
{
	if (typeof window === "undefined") return false;
	if (window.realjejuCurrentIsAdmin === true) return true;
	const profile = window.realjejuCurrentProfile || {};
	const user = window.realjejuCurrentAuthUser || {};
	const roles = [
		profile.role,
		profile.app_role,
		profile.user_role,
		user && user.app_metadata && user.app_metadata.role,
		user && user.user_metadata && user.user_metadata.role
	].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);
	return roles.includes("admin") || profile.is_admin === true || profile.admin === true;
}

function isRealjejuAdminOnlyGlobalCategory(category)
{
	return REALJEJU_ADMIN_ONLY_GLOBAL_CATEGORIES.has(String(category || "").trim());
}

function isRealjejuBlankMapGlobalCategory(category)
{
	return REALJEJU_BLANK_MAP_GLOBAL_CATEGORIES.has(String(category || "").trim());
}

function shouldShowGlobalCategoryEmptyMap(category = document.body && document.body.dataset ? document.body.dataset.globalCategory : "")
{
	return isRealjejuBlankMapGlobalCategory(category)
		|| (isRealjejuAdminOnlyGlobalCategory(category) && !isRealjejuAdminForGlobalCategoryAccess());
}

function shouldHideGlobalCategoryFilterMenu(category = document.body && document.body.dataset ? document.body.dataset.globalCategory : "")
{
	return shouldShowGlobalCategoryEmptyMap(category)
		|| REALJEJU_HIDE_FILTER_MENU_GLOBAL_CATEGORIES.has(String(category || "").trim());
}

