		if (typeof updateBrokerOfficeToolActiveState === "function") updateBrokerOfficeToolActiveState();
		if (typeof updateEducationFacilityToolActiveState === "function") updateEducationFacilityToolActiveState();
		if (typeof updateDevelopmentToolActiveState === "function") updateDevelopmentToolActiveState();
