function applyGlobalCategoryEmptyMapMode(category)
{
	if (!document.body) return false;
	const emptyMap = shouldShowGlobalCategoryEmptyMap(category);
	document.body.classList.toggle("global-category-empty-map-mode", emptyMap);
	document.body.classList.toggle("global-category-hide-filter-menu", shouldHideGlobalCategoryFilterMenu(category));
	if (emptyMap) document.body.dataset.globalCategoryEmptyMap = String(category || "");
	else delete document.body.dataset.globalCategoryEmptyMap;
	if (emptyMap) {
		closeRealjejuPartTimePage();
		closeGlobalCategorySidePanel();
		clearGlobalCategoryEmptyMapOverlays();
	}
	return emptyMap;
}

function applyGlobalCategorySideNavMode(category)
{
	const nextCategory = category || "realestate";
	const isRealestate = isGlobalRealestateCategory(nextCategory);
	if (document.body) {
		document.body.classList.toggle("global-category-nonrealestate-mode", !isRealestate);
		document.body.dataset.globalCategory = nextCategory;
	}
	if (typeof syncPickaxeMode === "function") syncPickaxeMode();
	// Mobile keeps one real-estate drawer structure across all four services.
	// Desktop preserves the existing category-specific side navigation.
	const useRealestateMobileDrawer = typeof window !== "undefined"
		&& window.matchMedia("(max-width: 850px)").matches;
	const drawerCategory = useRealestateMobileDrawer ? "realestate" : nextCategory;
	const homeButton = document.querySelector('.realjeju-side-nav-item[data-side-nav-action="home"]');
	const label = homeButton ? homeButton.querySelector("span") : null;
	const icon = homeButton ? homeButton.querySelector("i") : null;
	if (label) label.textContent = GLOBAL_CATEGORY_HOME_LABELS[drawerCategory] || GLOBAL_CATEGORY_HOME_LABELS.realestate;
	if (icon) icon.className = `fa-solid ${GLOBAL_CATEGORY_SIDE_NAV_ICONS[drawerCategory] || GLOBAL_CATEGORY_SIDE_NAV_ICONS.realestate}`;
	document.querySelectorAll("#realjejuSideNav [data-mobile-drawer-category]").forEach((button) => {
		const active = button.dataset.mobileDrawerCategory === nextCategory;
		button.classList.toggle("active", active);
		button.setAttribute("aria-current", active ? "page" : "false");
	});

	const registerButton = document.querySelector('.realjeju-side-register-btn[data-side-nav-action="register"]');
	const registerLabel = registerButton ? registerButton.querySelector("span") : null;
	if (registerLabel) registerLabel.textContent = "매물 등록";
	if (registerButton && !isRealestate && !useRealestateMobileDrawer) {
		registerButton.hidden = true;
		registerButton.setAttribute("aria-hidden", "true");
		registerButton.style.display = "none";
	} else if (registerButton) {
		registerButton.hidden = false;
		registerButton.setAttribute("aria-hidden", "false");
		registerButton.style.removeProperty("display");
	}
	if ((isRealestate || useRealestateMobileDrawer)
		&& typeof window.realjejuSyncSideNavVisibility === "function") {
		window.realjejuSyncSideNavVisibility();
	}
	if (typeof window.realjejuRenderSideRecentViewedList === "function") {
		window.realjejuRenderSideRecentViewedList();
	}
}

function getGlobalCategoryFilterBar()
{
	return document.querySelector("#topbarMenu .map-filter-bar")
		|| document.querySelector(".sub-topbar-right .map-filter-bar")
		|| document.querySelector(".map-filter-bar");
}

function closeGlobalCategoryFilterDropdowns()
{
	document.querySelectorAll(".global-category-filter-dropdown.open").forEach((dropdown) => {
		dropdown.classList.remove("open");
		const trigger = dropdown.querySelector(".extra-filter-trigger");
		if (trigger) trigger.setAttribute("aria-expanded", "false");
	});
}

function renderGlobalCategoryTopFilters(category)
{
	const filterBar = getGlobalCategoryFilterBar();
	if (!filterBar) return;

	let wrapper = filterBar.querySelector(".global-category-top-filters");
	if (!wrapper) {
		wrapper = document.createElement("div");
		wrapper.className = "global-category-top-filters";
		const allFilter = filterBar.querySelector("#allFilterDropdown");
		if (allFilter && allFilter.parentElement === filterBar) {
			allFilter.insertAdjacentElement("afterend", wrapper);
		} else {
			filterBar.appendChild(wrapper);
		}
	}

	const emptyMap = shouldShowGlobalCategoryEmptyMap(category);
	const hideFilterMenu = shouldHideGlobalCategoryFilterMenu(category);
	const config = emptyMap || hideFilterMenu ? null : GLOBAL_CATEGORY_SIDE_PANEL_CONFIG[category];
	if (!config || category === "realestate" || hideFilterMenu) {
		closeGlobalCategoryFilterDropdowns();
		wrapper.hidden = true;
		wrapper.innerHTML = "";
		filterBar.classList.remove("global-category-filter-mode");
		filterBar.hidden = hideFilterMenu;
		filterBar.setAttribute("aria-hidden", hideFilterMenu ? "true" : "false");
		scheduleMapFilterScrollSync();
		return;
	}

	filterBar.hidden = false;
	filterBar.setAttribute("aria-hidden", "false");
	const groups = Array.isArray(config.groups) ? config.groups : [];
	wrapper.hidden = false;
	filterBar.classList.add("global-category-filter-mode");
	wrapper.innerHTML = groups.map((group, groupIndex) => {
		const options = (Array.isArray(group.items) ? group.items : []).map((item) => `
			<button type="button" class="global-category-filter-option" data-global-category-option="${escapeGlobalCategoryText(item.key)}">
				<i class="fa-solid ${escapeGlobalCategoryText(item.icon || "fa-circle")}" aria-hidden="true"></i>
				<span>${escapeGlobalCategoryText(item.label)}</span>
			</button>
		`).join("");
		return `
			<div class="extra-filter-dropdown global-category-filter-dropdown" data-global-category-filter="${escapeGlobalCategoryText(group.title || groupIndex)}">
				<button type="button" class="extra-filter-trigger global-category-filter-trigger" aria-expanded="false">
					<span>${escapeGlobalCategoryText(group.title || "카테고리")}</span>
					<i class="fa-solid fa-chevron-down" aria-hidden="true"></i>
				</button>
				<div class="extra-filter-menu global-category-filter-menu" role="menu">
					<div class="global-category-filter-grid">${options}</div>
				</div>
			</div>
		`;
	}).join("");
	scheduleMapFilterScrollSync();
}

function setLocalBusinessOverlayMapVisible(overlayMapKey, visible)
{
	const overlayMap = state && state[overlayMapKey] instanceof Map ? state[overlayMapKey] : null;
	if (!overlayMap || !state.map) return false;
	let hasOverlay = false;
	overlayMap.forEach((overlay) => {
		if (!overlay || typeof overlay.setMap !== "function") return;
		overlay.setMap(visible ? state.map : null);
		hasOverlay = true;
	});
	return hasOverlay;
}

function hideLocalBusinessAutoMapOverlays(options = {})
{
	const preserveSelection = options && options.preserveSelection === true;
	if (!preserveSelection) {
		state.isConvenienceStoreVisible = false;
		state.isLargeMartVisible = false;
		state.isBankVisible = false;
		state.isCleanHouseVisible = false;
		state.isPlaygroundParkVisible = false;
		state.isEvChargerVisible = false;
		state.isBrokerOfficesVisible = false;
		state.brokerOfficeMapFilter = "none";
	}
	setLocalBusinessOverlayMapVisible("convenienceStoreOverlayMap", false);
	setLocalBusinessOverlayMapVisible("largeMartOverlayMap", false);
	setLocalBusinessOverlayMapVisible("bankOverlayMap", false);
	setLocalBusinessOverlayMapVisible("cleanHouseOverlayMap", false);
	setLocalBusinessOverlayMapVisible("playgroundParkOverlayMap", false);
	setLocalBusinessOverlayMapVisible("evChargerOverlayMap", false);
	setLocalBusinessOverlayMapVisible("brokerOfficeOverlayMap", false);
	hideEducationFacilityMapTooltip();
	if (typeof hideBrokerOfficeMapTooltip === "function") hideBrokerOfficeMapTooltip();
	if (typeof updateConvenienceToolActiveState === "function") updateConvenienceToolActiveState();
	if (typeof updateBrokerOfficeToolActiveState === "function") updateBrokerOfficeToolActiveState();
}

async function settleStaleLocalBusinessAutoMapRequest()
{
	const currentCategory = getCurrentRealjejuGlobalCategoryKey();
	if (state.localBusinessAutoMapMode && currentCategory === "local-business") return false;

	hideLocalBusinessAutoMapOverlays({ preserveSelection: true });
	const shouldRestoreCurrentRealestateLayers = isGlobalRealestateCategory(currentCategory)
		&& !realestateMapToolSelectionSnapshot
		&& document.body
		&& !document.body.classList.contains("main-landing-page-open");
	if (shouldRestoreCurrentRealestateLayers
		&& typeof renderVisibleFacilityOverlaysForViewport === "function") {
		await renderVisibleFacilityOverlaysForViewport();
	}
	return false;
}

function cloneLocalBusinessAutoRows(rows)
{
	return Array.isArray(rows) ? rows.map((row) => ({ ...row })) : [];
}

