function getLocalProfessionalBusinessMarkerKey(business)
{
	return `professional:${String(business && business.id || "").trim()}`;
}

function getLocalProfessionalOverlayEntries(mapBounds = null)
{
	if (!isLocalBusinessPageActive()) return [];
	return LOCAL_PROFESSIONAL_BUSINESSES
		.filter((business) => {
			if (!mapBounds || typeof isLatLngInsideBounds !== "function") return true;
			return isLatLngInsideBounds(business.lat, business.lng, mapBounds);
		})
		.map((business) => ({
			key: getLocalProfessionalBusinessMarkerKey(business),
			dataKey: [
				business.officeName,
				business.ownerName,
				business.phone,
				business.address,
				business.badgeColor
			].join("~"),
			zIndex: getFacilityOverlayZIndex("broker"),
			position: normalizeJejuLatLngPair(business.lat, business.lng),
			createOverlay: () => createLocalProfessionalBusinessOverlay(business)
		}));
}

function applyBrokerOfficeEntriesWithLocalProfessionals(entries, mapBounds = null)
{
	const mergedEntries = [
		...(Array.isArray(entries) ? entries : []),
		...getLocalProfessionalOverlayEntries(mapBounds)
	];
	applyBrokerOfficeOverlayEntries(mergedEntries);
	return mergedEntries;
}

function rememberLocalBusinessAutoRows()
{
	const brokerOfficeRows = cloneLocalBusinessAutoRows(state.brokerOfficeRows);
	if (!brokerOfficeRows.length) return false;
	state.localBusinessAutoRows = {
		convenienceStore: [],
		largeMart: [],
		brokerOffice: brokerOfficeRows
	};
	state.localBusinessAutoRowsReady = true;
	return true;
}

async function restoreBrokerOfficeOverlaysFromRows(rows)
{
	if (!state.map || !window.kakao || !kakao.maps || !Array.isArray(rows)) return false;
	let restoredRows = cloneLocalBusinessAutoRows(rows);
	if (!restoredRows.length) {
		state.brokerOfficeRows = restoredRows;
		const entries = applyBrokerOfficeEntriesWithLocalProfessionals([]);
		return entries.length > 0;
	}
	let client = getRealjejuSupabaseClient();
	if (!client && typeof loadSupabaseScript === "function") {
		try {
			await loadSupabaseScript();
			client = getRealjejuSupabaseClient();
		} catch (error) {
			console.warn("중개사 프로필 사진 복원 준비 실패:", error);
		}
	}
	restoredRows = await hydrateBrokerOfficeRowsWithProfileImages(client, restoredRows);
	commitBrokerOfficeProfileImageRows(restoredRows);
	const mapBounds = typeof getExpandedMapBounds === "function" ? getExpandedMapBounds() : null;
	const visibleRows = restoredRows.map((office) => {
		const normalized = normalizeJejuLatLngPair(office && office.lat, office && office.lng);
		return normalized ? { ...office, ...normalized } : null;
	}).filter((office) => {
		if (!office) return false;
		return !mapBounds || typeof isLatLngInsideBounds !== "function" || isLatLngInsideBounds(office.lat, office.lng, mapBounds);
	});
	if (!visibleRows.length) {
		const entries = applyBrokerOfficeEntriesWithLocalProfessionals([], mapBounds);
		return entries.length > 0;
	}
	if (!(await loadBrokerOfficeListingCountsForOffices(visibleRows))) return false;
	const entries = spreadBrokerOfficeOverlaysByAddress(visibleRows).map((office) => ({
		key: getBrokerOfficeOverlayKey(office),
		dataKey: getBrokerOfficeOverlayDataKey(office),
		zIndex: getFacilityOverlayZIndex("broker"),
		position: normalizeJejuLatLngPair(office.lat, office.lng),
		createOverlay: () => createBrokerOfficeOverlay(office)
	}));
	const mergedEntries = applyBrokerOfficeEntriesWithLocalProfessionals(entries, mapBounds);
	return mergedEntries.length > 0;
}

async function restoreLocalBusinessAutoRowsWithoutSearch()
{
	const saved = state.localBusinessAutoRows || {};
	const brokerOfficeRows = Array.isArray(saved.brokerOffice) ? saved.brokerOffice : [];
	state.isConvenienceStoreVisible = false;
	state.isLargeMartVisible = false;
	state.isBankVisible = false;
	state.isCleanHouseVisible = false;
	state.isPlaygroundParkVisible = false;
	state.isEvChargerVisible = false;
	state.isBrokerOfficesVisible = true;
	state.brokerOfficeMapFilter = "all";
	setLocalBusinessOverlayMapVisible("convenienceStoreOverlayMap", false);
	setLocalBusinessOverlayMapVisible("largeMartOverlayMap", false);
	setLocalBusinessOverlayMapVisible("bankOverlayMap", false);
	setLocalBusinessOverlayMapVisible("cleanHouseOverlayMap", false);
	setLocalBusinessOverlayMapVisible("playgroundParkOverlayMap", false);
	setLocalBusinessOverlayMapVisible("evChargerOverlayMap", false);
	await loadBrokerSpecialtyStats();
	if (!(await ensureBrokerSpecialtyStatsMatchOffices(brokerOfficeRows))) {
		applyBrokerOfficeEntriesWithLocalProfessionals([]);
		return false;
	}
	const brokerRestored = await restoreBrokerOfficeOverlaysFromRows(brokerOfficeRows);
	const restored = brokerRestored;
	if (restored && typeof syncFacilityOverlayZIndexes === "function") syncFacilityOverlayZIndexes();
	if (typeof updateConvenienceToolActiveState === "function") updateConvenienceToolActiveState();
	if (typeof updateBrokerOfficeToolActiveState === "function") updateBrokerOfficeToolActiveState();
	return restored || !!state.localBusinessAutoRowsReady;
}

async function restoreLoadedLocalBusinessAutoLayer()
{
	const restored = await restoreLocalBusinessAutoRowsWithoutSearch();
	if (!restored) {
		scheduleLocalBusinessAutoLayerRetry();
		return false;
	}
	return renderLocalBusinessAutoMapOverlays();
}

function isLocalBusinessAutoMapReady()
{
	return !!(state.map && window.kakao && kakao.maps && kakao.maps.services);
}

function resetLocalBusinessAutoLayerRetry()
{
	if (state.localBusinessAutoLayerRetryTimer) {
		clearTimeout(state.localBusinessAutoLayerRetryTimer);
		state.localBusinessAutoLayerRetryTimer = null;
	}
	state.localBusinessAutoLayerRetryCount = 0;
}

function scheduleLocalBusinessAutoLayerRetry()
{
	if (state.localBusinessAutoLayerRetryTimer
		|| Number(state.localBusinessAutoLayerRetryCount || 0) >= 6
		|| !state.localBusinessAutoMapMode) return;
	const attempt = Number(state.localBusinessAutoLayerRetryCount || 0) + 1;
	state.localBusinessAutoLayerRetryCount = attempt;
	state.localBusinessAutoLayerRetryTimer = setTimeout(() => {
		state.localBusinessAutoLayerRetryTimer = null;
		const isStillLocalBusiness = state.localBusinessAutoMapMode
			&& document.body
			&& document.body.dataset.globalCategory === "local-business";
		if (!isStillLocalBusiness) {
			state.localBusinessAutoLayerRetryCount = 0;
			return;
		}
		applyLocalBusinessMapLayerMode("local-business").catch((error) => {
			console.warn("동네업체 중개사 위치 재조회 실패:", error);
			scheduleLocalBusinessAutoLayerRetry();
		});
	}, attempt * 240);
}

async function renderLocalBusinessAutoMapOverlays()
{
	if (!isLocalBusinessAutoMapReady()) return false;
	state.isConvenienceStoreVisible = false;
	state.isLargeMartVisible = false;
	state.isBankVisible = false;
	state.isCleanHouseVisible = false;
	state.isPlaygroundParkVisible = false;
	state.isEvChargerVisible = false;
	state.isBrokerOfficesVisible = true;
	state.brokerOfficeMapFilter = "all";
	if (typeof setConvenienceStoreVisible === "function") await setConvenienceStoreVisible(false);
	if (typeof setLargeMartVisible === "function") await setLargeMartVisible(false);
	if (typeof setBankVisible === "function") await setBankVisible(false);
	if (typeof setCleanHouseVisible === "function") await setCleanHouseVisible(false);
	if (typeof setPlaygroundParkVisible === "function") await setPlaygroundParkVisible(false);
	if (typeof setEvChargerVisible === "function") await setEvChargerVisible(false);
	const brokerOfficeRowsReady = typeof renderBrokerOfficeOverlays === "function"
		? await renderBrokerOfficeOverlays()
		: false;
	if (brokerOfficeRowsReady) {
		rememberLocalBusinessAutoRows();
		resetLocalBusinessAutoLayerRetry();
	} else {
		scheduleLocalBusinessAutoLayerRetry();
	}
	if (typeof updateBrokerOfficeToolActiveState === "function") updateBrokerOfficeToolActiveState();
	return brokerOfficeRowsReady;
}

async function applyLocalBusinessMapLayerMode(category)
{
	const requestId = Number(state.localBusinessAutoMapRequestId || 0) + 1;
	state.localBusinessAutoMapRequestId = requestId;
	const isLocalBusiness = category === "local-business";
	const isCurrentRequest = () => state.localBusinessAutoMapRequestId === requestId
		&& state.localBusinessAutoMapMode
		&& document.body
		&& document.body.dataset.globalCategory === "local-business";
	if (!isLocalBusiness) {
		state.localBusinessAutoMapMode = false;
		resetLocalBusinessAutoLayerRetry();
		hideLocalBusinessAutoMapOverlays();
		if (typeof renderConvenienceFacilityFilterPanel === "function" && isConvenienceFacilityFilterPanelOpen()) {
			renderConvenienceFacilityFilterPanel();
		}
		if (state.propertyMarkersHiddenByLocalBusiness && isGlobalRealestateCategory(category)) {
			state.propertyMarkersHiddenByLocalBusiness = false;
			if (typeof restoreMapPropertyMarkersVisibility === "function") restoreMapPropertyMarkersVisibility();
			else state.isPropertyMarkersVisible = true;
		}
		return false;
	}

	state.localBusinessAutoMapMode = true;
	state.propertyMarkersHiddenByLocalBusiness = true;
	if (!isLocalBusinessAutoMapReady()) return false;
	if (state.localBusinessAutoLayerLoaded) {
		state.localBusinessAutoLayerLoaded = await restoreLoadedLocalBusinessAutoLayer();
		if (!isCurrentRequest()) {
			return settleStaleLocalBusinessAutoMapRequest();
		}
		if (typeof setMapPropertyMarkersVisible === "function") setMapPropertyMarkersVisible(false);
		else state.isPropertyMarkersVisible = false;
		return state.localBusinessAutoLayerLoaded;
	}
	if (state.localBusinessAutoLayerLoadPromise) {
		await state.localBusinessAutoLayerLoadPromise;
		if (!isCurrentRequest()) {
			return settleStaleLocalBusinessAutoMapRequest();
		}
		state.localBusinessAutoLayerLoaded = await restoreLoadedLocalBusinessAutoLayer();
		if (!isCurrentRequest()) {
			return settleStaleLocalBusinessAutoMapRequest();
		}
		return state.localBusinessAutoLayerLoaded;
	}
	if (typeof setMapPropertyMarkersVisible === "function") setMapPropertyMarkersVisible(false);
	else {
		state.isPropertyMarkersVisible = false;
		if (typeof clearMapObjects === "function") clearMapObjects();
	}

	if (typeof closeEducationFacilityFilterPanel === "function") closeEducationFacilityFilterPanel();
	if (typeof closeConvenienceFacilityFilterPanel === "function") closeConvenienceFacilityFilterPanel();
	if (typeof closeBrokerOfficeFilterPanel === "function") closeBrokerOfficeFilterPanel();
	if (typeof turnOffEducationFacilityMapLayer === "function") turnOffEducationFacilityMapLayer();
	if (typeof setLifeSafetyOverlayVisible === "function") await setLifeSafetyOverlayVisible(false);
	if (typeof setPublicParkingVisible === "function") await setPublicParkingVisible(false);
	if (typeof setPublicOfficeVisible === "function") await setPublicOfficeVisible(false);
	if (typeof ensureFacilityMapVisibleLevel === "function") ensureFacilityMapVisibleLevel();

	state.localBusinessAutoLayerLoadPromise = (async () => {
		try {
			state.localBusinessAutoLayerLoaded = await renderLocalBusinessAutoMapOverlays();
		} finally {
			state.localBusinessAutoLayerLoadPromise = null;
		}
	})();
	await state.localBusinessAutoLayerLoadPromise;
	if (!isCurrentRequest()) {
		return settleStaleLocalBusinessAutoMapRequest();
	}
	if (typeof renderConvenienceFacilityFilterPanel === "function" && isConvenienceFacilityFilterPanelOpen()) {
		renderConvenienceFacilityFilterPanel();
	}
	return state.localBusinessAutoLayerLoaded;
}

