// Mobile drawer service links navigate directly; hidden desktop navigation is not used as a proxy.
const MOBILE_DRAWER_CATEGORY_ROUTE_PATHS = Object.freeze({
	realestate: "/properties",
	parcel: "/parcels",
	"local-business": "/companies",
	"ev-charger": "/ev-chargers"
});

document.addEventListener("click", (event) => {
	const button = event.target?.closest?.("#realjejuSideNav [data-mobile-drawer-category]");
	if (!button) return;
	event.preventDefault();
	event.stopPropagation();
	const category = String(button.dataset.mobileDrawerCategory || "").trim();
	const routePath = MOBILE_DRAWER_CATEGORY_ROUTE_PATHS[category] || "";
	if (!routePath) return;
	if (typeof prepareServiceMapToolCategoryTransition === "function") {
		prepareServiceMapToolCategoryTransition(category);
	}
	document.body?.classList.remove("realjeju-mobile-side-nav-open");
	const drawer = document.getElementById("realjejuSideNav");
	const trigger = document.getElementById("realjejuMobileSideNavTrigger");
	const backdrop = document.getElementById("realjejuMobileSideNavBackdrop");
	if (drawer) drawer.setAttribute("aria-hidden", "true");
	if (trigger) trigger.setAttribute("aria-expanded", "false");
	if (backdrop) backdrop.hidden = true;
	const router = window.realjejuRouter;
	if (router && typeof router.navigate === "function") {
		router.navigate(routePath);
		return;
	}
	window.location.assign(new URL(routePath, window.location.href).href);
});

