async function applyGlobalCategoryMode(category)
{
	const requestId = ++globalCategoryModeRequestId;
	const nextCategory = category || "realestate";
	const previousCategory = getCurrentRealjejuGlobalCategoryKey();
	if (nextCategory === "parcel" && previousCategory !== "parcel") {
		rememberRealestatePropertyDataBeforeParcelEntry();
		resetRealestateSelectionBeforeParcelEntry();
	}
	if (previousCategory === "parcel" && nextCategory !== "parcel") {
		resetParcelSelectionBeforeRealestateEntry();
		if (isGlobalRealestateCategory(nextCategory)) restoreRealestatePropertyDataAfterParcelExit();
	}
	if (isGlobalRealestateCategory(previousCategory) && !isGlobalRealestateCategory(nextCategory)) {
		rememberRealestateMapToolSelections();
	}
	const emptyMap = applyGlobalCategoryEmptyMapMode(nextCategory);
	closeGlobalCategorySidePanel();
	applyGlobalCategorySideNavMode(nextCategory);
	renderGlobalCategoryTopFilters(nextCategory);
	if (emptyMap) clearGlobalCategoryEmptyMapOverlays();
	if (!emptyMap && !isGlobalRealestateCategory(nextCategory)) clearGlobalCategoryEmptyMapOverlays();
	if (nextCategory === "local-business") {
    window.realjejuServiceModes?.sync?.(nextCategory);
    await applyLocalBusinessMapLayerMode(nextCategory);
  } else if (window.realjejuServiceModes && typeof window.realjejuServiceModes.apply === "function") {
    await window.realjejuServiceModes.apply(nextCategory);
  } else {
    await applyLocalBusinessMapLayerMode(nextCategory);
  }
	if (requestId !== globalCategoryModeRequestId
		|| !document.body
		|| document.body.dataset.globalCategory !== nextCategory) return false;
	if (serviceMapToolRestorePendingCategory === nextCategory) {
		serviceMapToolRestorePendingCategory = "";
		restoreServiceMapToolSelections(nextCategory);
		serviceMapToolRestorePendingCategory = "";
		await renderVisibleFacilityOverlaysForViewport();
	}
	if (!emptyMap && nextCategory === "parcel") {
		if (document.body) document.body.classList.remove("parcel-region-trade-badges-hidden");
		const parcelMode = getPropertyMapPresentationMode();
		const parcelLevel = Number(state.map?.getLevel?.());
		const usesIndividualTradeBadges = Number.isFinite(parcelLevel) && parcelLevel >= 1 && parcelLevel <= 5;
		propertyMapPresentationMode = parcelMode;
		if (!usesIndividualTradeBadges && shouldRenderParcelRegionTradeMapBadges(parcelMode)) {
			clearMapObjects();
			await renderPropertyRegionCountOverlays(parcelMode);
		}
		await syncParcelTradeCanvasForCategory(nextCategory, { loadInitial: true });
	}
	if (!emptyMap && nextCategory === "realestate") {
		await restoreRealestateMapToolSelections();
		scheduleRealjejuPropertyMapRepaintAfterCategoryReturn();
	}
	if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
	return true;
}

function scheduleRealjejuPropertyMapRepaintAfterCategoryReturn()
{
	try {
		if (!document.body || document.body.classList.contains("global-category-empty-map-mode")) return false;
		if (document.body.dataset && document.body.dataset.globalCategory && !isGlobalRealestateCategory(document.body.dataset.globalCategory)) return false;
		if (typeof state === "undefined" || !state || !state.map || !state.clusterer || !Array.isArray(state.filtered)) return false;
		state.markerRenderSignature = "";
		if (typeof renderMarkers === "function") renderMarkers(state.filtered, { preserveViewport: true });
		let viewportItems = null;
		if (typeof refreshViewportList === "function") viewportItems = refreshViewportList();
		if (typeof updateMapEmptyState === "function") updateMapEmptyState(viewportItems || []);
		if (typeof refreshClusterBadges === "function") refreshClusterBadges();
		if (typeof refreshMapLayout === "function") refreshMapLayout();
		if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
		return true;
	} catch (error) {
		console.warn("부동산 카테고리 복귀 후 매물 뱃지 재렌더 실패:", error);
		return false;
	}
}

function setGlobalCategoryButtonState(category)
	{
		const nextCategory = String(category || "").trim();
		const previousCategory = getCurrentRealjejuGlobalCategoryKey();
		const pendingServiceTransition = pendingServiceMapToolCategoryTransition?.to === nextCategory
			? pendingServiceMapToolCategoryTransition
			: null;
		const serviceStatePreviousCategory = pendingServiceTransition?.from || previousCategory;
		if (nextCategory !== serviceStatePreviousCategory && distanceMeasureActive) {
			setDistanceMeasureActive(false, { clear: true });
		}
		if (nextCategory !== serviceStatePreviousCategory && !pendingServiceTransition) {
			rememberServiceMapToolSelections(serviceStatePreviousCategory);
		}
		if (nextCategory !== previousCategory && typeof setMapRoadviewOverlayVisible === "function") {
			setMapRoadviewOverlayVisible(false);
		}
		if (nextCategory === "parcel" && previousCategory !== "parcel") {
			resetRealestateSelectionBeforeParcelEntry();
		}
		if (previousCategory === "parcel" && nextCategory !== "parcel") {
			resetParcelSelectionBeforeRealestateEntry();
		}
		if (isGlobalRealestateCategory(previousCategory) && !isGlobalRealestateCategory(nextCategory)) {
			rememberRealestateMapToolSelections();
		}
		document.querySelectorAll("#globalCategoryMenu .global-category-item").forEach((button) => {
			const active = !!nextCategory && button.dataset.globalCategory === nextCategory;
			button.classList.toggle("is-active", active);
			if (active) button.setAttribute("aria-current", "page");
			else button.removeAttribute("aria-current");
		});
		if (document.body) {
			if (nextCategory) document.body.dataset.globalCategory = nextCategory;
			else delete document.body.dataset.globalCategory;
		}
		if (nextCategory !== serviceStatePreviousCategory) restoreServiceMapToolSelections(nextCategory);
		if (pendingServiceTransition) pendingServiceMapToolCategoryTransition = null;
		if (typeof syncPickaxeMode === "function") syncPickaxeMode();
		if (nextCategory && typeof shouldShowGlobalCategoryEmptyMap === "function" && shouldShowGlobalCategoryEmptyMap(nextCategory)) {
			clearGlobalCategoryEmptyMapOverlays();
		}
		scheduleRealjejuGlobalCategoryMenuPosition();
		if (typeof window.realjejuSyncDesktopSideNavToggle === "function") window.realjejuSyncDesktopSideNavToggle();
		if (typeof window.realjejuSyncMobileSideNavDrawer === "function") window.realjejuSyncMobileSideNavDrawer();
		if (typeof syncParcelTradeFilterControlVisibility === "function") syncParcelTradeFilterControlVisibility();
	}

function syncGlobalCategoryActive(category)
	{
		const nextCategory = category || "realestate";
		if (document.body && document.body.classList.contains("main-landing-page-open")) {
			clearGlobalCategoryActive();
			return Promise.resolve(false);
		}
		if (typeof closeRightMapToolPanels === "function") closeRightMapToolPanels();
		closeRealjejuTermsFullPageForNavigation();
		closeRealjejuCompanyFullPageForNavigation();
		if (nextCategory !== "part-time") closeRealjejuPartTimePage();
		setGlobalCategoryButtonState(nextCategory);
		return applyGlobalCategoryMode(nextCategory);
	}

function clearGlobalCategoryActive()
	{
		setGlobalCategoryButtonState("");
	}

