let mapRegionBoundaryListState = null;

let mapRegionBoundaryRemoteRequestSeq = 0;

const mapRegionBoundaryParentDongCache = new Map();

const mapRegionBoundaryListItemsCache = new WeakMap();

function normalizeJejuProvinceName(value)
{
	const text = String(value || "").trim();
	if (!text) return "제주도";
	return text.replace("제주특별자치도", "제주도");
}

function normalizeJejuCityName(value)
{
	const text = String(value || "").trim();
	if (text === "서귀포") return "서귀포시";
	if (text === "제주") return "제주시";
	return text;
}

function normalizeRegionDongName(value)
{
	return String(value || "").trim().replace(/\s+/g, "");
}

function getMapRegionDongAliases(city, dong)
{
	const normalizedCity = normalizeJejuCityName(city || "");
	const normalizedDong = normalizeRegionDongName(dong || "");
	if (!normalizedDong) return [];
	const aliasMap = JEJU_REGION_DONG_ALIASES[normalizedCity] || {};
	const direct = aliasMap[normalizedDong] || [];
	return [normalizedDong, ...direct.map(normalizeRegionDongName)];
}

function getMapRegionDisplayDong(city, dong)
{
	const normalizedCity = normalizeJejuCityName(city || "");
	const normalizedDong = normalizeRegionDongName(dong || "");
	if (!normalizedDong) return "";
	if ((JEJU_REGION_OPTIONS[normalizedCity] || []).includes(normalizedDong)) return normalizedDong;
	const aliasMap = JEJU_REGION_DONG_ALIASES[normalizedCity] || {};
	for (const [displayDong, aliases] of Object.entries(aliasMap)) {
		if ((aliases || []).map(normalizeRegionDongName).includes(normalizedDong)) return displayDong;
	}
	return normalizedDong;
}

function getMapCenterRegionMetaFromAdminBoundaryFeature(feature)
{
	if (!feature) return null;
	const props = feature.properties || {};
	const codeValue = getAdminBoundaryFeatureCodeValue(feature);
	const sigCode = String(props.sig_cd || props.SIG_CD || codeValue.slice(0, 5) || "").trim();
	const city = sigCode === "50130" ? "서귀포시" : (sigCode === "50110" ? "제주시" : "");
	const dong = normalizeRegionDongName(getAdminBoundaryFeatureName(feature));
	if (!city || !dong) return null;
	return {
		province: "제주도",
		city,
		dong
	};
}

function formatMapRegionButtonLabel(meta)
{
	const value = meta && typeof meta === "object" ? meta : {};
	const city = normalizeJejuCityName(value.city || "");
	const dong = normalizeRegionDongName(value.dong || "");
	if (city && dong) return `${city} ${dong}`;
	return dong || city || "";
}

function setMapCenterRegionLabel(text)
{
	if (!mapCenterRegionLabel) return;
	const nextMeta = text && typeof text === "object"
		? {
			province: normalizeJejuProvinceName(text.province || "제주도"),
			city: normalizeJejuCityName(text.city || mapRegionFilterState.city || "제주시"),
			dong: getMapRegionDisplayDong(normalizeJejuCityName(text.city || mapRegionFilterState.city || "제주시"), text.dong || mapRegionFilterState.dong || "")
		}
		: {
			province: mapRegionFilterState.province || "제주도",
			city: mapRegionFilterState.city || "제주시",
			dong: getMapRegionDisplayDong(mapRegionFilterState.city || "제주시", text || mapRegionFilterState.dong || "")
		};
	if (nextMeta.city || nextMeta.dong) {
		mapRegionFilterState.province = nextMeta.province || "제주도";
		mapRegionFilterState.city = nextMeta.city || mapRegionFilterState.city || "제주시";
		mapRegionFilterState.dong = nextMeta.dong || mapRegionFilterState.dong || "";
		if (mapRegionFilterState.mode !== "select" && mapRegionFilterState.mode !== "city") mapRegionFilterState.mode = "list";
	}
	const label = formatMapRegionButtonLabel(mapRegionFilterState);
	const regionTriggerLabel = document.getElementById("mapRegionFilterLabel");
	const regionMenuValue = document.getElementById("mapRegionFilterValue");
	window.realjejuCurrentMapCenterRegionLabel = label;
	window.realjejuCurrentMapCenterRegion = { ...mapRegionFilterState };
	if (regionTriggerLabel) regionTriggerLabel.textContent = label || "현재 위치";
	if (regionMenuValue) regionMenuValue.textContent = label || "지도 중심 주소를 불러오는 중입니다.";
	if (typeof renderMapRegionFilterMenu === "function") renderMapRegionFilterMenu();
	if (!label) {
		mapCenterRegionLabel.hidden = true;
		mapCenterRegionLabel.textContent = "";
		return;
	}
	mapCenterRegionLabel.textContent = label;
		mapCenterRegionLabel.hidden = true;
}

function normalizeMapCenterRegionMeta(meta)
{
	if (!meta || typeof meta !== "object") return null;
	const city = normalizeJejuCityName(meta.city || "");
	const dong = normalizeRegionDongName(meta.dong || "");
	if (!city && !dong) return null;
	return {
		province: normalizeJejuProvinceName(meta.province || "제주도"),
		city,
		dong
	};
}

function getMapCenterRegionCacheKey(lat, lng)
{
	const normalizedLat = Number(lat);
	const normalizedLng = Number(lng);
	if (!Number.isFinite(normalizedLat) || !Number.isFinite(normalizedLng)) return "";
	return `${normalizedLat.toFixed(MAP_CENTER_REGION_COORD_PRECISION)},${normalizedLng.toFixed(MAP_CENTER_REGION_COORD_PRECISION)}`;
}

function hydrateMapCenterRegionCache()
{
	if (mapCenterRegionCacheHydrated) return;
	mapCenterRegionCacheHydrated = true;
	try {
		const raw = window.localStorage && window.localStorage.getItem(MAP_CENTER_REGION_CACHE_STORAGE_KEY);
		const payload = raw ? JSON.parse(raw) : null;
		const entries = payload && Array.isArray(payload.entries) ? payload.entries : [];
		const now = Date.now();
		entries.slice(-MAP_CENTER_REGION_CACHE_MAX_ENTRIES).forEach((item) => {
			if (!Array.isArray(item) || item.length < 3) return;
			const cacheKey = String(item[0] || "");
			const cachedAt = Number(item[1]);
			const meta = normalizeMapCenterRegionMeta(item[2]);
			if (!cacheKey || !Number.isFinite(cachedAt) || now - cachedAt > MAP_CENTER_REGION_CACHE_TTL_MS || !meta) return;
			mapCenterRegionCache.set(cacheKey, { cachedAt, meta });
		});
	} catch (error) {
		// Storage may be unavailable in private or restricted browser contexts.
	}
}

function persistMapCenterRegionCache()
{
	try {
		if (!window.localStorage) return;
		const entries = Array.from(mapCenterRegionCache.entries())
			.slice(-MAP_CENTER_REGION_CACHE_MAX_ENTRIES)
			.map(([cacheKey, entry]) => [cacheKey, entry.cachedAt, entry.meta]);
		window.localStorage.setItem(MAP_CENTER_REGION_CACHE_STORAGE_KEY, JSON.stringify({ entries }));
	} catch (error) {
		// The in-memory cache remains available when storage is blocked or full.
	}
}

function getCachedMapCenterRegionMeta(cacheKey)
{
	hydrateMapCenterRegionCache();
	const entry = cacheKey ? mapCenterRegionCache.get(cacheKey) : null;
	if (!entry) return null;
	if (Date.now() - Number(entry.cachedAt || 0) > MAP_CENTER_REGION_CACHE_TTL_MS) {
		mapCenterRegionCache.delete(cacheKey);
		persistMapCenterRegionCache();
		return null;
	}
	mapCenterRegionCache.delete(cacheKey);
	mapCenterRegionCache.set(cacheKey, entry);
	return { ...entry.meta };
}

function setCachedMapCenterRegionMeta(cacheKey, meta)
{
	const normalizedMeta = normalizeMapCenterRegionMeta(meta);
	if (!cacheKey || !normalizedMeta) return null;
	mapCenterRegionCache.delete(cacheKey);
	mapCenterRegionCache.set(cacheKey, { cachedAt: Date.now(), meta: normalizedMeta });
	while (mapCenterRegionCache.size > MAP_CENTER_REGION_CACHE_MAX_ENTRIES) {
		const oldestKey = mapCenterRegionCache.keys().next().value;
		if (!oldestKey) break;
		mapCenterRegionCache.delete(oldestKey);
	}
	persistMapCenterRegionCache();
	return { ...normalizedMeta };
}

function resolveMapCenterRegionMeta(lat, lng)
{
	const cacheKey = getMapCenterRegionCacheKey(lat, lng);
	if (!cacheKey) return Promise.resolve(null);
	const cachedMeta = getCachedMapCenterRegionMeta(cacheKey);
	if (cachedMeta) return Promise.resolve(cachedMeta);
	const now = Date.now();
	if (mapCenterRegionServiceFailureUntil > now) return Promise.resolve(null);
	const failedUntil = Number(mapCenterRegionFailureUntil.get(cacheKey) || 0);
	if (failedUntil > now) return Promise.resolve(null);
	if (failedUntil) mapCenterRegionFailureUntil.delete(cacheKey);
	if (mapCenterRegionInflight.has(cacheKey)) return mapCenterRegionInflight.get(cacheKey);

	const request = loadAdminBoundaryGeoJson("emd").then((data) => {
		const features = data && Array.isArray(data.features) ? data.features : [];
		const feature = findAdminBoundaryFeatureAtCenter(features, [Number(lng), Number(lat)]);
		const meta = setCachedMapCenterRegionMeta(cacheKey, getMapCenterRegionMetaFromAdminBoundaryFeature(feature));
		if (meta) {
			mapCenterRegionServiceFailureUntil = 0;
			mapCenterRegionFailureUntil.delete(cacheKey);
		}
		else mapCenterRegionFailureUntil.set(cacheKey, Date.now() + MAP_CENTER_REGION_FAILURE_COOLDOWN_MS);
		return meta;
	}).catch(() => {
		mapCenterRegionServiceFailureUntil = Date.now() + MAP_CENTER_REGION_FAILURE_COOLDOWN_MS;
		mapCenterRegionFailureUntil.set(cacheKey, Date.now() + MAP_CENTER_REGION_FAILURE_COOLDOWN_MS);
		return null;
	}).finally(() => {
		if (mapCenterRegionInflight.get(cacheKey) === request) mapCenterRegionInflight.delete(cacheKey);
	});
	mapCenterRegionInflight.set(cacheKey, request);
	return request;
}

function updateMapCenterRegionLabel()
{
	if (!state.map || !mapCenterRegionLabel) return;
	if (window.location && window.location.protocol === "file:") {
		setMapCenterRegionLabel({
			province: mapRegionFilterState.province || "제주도",
			city: mapRegionFilterState.city || "제주시",
			dong: mapRegionFilterState.dong || ""
		});
		return;
	}
	const center = state.map.getCenter && state.map.getCenter();
	if (!center || typeof center.getLat !== "function" || typeof center.getLng !== "function") return;
	const lat = Number(center.getLat());
	const lng = Number(center.getLng());
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
	const requestSeq = ++mapCenterRegionRequestSeq;
	resolveMapCenterRegionMeta(lat, lng).then((meta) => {
		if (requestSeq !== mapCenterRegionRequestSeq) return;
		if (meta) setMapCenterRegionLabel(meta);
	});
}

function scheduleMapCenterRegionLabelUpdate()
{
	if (mapCenterRegionTimer) window.clearTimeout(mapCenterRegionTimer);
	mapCenterRegionTimer = window.setTimeout(updateMapCenterRegionLabel, MAP_CENTER_REGION_DEBOUNCE_MS);
}

function getMapRegionPanelElement()
{
	return document.getElementById("mapRegionPanel");
}

function getMapRegionCurrentMeta()
{
	return {
		province: normalizeJejuProvinceName(mapRegionFilterState.province || "제주도"),
		city: normalizeJejuCityName(mapRegionFilterState.city || "제주시"),
		dong: normalizeRegionDongName(mapRegionFilterState.dong || "")
	};
}

function getMapRegionItemText(item)
{
	if (!item || typeof item !== "object") return "";
	const payload = item.payload && typeof item.payload === "object" ? item.payload : {};
	const fields = [
		item.fullAddress,
		item.address,
		item.region,
		item.location,
		item.title,
		item.buildingName,
		payload.fullAddress,
		payload.full_address,
		payload.address,
		payload.address1,
		payload.address2,
		payload.roadAddress,
		payload.road_address,
		payload.jibunAddress,
		payload.jibun_address,
		payload.public_address,
		payload.소재지,
		payload.주소
	];
	return fields
		.filter(value => value !== null && value !== undefined && String(value).trim())
		.map(value => String(value))
		.join(" ");
}

function getMapRegionMetaFromItem(item)
{
	const text = getMapRegionItemText(item).replace(/제주특별자치도/g, "제주도");
	const current = getMapRegionCurrentMeta();
	const cityMatch = text.match(/(제주시|서귀포시)/);
	const city = cityMatch ? cityMatch[1] : current.city;
	const sourceAfterCity = cityMatch ? text.slice(cityMatch.index + cityMatch[1].length) : text;
	const dongMatch = sourceAfterCity.match(/([가-힣0-9]+(?:동|읍|면))/);
	const dong = dongMatch ? normalizeRegionDongName(dongMatch[1]) : "";
	return { province: "제주도", city, dong };
}

function getMapRegionSourceItems()
{
	if (typeof isPresaleMapMode === "function" && isPresaleMapMode()) return [];
	const filtered = Array.isArray(state.filtered) ? state.filtered : [];
	if (filtered.length) return filtered;
	return Array.isArray(state.all) ? state.all : [];
}

function getMapRegionItems(city, dong)
{
	const targetCity = normalizeJejuCityName(city || "");
	const targetDong = normalizeRegionDongName(dong || "");
	const targetDongs = getMapRegionDongAliases(targetCity, targetDong);
	if (!targetDongs.length) return [];
	return getMapRegionSourceItems().filter((item) => {
		const meta = getMapRegionMetaFromItem(item);
		const itemText = getMapRegionItemText(item).replace(/\s+/g, "");
		if (targetCity && meta.city && meta.city !== targetCity) return false;
		return targetDongs.some(name => meta.dong === name || itemText.includes(name));
	});
}

function clearMapRegionBoundaryListState()
{
	mapRegionBoundaryRemoteRequestSeq += 1;
	mapRegionBoundaryListState = null;
}

function getMapRegionBoundaryListState()
{
	return mapRegionBoundaryListState && mapRegionBoundaryListState.feature ? mapRegionBoundaryListState : null;
}

function getAdminBoundaryFeatureCodeValue(feature)
{
	const props = feature && feature.properties ? feature.properties : {};
	return String(props.code || props.ADM_CD || props.EMD_CD || props.LI_CD || "").trim();
}

async function resolveMapRegionBoundaryParentDong(feature, city)
{
	const boundaryName = normalizeRegionDongName(getAdminBoundaryFeatureName(feature));
	if (!boundaryName || !/리$/.test(boundaryName)) return boundaryName;
	const boundaryCode = getAdminBoundaryFeatureCodeValue(feature);
	const parentCacheKey = `${normalizeJejuCityName(city || "")}|${boundaryCode || boundaryName}`;
	if (mapRegionBoundaryParentDongCache.has(parentCacheKey)) return mapRegionBoundaryParentDongCache.get(parentCacheKey);
	if (boundaryCode && typeof loadAdminBoundaryGeoJson === "function") {
		try {
			const emdCode = boundaryCode.slice(0, 8);
			const emdData = await loadAdminBoundaryGeoJson("emd");
			const parentFeature = (emdData.features || []).find((item) => getAdminBoundaryFeatureCodeValue(item) === emdCode);
			const parentName = normalizeRegionDongName(getAdminBoundaryFeatureName(parentFeature));
			if (parentName) {
				mapRegionBoundaryParentDongCache.set(parentCacheKey, parentName);
				return parentName;
			}
		} catch (error) {
			console.warn("리 상위 읍면동 조회 실패:", error);
		}
	}
	const displayDong = getMapRegionDisplayDong(city, boundaryName);
	const fallbackParent = displayDong && displayDong !== boundaryName ? displayDong : normalizeRegionDongName(mapRegionFilterState.dong || "");
	mapRegionBoundaryParentDongCache.set(parentCacheKey, fallbackParent);
	return fallbackParent;
}

async function setMapRegionBoundaryListStateFromAdminFeature(feature, count)
{
	if (!feature) {
		clearMapRegionBoundaryListState();
		return null;
	}
	if (getAdminBoundaryFeatureCodeValue(feature) === "jeju-province") {
		mapRegionBoundaryListState = {
			feature,
			name: "제주도",
			parentDong: "",
			count: Math.max(0, Number(count) || 0),
			regionCode: "50",
			items: [],
			totalCount: Math.max(0, Number(count) || 0),
			loading: false,
			exhausted: false,
			requestSeq: ++mapRegionBoundaryRemoteRequestSeq,
			sort: mapRegionFilterState.sort || "latest"
		};
		return mapRegionBoundaryListState;
	}
	const name = normalizeRegionDongName(getAdminBoundaryFeatureName(feature));
	const city = normalizeJejuCityName(mapRegionFilterState.city || "제주시");
	const regionCode = getPropertyScaleRegionCode(feature);
	const sort = mapRegionFilterState.sort || "latest";
	const previousState = getMapRegionBoundaryListState();
	if (previousState
		&& previousState.regionCode === regionCode
		&& previousState.sort === sort) {
		previousState.feature = feature;
		previousState.name = name;
		previousState.count = Math.max(0, Number(count) || 0);
		previousState.totalCount = Math.max(
			previousState.items.length,
			Math.max(0, Number(count) || 0)
		);
		return previousState;
	}
	const parentDong = await resolveMapRegionBoundaryParentDong(feature, city);
	mapRegionBoundaryListState = {
		feature,
		name,
		parentDong: parentDong || name,
		count: Math.max(0, Number(count) || 0),
		regionCode,
		items: [],
		totalCount: Math.max(0, Number(count) || 0),
		loading: false,
		exhausted: false,
		requestSeq: ++mapRegionBoundaryRemoteRequestSeq,
		sort
	};
	return mapRegionBoundaryListState;
}

function getMapRegionBoundaryDisplayDong(meta)
{
	const boundary = getMapRegionBoundaryListState();
	if (!boundary || !boundary.name) return normalizeRegionDongName(meta && meta.dong || "");
	const parentDong = normalizeRegionDongName(boundary.parentDong || (meta && meta.dong) || "");
	if (parentDong && parentDong !== boundary.name) return `${parentDong}(${boundary.name})`;
	return boundary.name;
}

function getMapRegionBoundaryItemCacheId(item, index)
{
	if (!item || typeof item !== "object") return String(index || 0);
	try {
		if (typeof getItemViewKey === "function") {
			const viewKey = getItemViewKey(item);
			if (viewKey) return String(viewKey);
		}
	} catch (error) {
		// Cache IDs are only an optimization; fall through to simple fields.
	}
	return String(
		item.id
		|| item.listing_id
		|| item.listingId
		|| item.uuid
		|| item.uid
		|| `${item.lat || ""},${item.lng || ""},${item.title || ""},${index || 0}`
	);
}

function getMapRegionBoundarySourceSignature(items)
{
	const list = Array.isArray(items) ? items : [];
	if (!list.length) return "0";
	const first = getMapRegionBoundaryItemCacheId(list[0], 0);
	const middle = getMapRegionBoundaryItemCacheId(list[Math.floor((list.length - 1) / 2)], Math.floor((list.length - 1) / 2));
	const last = getMapRegionBoundaryItemCacheId(list[list.length - 1], list.length - 1);
	return `${list.length}|${first}|${middle}|${last}`;
}

function getMapRegionBoundaryListItems(feature)
{
	if (!feature) return [];
	const boundaryState = getMapRegionBoundaryListState();
	const featureCode = getPropertyScaleRegionCode(feature);
	if (boundaryState
		&& boundaryState.regionCode
		&& boundaryState.regionCode === featureCode
		&& Array.isArray(boundaryState.items)) {
		return boundaryState.items;
	}
	const sourceItems = getMapRegionSourceItems();
	if (!Array.isArray(sourceItems) || !sourceItems.length) return [];
	if (getAdminBoundaryFeatureCodeValue(feature) === "jeju-province") return sourceItems.slice();
	const featureKey = getAdminBoundaryFeatureCodeValue(feature) || normalizeRegionDongName(getAdminBoundaryFeatureName(feature));
	const cacheKey = `${featureKey}|${getMapRegionBoundarySourceSignature(sourceItems)}`;
	let sourceCache = mapRegionBoundaryListItemsCache.get(sourceItems);
	if (!sourceCache) {
		sourceCache = new Map();
		mapRegionBoundaryListItemsCache.set(sourceItems, sourceCache);
	}
	if (sourceCache.has(cacheKey)) return sourceCache.get(cacheKey);
	const items = sourceItems.filter((item) => {
		const point = getAdminBoundaryListingPoint(item);
		return point && doesAdminBoundaryFeatureContainPoint(feature, point);
	});
	sourceCache.set(cacheKey, items);
	return items;
}

async function loadMapRegionBoundaryRemotePage(options = {})
{
	const boundaryState = getMapRegionBoundaryListState();
	if (!boundaryState || !boundaryState.regionCode) return boundaryState;
	const reset = options.reset === true;
	const refresh = options.refresh === true;
	if (boundaryState.loading) return boundaryState;
	if (!reset && !refresh && boundaryState.exhausted) return boundaryState;
	if (reset || refresh) {
		if (!refresh) boundaryState.items = [];
		boundaryState.exhausted = false;
		boundaryState.requestSeq = ++mapRegionBoundaryRemoteRequestSeq;
		boundaryState.sort = mapRegionFilterState.sort || "latest";
	}
	const requestSeq = boundaryState.requestSeq;
	boundaryState.loading = true;
	try {
		const result = await fetchPropertyScaleRegionPage(boundaryState.regionCode, {
			offset: refresh ? 0 : boundaryState.items.length,
			limit: LEFT_LIST_PAGE_SIZE,
			totalCount: boundaryState.totalCount,
			sort: mapRegionFilterState.sort || "latest"
		});
		const activeState = getMapRegionBoundaryListState();
		if (activeState !== boundaryState || activeState.requestSeq !== requestSeq) return activeState;
		const knownIds = new Set((refresh ? [] : boundaryState.items).map((item) => normalizeItemId(item && item.id)).filter(Boolean));
		const nextItems = (Array.isArray(result.items) ? result.items : []).filter((item) => {
			const id = normalizeItemId(item && item.id);
			if (!id || knownIds.has(id)) return false;
			knownIds.add(id);
			return true;
		});
		if (refresh) boundaryState.items = nextItems;
		else boundaryState.items.push(...nextItems);
		boundaryState.totalCount = Number.isFinite(Number(result.totalCount))
			? Math.max(0, Number(result.totalCount))
			: boundaryState.totalCount;
		boundaryState.count = boundaryState.totalCount;
		boundaryState.exhausted = nextItems.length < LEFT_LIST_PAGE_SIZE
			|| boundaryState.items.length >= boundaryState.totalCount;
		return boundaryState;
	} finally {
		const activeState = getMapRegionBoundaryListState();
		if (activeState === boundaryState && activeState.requestSeq === requestSeq) activeState.loading = false;
	}
}

function getMapRegionItemTitle(item)
{
	if (!item || typeof item !== "object") return "이름 없는 매물";
	const payload = item.payload && typeof item.payload === "object" ? item.payload : {};
	return sanitizePublicListingText(String(
		item.buildingName
		|| item.complexName
		|| payload.complexName
		|| payload.complex_name
		|| payload.buildingName
		|| payload.building_name
		|| item.title
		|| payload.title
		|| payload.매물명
		|| payload.단지명
		|| "이름 없는 매물"
	).trim(), item);
}

function getMapRegionItemTypeLabel(item)
{
	const typeText = String(item && (item.type || item.propertyType || item.category) || "").trim();
	if (typeof getSummaryTypeBadgeLabel === "function") return getSummaryTypeBadgeLabel(typeText || "매물");
	if (typeof getCardTypeBadgeLabel === "function") return getCardTypeBadgeLabel(typeText || "매물");
	return typeText || "매물";
}

function getMapRegionItemDealLabel(item)
{
	const payload = item && item.payload && typeof item.payload === "object" ? item.payload : {};
	const raw = String(
		item && (item.dealType || item.deal || item.transactionType)
		|| payload.dealType
		|| payload.deal_type
		|| payload.trade_type
		|| payload.거래유형
		|| ""
	).trim();
	if (/전세/.test(raw)) return "전세";
	if (/월세/.test(raw)) return "월세";
	if (/년세|연세/.test(raw)) return "월세";
	if (/매매/.test(raw)) return "매매";
	return raw || "";
}

function getMapRegionItemHouseholdText(item)
{
	const text = getMapRegionItemText(item);
	const match = text.match(/([\d,]+)\s*세대/);
	return match ? `${match[1]}세대` : "";
}

function getMapRegionItemApprovalText(item)
{
	const payload = item && item.payload && typeof item.payload === "object" ? item.payload : {};
	const text = [
		item && (item.approvalDate || item.useApprovalDate || item.date),
		payload.approvalDate,
		payload.approval_date,
		payload.useApprovalDate,
		payload.use_approval_date,
		payload.사용승인일,
		getMapRegionItemText(item)
	].filter(Boolean).join(" ");
	const match = text.match(/((?:19|20)\d{2})[.\-/년\s]+(\d{1,2})/);
	if (!match) return "";
	const year = Number(match[1]);
	const month = Number(match[2]);
	const age = Number.isFinite(year) ? Math.max(1, new Date().getFullYear() - year + 1) : null;
	const dateText = `${match[1]}. ${String(month).padStart(2, "0")}.`;
	return age ? `${dateText} (${age}년차)` : dateText;
}

function buildMapRegionComplexGroups(items)
{
	const groups = new Map();
	(Array.isArray(items) ? items : []).forEach((item, index) => {
		const title = getMapRegionItemTitle(item);
		const type = getMapRegionItemTypeLabel(item);
		const key = `${type}::${title}`;
		if (!groups.has(key)) {
			groups.set(key, {
				key,
				title,
				type,
				first: item,
				items: [],
				index,
				count: 0,
				deals: { "매매": 0, "전세": 0, "월세": 0 },
				households: "",
				approval: ""
			});
		}
		const group = groups.get(key);
		group.count += 1;
		group.items.push(item);
		const deal = getMapRegionItemDealLabel(item);
		if (deal === "매매" || deal === "전세" || deal === "월세") group.deals[deal] += 1;
		if (!group.households) group.households = getMapRegionItemHouseholdText(item);
		if (!group.approval) group.approval = getMapRegionItemApprovalText(item);
	});
	return sortMapRegionGroups([...groups.values()]);
}

function buildMapRegionListingGroups(items)
{
	const groups = (Array.isArray(items) ? items : []).map((item, index) => {
		const deal = getMapRegionItemDealLabel(item);
		return {
			key: getMapRegionBoundaryItemCacheId(item, index),
			title: getMapRegionItemTitle(item),
			type: getMapRegionItemTypeLabel(item),
			first: item,
			items: [item],
			index,
			count: 1,
			deals: {
				"매매": deal === "매매" ? 1 : 0,
				"전세": deal === "전세" ? 1 : 0,
				"월세": deal === "월세" ? 1 : 0
			},
			households: getMapRegionItemHouseholdText(item),
			approval: getMapRegionItemApprovalText(item)
		};
	});
	return sortMapRegionGroups(groups);
}

function getMapRegionGroupBestValue(group, getter)
{
	const values = (Array.isArray(group && group.items) ? group.items : [group && group.first])
		.map(item => getter(item))
		.filter(value => value !== null && value !== undefined && Number.isFinite(Number(value)))
		.map(Number);
	return values.length ? Math.min(...values) : null;
}

function getMapRegionGroupLatestValue(group)
{
	const values = (Array.isArray(group && group.items) ? group.items : [group && group.first])
		.map(item => getSortDateValue(item))
		.filter(value => Number.isFinite(Number(value)))
		.map(Number);
	return values.length ? Math.max(...values) : 0;
}

function getMapRegionGroupPopularityValue(group)
{
	const itemPopularity = (Array.isArray(group && group.items) ? group.items : [group && group.first])
		.reduce((sum, item) => sum + (Number(getAgentListPopularityValue(item)) || 0), 0);
	return itemPopularity || Number(group && group.count) || 0;
}

function sortMapRegionGroups(groups)
{
	const list = Array.isArray(groups) ? [...groups] : [];
	const mode = mapRegionFilterState.sort || "latest";
	if (mode === "popular") {
		list.sort((a, b) => {
			const popularDiff = getMapRegionGroupPopularityValue(b) - getMapRegionGroupPopularityValue(a);
			if (popularDiff !== 0) return popularDiff;
			return getMapRegionGroupLatestValue(b) - getMapRegionGroupLatestValue(a);
		});
		return list;
	}
	if (mode === "price-asc" || mode === "price-desc") {
		const direction = mode === "price-desc" ? "desc" : "asc";
		list.sort((a, b) => {
			const priceDiff = compareAgentListNumbers(
				getMapRegionGroupBestValue(a, getAgentListPriceValue),
				getMapRegionGroupBestValue(b, getAgentListPriceValue),
				direction
			);
			return priceDiff || getMapRegionGroupLatestValue(b) - getMapRegionGroupLatestValue(a);
		});
		return list;
	}
	if (mode === "area-asc" || mode === "area-desc") {
		const direction = mode === "area-desc" ? "desc" : "asc";
		list.sort((a, b) => {
			const areaDiff = compareAgentListNumbers(
				getMapRegionGroupBestValue(a, getAgentListAreaValue),
				getMapRegionGroupBestValue(b, getAgentListAreaValue),
				direction
			);
			return areaDiff || getMapRegionGroupLatestValue(b) - getMapRegionGroupLatestValue(a);
		});
		return list;
	}
	list.sort((a, b) => {
		const latestDiff = getMapRegionGroupLatestValue(b) - getMapRegionGroupLatestValue(a);
		if (latestDiff !== 0) return latestDiff;
		const householdA = Number(String(a.households || "").replace(/[^\d]/g, "")) || 0;
		const householdB = Number(String(b.households || "").replace(/[^\d]/g, "")) || 0;
		if (householdA !== householdB) return householdB - householdA;
		return a.index - b.index;
	});
	return list;
}

function getMapRegionSortLabels()
{
	const mode = mapRegionFilterState.sort || "latest";
	return {
		popular: "인기순",
		price: mode === "price-asc" ? "낮은가격순" : mode === "price-desc" ? "높은가격순" : "가격순",
		latest: "최신순",
		area: mode === "area-asc" ? "좁은면적순" : mode === "area-desc" ? "넓은면적순" : "면적순"
	};
}

function getMapRegionSortArrow(type)
{
	const mode = mapRegionFilterState.sort || "latest";
	if (type === "price") {
		if (mode === "price-asc") return "↓";
		if (mode === "price-desc") return "↑";
	}
	if (type === "area") {
		if (mode === "area-asc") return "↓";
		if (mode === "area-desc") return "↑";
	}
	return "";
}

function getMapRegionDongOptions(city)
{
	const normalizedCity = normalizeJejuCityName(city || "제주시");
	return [...(JEJU_REGION_OPTIONS[normalizedCity] || [])];
}

function renderMapRegionBreadcrumb(meta, mode)
{
	const province = escapeHtml(meta.province || "제주도");
	const city = escapeHtml(meta.city || "제주시");
	if (mode === "province") {
		return `
			<div class="map-region-breadcrumb">
				<span class="map-region-breadcrumb-placeholder">시·도</span><span class="map-region-breadcrumb-chevron map-region-breadcrumb-chevron-muted">›</span>
				<span class="map-region-breadcrumb-placeholder">시·군·구</span><span class="map-region-breadcrumb-chevron map-region-breadcrumb-chevron-muted">›</span>
				<span class="map-region-breadcrumb-placeholder">읍·면·동 선택</span>
			</div>
		`;
	}
	if (mode === "city") {
		return `
			<div class="map-region-breadcrumb">
				<span class="map-region-breadcrumb-province" data-map-region-action="select-province">${province}</span><span class="map-region-breadcrumb-chevron">›</span>
				<span class="map-region-breadcrumb-placeholder">시·군·구</span><span class="map-region-breadcrumb-chevron map-region-breadcrumb-chevron-muted">›</span>
				<span class="map-region-breadcrumb-placeholder">읍·면·동 선택</span>
			</div>
		`;
	}
		if (mode === "select") {
			return `
				<div class="map-region-breadcrumb">
					<span class="map-region-breadcrumb-province" data-map-region-action="select-province">${province}</span><span class="map-region-breadcrumb-chevron">›</span>
					<span class="map-region-breadcrumb-city" data-map-region-action="select-city">${city}</span><span class="map-region-breadcrumb-chevron">›</span>
					<span class="map-region-breadcrumb-placeholder">읍·면·동 선택</span>
				</div>
			`;
		}
		const dongLabel = getMapRegionBoundaryDisplayDong(meta) || meta.dong || "읍·면·동";
		return `
			<div class="map-region-breadcrumb">
				<span class="map-region-breadcrumb-province" data-map-region-action="select-province">${province}</span><span class="map-region-breadcrumb-chevron">›</span>
				<span class="map-region-breadcrumb-city" data-map-region-action="select-city">${city}</span><span class="map-region-breadcrumb-chevron">›</span>
				<span class="map-region-breadcrumb-dong" data-map-region-action="select-dong">${escapeHtml(dongLabel)}</span>
			</div>
		`;
	}

let mapRegionComplexDetailGroups = [];

function renderMapRegionListView(meta)
{
	const boundaryState = getMapRegionBoundaryListState();
	const items = boundaryState ? getMapRegionBoundaryListItems(boundaryState.feature) : getMapRegionItems(meta.city, meta.dong);
	const groups = boundaryState ? buildMapRegionListingGroups(items) : buildMapRegionComplexGroups(items);
	const labels = getMapRegionSortLabels();
	const sortMode = mapRegionFilterState.sort || "latest";
	const priceActive = sortMode === "price-asc" || sortMode === "price-desc";
	const areaActive = sortMode === "area-asc" || sortMode === "area-desc";
	const displayDong = boundaryState ? getMapRegionBoundaryDisplayDong(meta) : (meta.dong || meta.city || "현재 위치");
	const countValue = boundaryState
		? Math.max(items.length, Number(boundaryState.totalCount) || Number(boundaryState.count) || 0)
		: groups.length;
		mapRegionComplexDetailGroups = groups;
	const listHtml = groups.length
		? groups.map((group, groupIndex) => {
			const metaParts = [group.households, group.approval].filter(Boolean);
			const favoriteId = normalizeItemId(getItemViewKey(group.first || (Array.isArray(group.items) && group.items[0])));
			const favoriteActive = favoriteId && isFavoriteListing(favoriteId);
			return `
				<div class="map-region-complex-card" role="button" tabindex="0" data-map-region-complex-index="${groupIndex}">
					<div class="map-region-complex-main">
						<div class="map-region-complex-title-row">
							<span class="map-region-complex-badge" data-type="${escapeHtml(group.type)}">${escapeHtml(group.type)}</span>
							<strong>${escapeHtml(group.title)}</strong>
						</div>
						${metaParts.length ? `<div class="map-region-complex-meta">${metaParts.map(escapeHtml).join("<span>|</span>")}</div>` : ""}
						<div class="map-region-complex-deals">
							<span>매매 <b>${group.deals["매매"] || 0}</b></span>
							<span>전세 <b>${group.deals["전세"] || 0}</b></span>
							<span>월세 <b>${group.deals["월세"] || 0}</b></span>
						</div>
					</div>
					<button type="button" class="map-region-heart-btn ${favoriteActive ? "active" : ""}" data-map-region-favorite-id="${escapeHtml(favoriteId)}" data-map-region-favorite-index="${groupIndex}" aria-label="${favoriteActive ? "관심 부동산 해제" : "관심 부동산 추가"}" aria-pressed="${favoriteActive ? "true" : "false"}" ${favoriteId ? "" : "disabled"}>
						<svg class="map-region-heart-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
							<path d="M12 20.25C7.85 16.42 4 13.2 4 9.2C4 6.73 5.93 4.75 8.35 4.75C9.75 4.75 11.06 5.42 12 6.48C12.94 5.42 14.25 4.75 15.65 4.75C18.07 4.75 20 6.73 20 9.2C20 13.2 16.15 16.42 12 20.25Z"></path>
						</svg>
					</button>
				</div>
			`;
		}).join("")
		: `<div class="map-region-empty">현재 조건에 맞는 매물이 없습니다.</div>`;
	return `
		${renderMapRegionBreadcrumb(meta, "list")}
		<div class="map-region-list-head" aria-label="읍면동 매물 정렬">
			<div class="map-region-list-count">매물 <strong>${countValue.toLocaleString("ko-KR")}</strong>개<span class="map-region-list-count-help" tabindex="0" aria-label="매물 수 설명">?<span class="map-region-list-count-help-panel" role="tooltip"><span>원하는 조건의 매물만 지도와 목록에서 볼 수 있습니다.</span><span>정렬을 바꾸면 목록 순서만 변경됩니다.</span></span></span></div>
			<div class="map-region-sort-actions">
				<button type="button" class="map-region-sort-btn ${sortMode === "popular" ? "active" : ""}" data-map-region-sort="popular">${labels.popular}</button>
				<span class="map-region-sort-divider" aria-hidden="true">|</span>
				<button type="button" class="map-region-sort-btn ${priceActive ? "active" : ""}" data-map-region-sort="price">${labels.price}${getMapRegionSortArrow("price")}</button>
				<span class="map-region-sort-divider" aria-hidden="true">|</span>
				<button type="button" class="map-region-sort-btn ${sortMode === "latest" ? "active" : ""}" data-map-region-sort="latest">${labels.latest}</button>
				<span class="map-region-sort-divider" aria-hidden="true">|</span>
				<button type="button" class="map-region-sort-btn ${areaActive ? "active" : ""}" data-map-region-sort="area">${labels.area}${getMapRegionSortArrow("area")}</button>
			</div>
		</div>
		<div class="map-region-complex-list">${listHtml}</div>
		<div class="map-region-footer">
			<button type="button" class="map-region-map-btn" data-map-region-action="focus-map">
				<i class="fa-solid fa-location-dot" aria-hidden="true"></i>
				<span>${escapeHtml(displayDong)} 지도로 보기</span>
			</button>
		</div>
	`;
}

