function getPropertyScaleSortValue()
{
	return ["popular", "price-asc", "price-desc", "area-asc", "area-desc"].includes(currentSort)
		? currentSort
		: "latest";
}

function getPropertyScaleTypeFilterValues()
{
	const selectedValues = selectedType instanceof Set ? [...selectedType] : [];
	const values = [...new Set(selectedValues.flatMap((value) => {
		const mapped = PROPERTY_SCALE_TYPE_VALUES[String(value || "").trim()];
		if (mapped) return mapped;
		const resolved = typeof resolveRealjejuPropertyTypeValue === "function"
			? resolveRealjejuPropertyTypeValue(value)
			: "";
		return [resolved, value].filter(Boolean);
	}))];
	// 매물유형 미선택은 결과 0건 처리(빈 배열은 전체 검색 조건으로 오인되는 RPC를 피한다).
	return values.length > 0
		? values
		: ["__realjeju_no_property_type__"];
}

function getPropertyScalePriceRanges()
{
	const source = selectedPriceRanges && typeof selectedPriceRanges === "object" ? selectedPriceRanges : {};
	const result = {};
	Object.entries(source).forEach(([key, range]) => {
		if (!range || typeof range !== "object") return;
		const min = Number(range.min);
		const max = Number(range.max);
		if ((!Number.isFinite(min) || min <= 0) && !Number.isFinite(max)) return;
		result[key] = {
			min: Number.isFinite(min) ? Math.max(0, min) : null,
			max: Number.isFinite(max) ? Math.max(0, max) : null
		};
	});
	return result;
}

function buildPropertyScaleFilters()
{
	const dealTypes = selectedDeal instanceof Set
		? [...selectedDeal].map((value) => getMapDealCodeFromLabel(value)).filter(Boolean)
		: [];
	const featureValues = state && state.selectedFeatures instanceof Set ? [...state.selectedFeatures] : [];
	// 4.969: `내 매물만`/`우리 사무소 매물`은 브라우저에 내려온 일부 행만 거르지 않습니다.
	// 행정구역 숫자, 지역 30건, 현재 화면 경량 좌표가 모두 같은 소유 범위를 서버에서 적용합니다.
	const requestedListingScope = String(state && state.brokerListingMapScope || "all");
	const listingScope = requestedListingScope !== "all" && canUseBrokerOwnListingMapFilters()
		? requestedListingScope
		: "all";
	const currentUser = getBrokerMapCurrentUser();
	const currentOfficeIdentity = getBrokerOfficeIdentityFromCurrentOffice();
	return {
		listing_scope: listingScope,
		owner_user_id: listingScope !== "all" ? normalizeItemId(currentUser && currentUser.id) : "",
		owner_agency_id: listingScope === "office" ? currentOfficeIdentity.agencyId : "",
		owner_office_name: listingScope === "office" ? currentOfficeIdentity.officeName : "",
		deal_types: [...new Set(dealTypes)],
		property_types: getPropertyScaleTypeFilterValues(),
		deal_method: selectedDealMethod || "all",
		keyword: String(keywordInput?.value || "").trim(),
		price_ranges: getPropertyScalePriceRanges(),
		area_min: Number.isFinite(selectedAreaMinM2) ? selectedAreaMinM2 : null,
		area_max: selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded()
			? selectedAreaMaxM2
			: null,
		features: featureValues,
		approval_age_min: Number.isFinite(selectedApprovalYearMinAge) ? selectedApprovalYearMinAge : null,
		approval_age_max: Number.isFinite(selectedApprovalYearMaxAge) ? selectedApprovalYearMaxAge : null,
		land_types: selectedLandTypeFilter instanceof Set ? [...selectedLandTypeFilter] : [],
		land_use_zones: selectedLandUseZoneFilter instanceof Set ? [...selectedLandUseZoneFilter] : [],
		rooms: selectedRoomFilter instanceof Set ? [...selectedRoomFilter] : [],
		baths: selectedBathFilter instanceof Set ? [...selectedBathFilter] : [],
		floors: selectedFloorFilter instanceof Set ? [...selectedFloorFilter] : [],
		directions: selectedDirectionFilter instanceof Set ? [...selectedDirectionFilter] : [],
		pet: !!selectedPetOnly,
		parking: !!selectedParkingOnly,
		city_gas: !!selectedCityGasOnly,
		duplex: !!selectedDuplexOnly,
		veranda: !!selectedVerandaOnly,
		elevator: !!selectedElevatorOnly,
		full_option: !!selectedFullOptionOnly,
		immediate_move_in: !!selectedImmediateMoveInOnly,
		negotiable_move_in: !!selectedNegotiableMoveInOnly,
		ocean_view: !!selectedOceanViewOnly
	};
}

function getPropertyScaleFilterKey(filters = buildPropertyScaleFilters())
{
	const ordered = {};
	Object.keys(filters || {}).sort().forEach((key) => {
		const value = filters[key];
		ordered[key] = Array.isArray(value) ? [...value].map(String).sort() : value;
	});
	return JSON.stringify(ordered);
}

function readPropertyScaleCache(cache, key)
{
	const entry = cache.get(key);
	if (!entry || Date.now() - Number(entry.cachedAt || 0) >= PROPERTY_SCALE_QUERY_CACHE_MS) {
		if (entry) cache.delete(key);
		return null;
	}
	return entry.value;
}

function writePropertyScaleCache(cache, key, value)
{
	cache.set(key, { cachedAt: Date.now(), value });
	return value;
}

function storePropertyScaleMarkerSnapshot(items = state.filtered, coverage = propertyScaleViewportCoverage)
{
	const sourceItems = Array.isArray(items) ? items.filter(Boolean) : [];
	const bounds = coverage && coverage.bounds;
	if (!sourceItems.length || !coverage?.key || !bounds) return false;
	propertyScaleMarkerSnapshot = {
		items: sourceItems.slice(),
		coverage: {
			key: coverage.key,
			bounds: { ...bounds }
		}
	};
	return true;
}

function readPropertyScaleMarkerSnapshot(coverageKey, visibleBounds)
{
	const snapshot = propertyScaleMarkerSnapshot;
	if (!snapshot || snapshot.coverage?.key !== coverageKey) return null;
	if (!doPropertyScaleBoundsContain(snapshot.coverage.bounds, visibleBounds)) return null;
	return snapshot;
}

async function getPropertyScaleClient()
{
	await loadSupabaseScript();
	const client = getMapListingsSupabaseClient();
	if (!client || typeof client.rpc !== "function") throw new Error("지도 매물 조회 클라이언트를 준비하지 못했습니다.");
	return client;
}

function getPropertyScaleRegionLevel(mode)
{
	if (mode === "province-count") return "province";
	if (mode === "city-counts") return "sig";
	if (mode === "district-counts") return "emd";
	if (mode === "local-counts") return "local";
	return "";
}

function getPropertyScaleRegionCode(feature)
{
	const code = getAdminBoundaryFeatureCodeValue(feature);
	return code === "jeju-province" ? "50" : code;
}

async function fetchPropertyScaleRegionCountRows(level, filters = buildPropertyScaleFilters())
{
	const cacheKey = `${level}|${getPropertyScaleFilterKey(filters)}`;
	const staleEntry = propertyScaleRegionCountCache.get(cacheKey);
	const staleRows = Array.isArray(staleEntry?.value) ? staleEntry.value : [];
	const cached = readPropertyScaleCache(propertyScaleRegionCountCache, cacheKey);
	if (cached) return cached;
	const failed = propertyScaleRegionCountFailureCache.get(cacheKey);
	if (failed && Date.now() - Number(failed.failedAt || 0) < PROPERTY_SCALE_REGION_TIMEOUT_COOLDOWN_MS) {
		return Array.isArray(failed.rows) ? failed.rows : staleRows;
	}
	if (failed) propertyScaleRegionCountFailureCache.delete(cacheKey);
	const inflight = propertyScaleRegionCountInflight.get(cacheKey);
	if (inflight) return inflight;
	const requestGeneration = propertyScaleRegionCountGeneration;
	const request = (async () => {
		const client = await getPropertyScaleClient();
		const { data, error } = await client.rpc(PROPERTY_SCALE_RPC.regionCounts, {
			p_region_level: level,
			p_filters: filters,
			// 잠금 규칙: 제주도ㆍ행정시는 관리자 `전체`와 같은 비삭제ㆍ비숨김 기준,
			// 읍면동 이하는 기존 공개 매물 기준을 그대로 사용한다.
		// 상위 행정구역도 현재 필터 조건을 동일하게 적용해서 매물유형/거래유형 등 선택값을 반영한다.
		p_management: false
		});
		if (error) {
			if (String(error.code || "") === "57014") {
				propertyScaleRegionCountFailureCache.set(cacheKey, { failedAt: Date.now(), rows: staleRows });
				console.warn("지역 집계 조회가 시간 초과되어 직전 결과를 유지합니다:", level);
				return staleRows;
			}
			throw error;
		}
		propertyScaleRegionCountFailureCache.delete(cacheKey);
		const rows = Array.isArray(data) ? data : [];
		if (requestGeneration === propertyScaleRegionCountGeneration) {
			writePropertyScaleCache(propertyScaleRegionCountCache, cacheKey, rows);
		}
		return rows;
	})();
	propertyScaleRegionCountInflight.set(cacheKey, request);
	try {
		return await request;
	} finally {
		if (propertyScaleRegionCountInflight.get(cacheKey) === request) {
			propertyScaleRegionCountInflight.delete(cacheKey);
		}
	}
}

async function loadPropertyScaleRegionStats(mode)
{
	const level = getPropertyScaleRegionLevel(mode);
	const filters = buildPropertyScaleFilters();
	let rows = [];
	if (level === "local") {
		// 화면의 local 축척은 리 경계와 동 경계를 함께 쓰므로 두 서버 집계를 합친다.
		const [lioRows, emdRows] = await Promise.all([
			fetchPropertyScaleRegionCountRows("lio", filters),
			fetchPropertyScaleRegionCountRows("emd", filters)
		]);
		rows = [...lioRows, ...emdRows.filter((row) => /동$/.test(String(row?.region_name || "")))];
	} else {
		rows = await fetchPropertyScaleRegionCountRows(level, filters);
	}
	const statsByCode = new Map();
	rows.forEach((row) => {
		const code = String(row?.region_code || "").trim();
		if (!code) return;
		statsByCode.set(code, {
			listingCount: Math.max(0, Number(row?.listing_count) || 0),
			brokerCount: Math.max(0, Number(row?.broker_count) || 0)
		});
	});
	// 4.929: 관리자ㆍ운영자 왼쪽 하단 매물 수와 제주도 전체 뱃지는 같은 서버 집계 결과를 씁니다.
	// 서로 다른 조회 캐시의 갱신 시점 때문에 같은 화면에서 두 숫자가 갈리는 회귀를 막습니다.
	if (level === "province"
		&& shouldShowRealjejuTopbarVersionStats()
		&& !(document.body && document.body.classList.contains("admin-page-open"))) {
		const provinceCount = Number(statsByCode.get("50")?.listingCount);
		if (Number.isFinite(provinceCount)) {
			realjejuManagementVersionListingCount = Math.max(0, Math.trunc(provinceCount));
			updateRealjejuTopbarVersionText();
		}
	}
	return statsByCode;
}

function getPropertyScaleRegionLevelForFeature(feature)
{
	const code = getPropertyScaleRegionCode(feature);
	if (code === "50") return "province";
	if (code.length === 5) return "sig";
	if (code.length >= 10) return "lio";
	if (code.length >= 8) return "emd";
	return "";
}

async function loadPropertyScaleFeatureStats(feature)
{
	const regionCode = getPropertyScaleRegionCode(feature);
	const regionLevel = getPropertyScaleRegionLevelForFeature(feature);
	if (!regionCode || !regionLevel) return { listingCount: 0, brokerCount: 0 };
	const filters = buildPropertyScaleFilters();
	const rows = await fetchPropertyScaleRegionCountRows(regionLevel, filters);
	const row = (Array.isArray(rows) ? rows : []).find((item) => String(item?.region_code || "").trim() === regionCode);
	return {
		listingCount: Math.max(0, Number(row?.listing_count) || 0),
		brokerCount: Math.max(0, Number(row?.broker_count) || 0)
	};
}

async function fetchPropertyScaleRegionFirstPage(regionCode, options = {})
{
	const filters = options.filters && typeof options.filters === "object"
		? options.filters
		: buildPropertyScaleFilters();
	const requestedSort = String(options.sort || getPropertyScaleSortValue()).trim();
	const sort = ["popular", "price-asc", "price-desc", "area-asc", "area-desc", "latest"].includes(requestedSort)
		? requestedSort
		: "latest";
	const cacheKey = `${regionCode}|${sort}|${getPropertyScaleFilterKey(filters)}`;
	const cached = readPropertyScaleCache(propertyScaleRegionFirstPageCache, cacheKey);
	if (cached) return cached;

	const client = await getPropertyScaleClient();
	const rpcName = propertyScaleRegionFastRpcDisabled
		? PROPERTY_SCALE_RPC.legacyRegionFirstPage
		: PROPERTY_SCALE_RPC.regionFirstPage;
	let { data, error } = await client.rpc(rpcName, {
		p_region_code: regionCode,
		p_limit: REGION_LIST_FIRST_PAINT_SIZE,
		p_filters: filters,
		p_sort: sort
	});
	if (error) {
		if (!isMissingRpcError(error)) throw error;

		if (!propertyScaleRegionFastRpcDisabled) {
			propertyScaleRegionFastRpcDisabled = true;
			({ data, error } = await client.rpc(PROPERTY_SCALE_RPC.legacyRegionFirstPage, {
				p_region_code: regionCode,
				p_limit: REGION_LIST_FIRST_PAINT_SIZE,
				p_filters: filters,
				p_sort: sort
			}));
		}

		// 구형 첫 8건 RPC도 없는 환경에서만 기존 30건 RPC를 limit 8로 사용합니다.
		if (error && isMissingRpcError(error)) {
			({ data, error } = await client.rpc(PROPERTY_SCALE_RPC.legacyRegionPage, {
				p_region_code: regionCode,
				p_limit: REGION_LIST_FIRST_PAINT_SIZE,
				p_offset: 0,
				p_filters: filters,
				p_sort: sort
			}));
		}
		if (error) throw error;
	}

	const rows = Array.isArray(data) ? data : [];
	const items = rows.map((row) => mapPropertyListingRowToMapItem(row));
	rememberLeftListDetailItems(items);
	return writePropertyScaleCache(propertyScaleRegionFirstPageCache, cacheKey, {
		items,
		// 첫 8건 전용 RPC는 빠른 첫 화면을 위해 전체 count를 계산하지 않는다.
		// 실제 공개 총건수는 바로 뒤의 22건 페이지 응답에서 동기화한다.
		totalCount: null
	});
}

async function fetchPropertyScaleRegionPage(regionCode, options = {})
{
	const filters = options.filters && typeof options.filters === "object"
		? options.filters
		: buildPropertyScaleFilters();
	const offset = Math.max(0, Number(options.offset) || 0);
	const limit = Math.min(100, Math.max(1, Number(options.limit) || LEFT_LIST_PAGE_SIZE));
	const requestedSort = String(options.sort || getPropertyScaleSortValue()).trim();
	const sort = ["popular", "price-asc", "price-desc", "area-asc", "area-desc", "latest"].includes(requestedSort)
		? requestedSort
		: "latest";
	const cacheKey = `${regionCode}|${offset}|${limit}|${sort}|${getPropertyScaleFilterKey(filters)}`;
	const cached = readPropertyScaleCache(propertyScaleRegionPageCache, cacheKey);
	if (cached) return cached;
	const client = await getPropertyScaleClient();
	const rpcName = propertyScaleRegionFastRpcDisabled
		? PROPERTY_SCALE_RPC.legacyRegionPage
		: PROPERTY_SCALE_RPC.regionPage;
	let { data, error } = await client.rpc(rpcName, {
		p_region_code: regionCode,
		p_limit: limit,
		p_offset: offset,
		p_filters: filters,
		p_sort: sort
	});
	if (error) {
		if (!isMissingRpcError(error) || propertyScaleRegionFastRpcDisabled) throw error;
		propertyScaleRegionFastRpcDisabled = true;
		({ data, error } = await client.rpc(PROPERTY_SCALE_RPC.legacyRegionPage, {
			p_region_code: regionCode,
			p_limit: limit,
			p_offset: offset,
			p_filters: filters,
			p_sort: sort
		}));
		if (error) throw error;
	}
	const rows = Array.isArray(data) ? data : [];
	// 4.985: 지역 인덱스로 선택된 목록용 registrantㆍ썸네일ㆍ가격ㆍ면적만 받습니다.
	// 상세 원본과 최신 중개사 정보는 사용자가 실제 매물을 열 때 한 건만 조회합니다.
	const items = rows.map((row) => mapPropertyListingRowToMapItem(row));
	rememberLeftListDetailItems(items);
	return writePropertyScaleCache(propertyScaleRegionPageCache, cacheKey, {
		items,
		totalCount: rows.length ? Math.max(0, Number(rows[0].total_count) || 0) : Number(options.totalCount) || 0
	});
}

function getPropertyScaleAgentFilterKey(filter)
{
	if (!filter) return "";
	return [
		normalizeItemId(filter.agencyId || filter.agency_id),
		normalizeItemId(filter.userId || filter.user_id),
		normalizeAgentOfficeKey(filter.rawOfficeName || filter.officeName || filter.label || "")
	].join("|");
}

function getPropertyScaleAgentSortValue()
{
	const mode = String(state.agentListSort || "latest");
	if (mode === "popular") return "popular";
	if (mode === "priceAsc") return "price-asc";
	if (mode === "priceDesc") return "price-desc";
	if (mode === "areaAsc") return "area-asc";
	if (mode === "areaDesc") return "area-desc";
	return "latest";
}

function getBrokerOfficeListingCountLookupKeys(office)
{
	const keys = [];
	const addKey = (key) => {
		if (key && !keys.includes(key)) keys.push(key);
	};
	const agencyId = normalizeItemId(office && (office.agencyId || office.agency_id));
	const userId = normalizeItemId(office && (office.userId || office.user_id));
	const officeName = office && (office.officeName || office.office_name || office.rawOfficeName || office.label);
	const officeNameKey = normalizeBrokerSpecialtyOfficeKey(officeName);
	if (agencyId) addKey("agency:" + agencyId);
	if (userId) addKey("user:" + userId);
	if (officeNameKey) addKey("office:" + officeNameKey);
	return keys;
}

function getBrokerOfficeListingCountFromCache(office)
{
	for (const key of getBrokerOfficeListingCountLookupKeys(office)) {
		if (brokerOfficeListingCountCache.has(key)) {
			return Math.max(0, Number(brokerOfficeListingCountCache.get(key)) || 0);
		}
	}
	return null;
}

function cacheBrokerOfficeListingCount(office, count)
{
	const normalizedCount = Math.max(0, Math.trunc(Number(count) || 0));
	getBrokerOfficeListingCountLookupKeys(office).forEach((key) => {
		brokerOfficeListingCountCache.set(key, normalizedCount);
	});
	return normalizedCount;
}

function getPropertyScaleAgentQueryCandidates(filter)
{
	const agencyId = normalizeItemId(filter && (filter.agencyId || filter.agency_id));
	const userId = normalizeItemId(filter && (filter.userId || filter.user_id));
	const officeName = String(filter && (filter.rawOfficeName || filter.officeName || filter.label) || "").trim();
	const candidates = [];
	const candidateKeys = new Set();
	const addCandidate = (candidate) => {
		const key = [candidate.agencyId, candidate.userId, candidate.officeName].join("|");
		if (!key.replace(/\|/g, "") || candidateKeys.has(key)) return;
		candidateKeys.add(key);
		candidates.push(candidate);
	};
	addCandidate({ agencyId, userId, officeName });
	if (userId) addCandidate({ agencyId: "", userId, officeName: "" });
	if (officeName) addCandidate({ agencyId: "", userId: "", officeName });
	return candidates;
}

async function loadBrokerOfficeListingCounts(options = {})
{
	const force = !!options.force;
	const fresh = brokerOfficeListingCountsLoadedAt > 0
		&& Date.now() - brokerOfficeListingCountsLoadedAt < PROPERTY_SCALE_QUERY_CACHE_MS;
	if (!force && fresh) return brokerOfficeListingCountCache;
	if (brokerOfficeListingCountsLoadPromise) return brokerOfficeListingCountsLoadPromise;
	if (brokerOfficeListingCountsRpcAvailable === false) return brokerOfficeListingCountCache;

	const promise = (async () => {
		let client = options.client || getRealjejuSupabaseClient();
		if (!client && typeof loadSupabaseScript === "function") {
			try {
				await loadSupabaseScript();
				client = getRealjejuSupabaseClient();
			} catch (error) {
				console.warn("중개사 공개 매물 수 연결 준비 실패:", error);
			}
		}
		if (!client) return brokerOfficeListingCountCache;
		const { data, error } = await client.rpc(BROKER_OFFICE_LISTING_COUNTS_RPC);
		if (error) {
			if (isMissingRpcError(error)) brokerOfficeListingCountsRpcAvailable = false;
			else console.warn("중개사 공개 매물 수 일괄 조회 실패:", error);
			return brokerOfficeListingCountCache;
		}
		brokerOfficeListingCountsRpcAvailable = true;
		brokerOfficeListingCountCache.clear();
		(Array.isArray(data) ? data : []).forEach((row) => {
			cacheBrokerOfficeListingCount({
				agencyId: row && row.agency_id,
				userId: row && row.user_id,
				officeName: row && row.office_name
			}, row && row.listing_count);
		});
		brokerOfficeListingCountsLoadedAt = Date.now();
		return brokerOfficeListingCountCache;
	})();
	brokerOfficeListingCountsLoadPromise = promise;
	try {
		return await promise;
	} finally {
		if (brokerOfficeListingCountsLoadPromise === promise) brokerOfficeListingCountsLoadPromise = null;
	}
}

async function fetchBrokerOfficeListingCountFromAgentPage(office, options = {})
{
	const filter = buildBrokerOfficeAgentFilter(office);
	if (!filter) return null;
	const cachedCount = getBrokerOfficeListingCountFromCache(filter);
	if (!options.force && cachedCount !== null) return cachedCount;
	const filterKey = getPropertyScaleAgentFilterKey(filter);
	if (!filterKey) return null;
	if (!options.force && brokerOfficeListingCountInflight.has(filterKey)) {
		return brokerOfficeListingCountInflight.get(filterKey);
	}
	const promise = (async () => {
		let client = options.client || getRealjejuSupabaseClient();
		if (!client && typeof loadSupabaseScript === "function") {
			try {
				await loadSupabaseScript();
				client = getRealjejuSupabaseClient();
			} catch (error) {
				console.warn("중개사 공개 매물 수 연결 준비 실패:", error);
			}
		}
		if (!client) return null;
		let rows = [];
		for (const candidate of getPropertyScaleAgentQueryCandidates(filter)) {
			const { data, error } = await client.rpc(PROPERTY_SCALE_RPC.agentPage, {
				p_agency_id: candidate.agencyId,
				p_user_id: candidate.userId,
				p_office_name: candidate.officeName,
				p_limit: 1,
				p_offset: 0,
				p_sort: "latest"
			});
			if (error) throw error;
			rows = Array.isArray(data) ? data : [];
			if (rows.length) break;
		}
		const count = rows.length ? Math.max(0, Number(rows[0].total_count) || 0) : 0;
		cacheBrokerOfficeListingCount(office, count);
		cacheBrokerOfficeListingCount(filter, count);
		brokerOfficeListingCountsLoadedAt = Date.now();
		return count;
	})();
	brokerOfficeListingCountInflight.set(filterKey, promise);
	try {
		return await promise;
	} catch (error) {
		console.warn("중개사 공개 매물 수 개별 조회 실패:", error);
		return null;
	} finally {
		if (brokerOfficeListingCountInflight.get(filterKey) === promise) {
			brokerOfficeListingCountInflight.delete(filterKey);
		}
	}
}

async function loadBrokerOfficeListingCountsForOffices(offices, options = {})
{
	const sourceRows = Array.isArray(offices) ? offices : [];
	if (!sourceRows.length) return true;
	await loadBrokerOfficeListingCounts(options);
	const countCacheStale = brokerOfficeListingCountsLoadedAt <= 0
		|| Date.now() - brokerOfficeListingCountsLoadedAt >= PROPERTY_SCALE_QUERY_CACHE_MS;
	const forceIndividual = brokerOfficeListingCountsRpcAvailable !== true
		&& (!!options.force || countCacheStale);
	const uniqueOffices = new Map();
	sourceRows.forEach((office) => {
		const filter = buildBrokerOfficeAgentFilter(office);
		const key = getPropertyScaleAgentFilterKey(filter);
		if (key && !uniqueOffices.has(key)) uniqueOffices.set(key, office);
	});
	const pending = Array.from(uniqueOffices.values()).filter((office) => {
		return forceIndividual || getBrokerOfficeListingCountFromCache(office) === null;
	});
	let cursor = 0;
	const worker = async () => {
		while (cursor < pending.length) {
			const office = pending[cursor];
			cursor += 1;
			await fetchBrokerOfficeListingCountFromAgentPage(office, {
				client: options.client,
				force: forceIndividual
			});
		}
	};
	const workerCount = Math.min(6, pending.length);
	if (workerCount > 0) {
		await Promise.all(Array.from({ length: workerCount }, () => worker()));
	}
	return sourceRows.every(office => getBrokerOfficeListingCountFromCache(office) !== null);
}

async function fetchPropertyScaleAgentPage(filter, options = {})
{
	const filterKey = getPropertyScaleAgentFilterKey(filter);
	if (!filterKey) return { items: [], totalCount: 0 };
	const offset = Math.max(0, Number(options.offset) || 0);
	const limit = Math.min(100, Math.max(1, Number(options.limit) || LEFT_LIST_PAGE_SIZE));
	const sort = getPropertyScaleAgentSortValue();
	const cacheKey = `${filterKey}|${offset}|${limit}|${sort}`;
	const cached = readPropertyScaleCache(propertyScaleAgentPageCache, cacheKey);
	if (cached) return cached;
	const client = await getPropertyScaleClient();
	const queryCandidates = getPropertyScaleAgentQueryCandidates(filter);

	let rows = [];
	for (const candidate of queryCandidates) {
		const { data, error } = await client.rpc(PROPERTY_SCALE_RPC.agentPage, {
			p_agency_id: candidate.agencyId,
			p_user_id: candidate.userId,
			p_office_name: candidate.officeName,
			p_limit: limit,
			p_offset: offset,
			p_sort: sort
		});
		if (error) throw error;
		rows = Array.isArray(data) ? data : [];
		if (rows.length) break;
	}
	const ownerData = await loadMapListingOwnerData(client, rows);
	const items = rows.map((row) => mapPropertyListingRowToMapItem(
		row,
		ownerData.profilesByUserId,
		ownerData.agenciesById,
		ownerData.agenciesByUserId,
		ownerData.agenciesByOfficeName
	));
	rememberLeftListDetailItems(items);
	const totalCount = rows.length ? Math.max(0, Number(rows[0].total_count) || 0) : Number(options.totalCount) || 0;
	cacheBrokerOfficeListingCount(filter, totalCount);
	brokerOfficeListingCountsLoadedAt = Date.now();
	return writePropertyScaleCache(propertyScaleAgentPageCache, cacheKey, {
		items,
		totalCount
	});
}

function getPropertyScaleViewportBounds()
{
	if (!state.map || typeof state.map.getBounds !== "function") return null;
	const bounds = state.map.getBounds();
	const sw = bounds && bounds.getSouthWest ? bounds.getSouthWest() : null;
	const ne = bounds && bounds.getNorthEast ? bounds.getNorthEast() : null;
	if (!sw || !ne) return null;
	const result = {
		swLat: Number(sw.getLat()),
		swLng: Number(sw.getLng()),
		neLat: Number(ne.getLat()),
		neLng: Number(ne.getLng())
	};
	return Object.values(result).every(Number.isFinite) ? result : null;
}

function expandPropertyScaleViewportBounds(bounds, ratio = PROPERTY_SCALE_CLUSTER_VIEWPORT_BUFFER_RATIO)
{
	if (!bounds) return null;
	const safeRatio = Math.max(0, Number(ratio) || 0);
	const latSpan = Math.max(0, Number(bounds.neLat) - Number(bounds.swLat));
	const lngSpan = Math.max(0, Number(bounds.neLng) - Number(bounds.swLng));
	if (![latSpan, lngSpan].every(Number.isFinite)) return bounds;
	return {
		swLat: Number(bounds.swLat) - (latSpan * safeRatio),
		swLng: Number(bounds.swLng) - (lngSpan * safeRatio),
		neLat: Number(bounds.neLat) + (latSpan * safeRatio),
		neLng: Number(bounds.neLng) + (lngSpan * safeRatio)
	};
}

function doPropertyScaleBoundsContain(outerBounds, innerBounds)
{
	if (!outerBounds || !innerBounds) return false;
	const outer = [outerBounds.swLat, outerBounds.swLng, outerBounds.neLat, outerBounds.neLng].map(Number);
	const inner = [innerBounds.swLat, innerBounds.swLng, innerBounds.neLat, innerBounds.neLng].map(Number);
	if (![...outer, ...inner].every(Number.isFinite)) return false;
	const epsilon = 1e-9;
	return inner[0] >= outer[0] - epsilon
		&& inner[1] >= outer[1] - epsilon
		&& inner[2] <= outer[2] + epsilon
		&& inner[3] <= outer[3] + epsilon;
}

function getPropertyScaleViewportCoverageKey(mode, filters = buildPropertyScaleFilters())
{
	return `${String(mode || "")}|${getPropertyScaleSortValue()}|${getPropertyScaleFilterKey(filters)}`;
}

function getPropertyScaleViewportKey(bounds, filters)
{
	const rounded = [bounds.swLat, bounds.swLng, bounds.neLat, bounds.neLng]
		.map((value) => Number(value).toFixed(4)).join("|");
	return `${rounded}|rows|${getPropertyScaleSortValue()}|${getPropertyScaleFilterKey(filters)}`;
}

async function fetchPropertyScaleViewportRows(options = {})
{
	const visibleBounds = options.bounds || getPropertyScaleViewportBounds();
	if (!visibleBounds) return { items: [], totalCount: 0 };
	const filters = buildPropertyScaleFilters();
	// 한 단계 줌 주변까지 받아 두고, 포함 범위 안에서는 서버 재조회와 마커 재생성을 생략한다.
	const bounds = expandPropertyScaleViewportBounds(visibleBounds);
	const cacheKey = getPropertyScaleViewportKey(bounds, filters);
	const cached = options.force ? null : readPropertyScaleCache(propertyScaleViewportCache, cacheKey);
	if (cached) return cached;
	const inflightRequest = options.force ? null : propertyScaleViewportInflight.get(cacheKey);
	if (inflightRequest) return inflightRequest;

	const requestPromise = (async () => {
		const client = await getPropertyScaleClient();
		const { data, error } = await client.rpc(PROPERTY_SCALE_RPC.viewportRows, {
			p_sw_lat: bounds.swLat,
			p_sw_lng: bounds.swLng,
			p_ne_lat: bounds.neLat,
			p_ne_lng: bounds.neLng,
			p_limit: PROPERTY_SCALE_VIEWPORT_LIMIT,
			p_offset: 0,
			p_filters: filters,
			// RPC 시그니처 호환용 값입니다. 실제 지도 묶음은 카카오 MarkerClusterer만 담당합니다.
			p_cluster: false,
			p_grid_lat: 0.001,
			p_grid_lng: 0.0012,
			p_sort: getPropertyScaleSortValue()
		});
		if (error) throw error;
		const rows = Array.isArray(data) ? data : [];
		const items = rows.map((row) => mapPropertyListingMarkerRowToMapItem(row));
		return writePropertyScaleCache(propertyScaleViewportCache, cacheKey, {
			items,
			totalCount: rows.length ? Math.max(0, Number(rows[0].total_count) || 0) : 0,
			coverageBounds: { ...bounds }
		});
	})();
	propertyScaleViewportInflight.set(cacheKey, requestPromise);
	try {
		return await requestPromise;
	} finally {
		if (propertyScaleViewportInflight.get(cacheKey) === requestPromise) {
			propertyScaleViewportInflight.delete(cacheKey);
		}
	}
}

function preferCachedAgency(current, next)
{
	if (!current) return next;
	if (!next) return current;
	if (current.status !== "active" && next.status === "active") return next;
	if (current.status === "active" && next.status !== "active") return current;
	const currentTime = Date.parse(current.updated_at || current.created_at || "") || 0;
	const nextTime = Date.parse(next.updated_at || next.created_at || "") || 0;
	return nextTime >= currentTime ? next : current;
}

function cacheMapListingProfile(profile)
{
	if (!profile || typeof profile !== "object") return null;
	const key = getViewCountKey(profile.id);
	if (!key) return null;
	mapListingOwnerCache.profilesByUserId.set(key, profile);
	return profile;
}

function cacheMapListingAgency(agency)
{
	if (!agency || typeof agency !== "object") return null;
	const idKey = getViewCountKey(agency.id);
	const userKey = getViewCountKey(agency.user_id);
	const officeKey = String(agency.office_name || "").trim();
	if (idKey) {
		const next = preferCachedAgency(mapListingOwnerCache.agenciesById.get(idKey), agency);
		mapListingOwnerCache.agenciesById.set(idKey, next);
	}
	if (userKey) {
		const next = preferCachedAgency(mapListingOwnerCache.agenciesByUserId.get(userKey), agency);
		mapListingOwnerCache.agenciesByUserId.set(userKey, next);
	}
	if (officeKey) {
		const next = preferCachedAgency(mapListingOwnerCache.agenciesByOfficeName.get(officeKey), agency);
		mapListingOwnerCache.agenciesByOfficeName.set(officeKey, next);
	}
	return agency;
}

function getMapListingOwnerFetchKey(value)
{
	return String(value || "").trim();
}

function getUniqueMapListingOwnerFetchKeys(values)
{
	return [...new Set((values || []).map(getMapListingOwnerFetchKey).filter(Boolean))];
}

function isMapListingOwnerMissingCached(missingMap, key)
{
	const cachedAt = Number(missingMap && missingMap.get(key) || 0);
	return !!cachedAt && Date.now() - cachedAt < MAP_LISTING_OWNER_MISSING_CACHE_MS;
}

function rememberMapListingOwnerMissing(missingMap, key)
{
	if (missingMap && key) missingMap.set(key, Date.now());
}

async function fetchMapListingOwnerRowsByKeys(client, options)
{
	if (!client || !options) return [];
	const keys = getUniqueMapListingOwnerFetchKeys(options.keys);
	if (!keys.length) return [];
	const cacheMap = options.cacheMap;
	const inflightMap = options.inflightMap;
	const missingMap = options.missingMap;
	const rows = [];
	const keysToFetch = [];
	const pendingPromises = [];
	const pendingPromiseSet = new Set();

	keys.forEach(key => {
		const cached = cacheMap && cacheMap.get(key);
		if (cached) {
			rows.push(cached);
			return;
		}
		if (isMapListingOwnerMissingCached(missingMap, key)) return;
		const pending = inflightMap && inflightMap.get(key);
		if (pending) {
			if (!pendingPromiseSet.has(pending)) {
				pendingPromiseSet.add(pending);
				pendingPromises.push(pending);
			}
			return;
		}
		keysToFetch.push(key);
	});

	if (keysToFetch.length) {
		const fetchPromise = (async () => {
			const fetchedRows = await options.fetchRows(keysToFetch);
			const foundKeys = new Set();
			const storedRows = [];
			(Array.isArray(fetchedRows) ? fetchedRows : []).forEach(row => {
				const stored = typeof options.rememberRow === "function" ? (options.rememberRow(row) || row) : row;
				if (!stored) return;
				storedRows.push(stored);
				const rowKeys = typeof options.getRowKeys === "function" ? options.getRowKeys(stored) : [];
				getUniqueMapListingOwnerFetchKeys(rowKeys).forEach(rowKey => foundKeys.add(rowKey));
			});
			keysToFetch.forEach(key => {
				if (!foundKeys.has(key)) rememberMapListingOwnerMissing(missingMap, key);
			});
			return storedRows;
		})().finally(() => {
			keysToFetch.forEach(key => {
				if (inflightMap) inflightMap.delete(key);
			});
		});
		keysToFetch.forEach(key => {
			if (inflightMap) inflightMap.set(key, fetchPromise);
		});
		pendingPromises.push(fetchPromise);
	}

	if (pendingPromises.length) {
		const settled = await Promise.allSettled(pendingPromises);
		let firstError = null;
		settled.forEach(result => {
			if (result.status !== "fulfilled") {
				if (!firstError) firstError = result.reason;
				return;
			}
			(Array.isArray(result.value) ? result.value : []).forEach(row => {
				if (row) rows.push(row);
			});
		});
		if (firstError && !rows.length) throw firstError;
	}

	return rows;
}

async function fetchPublicBrokerProfileRowsByUserIds(client, userIds)
{
	const ids = getUniqueMapListingOwnerFetchKeys(userIds);
	if (!client || !ids.length) return [];

	const profileByUserId = new Map();
	const { data: profileRows, error: profileError } = await client
		.from("profiles")
		.select("id, name, phone, profile_image, role_request")
		.in("id", ids);
	if (profileError) {
		// 공개 상세 화면에서는 profiles RLS가 사진 표시를 막더라도 카드 전체를 실패시키지 않는다.
		console.warn("공개 중개사 프로필 직접 조회 실패, 공개 사진 복제본으로 보강합니다:", profileError);
	} else {
		(Array.isArray(profileRows) ? profileRows : []).forEach((profile) => {
			const userId = String(profile && profile.id || "").trim();
			if (userId) profileByUserId.set(userId, profile);
		});
	}

	const userIdsMissingImage = ids.filter((userId) => {
		const profile = profileByUserId.get(userId);
		return !String(profile && profile.profile_image || "").trim();
	});
	if (userIdsMissingImage.length) {
		// 프로필 저장 시 함께 동기화되는 공개용 사진 복제본만 선택된 중개사 ID 범위로 조회한다.
		// 전체 중개사 목록을 내려받지 않으며 profiles와 공개 복제본 모두 없을 때만 기본 아이콘을 사용한다.
		const { data: locationRows, error: locationError } = await client
			.from("broker_office_locations")
			.select("user_id,broker_name,phone,profile_image,updated_at")
			.in("user_id", userIdsMissingImage)
			.order("updated_at", { ascending: false });
		if (locationError) {
			console.warn("공개 중개사 프로필 사진 복제본 조회 실패:", locationError);
		} else {
			(Array.isArray(locationRows) ? locationRows : []).forEach((location) => {
				const userId = String(location && location.user_id || "").trim();
				const profileImage = String(location && location.profile_image || "").trim();
				if (!userId || !profileImage) return;
				const current = profileByUserId.get(userId) || {};
				if (String(current.profile_image || "").trim()) return;
				profileByUserId.set(userId, {
					...current,
					id: userId,
					name: String(current.name || location.broker_name || "").trim(),
					phone: String(current.phone || location.phone || "").trim(),
					profile_image: profileImage,
					role_request: current.role_request || "broker"
				});
			});
		}
	}

	return Array.from(profileByUserId.values());
}

