function normalizeBrokerOfficeRegNo(value)
{
	const text = String(value || "").trim();
	if (/^\d{5}-\d{4}-\d{5}$/.test(text)) return text;
	if (!/^\d{14}$/.test(text)) return text;
	return `${text.slice(0, 5)}-${text.slice(5, 9)}-${text.slice(9, 14)}`;
}

