function isPickaxeModeEntryConditionMet()
{
	const map = document.getElementById("map");
	const mapRect = map ? map.getBoundingClientRect() : null;
	const isMapVisible = !!(mapRect && mapRect.width > 0 && mapRect.height > 0);
	const category = document.body && document.body.dataset
		? String(document.body.dataset.globalCategory || "realestate")
		: "realestate";
	const isRealestate = typeof isGlobalRealestateCategory === "function"
		? isGlobalRealestateCategory(category)
		: category === "realestate";
	return isMapVisible
		&& !document.body.classList.contains("main-landing-page-open")
		&& isRealestate
		&& currentMapTypeMode === "satellite"
		&& state.isPropertyMarkersVisible === false
		&& selectedLandTypeFilter instanceof Set
		&& selectedLandTypeFilter.size === 1
		&& selectedLandTypeFilter.has("광천지");
}

function positionPickaxeModeHud()
{
	const hud = getPickaxeModeHud();
	const map = document.getElementById("map");
	if (!map) return;
	const mapRect = map.getBoundingClientRect();
	const panelRight = typeof getMapFilterVisiblePanelRightEdge === "function"
		? getMapFilterVisiblePanelRightEdge()
		: mapRect.left;
	const visibleLeft = Math.max(mapRect.left, Math.min(mapRect.right - 80, panelRight));
	const visibleRight = Math.max(visibleLeft + 80, mapRect.right);
	const visibleCenterLeft = Math.round(visibleLeft + ((visibleRight - visibleLeft) / 2));
	if (hud && !hud.hidden) hud.style.left = `${visibleCenterLeft}px`;
	const centerMessage = getPickaxeModeCenterMessage();
	if (centerMessage && !centerMessage.hidden) {
		centerMessage.style.left = `${visibleCenterLeft}px`;
		centerMessage.style.top = `${Math.round(mapRect.top + (mapRect.height / 2))}px`;
	}
}

function setPickaxeRemainingCount(remaining, options = {})
{
	const count = getPickaxeModeCount();
	const hud = getPickaxeModeHud();
	const hasRemainingValue = remaining !== null
		&& remaining !== undefined
		&& String(remaining).trim() !== "";
	const numericRemaining = hasRemainingValue ? Number(remaining) : Number.NaN;
	pickaxeRemainingCount = Number.isFinite(numericRemaining)
		? Math.max(0, Math.min(PICKAXE_DAILY_LIMIT, Math.trunc(numericRemaining)))
		: null;
	if (count) {
		count.textContent = options.loginRequired === true
			? "로그인"
			: (pickaxeRemainingCount === null ? `--/${PICKAXE_DAILY_LIMIT}` : `${pickaxeRemainingCount}/${PICKAXE_DAILY_LIMIT}`);
	}
	if (hud) hud.classList.toggle("is-empty", pickaxeRemainingCount === 0);
}

function clearPickaxeHudMessage()
{
	if (pickaxeHudMessageTimer) clearTimeout(pickaxeHudMessageTimer);
	pickaxeHudMessageTimer = 0;
	const hud = getPickaxeModeHud();
	if (!hud) return;
	hud.classList.remove("has-message");
	hud.removeAttribute("data-message");
}

function clearPickaxeCenterMessage()
{
	if (pickaxeCenterMessageTimer) clearTimeout(pickaxeCenterMessageTimer);
	pickaxeCenterMessageTimer = 0;
	const message = getPickaxeModeCenterMessage();
	if (!message) return;
	message.hidden = true;
	message.textContent = "";
}

function showPickaxeCenterMessage(text, duration = 1800)
{
	const message = getPickaxeModeCenterMessage();
	if (!message || !isPickaxeModeActive) return;
	clearPickaxeCenterMessage();
	message.textContent = String(text || "");
	message.hidden = false;
	positionPickaxeModeHud();
	pickaxeCenterMessageTimer = window.setTimeout(clearPickaxeCenterMessage, Math.max(800, Number(duration) || 1800));
}

function getPickaxeSupabaseClient()
{
	return typeof window.getRealjejuSupabaseClient === "function"
		? window.getRealjejuSupabaseClient()
		: null;
}

function getMillisecondsUntilNextKoreanDay()
{
	const dayMs = 24 * 60 * 60 * 1000;
	const koreaOffsetMs = 9 * 60 * 60 * 1000;
	const now = Date.now();
	const nextKoreanMidnightUtc = (Math.floor((now + koreaOffsetMs) / dayMs) + 1) * dayMs - koreaOffsetMs;
	return Math.max(1000, nextKoreanMidnightUtc - now + 250);
}

function schedulePickaxeDailyRefresh()
{
	if (pickaxeDailyRefreshTimer) clearTimeout(pickaxeDailyRefreshTimer);
	pickaxeDailyRefreshTimer = 0;
	if (!isPickaxeModeActive) return;
	pickaxeDailyRefreshTimer = window.setTimeout(async () => {
		pickaxeDailyRefreshTimer = 0;
		if (isPickaxeModeActive) await refreshPickaxeStatus({ force: true });
		schedulePickaxeDailyRefresh();
	}, getMillisecondsUntilNextKoreanDay());
}

async function getPickaxeSessionUser(client)
{
	const cached = window.realjejuCurrentAuthUser || null;
	if (cached && cached.id) return cached;
	if (!client || !client.auth || typeof client.auth.getUser !== "function") return null;
	const { data, error } = await client.auth.getUser();
	if (error) return null;
	return data && data.user ? data.user : null;
}

async function refreshPickaxeStatus(options = {})
{
	if (!isPickaxeModeActive) return null;
	const sequence = ++pickaxeStatusLoadSequence;
	const client = getPickaxeSupabaseClient();
	const user = await getPickaxeSessionUser(client);
	if (sequence !== pickaxeStatusLoadSequence || !isPickaxeModeActive) return null;
	if (!user || !user.id) {
		setPickaxeRemainingCount(null, { loginRequired: true });
		return null;
	}
	if (!client) {
		setPickaxeRemainingCount(null);
		return null;
	}
	try {
		const { data, error } = await client.rpc("get_my_map_pickaxe_status_5190");
		if (error) throw error;
		if (sequence !== pickaxeStatusLoadSequence || !isPickaxeModeActive) return null;
		setPickaxeRemainingCount(data && data.remaining);
		return data || null;
	} catch (error) {
		if (options.silent !== true) console.error("곡괭이 상태 조회 실패:", error);
		if (sequence === pickaxeStatusLoadSequence) setPickaxeRemainingCount(null);
		return null;
	}
}

function syncPickaxeMode()
{
	const shouldActivate = isPickaxeModeEntryConditionMet();
	const hud = getPickaxeModeHud();
	if (shouldActivate === isPickaxeModeActive) {
		if (hud) hud.hidden = !shouldActivate;
		if (shouldActivate) positionPickaxeModeHud();
		return;
	}
	isPickaxeModeActive = shouldActivate;
	document.body.classList.toggle("pickaxe-mode-active", shouldActivate);
	if (hud) hud.hidden = !shouldActivate;
	clearPickaxeHudMessage();
	clearPickaxeCenterMessage();
	if (!shouldActivate) {
		pickaxeStatusLoadSequence += 1;
		pickaxeDigInProgress = false;
		pickaxeRemainingCount = null;
		if (pickaxeDailyRefreshTimer) clearTimeout(pickaxeDailyRefreshTimer);
		pickaxeDailyRefreshTimer = 0;
		return;
	}
	setPickaxeRemainingCount(null);
	positionPickaxeModeHud();
	void refreshPickaxeStatus();
	schedulePickaxeDailyRefresh();
}

async function handlePickaxeMapClick(mouseEvent)
{
	if (!isPickaxeModeActive) return false;
	if (typeof kakao !== "undefined" && kakao.maps && kakao.maps.event && typeof kakao.maps.event.preventMap === "function") {
		kakao.maps.event.preventMap();
	}
	if (pickaxeDigInProgress) return true;
	const client = getPickaxeSupabaseClient();
	const user = await getPickaxeSessionUser(client);
	if (!user || !user.id) {
		if (typeof openAuthErrorModal === "function") {
			openAuthErrorModal(
				"로그인 후 곡괭이를 사용할 수 있습니다.",
				"곡괭이",
				null,
				typeof openAuthModal === "function" ? openAuthModal : null
			);
		}
		setPickaxeRemainingCount(null, { loginRequired: true });
		return true;
	}
	if (!client) {
		if (typeof openAuthErrorModal === "function") openAuthErrorModal("Supabase 연결 설정을 확인하세요.", "곡괭이", null);
		return true;
	}
	if (pickaxeRemainingCount === 0) {
		showPickaxeCenterMessage("오늘 사용할 곡괭이를 모두 사용했습니다.", 2400);
		return true;
	}
	if (!mouseEvent || !mouseEvent.latLng) return true;
	pickaxeDigInProgress = true;
	try {
		const { data, error } = await client.rpc("dig_map_treasure_5190", {
			p_latitude: mouseEvent.latLng.getLat(),
			p_longitude: mouseEvent.latLng.getLng()
		});
		if (error) throw error;
		const result = data && typeof data === "object" ? data : {};
		setPickaxeRemainingCount(result.remaining);
		if (result.status === "won") {
			if (typeof window.refreshRealjejuPaymentPlanState === "function") {
				void window.refreshRealjejuPaymentPlanState({ force: true });
			}
			if (typeof openAuthErrorModal === "function") {
				openAuthErrorModal("오늘 날짜 갱신권 10건 쿠폰이 쿠폰함에 지급되었습니다.", "보물 발견", null);
			}
		} else if (result.status === "already_claimed") {
			showPickaxeCenterMessage("이미 발견한 보물입니다.", 2400);
		} else if (result.status === "depleted") {
			showPickaxeCenterMessage("오늘 사용할 곡괭이를 모두 사용했습니다.", 2400);
		} else {
			showPickaxeCenterMessage("아무것도 발견하지 못했습니다.");
		}
	} catch (error) {
		console.error("곡괭이 사용 실패:", error);
		if (typeof openAuthErrorModal === "function") {
			openAuthErrorModal("곡괭이 기능을 불러오지 못했습니다.\nsql/pickaxe_treasure_5.190/01_pickaxe_treasure_5.190.sql 적용 상태를 확인하세요.", "곡괭이", null);
		}
	} finally {
		pickaxeDigInProgress = false;
	}
	return true;
}

