function normalizeParcelLandCharacteristicsPayload(value)
{
	if (!value || typeof value !== "object") return null;
	const areaM2 = Number(value.areaM2);
	const publishedLandPrice = Number(value.publishedLandPrice);
	return {
		pnu: String(value.pnu || "").trim(),
		legalDongName: String(value.legalDongName || "").trim(),
		jibun: String(value.jibun || "").trim(),
		jimok: String(value.jimok || "").trim(),
		areaM2: Number.isFinite(areaM2) ? areaM2 : null,
		landUseZone: String(value.landUseZone || "").trim(),
		landUseSituation: String(value.landUseSituation || "").trim(),
		terrainHeight: String(value.terrainHeight || "").trim(),
		terrainShape: String(value.terrainShape || "").trim(),
		roadSide: String(value.roadSide || "").trim(),
		publishedLandPrice: Number.isFinite(publishedLandPrice) ? publishedLandPrice : null,
		standardYear: String(value.standardYear || "").trim(),
		standardMonth: String(value.standardMonth || "").trim(),
		lastUpdatedAt: String(value.lastUpdatedAt || "").trim()
	};
}

function getParcelBoundaryApiConfig()
{
	const runtimeConfig = typeof window !== "undefined" && window.realjejuParcelBoundaryConfig
		? window.realjejuParcelBoundaryConfig
		: null;
	const isLocalStaticPreview = typeof window !== "undefined"
		&& (window.location.hostname === "localhost" || window.location.hostname === "127.0.0.1")
		&& window.location.port === "5500";
	const defaultEndpoint = isLocalStaticPreview
		? "http://localhost:5500/api/parcel-boundary-by-point"
		: PARCEL_BOUNDARY_ENDPOINT;
	const endpoint = runtimeConfig && typeof runtimeConfig.endpoint === "string"
		? runtimeConfig.endpoint.trim()
		: defaultEndpoint;
	const rawEndpoint = String(endpoint || "").trim();
	const normalizedEndpoint = /^(https?:\/\/)(localhost|127\.0\.0\.1):\d+/i.test(rawEndpoint)
		? rawEndpoint.replace(/^(https?:\/\/)(localhost|127\.0\.0\.1):\d+/i, `${window.location.protocol}//localhost:5500`)
		: rawEndpoint;
	return {
		url: normalizedEndpoint,
		enableLogging: !!(runtimeConfig && runtimeConfig.enableLogging),
		query: runtimeConfig && typeof runtimeConfig.query === "object" && runtimeConfig.query ? runtimeConfig.query : {}
	};
}

async function parseParcelBoundaryApiResponse(response)
{
	const contentType = String(response && response.headers ? response.headers.get("content-type") || "" : "").toLowerCase();
	const responseText = await response.text();
	let payload = null;
	try {
		payload = responseText ? JSON.parse(responseText) : null;
	} catch (error) {
		const looksLikeHtml = contentType.includes("text/html") || /^\s*</.test(responseText);
		if (looksLikeHtml) {
			throw new Error("필지 경계 API가 배포되지 않았거나 정적 서버가 HTML을 반환했습니다.");
		}
		throw new Error("필지 경계 API 응답이 올바른 JSON 형식이 아닙니다.");
	}
	if (!response.ok) {
		const responseCode = payload && payload.code ? String(payload.code) : `HTTP_${response.status}`;
		throw new Error(`필지 경계 조회 실패: ${responseCode}`);
	}
	return payload;
}

function buildParcelBoundaryPointKey(lat, lng)
{
	const sanitizedLat = Number(lat);
	const sanitizedLng = Number(lng);
	if (!Number.isFinite(sanitizedLat) || !Number.isFinite(sanitizedLng)) return "";
	return `${sanitizedLng.toFixed(PARCEL_BOUNDARY_COORD_PRECISION)},${sanitizedLat.toFixed(PARCEL_BOUNDARY_COORD_PRECISION)}`;
}

function isParcelBoundaryJejuCoordinate(lat, lng)
{
	const latNum = Number(lat);
	const lngNum = Number(lng);
	return Number.isFinite(latNum)
		&& Number.isFinite(lngNum)
		&& latNum >= PARCEL_BOUNDARY_JEJU_QUERY_BOUNDS.minLat
		&& latNum <= PARCEL_BOUNDARY_JEJU_QUERY_BOUNDS.maxLat
		&& lngNum >= PARCEL_BOUNDARY_JEJU_QUERY_BOUNDS.minLng
		&& lngNum <= PARCEL_BOUNDARY_JEJU_QUERY_BOUNDS.maxLng;
}

function clampParcelBoundaryCalibrationValue(value, min, max, fallback)
{
	const number = Number(value);
	return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
}

function getParcelBoundaryDisplayCalibration()
{
	const runtimeCalibration = typeof window !== "undefined"
		&& window.realjejuParcelBoundaryDisplayCalibration
		&& typeof window.realjejuParcelBoundaryDisplayCalibration === "object"
		? window.realjejuParcelBoundaryDisplayCalibration
		: {};
	return {
		scale: clampParcelBoundaryCalibrationValue(
			runtimeCalibration.scale,
			0.96,
			1.06,
			PARCEL_BOUNDARY_DISPLAY_CALIBRATION_DEFAULT.scale
		),
		rotationDeg: clampParcelBoundaryCalibrationValue(
			runtimeCalibration.rotationDeg,
			-3,
			3,
			PARCEL_BOUNDARY_DISPLAY_CALIBRATION_DEFAULT.rotationDeg
		),
		offsetEastMeters: clampParcelBoundaryCalibrationValue(
			runtimeCalibration.offsetEastMeters,
			-20,
			20,
			PARCEL_BOUNDARY_DISPLAY_CALIBRATION_DEFAULT.offsetEastMeters
		),
		offsetNorthMeters: clampParcelBoundaryCalibrationValue(
			runtimeCalibration.offsetNorthMeters,
			-20,
			20,
			PARCEL_BOUNDARY_DISPLAY_CALIBRATION_DEFAULT.offsetNorthMeters
		)
	};
}

function getParcelBoundaryDisplayCenter(paths)
{
	let latitudeSum = 0;
	let longitudeSum = 0;
	let pointCount = 0;
	(Array.isArray(paths) ? paths : []).forEach((path) => {
		if (!Array.isArray(path)) return;
		path.forEach((latLng, index) => {
			if (!latLng || typeof latLng.getLat !== "function" || typeof latLng.getLng !== "function") return;
			if (
				index === path.length - 1
				&& path.length > 3
				&& path[0]
				&& typeof path[0].getLat === "function"
				&& Math.abs(latLng.getLat() - path[0].getLat()) < 1e-12
				&& Math.abs(latLng.getLng() - path[0].getLng()) < 1e-12
			) return;
			latitudeSum += Number(latLng.getLat());
			longitudeSum += Number(latLng.getLng());
			pointCount += 1;
		});
	});
	if (!pointCount) return null;
	return {
		lat: latitudeSum / pointCount,
		lng: longitudeSum / pointCount
	};
}

function buildParcelBoundaryDisplayPaths(paths, calibration)
{
	const sourcePaths = Array.isArray(paths) ? paths : [];
	const center = getParcelBoundaryDisplayCenter(sourcePaths);
	if (!center) return sourcePaths;
	const resolved = calibration || getParcelBoundaryDisplayCalibration();
	const radians = resolved.rotationDeg * Math.PI / 180;
	const rotationCos = Math.cos(radians);
	const rotationSin = Math.sin(radians);
	const metersPerLatitudeDegree = 110574;
	const metersPerLongitudeDegree = Math.max(1, 111320 * Math.cos(center.lat * Math.PI / 180));

	return sourcePaths.map((path) => path.map((latLng) => {
		if (!latLng || typeof latLng.getLat !== "function" || typeof latLng.getLng !== "function") return latLng;
		const eastMeters = (Number(latLng.getLng()) - center.lng) * metersPerLongitudeDegree;
		const northMeters = (Number(latLng.getLat()) - center.lat) * metersPerLatitudeDegree;
		const scaledEastMeters = eastMeters * resolved.scale;
		const scaledNorthMeters = northMeters * resolved.scale;
		const rotatedEastMeters = scaledEastMeters * rotationCos - scaledNorthMeters * rotationSin;
		const rotatedNorthMeters = scaledEastMeters * rotationSin + scaledNorthMeters * rotationCos;
		return new kakao.maps.LatLng(
			center.lat + (rotatedNorthMeters + resolved.offsetNorthMeters) / metersPerLatitudeDegree,
			center.lng + (rotatedEastMeters + resolved.offsetEastMeters) / metersPerLongitudeDegree
		);
	}));
}

function toLatLngListFromRing(ring)
{
	if (!Array.isArray(ring)) return [];
	return ring
		.map((point) => Array.isArray(point) ? new kakao.maps.LatLng(Number(point[1]), Number(point[0])) : null)
		.filter(Boolean);
}

function toLatLngPathGroupsFromGeometry(geometry)
{
	if (!geometry || !Array.isArray(geometry.coordinates)) return [];
	if (geometry.type === "Polygon") {
		const group = geometry.coordinates
			.map(toLatLngListFromRing)
			.filter((path) => Array.isArray(path) && path.length >= 3);
		return group.length ? [group] : [];
	}
	if (geometry.type === "MultiPolygon") {
		return geometry.coordinates
			.filter(Array.isArray)
			.map((polygon) => polygon
				.map(toLatLngListFromRing)
				.filter((path) => Array.isArray(path) && path.length >= 3))
			.filter((group) => group.length);
	}
	return [];
}

function normalizeParcelDisplayJibun(value)
{
	return String(value || "").trim().replace(/(\d)\s*[가-힣]+$/u, "$1").trim();
}

function normalizeParcelBoundaryPayload(payload)
{
	if (!payload || typeof payload !== "object") return null;
	const geometry = payload.geometry
		|| (payload.feature && payload.feature.geometry)
		|| payload.polygon
		|| payload.data;
	if (!geometry) return null;
	const pathGroups = toLatLngPathGroupsFromGeometry(geometry);
	const paths = pathGroups.flat();
	if (!paths.length) return null;

	const landCharacteristics = normalizeParcelLandCharacteristicsPayload(payload.landCharacteristics);
	const landPossession = payload.landPossession && typeof payload.landPossession === "object"
		? payload.landPossession
		: null;
	const explicitAreaValue = [payload.area_m2, payload.areaM2, payload.area, payload.pnuArea, payload.areaPy, payload.area_py, landCharacteristics && landCharacteristics.areaM2]
		.find((value) => value !== null && value !== undefined && value !== "" && Number.isFinite(Number(value)));
	const geometryAreaValue = (() => {
		const geometry = payload.geometry;
		if (!geometry || !Array.isArray(geometry.coordinates)) return null;
		const polygons = geometry.type === "Polygon" ? [geometry.coordinates] : (geometry.type === "MultiPolygon" ? geometry.coordinates : []);
		if (!polygons.length) return null;
		const earthRadius = 6378137;
		const toRadians = (value) => Number(value) * Math.PI / 180;
		const ringArea = (ring) => {
			if (!Array.isArray(ring) || ring.length < 3) return 0;
			let area = 0;
			for (let index = 0; index < ring.length; index += 1) {
				const current = ring[index];
				const next = ring[(index + 1) % ring.length];
				if (!Array.isArray(current) || !Array.isArray(next)) continue;
				area += (toRadians(next[0]) - toRadians(current[0]))
					* (2 + Math.sin(toRadians(current[1])) + Math.sin(toRadians(next[1])));
			}
			return Math.abs(area * earthRadius * earthRadius / 2);
		};
		const areaM2 = polygons.reduce((total, polygon) => {
			if (!Array.isArray(polygon) || !polygon.length) return total;
			const outerArea = ringArea(polygon[0]);
			const holeArea = polygon.slice(1).reduce((sum, ring) => sum + ringArea(ring), 0);
			return total + Math.max(0, outerArea - holeArea);
		}, 0);
		return Number.isFinite(areaM2) && areaM2 > 0 ? areaM2 : null;
	})();
	const areaValue = explicitAreaValue !== undefined ? Number(explicitAreaValue) : geometryAreaValue;
	const pnu = String(payload.pnu || payload.PNU || payload.parcel_pnu || payload.id || (landCharacteristics && landCharacteristics.pnu) || "").trim();
	const landUseZone = String(
		payload.land_use_zone
		|| payload.landUseZone
		|| payload.landUse
		|| payload.land
		|| payload["용도지역"]
		|| (landCharacteristics && landCharacteristics.landUseZone)
		|| ""
	).trim();
	const purpose = String(payload.land_use_purpose || payload.use || payload.purpose || payload["용도"] || (landCharacteristics && landCharacteristics.landUseSituation) || "").trim();
	const properties = payload.properties && typeof payload.properties === "object" ? payload.properties : {};

	
  const landUsePlanSource = Array.isArray(payload?.landUsePlan)
    ? payload.landUsePlan
    : (Array.isArray(properties?.landUsePlan) ? properties.landUsePlan : []);
  const landUsePlan = landUsePlanSource.map((item) => {
    const relationCode = String(item?.relationCode || item?.cnflcAt || "").trim();
    const rawRelation = String(item?.relation || item?.cnflcAtNm || "").trim();
    const relationByCode = { "1": "포함", "2": "저촉", "3": "접합" };
    return {
      ...item,
      relationCode,
      relation: relationByCode[relationCode] || (rawRelation === "접함" ? "접합" : rawRelation)
    };
  });
  const primaryLandUseZoneNames = new Set([
    "제1종전용주거지역", "제2종전용주거지역", "제1종일반주거지역", "제2종일반주거지역",
    "제3종일반주거지역", "준주거지역", "중심상업지역", "일반상업지역", "근린상업지역",
    "유통상업지역", "전용공업지역", "일반공업지역", "준공업지역", "보전녹지지역",
    "생산녹지지역", "자연녹지지역", "보전관리지역", "생산관리지역", "계획관리지역",
    "자연환경보전지역", "농림지역"
  ]);
  const isPrimaryLandUseZoneName = (value) => primaryLandUseZoneNames.has(
    String(value || "").replace(/\s+/g, "").replace(/\([^)]*\)$/g, "").trim()
  );
  const includedPrimaryLandUseZone = landUsePlan.find((item) => (
    item
    && item.relation === "포함"
    && isPrimaryLandUseZoneName(item.districtName || item.zoneName || item.prposAreaDstrcCodeNm)
  ));
  const landCharacteristicsZone = String(landCharacteristics && landCharacteristics.landUseZone || "").trim();
  const representativeLandUseZone = String(
    (includedPrimaryLandUseZone && (includedPrimaryLandUseZone.districtName || includedPrimaryLandUseZone.zoneName || includedPrimaryLandUseZone.prposAreaDstrcCodeNm))
    || (isPrimaryLandUseZoneName(landCharacteristicsZone) ? landCharacteristicsZone : "")
    || landUseZone
  ).trim();
  const landUsePlanStatus = typeof payload?.landUsePlanStatus === "string" ? payload.landUsePlanStatus : "not-found";
  const landMovesSource = Array.isArray(payload?.landMoves)
    ? payload.landMoves
    : (Array.isArray(properties?.landMoves) ? properties.landMoves : []);
  const landMoves = landMovesSource.map((item) => ({
    movedAt: String(item?.movedAt || item?.ladMvmnDe || "").trim(),
    reason: String(item?.reason || item?.ladMvmnPrvonshCodeNm || "").trim(),
    reasonCode: String(item?.reasonCode || item?.ladMvmnPrvonshCode || "").trim(),
    areaM2: Number.isFinite(Number(item?.areaM2 ?? item?.lndpclAr)) ? Number(item?.areaM2 ?? item?.lndpclAr) : null,
    jimok: String(item?.jimok || item?.lndcgrCodeNm || "").trim()
  })).filter((item) => item.movedAt || item.reason)
    .sort((left, right) => right.movedAt.localeCompare(left.movedAt));
  const landMovesStatus = typeof payload?.landMovesStatus === "string" ? payload.landMovesStatus : "not-found";
  const individualLandPrices = Array.isArray(payload?.individualLandPrices) ? payload.individualLandPrices : [];
  const individualLandPricesStatus = typeof payload?.individualLandPricesStatus === "string" ? payload.individualLandPricesStatus : "not-found";
  const individualHousingPrices = Array.isArray(payload?.individualHousingPrices) ? payload.individualHousingPrices : [];
  const individualHousingPricesStatus = typeof payload?.individualHousingPricesStatus === "string" ? payload.individualHousingPricesStatus : "not-found";
return {
		pnu,
		areaM2: Number.isFinite(areaValue) ? areaValue : null,
		landUseZone: representativeLandUseZone,
		use: purpose,
		address: normalizeParcelDisplayJibun(payload.address),
		jibun: normalizeParcelDisplayJibun(payload.jibun || properties.jibun),
		jimok: String(payload.jimok || properties.jimok || (landCharacteristics && landCharacteristics.jimok) || "").trim(),
		landCharacteristics,
		landCharacteristicsStatus: String(payload.landCharacteristicsStatus || "").trim(),
		landPossession,
		landPossessionStatus: String(payload.landPossessionStatus || "").trim(),
		landUsePlan,
		landUsePlanStatus,
		landMoves,
		landMovesStatus,
		individualLandPrices,
		individualLandPricesStatus,
		individualHousingPrices,
		individualHousingPricesStatus,
		propertyInformationAvailable: payload.propertyInformationAvailable === true,
		apiCapabilities: payload.apiCapabilities && typeof payload.apiCapabilities === "object"
			? {
				priceOnly: payload.apiCapabilities.priceOnly === true,
				roadContactBounds: payload.apiCapabilities.roadContactBounds === true
			}
			: {},
		pathGroups,
		paths
	};
}

function cancelParcelBoundaryLookup()
{
	if (parcelBoundaryAbortController) {
		parcelBoundaryAbortController.abort();
		parcelBoundaryAbortController = null;
	}
}

async function lookupParcelBoundaryByLatLng(lat, lng, options = {})
{
	const config = getParcelBoundaryApiConfig();
	const query = new URLSearchParams();
	const boundaryOnly = options && options.boundaryOnly === true;
	const pointKey = buildParcelBoundaryPointKey(lat, lng);
	const key = `${pointKey}|${boundaryOnly ? "boundary" : "details"}`;
	cancelParcelBoundaryLookup();
	const cached = parcelBoundaryLookupCache.get(key);
	if (cached && cached.expiresAt > Date.now()) return cached.value;
	if (cached) parcelBoundaryLookupCache.delete(key);

	if (!config.url) {
		throw new Error("필지 경계 API URL이 설정되지 않았습니다.");
	}

	const requestUrl = new URL(config.url, window.location.origin);
	query.set("lng", String(lng));
	query.set("lat", String(lat));
	query.set("dbOnly", "1");
    // Boundary geometry is returned independently of land_basic. Detailed property
    // datasets remain database-only and are resolved by their own load state.
    query.set("_rj_db_contract", "parcel-master-boundary-property-db-only-v4");
	if (window.location.hostname === "localhost" || window.location.hostname === "127.0.0.1") {
		// Vercel의 과거 CORS 헤더 없는 캐시와 로컬 미리보기 요청을 분리합니다.
      query.set("_rj_cors", "local-" + (window.location.port || "5500") + "-v4");
	}
	Object.keys(config.query).forEach((name) => {
		if (!name) return;
		query.set(name, String(config.query[name]));
	});
	if (boundaryOnly) query.set("boundaryOnly", "1");
	else query.delete("boundaryOnly");
	requestUrl.search = query.toString();
	const isCrossOriginRequest = requestUrl.origin !== window.location.origin;

	const controller = new AbortController();
	parcelBoundaryAbortController = controller;
	const timeout = window.setTimeout(() => {
		controller.abort();
	}, PARCEL_BOUNDARY_LOOKUP_TIMEOUT_MS);
	try {
		const response = await fetch(requestUrl.toString(), {
			method: "GET",
			credentials: isCrossOriginRequest ? "omit" : "same-origin",
			signal: controller.signal,
			mode: isCrossOriginRequest ? "cors" : "same-origin",
			cache: "no-cache"
		});
		const payload = await parseParcelBoundaryApiResponse(response);
		const normalized = normalizeParcelBoundaryPayload(payload);
		if (!normalized) {
			throw new Error("필지 경계 조회 응답 형식이 일치하지 않습니다.");
		}
		if (config.enableLogging) {
			console.debug("[realjeju parcel] boundary hit", { pnu: normalized.pnu, lat, lng });
		}
		if (parcelBoundaryLookupCache.size >= PARCEL_BOUNDARY_MAX_FETCH_CACHE) {
			const firstKey = parcelBoundaryLookupCache.keys().next().value;
			if (firstKey) parcelBoundaryLookupCache.delete(firstKey);
		}
		const stableStatuses = [
			normalized.landCharacteristicsStatus,
			normalized.ownershipStatus,
			normalized.landUsePlanStatus,
			normalized.landMovesStatus,
			normalized.individualLandPricesStatus,
			normalized.individualHousingPricesStatus
		];
		if (stableStatuses.every(function(status) {
			return status !== "unavailable" && status !== "stale";
		})) parcelBoundaryLookupCache.set(key, {
			value: normalized,
			expiresAt: Date.now() + PARCEL_BOUNDARY_BROWSER_CACHE_TTL_MS
		});
		return normalized;
	} finally {
		window.clearTimeout(timeout);
		if (parcelBoundaryAbortController === controller) parcelBoundaryAbortController = null;
	}
}

function clearParcelBoundaryOverlays()
{
	parcelBoundaryPolygonOverlays.forEach((polygon) => {
		if (polygon && typeof polygon.setMap === "function") polygon.setMap(null);
	});
	parcelBoundaryPolygonOverlays = [];
	parcelBoundaryFeature = null;
}

function clearParcelBoundaryRenderState()
{
	parcelBoundaryRequestToken += 1;
	cancelParcelBoundaryLookup();
	parcelBoundaryLoading = false;
	parcelBoundaryRenderError = "";
	clearParcelBoundaryOverlays();
}

function shouldSuppressParcelMapClickAfterDrag() {
  return Date.now() < parcelRegionTradeMapDragSuppressUntil;
}

function renderParcelBoundaryOverlay(feature)
{
	if (!state.map || !window.kakao || !kakao.maps || !kakao.maps.Polygon) return false;
	clearParcelBoundaryOverlays();
	if (!feature || !Array.isArray(feature.paths) || !feature.paths.length) return false;

	const displayCalibration = getParcelBoundaryDisplayCalibration();
	const displayPaths = buildParcelBoundaryDisplayPaths(feature.paths, displayCalibration);
	const sourcePathGroups = Array.isArray(feature.pathGroups) && feature.pathGroups.length
		? feature.pathGroups
		: feature.paths.map((path) => [path]);
	let displayPathIndex = 0;
	const displayPathGroups = sourcePathGroups.map((group) => group.map(() => displayPaths[displayPathIndex++]))
		.map((group) => group.filter((path) => Array.isArray(path) && path.length >= 3))
		.filter((group) => group.length);
	const sharedBoundaryStyle = typeof getAdminBoundaryStylePreference === "function"
		? getAdminBoundaryStylePreference()
		: { color: PARCEL_BOUNDARY_STROKE_COLOR, opacity: PARCEL_BOUNDARY_FILL_OPACITY };
	const polygonStyle = {
		strokeWeight: 2,
		strokeColor: sharedBoundaryStyle.color,
		strokeOpacity: PARCEL_BOUNDARY_STROKE_OPACITY,
		strokeStyle: PARCEL_BOUNDARY_STROKE_STYLE,
		fillColor: sharedBoundaryStyle.color,
		fillOpacity: sharedBoundaryStyle.opacity,
		zIndex: PARCEL_BOUNDARY_ACTIVE_Z_INDEX
	};

	try {
		parcelBoundaryPolygonOverlays = displayPathGroups
			.map((group) => new kakao.maps.Polygon({
				path: group.length === 1 ? group[0] : group,
				strokeWeight: polygonStyle.strokeWeight,
				strokeColor: polygonStyle.strokeColor,
				strokeOpacity: polygonStyle.strokeOpacity,
				strokeStyle: polygonStyle.strokeStyle,
				fillColor: polygonStyle.fillColor,
				fillOpacity: polygonStyle.fillOpacity
			}));
		parcelBoundaryPolygonOverlays.forEach(polygon => polygon.setMap(state.map));
		parcelBoundaryPolygonOverlays.forEach((polygon) => {
			if (polygon && typeof polygon.setZIndex === "function") polygon.setZIndex(PARCEL_BOUNDARY_ACTIVE_Z_INDEX);
		});
		parcelBoundaryFeature = feature;
		return true;
	} catch (error) {
		clearParcelBoundaryOverlays();
		console.error("[realjeju parcel] polygon render error", error);
		return false;
	}
}

function clearParcelAreaMeasureOverlays()
{
	parcelAreaMeasurePolygonOverlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	parcelAreaMeasureBoundaryOverlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	parcelAreaMeasureLabelOverlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	parcelAreaMeasurePolygonOverlays = [];
	parcelAreaMeasureBoundaryOverlays = [];
	parcelAreaMeasureBoundarySegmentKeys.clear();
	parcelAreaMeasureLabelOverlays = [];
}

function getParcelAreaMeasurePoint(point)
{
	if (!point) return null;
	const lat = Number(typeof point.getLat === "function" ? point.getLat() : (point.lat ?? point.y));
	const lng = Number(typeof point.getLng === "function" ? point.getLng() : (point.lng ?? point.x));
	return Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null;
}

function estimateParcelAreaMeasureM2(paths, pathGroups)
{
	if (!Array.isArray(paths)) return 0;
	const measureRing = (path) => {
		if (!Array.isArray(path) || path.length < 3) return;
		const points = path.map(getParcelAreaMeasurePoint).filter(Boolean);
		if (points.length < 3) return 0;
		const centerLat = points.reduce((sum, point) => sum + point.lat, 0) / points.length;
		const metersPerLng = 111320 * Math.cos(centerLat * Math.PI / 180);
		const metersPerLat = 110540;
		let signedArea = 0;
		for (let index = 0; index < points.length; index += 1) {
			const current = points[index];
			const next = points[(index + 1) % points.length];
			signedArea += (current.lng * metersPerLng) * (next.lat * metersPerLat)
				- (next.lng * metersPerLng) * (current.lat * metersPerLat);
		}
		return Math.abs(signedArea / 2);
	};
	if (Array.isArray(pathGroups) && pathGroups.length) {
		return pathGroups.reduce((total, group) => {
			if (!Array.isArray(group) || !group.length) return total;
			const ringAreas = group.map(measureRing);
			const outerArea = Number(ringAreas[0] || 0);
			const holeArea = ringAreas.slice(1).reduce((sum, area) => sum + Number(area || 0), 0);
			return total + Math.max(0, outerArea - holeArea);
		}, 0);
	}
	return paths.reduce((total, path) => total + Number(measureRing(path) || 0), 0);
}

function getParcelAreaMeasureAreaM2(feature)
{
	const properties = feature?.properties || feature?.attributes || {};
	const candidates = [
		feature?.areaM2,
		feature?.landCharacteristics?.areaM2,
		properties.areaM2,
		properties.area_m2,
		properties.area,
		properties.parea
	];
	for (const candidate of candidates) {
		const value = Number(String(candidate ?? "").replace(/,/g, ""));
		if (Number.isFinite(value) && value > 0) return value;
	}
	return estimateParcelAreaMeasureM2(feature?.paths, feature?.pathGroups);
}

function formatParcelAreaMeasureValue(areaM2, unit = globalAreaUnit)
{
	const normalizedArea = Number(areaM2);
	if (!Number.isFinite(normalizedArea) || normalizedArea <= 0) return "-";
	const value = unit === "py" ? normalizedArea / 3.305785 : normalizedArea;
	const digits = value >= 100 ? 0 : 1;
	return value.toLocaleString("ko-KR", { maximumFractionDigits: digits }) + (unit === "py" ? "평" : "㎡");
}

function getParcelAreaMeasurePnu(feature)
{
	const properties = feature?.properties || feature?.attributes || {};
	return String(feature?.pnu || properties.pnu || properties.PNU || "").trim();
}

function getParcelAreaMeasureJibunFromPnu(value)
{
	const pnu = String(value || "").replace(/\D/g, "");
	if (!/^\d{19}$/.test(pnu)) return "";
	const mainNumber = Number(pnu.slice(11, 15));
	const subNumber = Number(pnu.slice(15, 19));
	if (!Number.isFinite(mainNumber) || mainNumber <= 0) return "";
	return (pnu.charAt(10) === "2" ? "산" : "")
		+ String(mainNumber)
		+ (Number.isFinite(subNumber) && subNumber > 0 ? "-" + String(subNumber) : "");
}

function compactParcelAreaMeasureAddress(value)
{
	const normalized = String(value || "").replace(/\s+/g, " ").trim();
	if (!normalized || /^\d{19}$/.test(normalized)) return "";
	const match = normalized.match(/((?:[가-힣0-9]+(?:읍|면)\s+)?[가-힣0-9]+(?:동|리))\s+(산?\d+(?:-\d+)?)/u);
	return match ? (match[1] + " " + match[2]) : "";
}

async function getParcelAreaMeasureAddress(feature)
{
	const properties = feature?.properties || feature?.attributes || {};
	const pnu = getParcelAreaMeasurePnu(feature);
	const directAddress = compactParcelAreaMeasureAddress(
		feature?.address
		|| properties.address
		|| properties.fullAddress
		|| properties.full_address
		|| properties.addr
		|| ""
	);
	if (directAddress) return directAddress;
	let legalDongName = String(
		feature?.legalDongName
		|| feature?.landCharacteristics?.legalDongName
		|| properties.legalDongName
		|| properties.legal_dong_name
		|| ""
	).trim();
	const jibun = String(
		feature?.jibun
		|| feature?.landCharacteristics?.jibun
		|| properties.jibun
		|| properties.jibunAddress
		|| properties.jibun_address
		|| getParcelAreaMeasureJibunFromPnu(pnu)
		|| ""
	).trim();
	if (/^\d{19}$/.test(legalDongName)) legalDongName = "";
	if (!legalDongName && /^\d{19}$/.test(pnu) && typeof loadAdminBoundaryGeoJson === "function") {
		try {
			const data = await loadAdminBoundaryGeoJson("local");
			const features = Array.isArray(data?.features) ? data.features : [];
			const matches = features.filter((item) => {
				const code = String(getAdminBoundaryFeatureCodeValue(item) || "").replace(/\D/g, "");
				return code && pnu.startsWith(code);
			}).sort((left, right) => {
				return String(getAdminBoundaryFeatureCodeValue(right) || "").length
					- String(getAdminBoundaryFeatureCodeValue(left) || "").length;
			});
			const localFeature = matches[0] || null;
			const localName = String(getAdminBoundaryFeatureName(localFeature) || "").trim();
			if (/리$/.test(localName)) {
				const emdData = await loadAdminBoundaryGeoJson("emd");
				const emdCode = pnu.slice(0, 8);
				const parentFeature = (Array.isArray(emdData?.features) ? emdData.features : []).find((item) => {
					return String(getAdminBoundaryFeatureCodeValue(item) || "").replace(/\D/g, "") === emdCode;
				});
				const parentName = String(getAdminBoundaryFeatureName(parentFeature) || "").trim();
				legalDongName = [parentName, localName].filter(Boolean).join(" ");
			} else {
				legalDongName = localName;
			}
		} catch (_error) {}
	}
	const address = [legalDongName, jibun].filter(Boolean).join(" ").trim();
	return compactParcelAreaMeasureAddress(address) || address || jibun || "선택 필지";
}

const PARCEL_AREA_MEASURE_PRICE_CACHE_TTL_MS = 30 * 60 * 1000;

const PARCEL_AREA_MEASURE_PRICE_TIMEOUT_MS = 6000;

const parcelAreaMeasurePriceCache = new Map();

const parcelAreaMeasurePriceInflight = new Map();

function formatParcelAreaMeasureOfficialPrice(value)
{
	const price = Number(value);
	if (!Number.isFinite(price) || price <= 0) return "-";
	if (price >= 100000000) {
		return (price / 100000000).toLocaleString("ko-KR", { maximumFractionDigits: 2 }) + "억";
	}
	return Math.round(price / 10000).toLocaleString("ko-KR") + "만";
}

async function lookupParcelAreaMeasureOfficialPrice(pnu, lat, lng, supportsPriceOnly)
{
	const normalizedPnu = String(pnu || "").replace(/\D/g, "");
	if (!/^\d{19}$/.test(normalizedPnu)) return null;
	const normalizedLat = Number(lat);
	const normalizedLng = Number(lng);
	const cached = parcelAreaMeasurePriceCache.get(normalizedPnu);
	if (cached && cached.expiresAt > Date.now()) return cached.value;
	if (parcelAreaMeasurePriceInflight.has(normalizedPnu)) return parcelAreaMeasurePriceInflight.get(normalizedPnu);
	const request = (async () => {
		const config = getParcelBoundaryApiConfig();
		if (!config.url) return null;
		const requestUrl = new URL(config.url, window.location.origin);
		Object.keys(config.query || {}).forEach((name) => {
			if (name) requestUrl.searchParams.set(name, String(config.query[name]));
		});
		requestUrl.searchParams.set("pnu", normalizedPnu);
		requestUrl.searchParams.set("priceOnly", "1");
		requestUrl.searchParams.set("dbOnly", "1");
		const controller = new AbortController();
		const timeout = window.setTimeout(() => controller.abort(), PARCEL_AREA_MEASURE_PRICE_TIMEOUT_MS);
		try {
			const requestOptions = {
				method: "GET",
				credentials: requestUrl.origin === window.location.origin ? "same-origin" : "omit",
				mode: requestUrl.origin === window.location.origin ? "same-origin" : "cors",
				signal: controller.signal,
				cache: "no-cache"
			};
			const canUseLegacyFallback = Number.isFinite(normalizedLat)
				&& Number.isFinite(normalizedLng);
			let payload = null;
			if (supportsPriceOnly === true) {
				const response = await fetch(requestUrl.toString(), requestOptions);
				payload = response.ok ? await response.json().catch(() => null) : null;
			}
			if (!payload && supportsPriceOnly !== true && canUseLegacyFallback) {
				const fallbackUrl = new URL(config.url, window.location.origin);
				Object.keys(config.query || {}).forEach((name) => {
					if (name) fallbackUrl.searchParams.set(name, String(config.query[name]));
				});
				fallbackUrl.searchParams.delete("pnu");
				fallbackUrl.searchParams.delete("priceOnly");
				fallbackUrl.searchParams.delete("boundaryOnly");
				fallbackUrl.searchParams.set("lat", String(normalizedLat));
				fallbackUrl.searchParams.set("lng", String(normalizedLng));
				fallbackUrl.searchParams.set("dbOnly", "1");
				const fallbackResponse = await fetch(fallbackUrl.toString(), {
					...requestOptions,
					credentials: fallbackUrl.origin === window.location.origin ? "same-origin" : "omit",
					mode: fallbackUrl.origin === window.location.origin ? "same-origin" : "cors"
				});
				payload = fallbackResponse.ok ? await fallbackResponse.json().catch(() => null) : null;
			}
			if (!payload) return null;
			const latest = normalizeParcelLandPriceItems(payload?.individualLandPrices)[0] || null;
			return latest && Number.isFinite(Number(latest.pricePerSquareMeter))
				? Number(latest.pricePerSquareMeter)
				: null;
		} finally {
			window.clearTimeout(timeout);
		}
	})().catch(() => null).then((value) => {
		parcelAreaMeasurePriceCache.set(normalizedPnu, {
			value,
			expiresAt: Date.now() + PARCEL_AREA_MEASURE_PRICE_CACHE_TTL_MS
		});
		return value;
	}).finally(() => {
		parcelAreaMeasurePriceInflight.delete(normalizedPnu);
	});
	parcelAreaMeasurePriceInflight.set(normalizedPnu, request);
	return request;
}

async function hydrateParcelAreaMeasureOfficialPrice(selection)
{
	const pricePerSquareMeter = await lookupParcelAreaMeasureOfficialPrice(
		selection?.pnu,
		selection?.selectionLat,
		selection?.selectionLng,
		selection?.feature?.apiCapabilities?.priceOnly === true
	);
	if (!parcelAreaMeasureActive || !parcelAreaMeasureSelections.includes(selection)) return;
	selection.officialPricePerM2 = Number.isFinite(Number(pricePerSquareMeter)) ? Number(pricePerSquareMeter) : null;
	selection.officialPriceStatus = selection.officialPricePerM2 ? "loaded" : "unavailable";
	renderParcelAreaMeasurePanel();
}

function getParcelAreaMeasureDisplayPathGroups(feature)
{
	if (!feature || !Array.isArray(feature.paths) || !feature.paths.length) return [];
	const displayPaths = buildParcelBoundaryDisplayPaths(feature.paths, getParcelBoundaryDisplayCalibration());
	const sourcePathGroups = Array.isArray(feature.pathGroups) && feature.pathGroups.length
		? feature.pathGroups
		: feature.paths.map((path) => [path]);
	let displayPathIndex = 0;
	return sourcePathGroups.map((group) => group.map(() => displayPaths[displayPathIndex++]))
		.map((group) => group.filter((path) => Array.isArray(path) && path.length >= 3))
		.filter((group) => group.length);
}

const PARCEL_AREA_MEASURE_BOUNDARY_SNAP_DEGREES = 0.000002;

function getParcelAreaMeasureBoundarySegment(start, end)
{
	const startPoint = getParcelAreaMeasurePoint(start);
	const endPoint = getParcelAreaMeasurePoint(end);
	if (!startPoint || !endPoint) return null;
	const snapCoordinate = (value) => Math.round(value / PARCEL_AREA_MEASURE_BOUNDARY_SNAP_DEGREES);
	const startKey = snapCoordinate(startPoint.lat) + "," + snapCoordinate(startPoint.lng);
	const endKey = snapCoordinate(endPoint.lat) + "," + snapCoordinate(endPoint.lng);
	if (startKey === endKey) return null;
	const isForward = startKey < endKey;
	return {
		key: isForward ? startKey + "|" + endKey : endKey + "|" + startKey,
		path: isForward ? [start, end] : [end, start]
	};
}

function appendParcelAreaMeasureBoundarySegments(pathGroups)
{
	if (!window.kakao?.maps?.Polyline) return;
	pathGroups.flat().forEach((path) => {
		if (!Array.isArray(path) || path.length < 2) return;
		for (let index = 0; index < path.length; index += 1) {
			const segment = getParcelAreaMeasureBoundarySegment(path[index], path[(index + 1) % path.length]);
			if (!segment || parcelAreaMeasureBoundarySegmentKeys.has(segment.key)) continue;
			try {
				const boundary = new kakao.maps.Polyline({
					path: segment.path,
					strokeWeight: 2,
					strokeColor: "#1764ff",
					strokeOpacity: 0.96,
					strokeStyle: "shortdash"
				});
				boundary.setMap(state.map);
				if (typeof boundary.setZIndex === "function") boundary.setZIndex(PARCEL_BOUNDARY_ACTIVE_Z_INDEX + 1);
				parcelAreaMeasureBoundarySegmentKeys.add(segment.key);
				parcelAreaMeasureBoundaryOverlays.push(boundary);
			} catch (_error) {}
		}
	});
}

function appendParcelAreaMeasureOverlay(selection, selectionIndex)
{
	const pathGroups = getParcelAreaMeasureDisplayPathGroups(selection.feature);
	pathGroups.forEach((group) => {
		try {
			const polygon = new kakao.maps.Polygon({
				path: group.length === 1 ? group[0] : group,
				strokeWeight: 0,
				strokeOpacity: 0,
				fillColor: "#1764ff",
				fillOpacity: 0.18
			});
			polygon.setMap(state.map);
			if (typeof polygon.setZIndex === "function") polygon.setZIndex(PARCEL_BOUNDARY_ACTIVE_Z_INDEX + 1);
			parcelAreaMeasurePolygonOverlays.push(polygon);
		} catch (_error) {}
	});
	appendParcelAreaMeasureBoundarySegments(pathGroups);
	const center = getParcelBoundaryDisplayCenter(pathGroups.flat());
	if (!center || !Number.isFinite(center.lat) || !Number.isFinite(center.lng) || !kakao.maps.CustomOverlay || !kakao.maps.LatLng) return;
	const label = document.createElement("div");
	label.className = "parcel-area-measure-map-label";
	label.innerHTML = "<strong>" + escapeParcelLandInfoHtml(formatParcelAreaMeasureValue(selection.areaM2))
		+ "</strong><span>" + (selectionIndex + 1) + "</span>";
	const overlay = new kakao.maps.CustomOverlay({
		map: state.map,
		position: new kakao.maps.LatLng(center.lat, center.lng),
		content: label,
		xAnchor: 0.5,
		yAnchor: 0.5,
		zIndex: PARCEL_BOUNDARY_ACTIVE_Z_INDEX + 2
	});
	parcelAreaMeasureLabelOverlays.push(overlay);
}

function renderParcelAreaMeasureOverlays(options = {})
{
	if (!parcelAreaMeasureActive || !state.map || !window.kakao?.maps) return;
	if (options.appendOnly === true && parcelAreaMeasureSelections.length) {
		const selectionIndex = parcelAreaMeasureSelections.length - 1;
		appendParcelAreaMeasureOverlay(parcelAreaMeasureSelections[selectionIndex], selectionIndex);
		return;
	}
	clearParcelAreaMeasureOverlays();
	parcelAreaMeasureSelections.forEach(appendParcelAreaMeasureOverlay);
}

function renderParcelAreaMeasurePanel()
{
	if (!propertyList || !parcelAreaMeasureActive) return;
	const totalAreaM2 = parcelAreaMeasureSelections.reduce((sum, item) => sum + Number(item.areaM2 || 0), 0);
	const hasPendingPrice = parcelAreaMeasureSelections.some((item) => item.officialPriceStatus === "loading");
	const hasAvailablePrice = parcelAreaMeasureSelections.some((item) => (
		item.officialPriceStatus === "loaded"
		&& Number(item.areaM2 || 0) > 0
		&& Number(item.officialPricePerM2 || 0) > 0
	));
	const totalOfficialPrice = parcelAreaMeasureSelections.reduce((sum, item) => {
		if (item.officialPriceStatus !== "loaded") return sum;
		const areaM2 = Number(item.areaM2 || 0);
		const pricePerSquareMeter = Number(item.officialPricePerM2 || 0);
		return sum + (areaM2 > 0 && pricePerSquareMeter > 0 ? areaM2 * pricePerSquareMeter : 0);
	}, 0);
	const rowsHtml = parcelAreaMeasureSelections.map((selection, index) => {
		const officialPrice = Number(selection.areaM2 || 0) * Number(selection.officialPricePerM2 || 0);
		const officialPriceText = selection.officialPriceStatus === "loading"
			? ""
			: formatParcelAreaMeasureOfficialPrice(officialPrice);
		return '<div class="parcel-area-measure-row">'
			+ '<span class="parcel-area-measure-index">' + (index + 1) + '</span>'
			+ '<strong>' + escapeParcelLandInfoHtml(selection.address) + '</strong>'
			+ '<span class="parcel-area-measure-area"><b>' + escapeParcelLandInfoHtml(formatParcelAreaMeasureValue(selection.areaM2)) + '</b></span>'
			+ '<span class="parcel-area-measure-price">' + escapeParcelLandInfoHtml(officialPriceText) + '</span>'
			+ '<button type="button" data-parcel-area-remove="' + index + '" aria-label="' + (index + 1) + '번 필지 삭제">×</button>'
			+ '</div>';
	}).join("");
	let panel = propertyList.querySelector(".parcel-area-measure-panel");
	if (!panel) {
		propertyList.innerHTML = '<section class="parcel-area-measure-panel">'
			+ '<div class="parcel-area-measure-summary">'
			+ '<div class="parcel-area-measure-summary-head"><strong data-parcel-area-count></strong>'
			+ '<div class="parcel-area-measure-summary-actions">'
			+ '<button type="button" data-parcel-area-unit-toggle aria-label="평 단위로 전환"><i class="fa-solid fa-arrows-rotate" aria-hidden="true"></i><span data-parcel-area-unit-label>평</span></button>'
			+ '<button type="button" data-parcel-area-cadastral aria-label="지적도 켜기" aria-pressed="false">지적</button>'
			+ '<button type="button" data-parcel-area-reset>초기화</button></div></div>'
			+ '<div class="parcel-area-measure-summary-metrics">'
			+ '<div><span>총 면적</span><strong data-parcel-area-total></strong></div>'
			+ '<div><span>공시지가</span><strong data-parcel-area-price-total></strong></div></div></div>'
			+ '<div class="parcel-area-measure-table-head"><span>번호</span><span>지번</span><span>면적</span><span>공시지가</span><span></span></div>'
			+ '<div class="parcel-area-measure-rows" data-parcel-area-rows></div>'
			+ '</section>';
		panel = propertyList.querySelector(".parcel-area-measure-panel");
		panel?.addEventListener("click", (event) => {
			const unitToggleButton = event.target.closest("[data-parcel-area-unit-toggle]");
			if (unitToggleButton) {
				event.preventDefault();
				event.stopPropagation();
				toggleSharedAreaUnit();
				return;
			}
			const cadastralButton = event.target.closest("[data-parcel-area-cadastral]");
			if (cadastralButton) {
				event.preventDefault();
				event.stopPropagation();
				if (typeof window.toggleMapCadastralOverlay === "function") window.toggleMapCadastralOverlay();
				requestAnimationFrame(() => {
					const mapCadastralButton = document.getElementById("mapTypeCadastralBtn");
					const isActive = mapCadastralButton?.getAttribute("aria-pressed") === "true";
					cadastralButton.classList.toggle("is-active", isActive);
					cadastralButton.setAttribute("aria-pressed", String(isActive));
					cadastralButton.setAttribute("aria-label", isActive ? "지적도 끄기" : "지적도 켜기");
				});
				return;
			}
			const resetButton = event.target.closest("[data-parcel-area-reset]");
			if (resetButton) {
				parcelAreaMeasureSelections = [];
				renderParcelAreaMeasureOverlays();
				renderParcelAreaMeasurePanel();
				return;
			}
			const removeButton = event.target.closest("[data-parcel-area-remove]");
			if (!removeButton) return;
			const index = Number(removeButton.dataset.parcelAreaRemove);
			if (!Number.isInteger(index) || index < 0) return;
			parcelAreaMeasureSelections.splice(index, 1);
			renderParcelAreaMeasureOverlays();
			renderParcelAreaMeasurePanel();
		});
	}
	panel?.querySelector("[data-parcel-area-count]")?.replaceChildren(document.createTextNode("총 " + parcelAreaMeasureSelections.length.toLocaleString("ko-KR") + "개 필지가 선택됨"));
	panel?.querySelector("[data-parcel-area-total]")?.replaceChildren(document.createTextNode(formatParcelAreaMeasureValue(totalAreaM2)));
	const unitToggleButton = panel?.querySelector("[data-parcel-area-unit-toggle]");
	if (unitToggleButton) {
		const nextUnitLabel = globalAreaUnit === "py" ? "㎡" : "평";
		const unitToggleLabel = unitToggleButton.querySelector("[data-parcel-area-unit-label]");
		if (unitToggleLabel) unitToggleLabel.textContent = nextUnitLabel;
		unitToggleButton.setAttribute("aria-label", nextUnitLabel + " 단위로 전환");
	}
	const cadastralButton = panel?.querySelector("[data-parcel-area-cadastral]");
	if (cadastralButton) {
		const mapCadastralButton = document.getElementById("mapTypeCadastralBtn");
		const isActive = mapCadastralButton?.getAttribute("aria-pressed") === "true";
		cadastralButton.classList.toggle("is-active", isActive);
		cadastralButton.setAttribute("aria-pressed", String(isActive));
		cadastralButton.setAttribute("aria-label", isActive ? "지적도 끄기" : "지적도 켜기");
	}
	// 조회 중에는 기존 합계를 유지하고, 공시지가가 없는 필지는 합계에서 제외한다.
	const totalPriceText = hasAvailablePrice
		? formatParcelAreaMeasureOfficialPrice(totalOfficialPrice)
		: (hasPendingPrice ? "" : "-");
	panel?.querySelector("[data-parcel-area-price-total]")?.replaceChildren(document.createTextNode(totalPriceText));
	const resetButton = panel?.querySelector("[data-parcel-area-reset]");
	if (resetButton) resetButton.disabled = !parcelAreaMeasureSelections.length;
	const rowsHost = panel?.querySelector("[data-parcel-area-rows]");
	if (rowsHost) rowsHost.innerHTML = rowsHtml || '<p class="parcel-area-measure-empty">지도에서 필지를 차례대로 선택하세요.</p>';
}

function isParcelAnalysisToolVisibleLevel()
{
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	const level = Number(state.map?.getLevel?.());
	return category === "parcel" && Number.isFinite(level) && level >= 1 && level <= 5;
}

function isParcelAreaMeasureVisibleLevel()
{
	return isParcelAnalysisToolVisibleLevel();
}

function syncParcelAreaMeasureButton()
{
	const button = document.getElementById("mapParcelAreaToolBtn");
	if (!button) return;
	const isAvailable = isParcelAreaMeasureVisibleLevel();
	button.disabled = !isAvailable;
	button.classList.toggle("is-level-disabled", !isAvailable);
	button.classList.toggle("active", parcelAreaMeasureActive && isAvailable);
	button.setAttribute("aria-disabled", isAvailable ? "false" : "true");
	button.setAttribute("aria-pressed", parcelAreaMeasureActive && isAvailable ? "true" : "false");
	button.title = isAvailable ? "필지 면적 선택" : "지도 1~5레벨에서 사용 가능";
}

function deactivateParcelAreaMeasure()
{
	parcelAreaMeasureRequestToken += 1;
	parcelAreaMeasureActive = false;
	parcelAreaMeasureSelections = [];
	clearParcelAreaMeasureOverlays();
	if (isMapCadastralOverlayVisible) toggleMapCadastralOverlay();
	syncParcelAreaMeasureButton();
}

async function handleParcelAreaMeasureMapClick(mouseEvent)
{
	if (!parcelAreaMeasureActive) return false;
	if (!isParcelAnalysisToolVisibleLevel()) return false;
	if (window.kakao?.maps?.event && typeof kakao.maps.event.preventMap === "function") kakao.maps.event.preventMap();
	if (!mouseEvent?.latLng) return true;
	const token = ++parcelAreaMeasureRequestToken;
	const selectionLat = mouseEvent.latLng.getLat();
	const selectionLng = mouseEvent.latLng.getLng();
	try {
		const feature = await lookupParcelBoundaryByLatLng(
			selectionLat,
			selectionLng,
			{ boundaryOnly: true }
		);
		if (token !== parcelAreaMeasureRequestToken || !parcelAreaMeasureActive || !feature) return true;
		const pnu = getParcelAreaMeasurePnu(feature);
		const address = await getParcelAreaMeasureAddress(feature);
		if (token !== parcelAreaMeasureRequestToken || !parcelAreaMeasureActive) return true;
		const selectionKey = pnu || address;
		const existingSelectionIndex = parcelAreaMeasureSelections.findIndex((item) => item.selectionKey === selectionKey);
		if (existingSelectionIndex >= 0) {
			parcelAreaMeasureSelections.splice(existingSelectionIndex, 1);
			renderParcelAreaMeasureOverlays();
			renderParcelAreaMeasurePanel();
			return true;
		}
		const selection = {
			selectionKey,
			pnu,
			address,
			areaM2: getParcelAreaMeasureAreaM2(feature),
			selectionLat,
			selectionLng,
			officialPricePerM2: null,
			officialPriceStatus: "loading",
			feature
		};
		parcelAreaMeasureSelections.push(selection);
		renderParcelAreaMeasureOverlays({ appendOnly: true });
		renderParcelAreaMeasurePanel();
		void hydrateParcelAreaMeasureOfficialPrice(selection);
	} catch (error) {
		console.error("[realjeju parcel area] selection error", error);
	}
	return true;
}

const PARCEL_ROAD_CONTACT_EXCLUDED_JIMOK = new Set(["하천", "강", "구거", "묘지"]);

const PARCEL_ROAD_CONTACT_GRID_DEGREES = 0.002;

const PARCEL_ROAD_CONTACT_CACHE_LIMIT = 12;

const PARCEL_ROAD_CONTACT_REQUEST_LIMIT = 1200;

const PARCEL_ROAD_CONTACT_REFRESH_DELAY_MS = 180;

const PARCEL_ROAD_CONTACT_REQUEST_TIMEOUT_MS = 9000;

let parcelRoadContactActive = false;

let parcelRoadContactOverlays = [];

let parcelRoadContactRenderToken = 0;

let parcelRoadContactRefreshTimer = null;

const parcelRoadContactViewportCache = new Map();

const parcelRoadContactViewportInflight = new Map();

function isParcelRoadContactVisibleLevel()
{
	return isParcelAnalysisToolVisibleLevel();
}

function clearParcelRoadContactOverlays()
{
	parcelRoadContactOverlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	parcelRoadContactOverlays = [];
}

function syncParcelRoadContactButton()
{
	const button = document.getElementById("mapParcelRoadContactToolBtn");
	if (!button) return;
	const isAvailable = isParcelRoadContactVisibleLevel();
	button.disabled = !isAvailable;
	button.classList.toggle("is-level-disabled", !isAvailable);
	button.classList.toggle("active", parcelRoadContactActive && isAvailable);
	button.setAttribute("aria-disabled", isAvailable ? "false" : "true");
	button.setAttribute("aria-pressed", parcelRoadContactActive && isAvailable ? "true" : "false");
	button.title = isAvailable ? "도로접면" : "지도 1~5레벨에서 사용 가능";
}

function getParcelRoadContactViewportRequest()
{
	const bounds = state.map?.getBounds?.();
	const sw = bounds?.getSouthWest?.();
	const ne = bounds?.getNorthEast?.();
	if (!sw || !ne) return null;
	const rawSouth = Number(sw.getLat());
	const rawWest = Number(sw.getLng());
	const rawNorth = Number(ne.getLat());
	const rawEast = Number(ne.getLng());
	if (![rawSouth, rawWest, rawNorth, rawEast].every(Number.isFinite)) return null;
	const grid = PARCEL_ROAD_CONTACT_GRID_DEGREES;
	const south = Math.floor(Math.min(rawSouth, rawNorth) / grid) * grid;
	const west = Math.floor(Math.min(rawWest, rawEast) / grid) * grid;
	const north = Math.ceil(Math.max(rawSouth, rawNorth) / grid) * grid;
	const east = Math.ceil(Math.max(rawWest, rawEast) / grid) * grid;
	return {
		south,
		west,
		north,
		east,
		key: [south, west, north, east].map((value) => value.toFixed(4)).join("|")
	};
}

async function loadParcelRoadContactViewportRows(viewport)
{
	if (!viewport?.key) return [];
	if (parcelRoadContactViewportCache.has(viewport.key)) return parcelRoadContactViewportCache.get(viewport.key);
	if (parcelRoadContactViewportInflight.has(viewport.key)) return parcelRoadContactViewportInflight.get(viewport.key);
	const request = (async () => {
		const config = getParcelBoundaryApiConfig();
		if (!config.url) return [];
		const requestUrl = new URL(config.url, window.location.origin);
		Object.keys(config.query || {}).forEach((name) => {
			if (name) requestUrl.searchParams.set(name, String(config.query[name]));
		});
		requestUrl.searchParams.delete("pnu");
		requestUrl.searchParams.delete("priceOnly");
		requestUrl.searchParams.delete("boundaryOnly");
		requestUrl.searchParams.set("roadContactBounds", "1");
		requestUrl.searchParams.set("west", String(viewport.west));
		requestUrl.searchParams.set("south", String(viewport.south));
		requestUrl.searchParams.set("east", String(viewport.east));
		requestUrl.searchParams.set("north", String(viewport.north));
		requestUrl.searchParams.set("limit", String(PARCEL_ROAD_CONTACT_REQUEST_LIMIT));
		requestUrl.searchParams.set("dbOnly", "1");
		const controller = new AbortController();
		const timeout = window.setTimeout(() => controller.abort(), PARCEL_ROAD_CONTACT_REQUEST_TIMEOUT_MS);
		try {
			const response = await fetch(requestUrl.toString(), {
				method: "GET",
				credentials: requestUrl.origin === window.location.origin ? "same-origin" : "omit",
				mode: requestUrl.origin === window.location.origin ? "same-origin" : "cors",
				signal: controller.signal,
				cache: "no-cache"
			});
			if (!response.ok) throw new Error("도로접면 필지 조회 실패");
			const payload = await response.json().catch(() => null);
			return (Array.isArray(payload?.parcels) ? payload.parcels : []).filter((row) => {
				const jimok = String(row?.jimok || "").replace(/\s+/g, "").trim();
				return jimok && !PARCEL_ROAD_CONTACT_EXCLUDED_JIMOK.has(jimok) && row?.geometry;
			});
		} finally {
			window.clearTimeout(timeout);
		}
	})().then((rows) => {
		if (parcelRoadContactViewportCache.size >= PARCEL_ROAD_CONTACT_CACHE_LIMIT) {
			const oldestKey = parcelRoadContactViewportCache.keys().next().value;
			if (oldestKey) parcelRoadContactViewportCache.delete(oldestKey);
		}
		parcelRoadContactViewportCache.set(viewport.key, rows);
		return rows;
	}).finally(() => {
		parcelRoadContactViewportInflight.delete(viewport.key);
	});
	parcelRoadContactViewportInflight.set(viewport.key, request);
	return request;
}

function renderParcelRoadContactRows(rows)
{
	if (!state.map || !window.kakao?.maps?.Polygon) return;
	const nextOverlays = [];
	(Array.isArray(rows) ? rows : []).forEach((row) => {
		const jimok = String(row?.jimok || "").replace(/\s+/g, "").trim();
		const isRoadParcel = jimok === "도로";
		const polygonStyle = isRoadParcel
			? { strokeColor: "#EAB308", strokeOpacity: 0.90, fillColor: "#FACC15", fillOpacity: 0.34 }
			: { strokeColor: "#111827", strokeOpacity: 0.72, fillColor: "#111827", fillOpacity: 0.45 };
		let geometry = row?.geometry;
		if (typeof geometry === "string") {
			try { geometry = JSON.parse(geometry); } catch (_error) { geometry = null; }
		}
		toLatLngPathGroupsFromGeometry(geometry).forEach((group) => {
			if (!Array.isArray(group) || !group.length) return;
			try {
				const polygon = new kakao.maps.Polygon({
					map: state.map,
					path: group.length === 1 ? group[0] : group,
					strokeWeight: 1,
					strokeColor: polygonStyle.strokeColor,
					strokeOpacity: polygonStyle.strokeOpacity,
					strokeStyle: "solid",
					fillColor: polygonStyle.fillColor,
					fillOpacity: polygonStyle.fillOpacity,
					clickable: false
				});
				if (typeof polygon.setZIndex === "function") polygon.setZIndex(3);
				nextOverlays.push(polygon);
			} catch (_error) {}
		});
	});
	const previousOverlays = parcelRoadContactOverlays;
	parcelRoadContactOverlays = nextOverlays;
	previousOverlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
}

async function refreshParcelRoadContactViewport()
{
	const token = ++parcelRoadContactRenderToken;
	if (!parcelRoadContactActive || !isParcelRoadContactVisibleLevel()) {
		clearParcelRoadContactOverlays();
		return false;
	}
	const viewport = getParcelRoadContactViewportRequest();
	if (!viewport) return false;
	try {
		const rows = await loadParcelRoadContactViewportRows(viewport);
		if (token !== parcelRoadContactRenderToken || !parcelRoadContactActive || !isParcelRoadContactVisibleLevel()) return false;
		renderParcelRoadContactRows(rows);
		return true;
	} catch (_error) {
		return false;
	}
}

function scheduleParcelRoadContactViewportRefresh()
{
	syncParcelRoadContactButton();
	if (parcelRoadContactRefreshTimer) window.clearTimeout(parcelRoadContactRefreshTimer);
	if (!parcelRoadContactActive) {
		parcelRoadContactRefreshTimer = null;
		return;
	}
	parcelRoadContactRefreshTimer = window.setTimeout(() => {
		parcelRoadContactRefreshTimer = null;
		void refreshParcelRoadContactViewport();
	}, PARCEL_ROAD_CONTACT_REFRESH_DELAY_MS);
}

function setParcelRoadContactActive(active)
{
	parcelRoadContactActive = active === true;
	parcelRoadContactRenderToken += 1;
	if (parcelRoadContactRefreshTimer) {
		window.clearTimeout(parcelRoadContactRefreshTimer);
		parcelRoadContactRefreshTimer = null;
	}
	if (!parcelRoadContactActive) clearParcelRoadContactOverlays();
	else scheduleParcelRoadContactViewportRefresh();
	syncParcelRoadContactButton();
}

function escapeParcelLandInfoHtml(value)
{
	return String(value == null ? "" : value)
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&#39;");
}

function formatParcelLandInfoValue(value)
{
	const text = String(value == null ? "" : value).trim();
	return text || "-";
}

function formatParcelLandInfoAddress(value)
{
	return String(value == null ? "" : value)
		.replace(/(\d+(?:-\d+)?)\s*(?:전|답|대)$/u, "$1")
		.trim();
}

function formatParcelLandArea(areaM2)
{
	const area = Number(areaM2);
	if (!Number.isFinite(area) || area <= 0) return "-";
	if (globalAreaUnit === "py") {
		const pyeong = Math.round(area / 3.305785);
		return new Intl.NumberFormat("ko-KR").format(pyeong) + "평";
	}
	const areaText = new Intl.NumberFormat("ko-KR", { maximumFractionDigits: 1 }).format(area);
	return areaText + "㎡";
}

function buildParcelLandInfoRow(label, value, rawValue)
{
	const areaValueClass = label === "면적" ? " parcel-land-info-area-value" : "";
	const groupStartClass = label === "소유구분" || label === "도로접면"
		? " parcel-land-info-group-start"
		: "";
	const areaData = label === "면적" && Number.isFinite(Number(rawValue))
		? ' data-area-m2="' + escapeParcelLandInfoHtml(Number(rawValue)) + '"'
		: "";
	return '<div class="parcel-land-info-row' + groupStartClass + '"><span class="parcel-land-info-label">' + escapeParcelLandInfoHtml(label) + '</span><strong class="parcel-land-info-value' + areaValueClass + '"' + areaData + '>' + escapeParcelLandInfoHtml(formatParcelLandInfoValue(value)) + '</strong></div>';
}

const PARCEL_LAND_USE_RELATIONS = ["포함", "저촉", "접합"];

function escapeParcelPublicDataHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function isNationalPlanningLandUseItem(item) {
  const code = String(item?.districtCode || item?.prposAreaDstrcCode || "").toUpperCase();
  const name = String(item?.districtName || item?.prposAreaDstrcCodeNm || "");
  return (
    item?.lawGroup === "national-planning" ||
    /^UQ/.test(code) ||
    /용도지역|용도지구|용도구역|녹지지역|주거지역|상업지역|공업지역|관리지역|농림지역|자연환경보전지역|취락지구|개발진흥지구|고도지구|방화지구|방재지구|보호지구|경관지구|복합용도지구|성장관리계획구역|도시지역|토지거래계약에관한허가구역/.test(name)
  );
}

function buildParcelLandUsePlanSection(feature) {
  const properties = feature?.properties || feature || {};
  const sourceItems = Array.isArray(feature?.landUsePlan)
    ? feature.landUsePlan
    : (Array.isArray(properties.landUsePlan) ? properties.landUsePlan : []);
  const uniqueItems = [];
  const seen = new Set();

  sourceItems.forEach((item) => {
    const relationCode = String(item?.relationCode || item?.cnflcAt || "").trim();
    const rawRelation = String(item?.relation || item?.cnflcAtNm || "").trim();
    const relationByCode = { "1": "포함", "2": "저촉", "3": "접합" };
    const relation = relationByCode[relationCode] || (rawRelation === "접함" ? "접합" : rawRelation);
    const districtCode = String(item?.districtCode || item?.prposAreaDstrcCode || "").trim();
    const districtName = String(item?.districtName || item?.prposAreaDstrcCodeNm || "").trim();
    if (!relation || !districtName) return;
    const key = `${relation}|${districtCode}|${districtName}`;
    if (seen.has(key)) return;
    seen.add(key);
    uniqueItems.push({ ...item, relation, districtCode, districtName });
  });

  const renderLawGroup = (title, groupName, secondary = false) => {
    const groupItems = uniqueItems.filter((item) => {
      const isNational = isNationalPlanningLandUseItem(item);
      return groupName === "national-planning" ? isNational : !isNational;
    });
    const rows = PARCEL_LAND_USE_RELATIONS.map((relation) => {
      const names = groupItems
        .filter((item) => item.relation === relation)
        .map((item) => item.districtName);
      const value = names.length ? names.join(", ") : "-";
      return `
        <div class="parcel-land-use-plan-row">
          <span class="parcel-land-use-plan-label">${relation}</span>
          <strong class="parcel-land-use-plan-value">${escapeParcelPublicDataHtml(value)}</strong>
        </div>
      `;
    }).join("");

    return `
      <div class="parcel-land-use-law-group${secondary ? " is-secondary" : ""}">
        <h3 class="parcel-land-use-law-title">${title}</h3>
        ${rows}
      </div>
    `;
  };

  return `
    <section class="parcel-land-use-plan-section" aria-label="토지이용계획">
      <h2 class="parcel-public-data-section-title">토지이용계획</h2>
      ${renderLawGroup("국토의 계획 및 이용에 관한 법률", "national-planning")}
      ${renderLawGroup("기타법률", "other", true)}
    </section>
  `;
}

function buildParcelLandMoveSection(feature) {
  const properties = feature?.properties || feature || {};
  const sourceItems = Array.isArray(feature?.landMoves)
    ? feature.landMoves
    : (Array.isArray(properties.landMoves) ? properties.landMoves : []);
  const items = sourceItems.map((item) => ({
    movedAt: String(item?.movedAt || item?.ladMvmnDe || "").trim(),
    reason: String(item?.reason || item?.ladMvmnPrvonshCodeNm || "").trim()
  })).filter((item) => item.movedAt || item.reason)
    .sort((left, right) => left.movedAt.localeCompare(right.movedAt));
  const status = String(feature?.landMovesStatus || properties.landMovesStatus || "not-found");
  const content = items.length
    ? `<div class="parcel-land-move-head"><span>일자</span><span>사유</span></div>
       <div class="parcel-land-move-list">${items.map((item) => `
         <div class="parcel-land-move-row">
           <span>${escapeParcelPublicDataHtml(item.movedAt || "-")}</span>
           <strong>${escapeParcelPublicDataHtml(item.reason || "-")}</strong>
         </div>
       `).join("")}</div>`
    : `<p class="parcel-public-data-empty">${status === "unavailable" ? "토지이동이력정보를 불러오지 못했습니다." : "토지 이동 이력이 없습니다."}</p>`;
  return `
    <section class="parcel-land-move-section" aria-label="토지 이동(변동) 사유">
      <h2 class="parcel-public-data-section-title">토지 이동(변동) 사유</h2>
      ${content}
    </section>
  `;
}

function normalizeParcelLandPriceItems(sourceItems) {
  const seen = new Set();
  return (Array.isArray(sourceItems) ? sourceItems : [])
    .reduce((result, item) => {
      const year = String(item?.year || item?.stdrYear || "").trim();
      const month = String(item?.month || item?.stdrMt || "01").trim().padStart(2, "0");
      const pricePerSquareMeter = Number(item?.pricePerSquareMeter ?? item?.pblntfPclnd ?? 0);
      if (!/^\d{4}$/.test(year) || !Number.isFinite(pricePerSquareMeter) || pricePerSquareMeter <= 0) {
        return result;
      }
      const key = `${year}.${month}`;
      if (seen.has(key)) return result;
      seen.add(key);
      result.push({
        year,
        month,
        pricePerSquareMeter,
        announcedAt: String(item?.announcedAt || item?.pblntfDe || "").trim()
      });
      return result;
    }, [])
    .sort((left, right) => Number(`${right.year}${right.month}`) - Number(`${left.year}${left.month}`))
    .slice(0, 20);
}

function buildParcelIndividualLandPriceSection(feature) {
  const properties = feature?.properties || feature || {};
  const prices = normalizeParcelLandPriceItems(properties.individualLandPrices);
  if (!prices.length) {
    return `
      <section class="parcel-land-price-section" aria-label="개별공시지가">
        <h2 class="parcel-public-data-section-title">개별공시지가</h2>
          <p class="parcel-public-data-empty realjeju-property-state-message">개별공시지가 정보가 없습니다.</p>
      </section>
    `;
  }

  const latest = prices[0];
  const rows = prices.map((item, index) => `
    <tr class="parcel-land-price-row" data-price-row-index="${index}">
      <td>${escapeParcelPublicDataHtml(`${item.year}.${item.month}`)}</td>
      <td data-parcel-land-price-sqm="${item.pricePerSquareMeter}" data-parcel-land-price-format="compact"></td>
    </tr>
  `).join("");

  return `
    <section
      class="parcel-land-price-section"
      aria-label="개별공시지가"
      data-parcel-land-price-section
      data-land-price-list-expanded="false"
      data-land-price-items="${encodeURIComponent(JSON.stringify(prices))}"
    >
      <h2 class="parcel-public-data-section-title">개별공시지가</h2>
      <div class="parcel-land-price-latest">
        <button
          type="button"
          class="parcel-land-price-nav-button"
          data-price-nav="older"
          aria-label="이전 연도 공시지가"
          title="이전 연도"
        >‹</button>
        <div class="parcel-land-price-latest-content">
          <span class="parcel-land-price-latest-label" data-parcel-land-price-selected-label></span>
          <strong class="parcel-land-price-latest-value" data-parcel-land-price-selected-value></strong>
        </div>
        <button
          type="button"
          class="parcel-land-price-nav-button"
          data-price-nav="newer"
          aria-label="다음 연도 공시지가"
          title="다음 연도"
        >›</button>
      </div>

      <div class="parcel-land-price-chart" data-parcel-land-price-chart></div>
      <div class="parcel-land-price-count-controls" aria-label="공시지가 표시 연도">
        <span>보기</span>
        <button type="button" class="parcel-land-price-count-button" data-price-count="5">5년</button>
        <button type="button" class="parcel-land-price-count-button" data-price-count="10">10년</button>
        <button type="button" class="parcel-land-price-count-button is-active" data-price-count="20">20년</button>
      </div>
      <table class="parcel-land-price-table">
        <thead>
          <tr>
            <th>기준연도</th>
            <th>공시지가 (<span data-parcel-land-price-unit>㎡</span>)</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
      ${prices.length > 5 ? `
        <button
          type="button"
          class="parcel-land-price-list-toggle"
          data-parcel-land-price-list-toggle
          aria-expanded="false"
        >(${prices.length - 5}건) 더보기</button>
      ` : ""}
    </section>
  `;
}

function getParcelPublicDataUnit() {
  return globalAreaUnit === "py" ? "pyeong" : "sqm";
}

function getParcelPriceForUnit(pricePerSquareMeter, unit) {
  return unit === "pyeong" ? pricePerSquareMeter * 3.305785 : pricePerSquareMeter;
}

function formatParcelLandPrice(price, format) {
  if (!Number.isFinite(price)) return "-";
  if (format === "full") return `${Math.round(price).toLocaleString("ko-KR")}원`;
  if (price >= 10000) {
    const manWon = (price / 10000).toFixed(2).replace(/\.00$/, "");
    return `${manWon}만원`;
  }
  return `${Math.round(price).toLocaleString("ko-KR")}원`;
}

function buildParcelLandPriceChart(items, unit, selectedIndex = 0) {
  if (!items.length) return "";
  const width = 640;
  const height = 360;
  const padding = { top: 30, right: 22, bottom: 46, left: 64 };
  const chronological = items.slice().reverse();
  const values = chronological.map((item) =>
    getParcelPriceForUnit(Number(item.pricePerSquareMeter), unit)
  );
  const minValue = Math.min(...values);
  const maxValue = Math.max(...values);
  const spread = Math.max(1, maxValue - minValue);
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;
  const points = values.map((value, index) => {
    const x = padding.left + (chronological.length === 1
      ? chartWidth / 2
      : (index / (chronological.length - 1)) * chartWidth);
    const y = padding.top + ((maxValue - value) / spread) * chartHeight;
    return {
      x,
      y,
      value,
      item: chronological[index],
      index,
      sourceIndex: chronological.length - 1 - index
    };
  });
  const pathPoints = points.map((point) => `${point.x.toFixed(1)},${point.y.toFixed(1)}`).join(" ");
  const labelStep = Math.max(1, Math.ceil((points.length - 1) / 4));
  const xLabels = points
    .filter((point) => point.index === 0 || point.index === points.length - 1 || point.index % labelStep === 0)
    .map((point) => `
      <text x="${point.x}" y="${height - 14}" text-anchor="middle">'${point.item.year.slice(2)}년</text>
    `)
    .join("");
  const yValues = [maxValue, minValue + spread / 2, minValue];
  const yLabels = yValues.map((value, index) => {
    const y = padding.top + (index / 2) * chartHeight;
    const label = value >= 10000
      ? `${Math.round(value / 10000)}만`
      : Math.round(value).toLocaleString("ko-KR");
    return `<text x="${padding.left - 12}" y="${y + 5}" text-anchor="end">${label}</text>`;
  }).join("");
  const selectedPoint = points.find((point) => point.sourceIndex === selectedIndex) || points[points.length - 1];
  const selectedDateLabel = selectedPoint
    ? `'${selectedPoint.item.year.slice(2)}.${selectedPoint.item.month}`
    : "";
  const guide = selectedPoint ? `
    <g class="parcel-land-price-chart-guide">
      <text x="${selectedPoint.x}" y="18" text-anchor="middle">${selectedDateLabel}</text>
      <line
        x1="${selectedPoint.x}"
        y1="${padding.top}"
        x2="${selectedPoint.x}"
        y2="${height - padding.bottom}"
      ></line>
    </g>
  ` : "";
  const pointGroups = points.map((point) => {
    const isSelected = point.sourceIndex === selectedIndex;
    const isEndpoint = point.index === 0 || point.index === points.length - 1;
    const showDot = isSelected || isEndpoint;
    const pointPrice = formatParcelLandPrice(point.value, "full");
    return `
      <g
        class="parcel-land-price-chart-point${isSelected ? " is-selected" : ""}"
        data-price-item-index="${point.sourceIndex}"
        data-price-x="${point.x}"
        role="button"
        tabindex="0"
        aria-label="${point.item.year}년 ${point.item.month}월 공시지가 ${pointPrice}"
      >
        <title>${point.item.year}.${point.item.month} ${pointPrice}</title>
        <circle class="parcel-land-price-chart-hit" cx="${point.x}" cy="${point.y}" r="15"></circle>
        ${showDot ? `<circle class="parcel-land-price-chart-dot" cx="${point.x}" cy="${point.y}" r="${isSelected ? 6 : 3.5}"></circle>` : ""}
      </g>
    `;
  }).join("");

  return `
    <svg viewBox="0 0 ${width} ${height}" role="img" aria-label="연도별 개별공시지가 그래프">
      <g class="parcel-land-price-chart-labels">${yLabels}${xLabels}</g>
      ${guide}
      <polyline class="parcel-land-price-chart-line" points="${pathPoints}"></polyline>
      <g class="parcel-land-price-chart-points">${pointGroups}</g>
    </svg>
  `;
}

function refreshParcelLandPriceDisplays() {
  const unit = getParcelPublicDataUnit();
  const unitLabel = unit === "pyeong" ? "평" : "㎡";
  document.querySelectorAll("[data-parcel-land-price-section]").forEach((section) => {
    let items = [];
    try {
      items = JSON.parse(decodeURIComponent(section.dataset.landPriceItems || ""));
    } catch (error) {
      items = [];
    }
    const activeButton = section.querySelector(".parcel-land-price-count-button.is-active");
    const requestedCount = Number(activeButton?.dataset.priceCount || 20);
    const visibleItems = items.slice(0, requestedCount);
    const listExpanded = section.dataset.landPriceListExpanded === "true";
    const listVisibleCount = listExpanded ? items.length : 5;
    const maxSelectedIndex = Math.max(0, visibleItems.length - 1);
    const requestedSelectedIndex = Number(section.dataset.selectedPriceIndex || 0);
    const selectedIndex = Math.min(maxSelectedIndex, Math.max(0, requestedSelectedIndex));
    const selectedItem = items[selectedIndex] || items[0] || null;
    section.dataset.selectedPriceIndex = String(selectedIndex);

    section.querySelectorAll("[data-parcel-land-price-unit]").forEach((node) => {
      if (node.textContent !== unitLabel) node.textContent = unitLabel;
    });
    section.querySelectorAll("[data-parcel-land-price-sqm]").forEach((node) => {
      const price = getParcelPriceForUnit(Number(node.dataset.parcelLandPriceSqm), unit);
      const nextText = formatParcelLandPrice(price, node.dataset.parcelLandPriceFormat);
      if (node.textContent !== nextText) node.textContent = nextText;
    });
    const selectedLabel = section.querySelector("[data-parcel-land-price-selected-label]");
    const selectedValue = section.querySelector("[data-parcel-land-price-selected-value]");
    if (selectedItem && selectedLabel) {
      selectedLabel.textContent = `${selectedItem.year}년 ${selectedItem.month}월 공시지가 (${unitLabel})`;
    }
    if (selectedItem && selectedValue) {
      const selectedPrice = getParcelPriceForUnit(Number(selectedItem.pricePerSquareMeter), unit);
      selectedValue.textContent = formatParcelLandPrice(selectedPrice, "full");
    }

    section.querySelectorAll("[data-price-row-index]").forEach((row) => {
      const rowIndex = Number(row.dataset.priceRowIndex);
      row.hidden = rowIndex >= listVisibleCount;
      row.classList.toggle("is-selected", rowIndex === selectedIndex);
    });
    const listToggle = section.querySelector("[data-parcel-land-price-list-toggle]");
    if (listToggle) {
      const hiddenCount = Math.max(0, items.length - 5);
      listToggle.hidden = hiddenCount === 0;
      listToggle.textContent = listExpanded ? "접기" : `(${hiddenCount}건) 더보기`;
      listToggle.setAttribute("aria-expanded", listExpanded ? "true" : "false");
    }
    const olderButton = section.querySelector('[data-price-nav="older"]');
    const newerButton = section.querySelector('[data-price-nav="newer"]');
    if (olderButton) olderButton.disabled = selectedIndex >= maxSelectedIndex;
    if (newerButton) newerButton.disabled = selectedIndex <= 0;

    const chart = section.querySelector("[data-parcel-land-price-chart]");
    if (chart) {
      const signature = `${unit}:${requestedCount}:${visibleItems.length}:${selectedIndex}`;
      if (chart.dataset.renderSignature !== signature) {
        chart.innerHTML = buildParcelLandPriceChart(visibleItems, unit, selectedIndex);
        chart.dataset.renderSignature = signature;
      }
    }
  });
}

let parcelLandPriceRefreshScheduled = false;

function scheduleParcelLandPriceRefresh() {
  if (parcelLandPriceRefreshScheduled) return;
  parcelLandPriceRefreshScheduled = true;
  requestAnimationFrame(() => {
    parcelLandPriceRefreshScheduled = false;
    refreshParcelLandPriceDisplays();
  });
}

function scheduleParcelBoundaryViewportReveal(feature, options = {})
{
	if (options.skip === true) return;
	if (!feature || !state.map || !propertyList || typeof requestAnimationFrame !== "function") return;
	const revealToken = (Number(scheduleParcelBoundaryViewportReveal.revealToken) || 0) + 1;
	scheduleParcelBoundaryViewportReveal.revealToken = revealToken;
	const revealWhenPanelSettled = () => {
		if (scheduleParcelBoundaryViewportReveal.revealToken !== revealToken) return;
		if (state.leftListDetailMode !== "parcel-land-info" || !propertyList.querySelector(".parcel-land-info-panel")) return;
		const mapNode = document.getElementById("map") || document.querySelector(".map-container");
		if (!mapNode || !document.body.contains(propertyList)) return;
		const mapRect = mapNode.getBoundingClientRect();
		const panelRect = propertyList.getBoundingClientRect();
		const panelStyle = window.getComputedStyle(propertyList);
		if (!mapRect.width || !panelRect.width || panelStyle.display === "none" || panelStyle.visibility === "hidden") return;
		const coveredLeft = Math.max(mapRect.left, panelRect.left);
		const coveredRight = Math.min(mapRect.right, panelRect.right);
		const coveredTop = Math.max(mapRect.top, panelRect.top);
		const coveredBottom = Math.min(mapRect.bottom, panelRect.bottom);
		if (coveredRight <= coveredLeft || coveredBottom <= coveredTop) return;
		const projection = state.map.getProjection && state.map.getProjection();
		if (!projection || !window.kakao || !kakao.maps) return;
		const selectionLat = Number(feature.selectionLat);
		const selectionLng = Number(feature.selectionLng);
		if (!Number.isFinite(selectionLat) || !Number.isFinite(selectionLng)) return;
		const selectionCoords = new kakao.maps.LatLng(selectionLat, selectionLng);
		const selectionPoint = typeof projection.containerPointFromCoords === "function"
			? projection.containerPointFromCoords(selectionCoords)
			: projection.pointFromCoords(selectionCoords);
		if (!selectionPoint) return;
		const selectionX = mapRect.left + Number(selectionPoint.x);
		const selectionY = mapRect.top + Number(selectionPoint.y);
		const selectionCovered = selectionX >= coveredLeft && selectionX <= coveredRight
			&& selectionY >= coveredTop && selectionY <= coveredBottom;
		if (!selectionCovered) return;
		const shiftRight = Math.min(mapRect.width * 0.58, coveredRight - selectionX + 40);
		if (!(shiftRight > 1)) return;
		const centerCoords = state.map.getCenter();
		const centerPoint = typeof projection.containerPointFromCoords === "function"
			? projection.containerPointFromCoords(centerCoords)
			: projection.pointFromCoords(centerCoords);
		if (!centerPoint) return;
		const nextPoint = new kakao.maps.Point(Number(centerPoint.x) - shiftRight, Number(centerPoint.y));
		const nextCenter = typeof projection.coordsFromContainerPoint === "function"
			? projection.coordsFromContainerPoint(nextPoint)
			: projection.coordsFromPoint(nextPoint);
		if (!nextCenter) return;
		if (typeof state.map.setCenter === "function") state.map.setCenter(nextCenter, { __allowClusterRestore: true });
		else if (typeof state.map.panTo === "function") state.map.panTo(nextCenter);
	};
	requestAnimationFrame(() => requestAnimationFrame(revealWhenPanelSettled));
}

function recordParcelInfoRecent(feature, address, info)
{
	const lat = Number(feature && feature.selectionLat);
	const lng = Number(feature && feature.selectionLng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
	const pnu = String(feature && feature.pnu || "").trim();
	const parcelAddress = String(address || "선택 필지").trim() || "선택 필지";
	const identity = pnu || parcelAddress || String(lat) + "," + String(lng);
	const jimok = String(feature && feature.jimok || info && info.jimok || "").trim();
	const landUseZone = String(feature && feature.landUseZone || info && info.landUseZone || "").trim();
	upsertSideCategoryRecentItem("parcel", {
		id: "parcel:" + identity,
		title: parcelAddress,
		summary: [jimok, landUseZone].filter(Boolean).join(" · "),
		action: "parcel-info",
		markerKey: pnu,
		lat,
		lng
	});
}

function openParcelLandInfoPanel(feature)
{
	if (!feature || !propertyList || !sidebarListTitle) return false;
	if (parcelAreaMeasureActive) deactivateParcelAreaMeasure();
	const hadOpenDetailPanel = !!state.leftListDetailMode
		&& propertyList.childElementCount > 0
		&& propertyList.getClientRects().length > 0;
	const isReplacingOpenParcelLandInfo = state.leftListDetailMode === "parcel-land-info"
		&& !!propertyList.querySelector(".parcel-land-info-panel");
	const isReplacingOpenParcelRegionStats = state.leftListDetailMode === "parcel-region-stats"
		&& !!propertyList.querySelector(".parcel-region-trade-stats-panel");
	if (isReplacingOpenParcelRegionStats && typeof cancelParcelRegionTradeStatsAfterZoom === "function") {
		cancelParcelRegionTradeStatsAfterZoom();
	}
	if (isReplacingOpenParcelLandInfo) {
		state.isListOpen = true;
		document.body.classList.remove("map-panels-collapsed");
	} else {
		if (typeof closeRightMapToolPanels === "function") closeRightMapToolPanels();
		if (typeof hardCloseDetailPanel === "function") hardCloseDetailPanel();
		if (typeof clearAgentListFilter === "function") clearAgentListFilter();
		if (typeof clearListLock === "function") clearListLock();
		if (typeof resetLeftListPagination === "function") resetLeftListPagination([]);
	}
	const info = feature.landCharacteristics || {};
	const possession = feature.landPossession || {};
	const address = formatParcelLandInfoAddress(feature.address || [info.legalDongName, info.jibun].filter(Boolean).join(" ") || feature.jibun || "선택 필지");
	const parcelAreaM2 = Number(feature.areaM2 || info.areaM2);
	const sharedOwnerCount = Number(possession.sharedOwnerCount);
	const ownershipType = String(possession.ownershipType || "").trim();
	const ownershipDisplay = ownershipType
		? ownershipType + (Number.isFinite(sharedOwnerCount) ? " (공유인수 " + new Intl.NumberFormat("ko-KR").format(sharedOwnerCount) + ")" : "")
		: "-";
	const rows = [
		["면적", formatParcelLandArea(parcelAreaM2), parcelAreaM2],
		["지목", feature.jimok || info.jimok],
		["용도지역", feature.landUseZone || info.landUseZone],
		["이용상황", feature.use || info.landUseSituation],
		["소유구분", ownershipDisplay],
		["소유권변동일자", possession.ownershipChangeDate],
		["소유권변동원인", possession.ownershipChangeCause],
		["도로접면", info.roadSide],
		["지형높이", info.terrainHeight],
		["지형형상", info.terrainShape]
	];
	state.leftListDetailMode = "parcel-land-info";
	state.leftListTitle = "부동산 정보";
	state.selectedClusterKey = null;
	state.selectedClusterAnchor = null;
	state.selectedMarkerId = null;
	state.selectedMarkerIds = new Set();
	state.selectionMode = "parcel-land-info";
	if (typeof updateMarkerSelection === "function") updateMarkerSelection(null, []);
	if (typeof refreshClusterBadges === "function") refreshClusterBadges();
	if (sidebarListShareBtn) sidebarListShareBtn.hidden = true;
	document.body.classList.remove("map-panels-collapsed");
	const parcelRoadAddress = String(feature.roadAddress || feature.road_address || "").trim();
	propertyList.innerHTML = '<article class="parcel-land-info-panel"><header class="parcel-land-info-address"><strong class="parcel-land-info-address-primary">' + escapeParcelLandInfoHtml(address) + '</strong>' + (parcelRoadAddress ? '<span class="parcel-land-info-address-road">' + escapeParcelLandInfoHtml(parcelRoadAddress) + '</span>' : "") + '</header><section class="parcel-land-info-section"><h2 class="parcel-land-info-section-title">토지 기본 정보</h2>' + rows.map(([label, value, rawValue]) => buildParcelLandInfoRow(label, value, rawValue)).join("") + '</section>' + (feature.landCharacteristicsStatus === "unavailable" ? '<div class="parcel-land-info-status">토지특성정보 서비스 승인 또는 조회 상태를 확인해 주세요.</div>' : "") + (feature.landPossessionStatus === "unavailable" && !/(?:아파트|연립|다세대|오피스텔|집합)/.test(String(feature.landUseSituation || (feature.landCharacteristics || {}).landUseSituation || "")) ? '<div class="parcel-land-info-status">토지소유정보 서비스 승인 또는 조회 상태를 확인해 주세요.</div>' : "") + buildParcelLandUsePlanSection(feature) + buildParcelLandMoveSection(feature) + buildParcelIndividualLandPriceSection(feature) + '</article>';
	syncSidebarListTitle();

	const parcelPropertyPanel = propertyList.querySelector(".parcel-land-info-panel");
	if (parcelPropertyPanel && typeof window.realjejuEnhanceParcelPropertyPanel === "function") {
		try {
			window.realjejuEnhanceParcelPropertyPanel(parcelPropertyPanel);
		} catch (error) {
			console.warn("[realjeju property info] synchronous enhancement failed", error);
		}
	}
	// 최종 정보 DOM을 먼저 완성한 뒤 지도 레이아웃을 한 번만 갱신합니다.
	openSidebarList({ singlePass: true });
	if (!propertyList.dataset.parcelLandAreaUnitDelegated) {
		propertyList.dataset.parcelLandAreaUnitDelegated = "true";
		propertyList.addEventListener("click", (event) => {
			const parcelLandAreaUnitToggle = event.target.closest("[data-parcel-land-area-unit-toggle]");
			if (!parcelLandAreaUnitToggle || !propertyList.contains(parcelLandAreaUnitToggle)) return;
			event.preventDefault();
			event.stopPropagation();
			toggleSharedAreaUnit();
		});
	}
	propertyList.scrollTop = 0;
	recordParcelInfoRecent(feature, address, info);
	scheduleParcelBoundaryViewportReveal(feature);
	if (!isReplacingOpenParcelLandInfo) {
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
	}
	return true;
}

async function showParcelBoundaryForSearchLocation(lat, lng, options = {})
{
	const latNum = Number(lat);
	const lngNum = Number(lng);
	if (!Number.isFinite(latNum) || !Number.isFinite(lngNum) || !state.map) {
		return false;
	}
	if (!isParcelBoundaryJejuCoordinate(latNum, lngNum)) return false;

	const requestToken = ++parcelBoundaryRequestToken;
	parcelBoundaryLoading = true;
	parcelBoundaryRenderError = "";

	let boundaryRendered = false;
	try {
		const boundaryFeature = await lookupParcelBoundaryByLatLng(latNum, lngNum, { boundaryOnly: true });
		if (requestToken !== parcelBoundaryRequestToken) {
			return false;
		}
		if (boundaryFeature) {
			boundaryFeature.selectionLat = latNum;
			boundaryFeature.selectionLng = lngNum;
		}
		if (!boundaryFeature || !renderParcelBoundaryOverlay(boundaryFeature)) {
			parcelBoundaryRenderError = "해당 위치의 토지 필지 경계를 찾지 못했습니다.";
			clearParcelBoundaryOverlays();
			return false;
		}
		boundaryRendered = true;
		parcelBoundaryFeature = boundaryFeature;
		if (!(options && options.openLandInfoPanel === true)) return true;

		const propertyInfoModuleRequest = typeof window.realjejuPreloadPropertyInfo === "function"
			? window.realjejuPreloadPropertyInfo()
			: Promise.resolve(true);
		const [feature] = await Promise.all([
			lookupParcelBoundaryByLatLng(latNum, lngNum, { boundaryOnly: false }),
			propertyInfoModuleRequest
		]);
		if (requestToken !== parcelBoundaryRequestToken) return false;
		if (feature) {
			feature.selectionLat = latNum;
			feature.selectionLng = lngNum;
		}
		if (!feature) return true;
		parcelBoundaryFeature = feature;
		if (feature.propertyInformationAvailable === true) {
			openParcelLandInfoPanel(feature);
		}
		return true;
	} catch (error) {
		if (requestToken !== parcelBoundaryRequestToken || (error && error.name === "AbortError")) {
			return true;
		}
		parcelBoundaryRenderError = String(error && error.message ? error.message : "필지 경계 조회 중 오류가 발생했습니다.");
		if (!boundaryRendered) clearParcelBoundaryOverlays();
		if (typeof console !== "undefined" && console.error) {
			console.error("[realjeju parcel]", parcelBoundaryRenderError);
		}
		return false;
	} finally {
		if (requestToken === parcelBoundaryRequestToken) {
			parcelBoundaryLoading = false;
		}
	}
}

async function handleParcelBoundaryMapClick(mouseEvent)
{
	if (shouldSuppressParcelMapClickAfterDrag()) return false;
	if (isParcelMapClickBlockedByFacilityMarker()) return false;
	const currentCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: "realestate";
	const currentMapLevel = state.map && typeof state.map.getLevel === "function"
		? Number(state.map.getLevel())
		: NaN;
	if (
		currentCategory !== "parcel"
		|| document.body.classList.contains("main-landing-page-open")
		|| isPresaleMapMode()
		|| isPickaxeModeActive
		|| distanceMeasureActive
		|| isMapRoadviewOverlayVisible
		|| !Number.isFinite(currentMapLevel)
		|| currentMapLevel > 5
		|| !mouseEvent
		|| !mouseEvent.latLng
		|| typeof mouseEvent.latLng.getLat !== "function"
		|| typeof mouseEvent.latLng.getLng !== "function"
	) {
		return false;
	}
	const lat = Number(mouseEvent.latLng.getLat());
	const lng = Number(mouseEvent.latLng.getLng());
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;
	if (!state.map) return false;
	return await showParcelBoundaryForSearchLocation(lat, lng, { openLandInfoPanel: true });
}

