function changeMobileMapZoom(levelDelta)
{
	const map = state && state.map;
	if (!map || typeof map.getLevel !== "function" || typeof map.setLevel !== "function") return;
	const currentLevel = Number(map.getLevel());
	if (!Number.isFinite(currentLevel)) return;
	const nextLevel = Math.max(1, Math.min(14, currentLevel + levelDelta));
	if (nextLevel === currentLevel) return;
	map.setLevel(nextLevel, { animate: { duration: 180 } });
}

if (mobileMapZoomInBtn) mobileMapZoomInBtn.addEventListener("click", () => changeMobileMapZoom(-1));
if (mobileMapZoomOutBtn) mobileMapZoomOutBtn.addEventListener("click", () => changeMobileMapZoom(1));

