function getGeoJsonOuterRings(geometry)
{
	if (!geometry || !Array.isArray(geometry.coordinates)) return [];
	if (geometry.type === "Polygon") {
		return Array.isArray(geometry.coordinates[0]) ? [geometry.coordinates[0]] : [];
	}
	if (geometry.type === "MultiPolygon") {
		return geometry.coordinates
		.map(polygon => Array.isArray(polygon) ? polygon[0] : null)
		.filter(ring => Array.isArray(ring));
	}
	return [];
}

function clearAdminBoundaryOverlay()
{
	adminBoundaryOverlayPolygons.forEach(polygon => {
		if (polygon && typeof polygon.setMap === "function") polygon.setMap(null);
	});
	adminBoundaryOverlayPolygons = [];
}

async function loadAdminBoundaryGeoJson(type)
{
	const supportedKeys = new Set(["emd", "lio", "sig", "local", "province"]);
	const key = supportedKeys.has(type) ? type : "emd";
	if (adminBoundaryGeoJsonCache[key]) return adminBoundaryGeoJsonCache[key];
	if (adminBoundaryGeoJsonPromiseCache[key]) return adminBoundaryGeoJsonPromiseCache[key];
	if (key === "local") {
		const request = Promise.all([
			loadAdminBoundaryGeoJson("lio"),
			loadAdminBoundaryGeoJson("emd")
		])
		.then(([lioData, emdData]) => {
			const riFeatures = Array.isArray(lioData && lioData.features) ? lioData.features : [];
			const dongFeatures = (Array.isArray(emdData && emdData.features) ? emdData.features : [])
			.filter((feature) => /동$/.test(getAdminBoundaryFeatureName(feature)));
			const data = {
				type: "FeatureCollection",
				name: "제주 리·동 경계",
				features: riFeatures.concat(dongFeatures)
			};
			adminBoundaryGeoJsonCache[key] = data;
			return data;
		})
		.finally(() => {
			if (adminBoundaryGeoJsonPromiseCache[key] === request) adminBoundaryGeoJsonPromiseCache[key] = null;
		});
		adminBoundaryGeoJsonPromiseCache[key] = request;
		return request;
	}
	if (key === "province") {
		const request = loadAdminBoundaryGeoJson("sig")
		.then((sigData) => {
			const polygons = [];
			(Array.isArray(sigData && sigData.features) ? sigData.features : []).forEach((feature) => {
				const geometry = feature && feature.geometry;
				if (!geometry || !Array.isArray(geometry.coordinates)) return;
				if (geometry.type === "Polygon") polygons.push(geometry.coordinates);
				else if (geometry.type === "MultiPolygon") geometry.coordinates.forEach((polygon) => polygons.push(polygon));
			});
			const data = {
				type: "FeatureCollection",
				name: "제주도 경계",
				features: [{
					type: "Feature",
					properties: { level: "province", code: "50", name: "제주도" },
					geometry: { type: "MultiPolygon", coordinates: polygons }
				}]
			};
			adminBoundaryGeoJsonCache[key] = data;
			return data;
		})
		.finally(() => {
			if (adminBoundaryGeoJsonPromiseCache[key] === request) adminBoundaryGeoJsonPromiseCache[key] = null;
		});
		adminBoundaryGeoJsonPromiseCache[key] = request;
		return request;
	}
	const sourceUrl = key === "sig" ? ADMIN_BOUNDARY_SIG_URL : (key === "lio" ? ADMIN_BOUNDARY_LIO_URL : ADMIN_BOUNDARY_EMD_URL);
	const url = resolveRealjejuLocalAssetUrl(sourceUrl);
	const request = fetch(url)
		.then((response) => {
			if (!response.ok) throw new Error(`행정구역 경계 파일 로드 실패: ${response.status}`);
			return response.json();
		})
		.then((data) => {
			adminBoundaryGeoJsonCache[key] = data;
			return data;
		})
		.finally(() => {
			if (adminBoundaryGeoJsonPromiseCache[key] === request) adminBoundaryGeoJsonPromiseCache[key] = null;
		});
	adminBoundaryGeoJsonPromiseCache[key] = request;
	return request;
}

function getAdminBoundaryFeatureBBox(feature)
{
	if (!feature || !feature.geometry) return null;
	if (feature.__realjejuBoundaryBBox) return feature.__realjejuBoundaryBBox;
	const bbox = [Infinity, Infinity, -Infinity, -Infinity];
	function visit(coords)
	{
		if (!Array.isArray(coords)) return;
		if (typeof coords[0] === "number" && typeof coords[1] === "number") {
			const lng = Number(coords[0]);
			const lat = Number(coords[1]);
			if (Number.isFinite(lng) && Number.isFinite(lat)) {
				bbox[0] = Math.min(bbox[0], lng);
				bbox[1] = Math.min(bbox[1], lat);
				bbox[2] = Math.max(bbox[2], lng);
				bbox[3] = Math.max(bbox[3], lat);
			}
			return;
		}
		coords.forEach(visit);
	}
	visit(feature.geometry.coordinates);
	if (!bbox.every(Number.isFinite)) return null;
	feature.__realjejuBoundaryBBox = bbox;
	return bbox;
}

function isPointInAdminBoundaryRing(point, ring)
{
	if (!Array.isArray(point) || !Array.isArray(ring) || ring.length < 3) return false;
	const x = Number(point[0]);
	const y = Number(point[1]);
	let inside = false;
	for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
		const xi = Number(ring[i][0]);
		const yi = Number(ring[i][1]);
		const xj = Number(ring[j][0]);
		const yj = Number(ring[j][1]);
		if (![xi, yi, xj, yj].every(Number.isFinite)) continue;
		const intersect = ((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / (yj - yi) + xi);
		if (intersect) inside = !inside;
	}
	return inside;
}

function doesAdminBoundaryFeatureContainPoint(feature, point)
{
	const bbox = getAdminBoundaryFeatureBBox(feature);
	if (bbox && point) {
		const lng = Number(point[0]);
		const lat = Number(point[1]);
		if (lng < bbox[0] || lng > bbox[2] || lat < bbox[1] || lat > bbox[3]) return false;
	}
	const geometry = feature && feature.geometry;
	if (!geometry || !Array.isArray(geometry.coordinates)) return false;
	const polygons = geometry.type === "Polygon" ? [geometry.coordinates] : geometry.coordinates;
	if (!Array.isArray(polygons)) return false;
	return polygons.some(polygon => {
		if (!Array.isArray(polygon) || !polygon.length) return false;
		if (!isPointInAdminBoundaryRing(point, polygon[0])) return false;
		return !polygon.slice(1).some(hole => isPointInAdminBoundaryRing(point, hole));
	});
}

function findAdminBoundaryFeatureAtCenter(features, point)
{
	if (!Array.isArray(features) || !point) return null;
	return features.find(feature => doesAdminBoundaryFeatureContainPoint(feature, point)) || null;
}

function hasAdminBoundarySelectedPoint()
{
	return Array.isArray(adminBoundarySelectedPoint)
		&& adminBoundarySelectedPoint.length >= 2
		&& adminBoundarySelectedPoint.every(Number.isFinite);
}

function getAdminBoundaryDataTypeForPresentationMode(mode = getPropertyMapPresentationMode())
{
	if (mode === "province-count") return "province";
	if (mode === "city-counts") return "sig";
	if (mode === "local-counts") return "local";
	if (mode === "clusters" || mode === "individual") return "local";
	return "emd";
}

async function findAdminBoundaryFeatureForPoint(point, mode = getPropertyMapPresentationMode())
{
	if (!Array.isArray(point) || point.length < 2 || !point.every(Number.isFinite)) return null;

	const data = await loadAdminBoundaryGeoJson(getAdminBoundaryDataTypeForPresentationMode(mode));
	return findAdminBoundaryFeatureAtCenter(data && data.features, point);
}

function getParcelMapLevelProfile(level = getAdminBoundaryLevel())
{
	const normalizedLevel = Number(level);
	if (!Number.isFinite(normalizedLevel)) {
		return { presentationMode: "local-counts", clickMode: "parcel" };
	}
	if (normalizedLevel >= 10) return { presentationMode: "province-count", clickMode: "region-stats" };
	if (normalizedLevel >= 9) return { presentationMode: "city-counts", clickMode: "region-stats" };
	if (normalizedLevel >= 8) return { presentationMode: "district-counts", clickMode: "region-stats" };
	if (normalizedLevel >= 6) return { presentationMode: "local-counts", clickMode: "region-stats" };
	return { presentationMode: "local-counts", clickMode: "parcel" };
}

function handleAdminBoundaryMapClick(mouseEvent)
{
	const mode = getPropertyMapPresentationMode();
	const shouldUseParcelAdminBoundary = shouldUseParcelAdminBoundaryPresentation();
	const currentCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	if (currentCategory === "realestate" && !propertyHomeAdminBoundaryEnabled) return false;
	const currentMapLevel = getAdminBoundaryLevel();
	const shouldUseRealestateLocalBoundary = currentCategory === "realestate"
		&& Number.isFinite(currentMapLevel)
		&& currentMapLevel >= 1
		&& currentMapLevel <= 5;
	const shouldHandleAdminBoundary = currentCategory === "parcel"
		? shouldUseParcelAdminBoundary
		: (shouldUseAdminBoundaryMapLevelPresentation() || shouldUseRealestateLocalBoundary);
	if (
		!shouldHandleAdminBoundary
		|| !mouseEvent
		|| !mouseEvent.latLng
		|| typeof mouseEvent.latLng.getLng !== "function"
		|| typeof mouseEvent.latLng.getLat !== "function"
	) return false;
	const point = [Number(mouseEvent.latLng.getLng()), Number(mouseEvent.latLng.getLat())];
	if (!point.every(Number.isFinite)) return false;
	const propertyHomeRequestToken = currentCategory === "realestate"
		? ++propertyHomeAdminBoundaryRequestToken
		: 0;
	if (typeof kakao.maps.event.preventMap === "function") kakao.maps.event.preventMap();
	clearParcelBoundaryRenderState();
	adminBoundarySelectedPoint = point;
	selectedPropertyRegionBoundaryFeature = null;
	hideAdminBoundaryBottomPill();
	void (async () => {
		const boundaryMode = shouldUseRealestateLocalBoundary ? "local-counts" : mode;
		const feature = await findAdminBoundaryFeatureForPoint(point, boundaryMode);
		if (currentCategory === "realestate" && (
			!propertyHomeAdminBoundaryEnabled
			|| propertyHomeRequestToken !== propertyHomeAdminBoundaryRequestToken
			|| getCurrentRealjejuGlobalCategoryKey() !== "realestate"
		)) return;
		if (!feature) return;
		if (
			!hasAdminBoundarySelectedPoint()
			|| adminBoundarySelectedPoint[0] !== point[0]
			|| adminBoundarySelectedPoint[1] !== point[1]
		) return;
		selectedPropertyRegionBoundaryFeature = feature;
		await renderAdminBoundaryOverlay();
		try {
			const stats = await loadPropertyScaleFeatureStats(feature);
			if (currentCategory === "realestate" && (
				!propertyHomeAdminBoundaryEnabled
				|| propertyHomeRequestToken !== propertyHomeAdminBoundaryRequestToken
				|| getCurrentRealjejuGlobalCategoryKey() !== "realestate"
			)) return;
			if (feature) updateAdminBoundaryBottomPill(feature, stats.listingCount);
		} catch (error) {
			console.warn("행정구역 매물 수 조회 실패", error);
		}
	})();
	return true;
}

function getAdminBoundaryLevel()
{
	if (!state.map || typeof state.map.getLevel !== "function") return NaN;
	const level = Number(state.map.getLevel());
	return Number.isFinite(level) ? level : NaN;
}

function getAdminBoundaryStyle()
{
	const preference = getAdminBoundaryStylePreference();
	return {
		strokeWeight: 2,
		strokeColor: preference.color,
		strokeOpacity: 1,
		strokeStyle: ADMIN_BOUNDARY_STROKE_STYLE,
		fillColor: preference.color,
		fillOpacity: preference.opacity
	};
}

function shouldShowPropertyScaleAdminBoundaryOverlay()
{
	if (!state.map || !window.kakao || !kakao.maps) return false;
	const shouldUseParcelAdminBoundary = shouldUseParcelAdminBoundaryPresentation()
		|| shouldShowParcelBadgeSelectedAdminBoundary();
	const mode = getPropertyMapPresentationMode();
	const currentCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	if (currentCategory === "realestate" && !propertyHomeAdminBoundaryEnabled) return false;
	const shouldKeepRealestateLocalBoundary = currentCategory === "realestate"
		&& (mode === "clusters" || mode === "individual");
	if (typeof shouldUseAdminBoundaryMapLevelPresentation === "function"
		&& !shouldUseAdminBoundaryMapLevelPresentation()
		&& !shouldUseParcelAdminBoundary
		&& !shouldKeepRealestateLocalBoundary) return false;
	if (shouldUseParcelAdminBoundary) {
		return hasAdminBoundarySelectedPoint() || !!selectedPropertyRegionBoundaryFeature;
	}
	return (mode === "clusters" || mode === "individual" || isPropertyRegionCountMode(mode))
		&& (hasAdminBoundarySelectedPoint() || !!selectedPropertyRegionBoundaryFeature);
}

function shouldUseParcelAdminBoundaryPresentation()
{
	const currentCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: "realestate";
	return currentCategory === "parcel"
		&& getParcelMapLevelProfile().clickMode === "region-stats";
}

function shouldShowParcelBadgeSelectedAdminBoundary()
{
	const currentCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: "realestate";
	return currentCategory === "parcel"
		&& !!selectedPropertyRegionBoundaryFeature
		&& (
			!!selectedPropertyRegionCountKey
			|| state.leftListDetailMode === "parcel-region-stats"
		);
}

const PARCEL_REGION_TRADE_TYPE_OPTIONS = Object.freeze([
	{ key: "land", label: "토지", serviceTypes: ["land-sale"] },
	{ key: "apartment", label: "아파트", serviceTypes: ["apt-sale"] },
	{ key: "rowhouse", label: "연립·다세대", serviceTypes: ["rowhouse-sale"] },
	{ key: "single-house", label: "단독·다가구", serviceTypes: ["single-house-sale"] },
	{ key: "officetel", label: "오피스텔", serviceTypes: ["officetel-sale"] },
	{ key: "commercial-building", label: "상업용건물", serviceTypes: ["commercial-sale"] }
]);

const PARCEL_REGION_TRADE_PERIOD_OPTIONS = Object.freeze([1, 3, 6, 12]);

const PARCEL_REGION_TRADE_METRIC_OPTIONS = Object.freeze([
	{ key: "totalAmount", label: "거래총액" },
	{ key: "count", label: "거래건수" },
	{ key: "unitPrice", label: "면적당 단가" }
]);

const parcelRegionTradeStatsCache = new Map();

const parcelRegionTradeStatsInFlight = new Map();

const parcelRegionTradeMetaPromiseCache = new WeakMap();

const parcelRegionTradeBadgeRenderInFlight = new Map();

let parcelRegionTradeBadgeRenderedSignature = "";

let parcelRegionTradeStatsRequestToken = 0;

let parcelRegionTradeStatsAnchorPoint = null;

let parcelRegionTradeZoomSyncToken = 0;

let parcelRegionTradeZoomSyncTimer = null;

let parcelRegionTradeZoomIdleHandler = null;

let parcelRegionTradeMapDragSuppressUntil = 0;

let parcelRegionTradeSelection = { type: "land", months: 12, metric: "totalAmount" };

let parcelRegionTradeCurrentMeta = null;

let parcelRegionTradeCurrentData = null;

let parcelRegionTradeCurrentError = "";

function normalizeParcelRegionTradeSelection(selection = {})
{
	const type = getParcelRegionTradeTypeOption(selection.type || parcelRegionTradeSelection.type).key;
	const monthsValue = Number(selection.months || parcelRegionTradeSelection.months);
	const months = PARCEL_REGION_TRADE_PERIOD_OPTIONS.includes(monthsValue) ? monthsValue : 12;
	const metricValue = String(selection.metric || parcelRegionTradeSelection.metric || "totalAmount");
	const metric = PARCEL_REGION_TRADE_METRIC_OPTIONS.some((option) => option.key === metricValue)
		? metricValue
		: "totalAmount";
	return { type, months, metric };
}

function getParcelRegionTradePresentationMode()
{
	return getParcelMapLevelProfile().presentationMode;
}

function getParcelRegionTradeBoundaryDataType()
{
	return getAdminBoundaryDataTypeForPresentationMode(getParcelRegionTradePresentationMode());
}

function doesParcelRegionTradeFeatureMatchMode(feature, mode = getParcelRegionTradePresentationMode())
{
	const rawCode = String(getAdminBoundaryFeatureCodeValue(feature) || "");
	const code = rawCode.replace(/\D/g, "");
	const name = normalizeRegionDongName(getAdminBoundaryFeatureName(feature));
	if (mode === "province-count") return rawCode === "jeju-province" || code === "50";
	if (mode === "city-counts") return code === "50110" || code === "50130";
	if (mode === "district-counts") return code.length === 8;
	return code.length >= 10 || (code.length === 8 && /동$/.test(name));
}

function getParcelRegionTradeFeatureInteriorPoint(feature)
{
	if (!feature) return null;
	const mapCenter = state.map && typeof state.map.getCenter === "function" ? state.map.getCenter() : null;
	const mapPoint = mapCenter ? [Number(mapCenter.getLng()), Number(mapCenter.getLat())] : null;
	if (mapPoint && mapPoint.every(Number.isFinite)
		&& isParcelRegionTradePointInFeature(mapPoint[0], mapPoint[1], feature)) return mapPoint;
	const preferred = typeof getAdminBoundaryFeatureAnchor === "function"
		? getAdminBoundaryFeatureAnchor(feature)
		: null;
	if (Array.isArray(preferred) && preferred.length >= 2
		&& preferred.every(Number.isFinite)
		&& isParcelRegionTradePointInFeature(preferred[0], preferred[1], feature)) return preferred.slice(0, 2);
	const rings = getGeoJsonOuterRings(feature.geometry);
	for (const ring of rings) {
		const points = (Array.isArray(ring) ? ring : [])
			.filter((point) => Array.isArray(point) && Number.isFinite(Number(point[0])) && Number.isFinite(Number(point[1])))
			.map((point) => [Number(point[0]), Number(point[1])]);
		if (!points.length) continue;
		let minLng = Infinity;
		let maxLng = -Infinity;
		let minLat = Infinity;
		let maxLat = -Infinity;
		points.forEach((point) => {
			minLng = Math.min(minLng, point[0]);
			maxLng = Math.max(maxLng, point[0]);
			minLat = Math.min(minLat, point[1]);
			maxLat = Math.max(maxLat, point[1]);
		});
		for (let row = 1; row <= 9; row += 1) {
			for (let column = 1; column <= 9; column += 1) {
				const candidate = [
					minLng + ((maxLng - minLng) * column) / 10,
					minLat + ((maxLat - minLat) * row) / 10
				];
				if (isParcelRegionTradePointInFeature(candidate[0], candidate[1], feature)) return candidate;
			}
		}
	}
	return null;
}

async function resolveParcelRegionTradeFeatureForCurrentLevel(feature)
{
	if (!feature || doesParcelRegionTradeFeatureMatchMode(feature)) return feature;
	const sourceCode = String(getAdminBoundaryFeatureCodeValue(feature) || "").replace(/\D/g, "");
	const data = await loadAdminBoundaryGeoJson(getParcelRegionTradeBoundaryDataType());
	const features = Array.isArray(data?.features) ? data.features : [];
	const mode = getParcelRegionTradePresentationMode();
	const expectedCode = mode === "city-counts"
		? sourceCode.slice(0, 5)
		: (mode === "district-counts" ? sourceCode.slice(0, 8) : sourceCode);
	const exactFeature = expectedCode
		? features.find((candidate) => String(getAdminBoundaryFeatureCodeValue(candidate) || "").replace(/\D/g, "") === expectedCode)
		: null;
	if (exactFeature) return exactFeature;
	const point = getParcelRegionTradeFeatureInteriorPoint(feature);
	return point ? findAdminBoundaryFeatureAtCenter(features, point) : feature;
}

function closeParcelRegionTradePickerSurface(options = {})
{
	const surface = document.querySelector("[data-parcel-region-trade-picker-surface]");
	if (surface) surface.remove();
	document.body.classList.remove("parcel-region-trade-picker-modal-open");
	const panel = document.getElementById("sidebarDetailPanel");
	if (panel) panel.classList.remove("parcel-region-trade-picker-open");
}

function openParcelRegionTradePicker(kind)
{
	if (!parcelRegionTradeCurrentMeta || state.leftListDetailMode !== "parcel-region-stats") return false;
	const panel = document.getElementById("sidebarDetailPanel");
	if (!panel) return false;
	const config = kind === "type"
		? { title: "부동산 유형", options: PARCEL_REGION_TRADE_TYPE_OPTIONS.map((option) => ({ value: option.key, label: option.label })) }
		: (kind === "months"
			? { title: "통계 기간", options: PARCEL_REGION_TRADE_PERIOD_OPTIONS.map((months) => ({ value: String(months), label: `${months}개월` })) }
			: { title: "통계 기준", options: PARCEL_REGION_TRADE_METRIC_OPTIONS.map((option) => ({ value: option.key, label: option.label })) });
	const currentValue = kind === "months"
		? String(parcelRegionTradeSelection.months)
		: String(parcelRegionTradeSelection[kind] || "");
	closeParcelRegionTradePickerSurface({ keepPanelOpen: true });
	const surface = document.createElement("section");
	surface.className = "parcel-building-unit-picker";
	surface.setAttribute("data-parcel-building-unit-picker", "true");
	surface.setAttribute("data-parcel-region-trade-picker-surface", "true");
	surface.dataset.parcelRegionTradePickerStandalone = "true";
	surface.setAttribute("aria-label", config.title);
	surface.innerHTML = `
		<div class="parcel-building-unit-picker-dialog" role="dialog" aria-modal="true" aria-label="${escapeHtml(config.title)}">
			<header><span aria-hidden="true"></span><h2>${escapeHtml(config.title)}</h2><button type="button" class="parcel-exact-area-close" data-parcel-region-picker-close aria-label="선택창 닫기"></button></header>
			<div class="parcel-building-unit-picker-list">
				${config.options.map((option) => `<button type="button" data-parcel-region-picker-value="${escapeHtml(option.value)}" class="parcel-building-unit-picker-row${String(option.value) === currentValue ? " is-selected" : ""}"><i aria-hidden="true"></i><span>${escapeHtml(option.label)}</span></button>`).join("")}
			</div>
		</div>
	`;
	document.body.appendChild(surface);
	document.body.classList.add("parcel-region-trade-picker-modal-open");
	surface.querySelector("[data-parcel-region-picker-close]")?.addEventListener("click", () => closeParcelRegionTradePickerSurface());
	surface.addEventListener("click", (event) => {
		if (event.target === surface) closeParcelRegionTradePickerSurface();
	});
	surface.querySelectorAll("[data-parcel-region-picker-value]").forEach((button) => {
		button.addEventListener("click", () => {
			const value = String(button.dataset.parcelRegionPickerValue || "");
			parcelRegionTradeSelection = normalizeParcelRegionTradeSelection({
				...parcelRegionTradeSelection,
				[kind]: kind === "months" ? Number(value) : value
			});
			closeParcelRegionTradePickerSurface();
			void loadParcelRegionTradeStatsPanel(parcelRegionTradeCurrentMeta, parcelRegionTradeSelection);
			if (shouldRenderParcelRegionTradeMapBadges(getPropertyMapPresentationMode())) {
				void renderPropertyRegionCountOverlays(getPropertyMapPresentationMode());
			}
		});
	});
	return true;
}

function getParcelRegionTradeTypeOption(key)
{
	return PARCEL_REGION_TRADE_TYPE_OPTIONS.find((option) => option.key === key)
		|| PARCEL_REGION_TRADE_TYPE_OPTIONS[0];
}

function formatParcelRegionTradeMoney(value, options = {})
{
	const amount = Number(value);
	if (!Number.isFinite(amount) || amount <= 0) return "-";
	if (options.unitPrice === true) {
		return `${(amount / 10000).toLocaleString("ko-KR", { maximumFractionDigits: 2 })}만원`;
	}
	if (amount >= 100000000) {
		return `${(amount / 100000000).toLocaleString("ko-KR", { maximumFractionDigits: 2 })}억`;
	}
	return `${(amount / 10000).toLocaleString("ko-KR", { maximumFractionDigits: 1 })}만원`;
}

function getParcelRegionTradeUnitLabel() {
  return globalAreaUnit === "py" ? "평당 단가" : "㎡당 단가";
}

function getParcelRegionTradeUnitPrice(period) {
  const unitPriceKrwM2 = Number(period?.unitPriceKrwM2 || 0);
  return globalAreaUnit === "py" ? unitPriceKrwM2 * 3.305785 : unitPriceKrwM2;
}

function getParcelRegionTradeMetricValue(period, metric) {
  if (!period) return 0;
  if (metric === "count") return Number(period.count || 0);
  if (metric === "totalAmount") return Number(period.totalAmountKrw || 0);
  return getParcelRegionTradeUnitPrice(period);
}

function formatParcelRegionTradeMetric(period, metric)
{
	const value = getParcelRegionTradeMetricValue(period, metric);
	if (metric === "count") return `${value.toLocaleString("ko-KR")}건`;
	return formatParcelRegionTradeMoney(value, { unitPrice: metric === "unitPrice" });
}

function getParcelRegionTradeChange(previous, recent, metric)
{
	const before = getParcelRegionTradeMetricValue(previous, metric);
	const after = getParcelRegionTradeMetricValue(recent, metric);
	if (before <= 0) return after > 0 ? { label: "신규", direction: "up" } : { label: "-", direction: "flat" };
	const rate = ((after - before) / before) * 100;
	return {
		label: `${Math.abs(rate).toLocaleString("ko-KR", { maximumFractionDigits: 2 })}%`,
		direction: rate > 0 ? "up" : (rate < 0 ? "down" : "flat")
	};
}

function buildParcelRegionTradeDeltaHtml(previousValue, recentValue, options = {})
{
	const before = Number(previousValue || 0);
	const after = Number(recentValue || 0);
	const difference = after - before;
	if (!Number.isFinite(before) || !Number.isFinite(after)) return "";
	if (difference === 0) {
		return '<span class="parcel-region-trade-delta is-flat"><strong>0%</strong><small>(변동 없음)</small></span>';
	}
	const direction = difference > 0 ? "up" : "down";
	const arrow = difference > 0 ? "▲" : "▼";
	const rateLabel = before > 0
		? `${Math.abs((difference / before) * 100).toLocaleString("ko-KR", { maximumFractionDigits: 2 })}%`
		: "신규";
	const absoluteDifference = Math.abs(difference);
	const differenceLabel = options.count === true
		? `${absoluteDifference.toLocaleString("ko-KR", { maximumFractionDigits: 0 })}건`
		: formatParcelRegionTradeMoney(absoluteDifference, { unitPrice: options.unitPrice === true });
	return `<span class="parcel-region-trade-delta is-${direction}"><strong>${rateLabel} ${arrow}</strong><small>(${difference > 0 ? "+" : "-"}${differenceLabel})</small></span>`;
}

const PARCEL_REGION_TRADE_RI_PARENT_BY_CODE_PREFIX = Object.freeze({
	"50110250": "한림읍",
	"50110253": "애월읍",
	"50110256": "구좌읍",
	"50110259": "조천읍",
	"50110310": "한경면",
	"50110320": "추자면",
	"50110330": "우도면",
	"50130250": "대정읍",
	"50130253": "남원읍",
	"50130259": "성산읍",
	"50130310": "안덕면",
	"50130320": "표선면"
});

function getParcelRegionTradeRiHeadingParent(regionCode, regionName)
{
	if (!/리$/.test(String(regionName || ""))) return "";
	const digits = String(regionCode || "").replace(/\D/g, "");
	return PARCEL_REGION_TRADE_RI_PARENT_BY_CODE_PREFIX[digits.slice(0, 8)] || "";
}

function buildParcelRegionTradeMeta(regionFeature, parcelFeature)
{
	const rawRegionCode = String(getAdminBoundaryFeatureCodeValue(regionFeature) || "");
	const regionCode = rawRegionCode === "jeju-province"
		? "50"
		: rawRegionCode.replace(/\D/g, "");
	const regionName = normalizeRegionDongName(getAdminBoundaryFeatureName(regionFeature));
	const isProvinceRegion = regionCode.length === 2;
	const city = isProvinceRegion ? "" : (regionCode.startsWith("50130") ? "서귀포시" : "제주시");
	const isCityRegion = regionCode.length === 5;
	const sourceAddress = String(parcelFeature?.address || parcelFeature?.jibunAddress || "").trim();
	const addressRegions = sourceAddress.match(/[^\s]+(?:읍|면|동|리)(?=\s|$)/g) || [];
	let parentName = isProvinceRegion
		? ""
		: isCityRegion
		? "제주특별자치도"
		: (/리$/.test(regionName)
		? String(addressRegions.slice(0, -1).reverse().find((name) => /(?:읍|면)$/.test(name)) || "")
		: "");
	// 지도 뱃지를 그릴 때 경계마다 부모 읍ㆍ면을 비동기로 역탐색하지 않습니다.
	// 부모가 없는 리 경계는 아래 DB 정적 행 매칭에서 region_name_key의 마지막
	// 지역명으로 연결해, 화면 진입 시 별도 백그라운드 계산이 돌지 않게 합니다.
	const headingRiParentName = parentName || getParcelRegionTradeRiHeadingParent(regionCode, regionName);
	const headingName = /리$/.test(regionName)
		? [headingRiParentName, regionName].filter(Boolean).join(" ")
		: (/동$/.test(regionName) && !isCityRegion
			? [city, regionName].filter(Boolean).join(" ")
			: regionName);
	const headingParentName = /리$/.test(regionName)
		? city
		: (/동$/.test(regionName) && !isCityRegion ? "" : (city !== regionName ? city : parentName));
	// 시 단위는 5자리 시군구 코드 자체가 범위 조건입니다. 시 이름을 읍면동명
	// 필터에 다시 넣으면 모든 거래가 제외되므로 시 단위 이름 필터는 비웁니다.
	const regionNames = (isProvinceRegion || isCityRegion) ? [] : [headingRiParentName, regionName].filter(Boolean);
	return {
		regionCode,
		regionName,
		parentName,
		city,
		headingName,
		headingParentName,
		regionNames,
		displayName: (isProvinceRegion
			? [regionName || "제주도"]
			: isCityRegion
				? [regionName]
				: [city, parentName, regionName])
			.filter((name, index, list) => name && list.indexOf(name) === index)
			.join(" ")
	};
}

function isParcelRegionTradePointInRing(lng, lat, ring)
{
	if (!Array.isArray(ring) || ring.length < 3) return false;
	let inside = false;
	for (let index = 0, previous = ring.length - 1; index < ring.length; previous = index, index += 1) {
		const currentPoint = ring[index];
		const previousPoint = ring[previous];
		if (!Array.isArray(currentPoint) || !Array.isArray(previousPoint)) continue;
		const currentLng = Number(currentPoint[0]);
		const currentLat = Number(currentPoint[1]);
		const previousLng = Number(previousPoint[0]);
		const previousLat = Number(previousPoint[1]);
		if (![currentLng, currentLat, previousLng, previousLat].every(Number.isFinite)) continue;
		const crosses = ((currentLat > lat) !== (previousLat > lat))
			&& (lng < ((previousLng - currentLng) * (lat - currentLat)) / ((previousLat - currentLat) || Number.EPSILON) + currentLng);
		if (crosses) inside = !inside;
	}
	return inside;
}

function isParcelRegionTradePointInFeature(lng, lat, feature)
{
	const geometry = feature?.geometry;
	if (!geometry || !Array.isArray(geometry.coordinates)) return false;
	const polygons = geometry.type === "Polygon"
		? [geometry.coordinates]
		: (geometry.type === "MultiPolygon" ? geometry.coordinates : []);
	return polygons.some((polygon) => {
		if (!Array.isArray(polygon) || !polygon[0] || !isParcelRegionTradePointInRing(lng, lat, polygon[0])) return false;
		return !polygon.slice(1).some((hole) => isParcelRegionTradePointInRing(lng, lat, hole));
	});
}

function getParcelRegionTradePointSegmentDistanceMeters(lng, lat, start, end)
{
	if (!Array.isArray(start) || !Array.isArray(end)) return Infinity;
	const startLng = Number(start[0]);
	const startLat = Number(start[1]);
	const endLng = Number(end[0]);
	const endLat = Number(end[1]);
	if (![lng, lat, startLng, startLat, endLng, endLat].every(Number.isFinite)) return Infinity;
	const lngScale = 111320 * Math.max(0.2, Math.cos((lat * Math.PI) / 180));
	const latScale = 110540;
	const startX = (startLng - lng) * lngScale;
	const startY = (startLat - lat) * latScale;
	const endX = (endLng - lng) * lngScale;
	const endY = (endLat - lat) * latScale;
	const deltaX = endX - startX;
	const deltaY = endY - startY;
	const lengthSquared = deltaX * deltaX + deltaY * deltaY;
	if (lengthSquared <= Number.EPSILON) return Math.hypot(startX, startY);
	const ratio = Math.max(0, Math.min(1, -((startX * deltaX) + (startY * deltaY)) / lengthSquared));
	return Math.hypot(startX + deltaX * ratio, startY + deltaY * ratio);
}

function getParcelRegionTradeFeatureBoundaryDistanceMeters(feature, lng, lat)
{
	const rings = getGeoJsonOuterRings(feature?.geometry);
	let nearestDistance = Infinity;
	for (const ring of rings) {
		if (!Array.isArray(ring) || ring.length < 2) continue;
		for (let index = 0; index < ring.length; index += 1) {
			const nextIndex = (index + 1) % ring.length;
			nearestDistance = Math.min(
				nearestDistance,
				getParcelRegionTradePointSegmentDistanceMeters(lng, lat, ring[index], ring[nextIndex])
			);
		}
	}
	return nearestDistance;
}

function getParcelRegionTradeNearestFeatureLimitMeters(mode = getParcelRegionTradePresentationMode())
{
	if (mode === "province-count") return 20000;
	if (mode === "city-counts") return 12000;
	if (mode === "district-counts") return 5000;
	return 2500;
}

function findNearestParcelRegionTradeFeature(features, lng, lat)
{
	const mode = getParcelRegionTradePresentationMode();
	const maxDistance = getParcelRegionTradeNearestFeatureLimitMeters(mode);
	const candidates = (Array.isArray(features) ? features : [])
		.filter((feature) => doesParcelRegionTradeFeatureMatchMode(feature, mode))
		.map((feature) => {
			const bbox = getAdminBoundaryFeatureBBox(feature);
			if (!bbox) return { feature, bboxDistance: Infinity };
			const nearestLng = Math.max(bbox[0], Math.min(lng, bbox[2]));
			const nearestLat = Math.max(bbox[1], Math.min(lat, bbox[3]));
			return {
				feature,
				bboxDistance: getParcelRegionTradePointSegmentDistanceMeters(
					lng,
					lat,
					[nearestLng, nearestLat],
					[nearestLng, nearestLat]
				)
			};
		})
		.filter((candidate) => candidate.bboxDistance <= maxDistance)
		.sort((left, right) => left.bboxDistance - right.bboxDistance)
		.slice(0, 32)
		.map((candidate) => ({
			feature: candidate.feature,
			distance: getParcelRegionTradeFeatureBoundaryDistanceMeters(candidate.feature, lng, lat)
		}))
		.sort((left, right) => left.distance - right.distance);
	const nearest = candidates[0] || null;
	return nearest && nearest.distance <= maxDistance ? nearest.feature : null;
}

async function resolveParcelRegionTradeFeatureByPoint(lat, lng)
{
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	const data = await loadAdminBoundaryGeoJson(getParcelRegionTradeBoundaryDataType());
	const features = Array.isArray(data?.features) ? data.features : [];
	const matches = features.filter((feature) => isParcelRegionTradePointInFeature(lng, lat, feature));
	matches.sort((a, b) => String(getAdminBoundaryFeatureCodeValue(b) || "").length - String(getAdminBoundaryFeatureCodeValue(a) || "").length);
	if (matches[0]) return matches[0];
	return findNearestParcelRegionTradeFeature(features, lng, lat);
}

function normalizeParcelRegionTradeStatsRegionCode(value)
{
	const code = String(value || "").replace(/\D/g, "");
	return code.length === 2 ? code : code.slice(0, 5);
}

async function fetchParcelRegionTradeStats(meta, selection)
{
	const type = getParcelRegionTradeTypeOption(selection.type);
	const regionLookupKey = getParcelRegionTradeMetaKey(meta);
	const cacheKey = `region-static-stats-v2|${regionLookupKey}|${type.key}|${selection.months}`;
	if (parcelRegionTradeStatsCache.has(cacheKey)) return parcelRegionTradeStatsCache.get(cacheKey);
	if (typeof loadSupabaseScript === "function") await loadSupabaseScript();
	const sharedClient = typeof window.getRealjejuSupabaseClient === "function"
		? window.getRealjejuSupabaseClient()
		: null;
	const client = sharedClient
		|| (typeof getMapListingsSupabaseClient === "function" ? getMapListingsSupabaseClient() : null)
		|| (typeof window.getMapListingsSupabaseClient === "function" ? window.getMapListingsSupabaseClient() : null)
		|| window.__realjejuSupabaseClient
		|| null;
	if (!client) throw new Error("실거래 통계 DB 연결을 준비하지 못했습니다.");
	const regionCode = normalizeParcelRegionTradeStatsRegionCode(meta.regionCode);
	const { data: rows, error } = await client
		.from("real_estate_region_trade_static_stats")
		.select("*")
		.eq("region_code", regionCode)
		.eq("type_key", type.key)
		.eq("period_months", selection.months);
	if (error) throw error;
	const row = findParcelRegionTradeStaticRow(rows, meta);
	const data = {
		regionCode,
		regionNames: meta.regionNames,
		serviceTypes: type.serviceTypes,
		periodMonths: selection.months,
		periods: buildParcelRegionTradeStaticPeriods(row),
		snapshotMonth: String(row?.snapshot_month || ""),
		source: "monthly-static-table"
	};
	parcelRegionTradeStatsCache.set(cacheKey, data);
	return data;
}

function getParcelRegionTradeMetaKey(meta)
{
	const regionCode = normalizeParcelRegionTradeStatsRegionCode(meta?.regionCode);
	const regionNames = Array.isArray(meta?.regionNames)
		? meta.regionNames.map((name) => String(name || "").replace(/\s+/g, "")).filter(Boolean)
		: [];
	return `${regionCode}|${regionNames.join(">")}`;
}

function normalizeParcelRegionTradeStaticName(value)
{
	return String(value || "").replace(/\s+/g, "").trim();
}

function findParcelRegionTradeStaticRow(rows, meta)
{
	const regionCode = normalizeParcelRegionTradeStatsRegionCode(meta?.regionCode);
	const regionName = normalizeParcelRegionTradeStaticName(meta?.regionName);
	const regionNames = Array.isArray(meta?.regionNames)
		? meta.regionNames.map(normalizeParcelRegionTradeStaticName).filter(Boolean)
		: [];
	const expectedNameKey = regionNames.join(">");
	const candidates = (Array.isArray(rows) ? rows : []).filter((row) => (
		normalizeParcelRegionTradeStatsRegionCode(row?.region_code) === regionCode
	));
	if (!candidates.length) return null;
	if (regionCode.length === 2) {
		return candidates.find((row) => String(row?.region_level || "") === "province")
			|| candidates.find((row) => !normalizeParcelRegionTradeStaticName(row?.region_name_key))
			|| null;
	}
	if (!regionNames.length) {
		return candidates.find((row) => String(row?.region_level || "") === "city")
			|| candidates.find((row) => !normalizeParcelRegionTradeStaticName(row?.region_name_key))
			|| null;
	}
	if (expectedNameKey) {
		const exact = candidates.find((row) => (
			normalizeParcelRegionTradeStaticName(row?.region_name_key) === expectedNameKey
		));
		if (exact) return exact;
	}
	if (!regionName) return null;
	const suffixMatches = candidates.filter((row) => {
		const nameParts = normalizeParcelRegionTradeStaticName(row?.region_name_key).split(">").filter(Boolean);
		return nameParts[nameParts.length - 1] === regionName;
	});
	if (!suffixMatches.length) return null;
	const preferredLevel = /(?:읍|면)$/.test(regionName) ? "town" : "local";
	return suffixMatches.find((row) => String(row?.region_level || "") === preferredLevel)
		|| suffixMatches[0]
		|| null;
}

function buildParcelRegionTradeStaticPeriod(row, prefix)
{
	return {
		label: String(row?.[`${prefix}_label`] || ""),
		from: String(row?.[`${prefix}_from`] || ""),
		to: String(row?.[`${prefix}_to`] || ""),
		count: Number(row?.[`${prefix}_trade_count`] || 0),
		totalAmountKrw: Number(row?.[`${prefix}_total_amount_krw`] || 0),
		totalAreaM2: Number(row?.[`${prefix}_total_area_m2`] || 0),
		averageAmountKrw: Number(row?.[`${prefix}_average_amount_krw`] || 0),
		unitPriceKrwM2: Number(row?.[`${prefix}_unit_price_krw_m2`] || 0),
		brokerTradeCount: Number(row?.[`${prefix}_broker_trade_count`] || 0),
		privateTradeCount: Number(row?.[`${prefix}_private_trade_count`] || 0),
		methodCountsReady: Object.prototype.hasOwnProperty.call(row || {}, `${prefix}_broker_trade_count`)
			&& Object.prototype.hasOwnProperty.call(row || {}, `${prefix}_private_trade_count`)
	};
}

function buildParcelRegionTradeStaticPeriods(row)
{
	return {
		previous: buildParcelRegionTradeStaticPeriod(row, "previous"),
		recent: buildParcelRegionTradeStaticPeriod(row, "recent")
	};
}

// 6.273: CSV 월간 집계의 공식 거래유형을 통계 거래건수 아래 한 줄로 표시합니다.
function buildParcelRegionTradeMethodSummary(previous, recent, months)
{
	if (!previous?.methodCountsReady || !recent?.methodCountsReady) return "&nbsp;";
	const previousBroker = Number(previous?.brokerTradeCount || 0).toLocaleString("ko-KR");
	const previousPrivate = Number(previous?.privateTradeCount || 0).toLocaleString("ko-KR");
	const recentBroker = Number(recent?.brokerTradeCount || 0).toLocaleString("ko-KR");
	const recentPrivate = Number(recent?.privateTradeCount || 0).toLocaleString("ko-KR");
	return `(이전) 중개 ${previousBroker}건, 개인 ${previousPrivate}건 / (최근) 중개 ${recentBroker}건, 개인 ${recentPrivate}건`;
}

function isParcelRegionTradeBadgesHidden()
{
	return !!(document.body && document.body.classList.contains("parcel-region-trade-badges-hidden"));
}

function setParcelRegionTradeBadgesHidden(hidden)
{
	const shouldHide = !!hidden;
	if (document.body) document.body.classList.toggle("parcel-region-trade-badges-hidden", shouldHide);
	if (shouldHide) {
		propertyRegionCountRenderToken += 1;
		clearPropertyRegionCountOverlays();
	} else if (getCurrentRealjejuGlobalCategoryKey() === "parcel") {
		const mode = getPropertyMapPresentationMode();
		const level = Number(state.map?.getLevel?.());
		if (Number.isFinite(level) && level >= 1 && level <= 5) {
			// 숨김 해제는 지도 이동 이벤트를 기다리지 않고 현재 프레임에서 즉시 확정한다.
			if (parcelTradeCanvas) {
				parcelTradeCanvas.hidden = false;
				parcelTradeCanvas.style.visibility = "";
			}
			drawParcelTradeCanvas();
			if (typeof window.requestAnimationFrame === "function") {
				window.requestAnimationFrame(() => {
					if (isParcelRegionTradeBadgesHidden()) return;
					if (parcelTradeCanvas) {
						parcelTradeCanvas.hidden = false;
						parcelTradeCanvas.style.visibility = "";
					}
					drawParcelTradeCanvas();
				});
			}
			// 기존 행을 먼저 유지하고, 같은 화면의 캐시/RPC 결과를 다시 연결한다.
			parcelTradeCanvasLoadedBoundsKey = "";
			void loadParcelTradeCanvasRowsForCurrentViewport({ source: "visibility-toggle" });
		} else if (shouldRenderParcelRegionTradeMapBadges(mode)) {
			void renderPropertyRegionCountOverlays(mode);
		}
	}
	if (typeof syncParcelTradeCanvasVisibility === "function") syncParcelTradeCanvasVisibility();
	syncParcelTradeBadgeVisibilityControl();
	syncMapPropertyToggleButton();
	return shouldHide;
}

function toggleParcelRegionTradeBadgesVisibility()
{
	return setParcelRegionTradeBadgesHidden(!isParcelRegionTradeBadgesHidden());
}

function shouldRenderParcelRegionTradeMapBadges(mode = getPropertyMapPresentationMode())
{
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	const level = getAdminBoundaryLevel();
	return category === "parcel"
		&& Number.isFinite(level)
		&& level >= 1
		&& !isParcelRegionTradeBadgesHidden()
		&& mode === getParcelMapLevelProfile().presentationMode
		&& isPropertyRegionCountMode(mode);
}

async function fetchParcelRegionTradeStatsBatchUncached(regionMetas, selection)
{
	const type = getParcelRegionTradeTypeOption(selection.type);
	const regions = (Array.isArray(regionMetas) ? regionMetas : [])
		.map((meta) => {
			const regionCode = normalizeParcelRegionTradeStatsRegionCode(meta?.regionCode);
			const regionNames = Array.isArray(meta?.regionNames) ? meta.regionNames : [];
			return { key: getParcelRegionTradeMetaKey(meta), regionCode, regionNames };
		})
		.filter((region) => region.key && region.regionCode);
	const cacheKey = `region-static-stats-batch-v2|${type.key}|${selection.months}|${regions.map((region) => region.key).sort().join(",")}`;
	if (parcelRegionTradeStatsCache.has(cacheKey)) return parcelRegionTradeStatsCache.get(cacheKey);
	if (!regions.length) return new Map();
	if (typeof loadSupabaseScript === "function") await loadSupabaseScript();
	const sharedClient = typeof window.getRealjejuSupabaseClient === "function"
		? window.getRealjejuSupabaseClient()
		: null;
	const client = sharedClient
		|| (typeof getMapListingsSupabaseClient === "function" ? getMapListingsSupabaseClient() : null)
		|| (typeof window.getMapListingsSupabaseClient === "function" ? window.getMapListingsSupabaseClient() : null)
		|| window.__realjejuSupabaseClient
		|| null;
	if (!client) throw new Error("실거래 통계 DB 연결을 준비하지 못했습니다.");
	const { data: rows, error } = await client
		.from("real_estate_region_trade_static_stats")
		.select("*")
		.in("region_code", Array.from(new Set(regions.map((region) => region.regionCode))))
		.eq("type_key", type.key)
		.eq("period_months", selection.months);
	if (error) throw error;
	const metaByKey = new Map((Array.isArray(regionMetas) ? regionMetas : []).map((meta) => [
		getParcelRegionTradeMetaKey(meta),
		meta
	]));
	const statsByKey = new Map(regions.map((region) => {
		const row = findParcelRegionTradeStaticRow(rows, metaByKey.get(region.key));
		return [region.key, {
			key: region.key,
			regionCode: region.regionCode,
			regionNames: region.regionNames,
			periodMonths: selection.months,
			periods: buildParcelRegionTradeStaticPeriods(row),
			snapshotMonth: String(row?.snapshot_month || ""),
			source: "monthly-static-table"
		}];
	}));
	parcelRegionTradeStatsCache.set(cacheKey, statsByKey);
	return statsByKey;
}

function getParcelRegionTradeBatchRequestKey(regionMetas, selection) {
  const regions = (Array.isArray(regionMetas) ? regionMetas : [])
    .map((meta) => [
      String(meta?.regionCode || ""),
      ...(Array.isArray(meta?.regionNames) ? meta.regionNames.map((name) => String(name || "")) : [])
    ].join(":"))
    .filter(Boolean)
    .sort();
  return [
    String(selection?.type || "land"),
    Number(selection?.months || 3),
    regions.join("|")
  ].join("::");
}

async function fetchParcelRegionTradeStatsBatch(regionMetas, selection) {
  const requestKey = getParcelRegionTradeBatchRequestKey(regionMetas, selection);
  if (parcelRegionTradeStatsInFlight.has(requestKey)) {
    return parcelRegionTradeStatsInFlight.get(requestKey);
  }
  const request = fetchParcelRegionTradeStatsBatchUncached(regionMetas, selection);
  parcelRegionTradeStatsInFlight.set(requestKey, request);
  try {
    return await request;
  } finally {
    if (parcelRegionTradeStatsInFlight.get(requestKey) === request) {
      parcelRegionTradeStatsInFlight.delete(requestKey);
    }
  }
}

function renderParcelRegionTradeStatsPanel(meta, selection, data = null, errorMessage = "")
{
	if (!propertyList) return;
	selection = normalizeParcelRegionTradeSelection(selection);
	parcelRegionTradeSelection = selection;
	parcelRegionTradeCurrentMeta = meta;
	parcelRegionTradeCurrentData = data;
	parcelRegionTradeCurrentError = errorMessage;
	const type = getParcelRegionTradeTypeOption(selection.type);
	const metric = PARCEL_REGION_TRADE_METRIC_OPTIONS.find((option) => option.key === selection.metric)
		|| PARCEL_REGION_TRADE_METRIC_OPTIONS[0];
  const metricLabel = metric.key === "unitPrice" ? getParcelRegionTradeUnitLabel() : metric.label;
	const previous = data?.periods?.previous || null;
	const recent = data?.periods?.recent || null;
	const change = getParcelRegionTradeChange(previous, recent, selection.metric);
	const stateHtml = errorMessage
		? `<p class="parcel-region-trade-state is-error">${escapeHtml(errorMessage)}</p>`
		: (!data
			? '<p class="parcel-region-trade-state" aria-hidden="true">&nbsp;</p>'
			: ((Number(previous?.count || 0) + Number(recent?.count || 0)) === 0
				? '<p class="parcel-region-trade-state">해당 유형의 거래내역이 없습니다.</p>'
				: ""));
	propertyList.innerHTML = `
		<section class="parcel-region-trade-stats-panel" data-region-code="${escapeHtml(meta.regionCode)}">
			<header class="parcel-region-trade-heading">
				<h2>${escapeHtml(meta.headingName || meta.regionName || "선택 지역")}</h2>
				<p>${escapeHtml(meta.headingParentName || "")}</p>
			</header>
			<div class="parcel-region-trade-summary-bar" aria-label="실거래 통계 설정">
				<button type="button" data-parcel-region-trade-picker="type"><span class="parcel-region-trade-status-dot" aria-hidden="true"></span><strong>${escapeHtml(type.label)}</strong><span aria-hidden="true">⋮</span></button>
				<button type="button" data-parcel-region-trade-picker="months"><strong>최근 ${selection.months}개월</strong><span aria-hidden="true">⋮</span></button>
				<button type="button" data-parcel-region-trade-picker="metric"><strong>${escapeHtml(metricLabel)}</strong><span aria-hidden="true">⋮</span></button>
			</div>
			<div class="parcel-region-trade-comparison">
				<div><span>${escapeHtml(previous?.label || "이전 기간")}</span><strong>${formatParcelRegionTradeMetric(previous, selection.metric)}</strong></div>
				<p class="is-${change.direction}"><span>${change.direction === "up" ? "▲" : (change.direction === "down" ? "▼" : "")}</span>${escapeHtml(change.label)}</p>
				<div><span>${escapeHtml(recent?.label || "최근 기간")}</span><strong>${formatParcelRegionTradeMetric(recent, selection.metric)}</strong></div>
			</div>
			<section class="parcel-region-trade-table-section">
				<h3>${escapeHtml(meta.displayName)}의 실거래가 통계</h3>
				<div class="parcel-region-trade-table-head"><span>항목</span><span>이전 ${selection.months}개월</span><span>최근 ${selection.months}개월</span></div>
				<div class="parcel-region-trade-table-row"><span>거래총액</span><strong>${formatParcelRegionTradeMoney(previous?.totalAmountKrw)}</strong><div class="parcel-region-trade-table-value"><strong>${formatParcelRegionTradeMoney(recent?.totalAmountKrw)}</strong>${buildParcelRegionTradeDeltaHtml(previous?.totalAmountKrw, recent?.totalAmountKrw)}</div></div>
				<div class="parcel-region-trade-table-row"><span>${escapeHtml(getParcelRegionTradeUnitLabel())}</span><strong>${formatParcelRegionTradeMoney(getParcelRegionTradeUnitPrice(previous), { unitPrice: true })}</strong><div class="parcel-region-trade-table-value"><strong>${formatParcelRegionTradeMoney(getParcelRegionTradeUnitPrice(recent), { unitPrice: true })}</strong>${buildParcelRegionTradeDeltaHtml(getParcelRegionTradeUnitPrice(previous), getParcelRegionTradeUnitPrice(recent), { unitPrice: true })}</div></div>
				<div class="parcel-region-trade-table-row"><span>거래건수</span><strong>${Number(previous?.count || 0).toLocaleString("ko-KR")}건</strong><div class="parcel-region-trade-table-value"><strong>${Number(recent?.count || 0).toLocaleString("ko-KR")}건</strong>${buildParcelRegionTradeDeltaHtml(previous?.count, recent?.count, { count: true })}</div></div>
				<p class="parcel-region-trade-method-summary">${buildParcelRegionTradeMethodSummary(previous, recent, selection.months)}</p>
			</section>
			${stateHtml}
			<p class="parcel-region-trade-source-note">※ 자료 출처: 국토교통부 실거래가 공개시스템 · 본 통계는 단순 참고용입니다.</p>
		</section>
	`;
	propertyList.querySelectorAll("[data-parcel-region-trade-picker]").forEach((button) => {
		button.addEventListener("click", () => openParcelRegionTradePicker(button.dataset.parcelRegionTradePicker));
	});
}

async function loadParcelRegionTradeStatsPanel(meta, selection)
{
	selection = normalizeParcelRegionTradeSelection(selection);
	parcelRegionTradeSelection = selection;
	const requestToken = ++parcelRegionTradeStatsRequestToken;
	renderParcelRegionTradeStatsPanel(meta, selection);
	try {
		const data = await fetchParcelRegionTradeStats(meta, selection);
		if (requestToken !== parcelRegionTradeStatsRequestToken || state.leftListDetailMode !== "parcel-region-stats") return;
		renderParcelRegionTradeStatsPanel(meta, selection, data);
	} catch (error) {
		if (requestToken !== parcelRegionTradeStatsRequestToken || state.leftListDetailMode !== "parcel-region-stats") return;
		console.error("[realjeju parcel region trade stats]", error);
		renderParcelRegionTradeStatsPanel(meta, selection, null, "실거래 통계를 불러오지 못했습니다.");
	}
}

async function openParcelRegionTradeStatsForFeature(regionFeature, parcelFeature = null, selectionSnapshot = parcelRegionTradeSelection, options = {})
{
	if (distanceMeasureActive) return false;
	const featureRequestGeneration = Number.isFinite(Number(options?.zoomSyncToken))
		? Number(options.zoomSyncToken)
		: parcelRegionTradeZoomSyncToken;
	const featureRequestIsCurrent = () => featureRequestGeneration === parcelRegionTradeZoomSyncToken;
	if (!featureRequestIsCurrent()) return false;
	selectionSnapshot = normalizeParcelRegionTradeSelection(selectionSnapshot);
	const shouldRenderBoundary = options?.renderBoundary !== false;
	const allowsBadgeSelection = options?.source === "badge";
	const badgeRegionKey = allowsBadgeSelection ? String(options?.regionKey || "") : "";
	if ((!allowsBadgeSelection && !shouldUseParcelAdminBoundaryPresentation()) || !regionFeature || !propertyList) return false;
	regionFeature = await resolveParcelRegionTradeFeatureForCurrentLevel(regionFeature);
	if (!featureRequestIsCurrent()) return false;
	if (!regionFeature || (!allowsBadgeSelection && !shouldUseParcelAdminBoundaryPresentation())) return false;
	// Render the selected administrative boundary before metadata and statistics work.
    selectedAdminBoundaryFeature = shouldRenderBoundary ? regionFeature : null;
    if (shouldRenderBoundary) renderAdminBoundaryOverlay({
		preferredFeature: regionFeature,
		source: allowsBadgeSelection ? "parcel-badge" : "parcel-map"
	});
    else clearAdminBoundaryOverlay();
	const meta = await buildParcelRegionTradeMeta(regionFeature, parcelFeature);
	if (!featureRequestIsCurrent()) return false;
	if (!meta.regionCode) return false;
	const regionAnchorPoint = getParcelRegionTradeFeatureInteriorPoint(regionFeature);
	if (regionAnchorPoint) parcelRegionTradeStatsAnchorPoint = regionAnchorPoint.slice(0, 2);
	closeParcelRegionTradePickerSurface();
	if (typeof hardCloseDetailPanel === "function") hardCloseDetailPanel();
	if (typeof clearAgentListFilter === "function") clearAgentListFilter();
	if (typeof clearListLock === "function") clearListLock();
	if (typeof resetLeftListPagination === "function") resetLeftListPagination([]);
	if (!featureRequestIsCurrent()) return false;
	if (badgeRegionKey) selectedPropertyRegionCountKey = badgeRegionKey;
	state.leftListDetailMode = "parcel-region-stats";
	state.leftListTitle = "부동산 통계";
	state.isListOpen = true;
	selectedPropertyRegionBoundaryFeature = shouldRenderBoundary ? regionFeature : null;
	selectedAdminBoundaryFeature = shouldRenderBoundary ? regionFeature : null;
	adminBoundarySelectedPoint = shouldRenderBoundary ? regionAnchorPoint : null;
	// 기존 개별필지 패널이 남아 있는 상태에서 제목을 먼저 동기화하면
	// syncSidebarListTitle이 모드를 parcel-land-info로 되돌려 통계 응답을 폐기한다.
	// 통계 패널을 먼저 확정한 뒤 제목과 목록 상태를 동기화한다.
	void loadParcelRegionTradeStatsPanel(meta, selectionSnapshot);
	syncSidebarListTitle();
	openSidebarList();
	if (shouldRenderBoundary) void renderAdminBoundaryOverlay({
		preferredFeature: regionFeature,
		source: allowsBadgeSelection ? "parcel-badge" : "parcel-map"
	});
	else clearAdminBoundaryOverlay();
	return true;
}

async function openParcelRegionTradeStatsAtPoint(lat, lng, selectionSnapshot = parcelRegionTradeSelection, options = {})
{
	selectionSnapshot = normalizeParcelRegionTradeSelection(selectionSnapshot);
	if (!shouldUseParcelAdminBoundaryPresentation()) return false;
	const expectedZoomSyncToken = Number(options?.zoomSyncToken);
	if (Number.isFinite(expectedZoomSyncToken) && expectedZoomSyncToken !== parcelRegionTradeZoomSyncToken) return false;
	const regionFeature = await resolveParcelRegionTradeFeatureByPoint(lat, lng);
	if (Number.isFinite(expectedZoomSyncToken) && expectedZoomSyncToken !== parcelRegionTradeZoomSyncToken) return false;
	if (!regionFeature || !shouldUseParcelAdminBoundaryPresentation()) return false;
	parcelRegionTradeStatsAnchorPoint = [Number(lng), Number(lat)];
	return openParcelRegionTradeStatsForFeature(regionFeature, null, selectionSnapshot, options);
}

function cancelParcelRegionTradeStatsAfterZoom()
{
	parcelRegionTradeZoomSyncToken += 1;
	if (parcelRegionTradeZoomSyncTimer) {
		clearTimeout(parcelRegionTradeZoomSyncTimer);
		parcelRegionTradeZoomSyncTimer = null;
	}
	if (parcelRegionTradeZoomIdleHandler && state.map && window.kakao?.maps?.event) {
		kakao.maps.event.removeListener(state.map, "idle", parcelRegionTradeZoomIdleHandler);
	}
	parcelRegionTradeZoomIdleHandler = null;
}

function teardownParcelAnalysisSession() {
  cancelParcelRegionTradeStatsAfterZoom();
  parcelRegionTradeStatsAnchorPoint = null;
  selectedPropertyRegionBoundaryFeature = null;
  adminBoundarySelectedPoint = null;
  clearParcelBoundaryRenderState();
}

function scheduleParcelRegionTradeStatsAfterZoom(point, selectionSnapshot, options = {})
{
	if (!Array.isArray(point) || point.length < 2) return;
	cancelParcelRegionTradeStatsAfterZoom();
	const syncToken = parcelRegionTradeZoomSyncToken;
	let completed = false;
	let opening = false;
	let idleHandler = null;
	const cleanup = () => {
		if (parcelRegionTradeZoomSyncTimer) clearTimeout(parcelRegionTradeZoomSyncTimer);
		parcelRegionTradeZoomSyncTimer = null;
		if (parcelRegionTradeZoomIdleHandler === idleHandler && state.map && window.kakao?.maps?.event) {
			kakao.maps.event.removeListener(state.map, "idle", idleHandler);
			parcelRegionTradeZoomIdleHandler = null;
		}
	};
	const run = async () => {
		if (completed || opening || syncToken !== parcelRegionTradeZoomSyncToken) return;
		const currentCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
			? getCurrentRealjejuGlobalCategoryKey()
			: String(document.body?.dataset?.globalCategory || "realestate");
		if (currentCategory !== "parcel" || !shouldUseParcelAdminBoundaryPresentation()) return;
		opening = true;
		let opened = false;
		try {
			opened = await openParcelRegionTradeStatsAtPoint(
				point[1],
				point[0],
				selectionSnapshot,
				{ ...options, zoomSyncToken: syncToken }
			);
		} catch (error) {
			console.warn("[realjeju parcel region stats] 확대·축소 자동 조회 실패:", error);
		} finally {
			opening = false;
		}
		if (!opened || syncToken !== parcelRegionTradeZoomSyncToken) return;
		completed = true;
		cleanup();
	};
	idleHandler = () => { void run(); };
	parcelRegionTradeZoomIdleHandler = idleHandler;
	if (state.map && window.kakao?.maps?.event) {
		kakao.maps.event.addListener(state.map, "idle", parcelRegionTradeZoomIdleHandler);
	}
	parcelRegionTradeZoomSyncTimer = setTimeout(() => {
		parcelRegionTradeZoomSyncTimer = null;
		void run();
	}, 0);
}

function getAdminBoundaryRingPath(ring)
{
	if (!Array.isArray(ring)) return [];
	return ring
	.map(point => Array.isArray(point) ? new kakao.maps.LatLng(Number(point[1]), Number(point[0])) : null)
	.filter(Boolean);
}

function getAdminBoundaryFeatureName(feature)
{
	const props = feature && feature.properties ? feature.properties : {};
	return (String(props.name || props.A5 || props.A4 || props.A2 || "행정구역").trim() || "행정구역").replace(/^제주도\s+/, "");
}

