function getAdminBoundaryFeaturePreferredAnchor(feature)
{
	const code = getAdminBoundaryFeatureCodeValue(feature);
	const point = PROPERTY_REGION_LABEL_ANCHORS_BY_CODE.get(code);
	return point || null;
}

function hasAdminBoundaryFeaturePreferredAnchor(feature)
{
	return PROPERTY_REGION_LABEL_ANCHORS_BY_CODE.has(getAdminBoundaryFeatureCodeValue(feature));
}

function getAdminBoundaryListingPoint(item)
{
	if (!item || typeof item !== "object") return null;
	let position = null;
	if (typeof getListingDisplayPosition === "function") {
		position = getListingDisplayPosition(item);
	}
	const lat = Number(position && position.lat != null ? position.lat : item.lat);
	const lng = Number(position && position.lng != null ? position.lng : item.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	return [lng, lat];
}

function getPropertyMapPresentationMode()
{
	const level = getAdminBoundaryLevel();
	if (!Number.isFinite(level)) return "clusters";
	const category = document.body && document.body.dataset
		? String(document.body.dataset.globalCategory || "realestate")
		: "realestate";
	if (category === "parcel") return getParcelMapLevelProfile(level).presentationMode;
	if (level >= PROPERTY_REGION_PROVINCE_MIN_LEVEL) return "province-count";
	if (level >= PROPERTY_REGION_CITY_MIN_LEVEL) return "city-counts";
	if (level >= PROPERTY_REGION_DISTRICT_MIN_LEVEL) return "district-counts";
	if (level >= PROPERTY_REGION_LOCAL_MIN_LEVEL) return "local-counts";
	if (level >= PROPERTY_CLUSTER_MIN_LEVEL) return "clusters";
	return "individual";
}

function isPropertyRegionCountMode(mode)
{
	return mode === "province-count" || mode === "city-counts" || mode === "district-counts" || mode === "local-counts";
}

function shouldUsePropertyMapLevelPresentation() {
	if (!document.body || !state.map || !window.kakao || !kakao.maps) return false;
	const category = document.body.dataset ? String(document.body.dataset.globalCategory || "realestate") : "realestate";
	const usesParcelTradeBadges = shouldRenderParcelRegionTradeMapBadges(getPropertyMapPresentationMode());
	if (state.isPropertyMarkersVisible === false && !usesParcelTradeBadges) return false;
	if ((!isGlobalRealestateCategory(category) && !usesParcelTradeBadges) || shouldShowGlobalCategoryEmptyMap(category)) return false;
	const blockedClasses = [
		"main-landing-page-open",
		"auth-page-open",
		"auth-recovery-page-open",
		"payment-page-open",
		"profile-page-open",
		"myinfo-page-open",
		"profile-edit-page-open",
		"broker-office-info-page-open",
		"broker-office-apply-page-open",
		"broker-office-edit-page-open",
		"property-register-page-open",
		"admin-page-open",
		"broker-home-page-open",
		"my-suite-page-open",
		"notice-page-open",
		"presale-page-open"
	];
	return !blockedClasses.some((className) => document.body.classList.contains(className));
}

function shouldUseAdminBoundaryMapLevelPresentation()
{
	if (!document.body || !state.map || !window.kakao || !kakao.maps) return false;
	const level = getAdminBoundaryLevel();
	if (!Number.isFinite(level) || level < PROPERTY_REGION_LOCAL_MIN_LEVEL) return false;
	const category = document.body.dataset ? String(document.body.dataset.globalCategory || "realestate") : "realestate";
	if (!isGlobalRealestateCategory(category) || shouldShowGlobalCategoryEmptyMap(category)) return false;
	const blockedClasses = [
		"main-landing-page-open",
		"auth-page-open",
		"auth-recovery-page-open",
		"payment-page-open",
		"profile-page-open",
		"myinfo-page-open",
		"profile-edit-page-open",
		"broker-office-info-page-open",
		"broker-office-apply-page-open",
		"broker-office-edit-page-open",
		"property-register-page-open",
		"admin-page-open",
		"broker-home-page-open",
		"my-suite-page-open",
		"notice-page-open",
		"presale-page-open"
	];
	return !blockedClasses.some((className) => document.body.classList.contains(className));
}

function hasPropertyRegionCountOverlaysForMode(mode)
{
	const prefix = `${String(mode || "")}:`;
	return Array.isArray(propertyRegionCountOverlays) && propertyRegionCountOverlays.some((overlay) => {
		const label = overlay && overlay.__realjejuRegionCountLabel;
		return !!label && String(label.dataset?.regionKey || "").startsWith(prefix);
	});
}

function clearPropertyRegionCountOverlays()
{
  parcelRegionTradeBadgeRenderedSignature = "";
	propertyRegionCountOverlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	propertyRegionCountOverlays = [];
}

function getAdminBoundaryRingAnchor(ring)
{
	if (!Array.isArray(ring) || ring.length < 3) return null;
	let areaSum = 0;
	let lngSum = 0;
	let latSum = 0;
	for (let index = 0; index < ring.length; index += 1) {
		const current = ring[index];
		const next = ring[(index + 1) % ring.length];
		if (!Array.isArray(current) || !Array.isArray(next)) continue;
		const currentLng = Number(current[0]);
		const currentLat = Number(current[1]);
		const nextLng = Number(next[0]);
		const nextLat = Number(next[1]);
		if (![currentLng, currentLat, nextLng, nextLat].every(Number.isFinite)) continue;
		const cross = (currentLng * nextLat) - (nextLng * currentLat);
		areaSum += cross;
		lngSum += (currentLng + nextLng) * cross;
		latSum += (currentLat + nextLat) * cross;
	}
	if (Math.abs(areaSum) < 1e-12) return null;
	return {
		point: [lngSum / (3 * areaSum), latSum / (3 * areaSum)],
		area: Math.abs(areaSum)
	};
}

function getAdminBoundaryFeatureAnchor(feature)
{
	if (!feature || !feature.geometry) return null;
	const preferred = getAdminBoundaryFeaturePreferredAnchor(feature);
	if (preferred) return preferred;
	if (Array.isArray(feature.__realjejuBoundaryAnchor)) return feature.__realjejuBoundaryAnchor;
	let bestAnchor = null;
	getGeoJsonOuterRings(feature.geometry).forEach((ring) => {
		const anchor = getAdminBoundaryRingAnchor(ring);
		if (anchor && (!bestAnchor || anchor.area > bestAnchor.area)) bestAnchor = anchor;
	});
	const bbox = getAdminBoundaryFeatureBBox(feature);
	const point = bestAnchor && bestAnchor.point
		? bestAnchor.point
		: (bbox ? [(bbox[0] + bbox[2]) / 2, (bbox[1] + bbox[3]) / 2] : null);
	if (point && point.every(Number.isFinite)) feature.__realjejuBoundaryAnchor = point;
	return point;
}

function getVisibleAdminBoundaryFeatureAnchor(feature)
{
	const point = getAdminBoundaryFeatureAnchor(feature);
	if (!point || !state.map || typeof state.map.getBounds !== "function") return null;
	const bounds = state.map.getBounds();
	const latLng = new kakao.maps.LatLng(Number(point[1]), Number(point[0]));
	return !bounds || bounds.contain(latLng) ? point : null;
}

function getPropertyRegionCountSelectionKey(feature, mode)
{
	return `${mode}:${getAdminBoundaryFeatureCodeValue(feature) || getAdminBoundaryFeatureName(feature)}`;
}

function syncPropertyRegionCountSelectedLabels()
{
	document.querySelectorAll(".property-region-count-label").forEach((label) => {
		const isSelected = label.dataset.regionKey === selectedPropertyRegionCountKey;
		label.classList.toggle("is-selected", isSelected);
		label.setAttribute("aria-pressed", isSelected ? "true" : "false");
	});
	propertyRegionCountOverlays.forEach((overlay) => {
		const label = overlay && overlay.__realjejuRegionCountLabel;
		if (!label || typeof overlay.setZIndex !== "function") return;
		overlay.setZIndex(getPropertyRegionCountOverlayZIndex(label));
	});
}

function clearPropertyRegionCountSelection(options = {})
{
	selectedPropertyRegionCountKey = "";
	if (options.preservePropertyRegionBoundaryFeature !== true) selectedPropertyRegionBoundaryFeature = null;
	if (options.preserveAdminBoundaryPoint !== true) adminBoundarySelectedPoint = null;
	adminBoundaryOverlayRenderToken += 1;
	clearAdminBoundaryOverlay();
	syncPropertyRegionCountSelectedLabels();
}

function formatPropertyRegionCountListTitle(boundaryState, feature)
{
	if (boundaryState && boundaryState.name === "제주도") return "제주도 전체";
	const name = boundaryState && boundaryState.name
		? normalizeRegionDongName(boundaryState.name)
		: normalizeRegionDongName(getAdminBoundaryFeatureName(feature));
	const parentDong = boundaryState && boundaryState.parentDong
		? normalizeRegionDongName(boundaryState.parentDong)
		: "";
	if (!name) return "매물 목록";
	if (/시$/.test(name)) return name;
	const city = getAdminBoundaryFeatureCodeValue(feature).startsWith("50130") ? "서귀포시" : "제주시";
	if (parentDong && parentDong !== name && /(?:읍|면)$/.test(parentDong)) return `${city} ${parentDong} ${name}`;
	return `${city} ${name}`;
}

function syncSidebarListTitle()
{
	if (!sidebarListTitle) return;
	const hasState = typeof state !== "undefined" && state;
	const hasOpenParcelLandInfo = !!(propertyList && propertyList.querySelector(".parcel-land-info-panel"));
	const hasOpenParcelRegionStats = !!(propertyList && propertyList.querySelector(".parcel-region-trade-stats-panel"));
	const hasOpenParcelAreaMeasure = !!(propertyList && propertyList.querySelector(".parcel-area-measure-panel"));
	const hasLockedParcelInfoMode = !!(hasState && (
		state.leftListDetailMode === "parcel-land-info"
		|| state.leftListDetailMode === "parcel-region-stats"
		|| state.leftListDetailMode === "parcel-area-measure"
	));
	const isParcelRegionStatsTitle = hasOpenParcelRegionStats
		|| (!!hasState && state.leftListDetailMode === "parcel-region-stats" && !hasOpenParcelLandInfo);
	const parcelPanelTitle = hasOpenParcelAreaMeasure || (!!hasState && state.leftListDetailMode === "parcel-area-measure")
		? "면적 측정"
		: (isParcelRegionStatsTitle ? "부동산 통계" : "부동산 정보");
	if (hasState && (hasOpenParcelLandInfo || hasOpenParcelRegionStats || hasOpenParcelAreaMeasure || hasLockedParcelInfoMode)) {
		state.leftListDetailMode = hasOpenParcelAreaMeasure
			? "parcel-area-measure"
			: (hasOpenParcelLandInfo ? "parcel-land-info" : "parcel-region-stats");
		state.leftListTitle = parcelPanelTitle;
	}
	const title = (hasOpenParcelLandInfo || hasOpenParcelRegionStats || hasOpenParcelAreaMeasure || hasLockedParcelInfoMode) ? parcelPanelTitle : (hasState && state.leftListTitle ? state.leftListTitle : "매물 목록");
	const isAgentOfficeTitle = !!(hasState && state.agentListFilter && title !== "매물 목록");
	sidebarListTitle.textContent = title;
	sidebarListTitle.classList.toggle("is-agent-office-title", isAgentOfficeTitle);
	if (isAgentOfficeTitle) sidebarListTitle.setAttribute("title", title);
	else sidebarListTitle.removeAttribute("title");
}

async function openPropertyRegionCountListPanel(feature, count)
{
	if (distanceMeasureActive || !feature) return false;
	if (shouldUseParcelAdminBoundaryPresentation()) {
		return openParcelRegionTradeStatsForFeature(feature);
	}
	prepareMobilePropertyBadgeListInteraction();
	if (typeof closeRightMapToolPanels === "function") closeRightMapToolPanels();
	if (typeof closeEducationFacilityDetailForPropertyInteraction === "function") closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	if (feature && typeof setMapRegionBoundaryListStateFromAdminFeature === "function") {
		await setMapRegionBoundaryListStateFromAdminFeature(feature, count);
	}
	const boundaryState = typeof getMapRegionBoundaryListState === "function" ? getMapRegionBoundaryListState() : null;
	const regionName = boundaryState && boundaryState.name ? boundaryState.name : (getAdminBoundaryFeatureName(feature) || "선택 지역");
	const regionCode = getPropertyScaleRegionCode(feature);
	const totalCount = Math.max(0, Number(count) || 0);
	if (!regionCode) return false;
	const prefetchedItems = boundaryState
		&& boundaryState.regionCode === regionCode
		&& Array.isArray(boundaryState.items)
		? boundaryState.items.slice(0, LEFT_LIST_PAGE_SIZE)
		: [];
	let regionItems = prefetchedItems;
	let listTotalCount = Math.max(
		regionItems.length,
		Math.max(0, Number(boundaryState?.totalCount) || 0),
		totalCount
	);
	if (!regionItems.length && totalCount > 0) {
		try {
			const firstPage = await fetchPropertyScaleRegionFirstPage(regionCode, { totalCount });
			regionItems = Array.isArray(firstPage?.items)
				? firstPage.items.slice(0, REGION_LIST_FIRST_PAINT_SIZE)
				: [];
			if (firstPage?.totalCount !== null
				&& firstPage?.totalCount !== undefined
				&& Number.isFinite(Number(firstPage.totalCount))) {
				listTotalCount = Math.max(regionItems.length, Number(firstPage.totalCount));
			}
		} catch (error) {
			console.error("행정구역 매물 첫 8건 준비 실패:", error);
		}
	}
	await new Promise((resolve) => setTimeout(resolve, 0));
	hardCloseDetailPanel();
	currentDetailItem = null;
	clearAgentListFilter();
	state.leftListDetailMode = "region-count";
	state.leftListTitle = formatPropertyRegionCountListTitle(boundaryState, feature);
	state.selectedMarkerId = null;
	state.selectedMarkerIds = new Set();
	// 네모 행정구역 선택은 네모 뱃지 자체의 키로만 관리합니다.
	// 지역 목록에 들어온 매물 ID를 원형 마커 선택으로 넘기지 않습니다.
	state.selectedClusterKey = null;
	state.selectedClusterAnchor = null;
	state.selectionMode = "region-list";
	clearListLock();
	syncSidebarListTitle();
	resetLeftListPagination([], { totalCount: listTotalCount });
	state.leftListRemoteRegion = {
		regionCode,
		totalCount: listTotalCount,
		items: regionItems.slice(),
		sourceSort: getPropertyScaleSortValue(),
		exhausted: listTotalCount <= regionItems.length,
		loading: false,
		seq: state.leftListSeq
	};
	state.leftListSourceKey = `remote-region:${regionCode}:${getPropertyScaleFilterKey()}:${getPropertyScaleSortValue()}`;
	lockListToItems(regionItems, { keepOnMapClick: true });
	updateMarkerSelection(null, []);
	await openPropertyBadgeListPanel(regionItems, {
		preserveRemoteRegion: true,
		totalCount: listTotalCount
	});
	if (regionItems.length < Math.min(listTotalCount, LEFT_LIST_PAGE_SIZE)) {
		void loadMorePropertyScaleRegionItems();
	}
	setResultInfo(`${regionName} 매물 ${listTotalCount}건`);
	setPagedListInfo(listTotalCount, regionItems.length);
	refreshClusterBadges();
	if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
	if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
	if (typeof refreshMapLayout === "function") {
		refreshMapLayout();
		// 왼쪽 지역 목록이 열리면 지도 폭이 바뀌면서 카카오 지도가 한 번 더 재배치됩니다.
		// 예전 개발 → 행정구역이 사용하던 선택 경계 GeoJSON을 재사용하되,
		// 최종 재배치가 끝난 뒤에도 클릭한 네모 뱃지의 경계가 남도록 같은 선택을 다시 그립니다.
		if (typeof renderAdminBoundaryOverlay === "function") renderAdminBoundaryOverlay();
		setTimeout(() => {
			refreshMapLayout();
			if (typeof renderAdminBoundaryOverlay === "function") renderAdminBoundaryOverlay();
		}, 260);
	}
	return true;
}

const PROPERTY_REGION_COUNT_OVERLAY_Z_INDEX = 18;

const PROPERTY_REGION_COUNT_HOVER_Z_INDEX = 19;

const PROPERTY_REGION_COUNT_SELECTED_Z_INDEX = 20;

function getPropertyRegionCountOverlayZIndex(label, isHovered = false)
{
	// 4.938: 선택한 지역은 겹친 뱃지 중 항상 가장 위에 두고, 일반 hover는 그 아래에서만 동작합니다.
	if (label && label.dataset.regionKey === selectedPropertyRegionCountKey) {
		return PROPERTY_REGION_COUNT_SELECTED_Z_INDEX;
	}
	return isHovered ? PROPERTY_REGION_COUNT_HOVER_Z_INDEX : PROPERTY_REGION_COUNT_OVERLAY_Z_INDEX;
}

function bindPropertyRegionCountOverlayHover(label, overlay)
{
	if (!label || !overlay || typeof overlay.setZIndex !== "function") return;
	label.addEventListener("pointerenter", () => {
		overlay.setZIndex(getPropertyRegionCountOverlayZIndex(label, true));
	});
	label.addEventListener("pointerleave", () => {
		overlay.setZIndex(getPropertyRegionCountOverlayZIndex(label));
	});
}

const PROPERTY_REGION_COUNT_CLICK_DRAG_THRESHOLD_PX = 6;

function createMapPureClickTracker(target)
{
	let activePointerId = null;
	let pointerStartX = 0;
	let pointerStartY = 0;
	let pointerDragged = false;

	const removeTrackingListeners = () => {
		document.removeEventListener("pointermove", trackPointerMove, true);
		document.removeEventListener("pointerup", finishPointer, true);
		document.removeEventListener("pointercancel", cancelPointer, true);
	};
	const trackPointerMove = (event) => {
		if (activePointerId === null || event.pointerId !== activePointerId) return;
		const distance = Math.hypot(
			Number(event.clientX) - pointerStartX,
			Number(event.clientY) - pointerStartY
		);
		if (distance > PROPERTY_REGION_COUNT_CLICK_DRAG_THRESHOLD_PX) pointerDragged = true;
	};
	const finishPointer = (event) => {
		if (activePointerId === null || event.pointerId !== activePointerId) return;
		trackPointerMove(event);
		removeTrackingListeners();
		activePointerId = null;
	};
	const cancelPointer = (event) => {
		if (activePointerId === null || event.pointerId !== activePointerId) return;
		pointerDragged = true;
		removeTrackingListeners();
		activePointerId = null;
	};

	if (target) {
		target.addEventListener("pointerdown", (event) => {
			if (event.pointerType === "mouse" && event.button !== 0) return;
			activePointerId = event.pointerId;
			pointerStartX = Number(event.clientX);
			pointerStartY = Number(event.clientY);
			pointerDragged = false;
			document.addEventListener("pointermove", trackPointerMove, true);
			document.addEventListener("pointerup", finishPointer, true);
			document.addEventListener("pointercancel", cancelPointer, true);
		}, { passive: true });
	}

	return {
		markDragged() {
			pointerDragged = true;
		},
		consumePureClick() {
			const isPureClick = !pointerDragged;
			pointerDragged = false;
			return isPureClick;
		}
	};
}

function bindPropertyRegionCountPureClick(label, onPureClick)
{
	if (!label || typeof onPureClick !== "function") return;
	// 지도 오버레이 안의 프로필 사진이 브라우저 기본 이미지 드래그를 시작하면
	// 지도 대신 사진 잔상이 포인터를 따라옵니다. 네모 뱃지와 같은 지도 드래그
	// 경로를 쓰도록 오버레이와 모든 하위 이미지를 비드래그 요소로 고정합니다.
	label.draggable = false;
	label.querySelectorAll("img").forEach((img) => {
		img.draggable = false;
	});
	label.addEventListener("dragstart", (event) => {
		event.preventDefault();
	}, true);
	let activePointerId = null;
	let pointerStartX = 0;
	let pointerStartY = 0;
	let pointerDragged = false;

	const removeTrackingListeners = () => {
		document.removeEventListener("pointermove", trackPointerMove, true);
		document.removeEventListener("pointerup", finishPointer, true);
		document.removeEventListener("pointercancel", cancelPointer, true);
	};
	const trackPointerMove = (event) => {
		if (activePointerId === null || event.pointerId !== activePointerId) return;
		const distance = Math.hypot(
			Number(event.clientX) - pointerStartX,
			Number(event.clientY) - pointerStartY
		);
		if (distance > PROPERTY_REGION_COUNT_CLICK_DRAG_THRESHOLD_PX) {
			pointerDragged = true;
		}
	};
	const finishPointer = (event) => {
		if (activePointerId === null || event.pointerId !== activePointerId) return;
		trackPointerMove(event);
		removeTrackingListeners();
		activePointerId = null;
	};
	const cancelPointer = (event) => {
		if (activePointerId === null || event.pointerId !== activePointerId) return;
		pointerDragged = true;
		removeTrackingListeners();
		activePointerId = null;
	};

	label.addEventListener("pointerdown", (event) => {
		if (event.pointerType === "mouse" && event.button !== 0) return;
		activePointerId = event.pointerId;
		pointerStartX = Number(event.clientX);
		pointerStartY = Number(event.clientY);
		pointerDragged = false;
		document.addEventListener("pointermove", trackPointerMove, true);
		document.addEventListener("pointerup", finishPointer, true);
		document.addEventListener("pointercancel", cancelPointer, true);
	}, { passive: true });
	label.addEventListener("click", (event) => {
		if (distanceMeasureActive) return;
		event.preventDefault();
		event.stopPropagation();
		if (pointerDragged) {
			pointerDragged = false;
			return;
		}
		onPureClick();
	});
}

function createPropertyRegionCountLabel(name, count, brokerCount, mode, feature, options = {})
{
	const label = document.createElement("button");
	label.type = "button";
	const modeClass = mode === "province-count" ? "is-province" : (mode === "city-counts" ? "is-city" : "is-district");
	label.className = `property-region-count-label ${modeClass}`;
	label.classList.toggle("is-circle-to-square-enter", options.animateEntry === true);
	label.dataset.regionKey = getPropertyRegionCountSelectionKey(feature, mode);
	label.setAttribute(
		"aria-label",
		`${name} 매물 ${Number(count || 0).toLocaleString("ko-KR")}개, 중개 ${Number(brokerCount || 0).toLocaleString("ko-KR")}곳 보기`
	);
	label.setAttribute("aria-pressed", label.dataset.regionKey === selectedPropertyRegionCountKey ? "true" : "false");
	label.classList.toggle("is-selected", label.dataset.regionKey === selectedPropertyRegionCountKey);
	const nameEl = document.createElement("strong");
	nameEl.textContent = name;
	const countEl = document.createElement("span");
	countEl.append(document.createTextNode("매물 "));
	const numberEl = document.createElement("b");
	numberEl.textContent = Number(count || 0).toLocaleString("ko-KR");
	countEl.appendChild(numberEl);
	const brokerCountEl = document.createElement("span");
	brokerCountEl.className = "property-region-broker-count";
	brokerCountEl.append(document.createTextNode("중개 "));
	const brokerNumberEl = document.createElement("b");
	brokerNumberEl.textContent = Number(brokerCount || 0).toLocaleString("ko-KR");
	brokerCountEl.appendChild(brokerNumberEl);
	label.append(nameEl, countEl, brokerCountEl);
	// 네모 뱃지 위에서 누른 채 지도를 움직이면 지도 드래그만 허용하고,
	// 포인터가 6px 이내에서 끝난 순수 클릭일 때만 지역을 선택합니다.
	bindPropertyRegionCountPureClick(label, () => {
		// 이미 선택된 같은 행정구역을 다시 누르면 목록 X와 같은 공통 닫기 경로를 사용합니다.
		// 선택 표시와 원격 목록 상태를 한 번에 비우고 같은 지역을 다시 조회하지 않습니다.
		const isSameOpenRegion = selectedPropertyRegionCountKey === label.dataset.regionKey
			&& state.isListOpen
			&& state.leftListDetailMode === "region-count";
		if (isSameOpenRegion) {
				closeSidebarList({
					preserveAdminBoundaryPoint: true,
					preservePropertyRegionBoundaryFeature: true
				});
			return;
		}
		selectedPropertyRegionCountKey = label.dataset.regionKey;
		adminBoundarySelectedPoint = getAdminBoundaryFeatureAnchor(feature);
		selectedPropertyRegionBoundaryFeature = feature;
		updateAdminBoundaryBottomPill(feature, count);
		syncPropertyRegionCountSelectedLabels();
		renderAdminBoundaryOverlay();
		if (typeof openPropertyRegionCountListPanel === "function") {
			Promise.resolve(openPropertyRegionCountListPanel(feature, count))
				.catch((error) => console.warn("행정구역 매물 목록 열기 실패", error));
		}
	});
	return label;
}

function createParcelRegionTradeMapBadge(feature, mode, meta, data, selection)
{
	const badge = document.createElement("button");
	badge.type = "button";
	badge.className = "parcel-region-trade-map-badge";
	badge.style.cursor = "pointer";
	getAdminBoundaryStylePreference();
	badge.dataset.regionKey = getPropertyRegionCountSelectionKey(feature, mode);
	const previous = data?.periods?.previous || null;
	const recent = data?.periods?.recent || null;
	const hasTrades = Number(previous?.count || 0) + Number(recent?.count || 0) > 0;
	const change = getParcelRegionTradeChange(previous, recent, selection.metric);
	const regionName = getAdminBoundaryFeatureName(feature);
	badge.classList.add(hasTrades ? `is-${change.direction}` : "is-empty");
	badge.classList.toggle("is-selected", badge.dataset.regionKey === selectedPropertyRegionCountKey);
	badge.setAttribute("aria-pressed", badge.dataset.regionKey === selectedPropertyRegionCountKey ? "true" : "false");
	badge.setAttribute("aria-label", hasTrades
		? `${regionName} ${formatParcelRegionTradeMetric(recent, selection.metric)}, ${change.label}`
		: `${regionName} 거래없음`);
	const name = document.createElement("strong");
	name.textContent = regionName;
	const value = document.createElement("span");
	const valueText = hasTrades ? formatParcelRegionTradeMetric(recent, selection.metric) : "거래없음";
	value.textContent = valueText;
	value.classList.toggle("is-long-value", valueText.length >= 8);
	badge.append(name, value);
	if (hasTrades) {
		const changeLabel = document.createElement("small");
		changeLabel.textContent = change.direction === "up"
			? `▲ ${change.label}`
			: (change.direction === "down" ? `▼ ${change.label}` : change.label);
		badge.appendChild(changeLabel);
	}
	const stopBadgeMapEvent = (event) => {
		if (distanceMeasureActive) return false;
		event.stopPropagation();
		if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
		if (window.kakao?.maps?.event && typeof kakao.maps.event.preventMap === "function") {
			kakao.maps.event.preventMap();
		}
	};
	["pointerdown", "mousedown", "touchstart", "dblclick"].forEach((eventName) => {
		badge.addEventListener(eventName, stopBadgeMapEvent, { passive: false });
	});
	badge.addEventListener("click", (event) => {
		if (distanceMeasureActive) return;
		event.preventDefault();
		stopBadgeMapEvent(event);
		clearParcelBoundaryRenderState();
		selectedPropertyRegionCountKey = badge.dataset.regionKey;
		adminBoundarySelectedPoint = getParcelRegionTradeFeatureInteriorPoint(feature);
		selectedPropertyRegionBoundaryFeature = feature;
		syncPropertyRegionCountSelectedLabels();
		void openParcelRegionTradeStatsForFeature(
			feature,
			null,
			parcelRegionTradeSelection,
			{ source: "badge", regionKey: badge.dataset.regionKey }
		);
	});
	return badge;
}

function isParcelIndividualTradeLevelNow()
{
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	const level = Number(state.map?.getLevel?.());
	return category === "parcel" && Number.isFinite(level) && level >= 1 && level <= 5;
}

async function renderParcelRegionTradeMapBadgesUncached(mode, renderToken, renderSignature)
{
	if (renderToken !== propertyRegionCountRenderToken || isParcelIndividualTradeLevelNow()) return false;
	const type = getAdminBoundaryDataTypeForPresentationMode(mode);
	const data = await loadAdminBoundaryGeoJson(type);
	if (renderToken !== propertyRegionCountRenderToken || isParcelIndividualTradeLevelNow()
		|| renderSignature !== getParcelRegionTradeBadgeRenderSignature(mode) || !shouldRenderParcelRegionTradeMapBadges(mode)
		|| getPropertyMapPresentationMode() !== mode) return false;
	const features = Array.isArray(data?.features)
		? data.features.filter((feature) => doesParcelRegionTradeFeatureMatchMode(feature, mode))
		: [];
	const projection = typeof state.map.getProjection === "function" ? state.map.getProjection() : null;
	const positioned = features.map((feature) => {
		const point = getAdminBoundaryFeatureAnchor(feature);
		if (!point) return null;
		const position = new kakao.maps.LatLng(Number(point[1]), Number(point[0]));
		const screenPoint = projection && typeof projection.containerPointFromCoords === "function"
			? projection.containerPointFromCoords(position)
			: null;
		return { feature, position, screenPoint, hasPreferredAnchor: hasAdminBoundaryFeaturePreferredAnchor(feature) };
	}).filter(Boolean);
	const candidates = (await Promise.all(positioned.map(async (candidate) => ({
		...candidate,
		meta: await loadParcelRegionTradeBadgeMeta(candidate.feature)
	})))).filter((candidate) => candidate.meta?.regionCode);
	if (renderToken !== propertyRegionCountRenderToken || isParcelIndividualTradeLevelNow()) return false;
	const statsByKey = await fetchParcelRegionTradeStatsBatch(candidates.map((candidate) => candidate.meta), parcelRegionTradeSelection);
	if (renderToken !== propertyRegionCountRenderToken || isParcelIndividualTradeLevelNow()
		|| renderSignature !== getParcelRegionTradeBadgeRenderSignature(mode) || !shouldRenderParcelRegionTradeMapBadges(mode)
		|| getPropertyMapPresentationMode() !== mode) return false;
	const visibleCandidates = candidates.sort((a, b) => {
		if (a.hasPreferredAnchor !== b.hasPreferredAnchor) return a.hasPreferredAnchor ? -1 : 1;
		return getAdminBoundaryFeatureName(a.feature).localeCompare(getAdminBoundaryFeatureName(b.feature), "ko");
	});
	clearPropertyRegionCountOverlays();
	visibleCandidates.forEach((candidate) => {
		const stats = statsByKey.get(getParcelRegionTradeMetaKey(candidate.meta)) || null;
		const content = createParcelRegionTradeMapBadge(
			candidate.feature,
			mode,
			candidate.meta,
			stats,
			parcelRegionTradeSelection
		);
		const overlay = new kakao.maps.CustomOverlay({
			map: state.map,
			position: candidate.position,
			content,
			xAnchor: 0.5,
			yAnchor: 0.5,
			zIndex: 24
		});
		overlay.__realjejuRegionCountLabel = content;
		bindPropertyRegionCountOverlayHover(content, overlay);
		propertyRegionCountOverlays.push(overlay);
	});
	if (hasAdminBoundarySelectedPoint() || selectedPropertyRegionBoundaryFeature) {
		void renderAdminBoundaryOverlay();
	}
	return true;
}

function getParcelRegionTradeBadgeRenderSignature(mode) {
  return [
    String(mode || ""),
    String(parcelRegionTradeSelection?.type || "land"),
    Number(parcelRegionTradeSelection?.months || 3),
    String(parcelRegionTradeSelection?.metric || "totalAmount"),
    String(parcelRegionTradeSelection?.metric === "unitPrice" ? globalAreaUnit : "fixed")
  ].join("|");
}

function loadParcelRegionTradeBadgeMeta(feature) {
  if (!feature || (typeof feature !== "object" && typeof feature !== "function")) {
    return buildParcelRegionTradeMeta(feature, null);
  }
  if (parcelRegionTradeMetaPromiseCache.has(feature)) {
    return parcelRegionTradeMetaPromiseCache.get(feature);
  }
  const request = Promise.resolve(buildParcelRegionTradeMeta(feature, null));
  parcelRegionTradeMetaPromiseCache.set(feature, request);
  request.catch(() => {
    if (parcelRegionTradeMetaPromiseCache.get(feature) === request) {
      parcelRegionTradeMetaPromiseCache.delete(feature);
    }
  });
  return request;
}

async function renderParcelRegionTradeMapBadges(mode, renderToken) {
  const renderSignature = getParcelRegionTradeBadgeRenderSignature(mode);
  const renderedMode = String(parcelRegionTradeBadgeRenderedSignature || "").split("|")[0];
  if (renderedMode && renderedMode !== String(mode || "") && propertyRegionCountOverlays.length) {
    // 새 단계가 준비될 때까지 기존 네모 뱃지를 유지한다.
    parcelRegionTradeBadgeRenderedSignature = "";
  }
  if (parcelRegionTradeBadgeRenderedSignature === renderSignature
      && propertyRegionCountOverlays.length) {
    return true;
  }
  if (parcelRegionTradeBadgeRenderInFlight.has(renderSignature)) {
    return parcelRegionTradeBadgeRenderInFlight.get(renderSignature);
  }
  const request = renderParcelRegionTradeMapBadgesUncached(mode, renderToken, renderSignature);
  parcelRegionTradeBadgeRenderInFlight.set(renderSignature, request);
  try {
    const rendered = await request;
    if (rendered && renderToken === propertyRegionCountRenderToken
        && !isParcelIndividualTradeLevelNow()
        && renderSignature === getParcelRegionTradeBadgeRenderSignature(mode)) {
      parcelRegionTradeBadgeRenderedSignature = renderSignature;
    }
    return rendered;
  } finally {
    if (parcelRegionTradeBadgeRenderInFlight.get(renderSignature) === request) {
      parcelRegionTradeBadgeRenderInFlight.delete(renderSignature);
    }
  }
}

async function renderPropertyRegionCountOverlays(mode = getPropertyMapPresentationMode(), options = {})
{
	if (isParcelIndividualTradeLevelNow()) {
		propertyLocalCountEntryAnimationPending = false;
		propertyRegionCountRenderToken += 1;
		parcelRegionTradeBadgeRenderedSignature = "";
		clearPropertyRegionCountOverlays();
		return false;
	}
	if ((!shouldUsePropertyMapLevelPresentation() && !shouldRenderParcelRegionTradeMapBadges(mode)) || !isPropertyRegionCountMode(mode)) {
		propertyLocalCountEntryAnimationPending = false;
		propertyRegionCountRenderToken += 1;
		clearPropertyRegionCountOverlays();
		return false;
	}
	const renderToken = ++propertyRegionCountRenderToken;
	if (shouldRenderParcelRegionTradeMapBadges(mode)) {
		try {
			return await renderParcelRegionTradeMapBadges(mode, renderToken);
		} catch (error) {
			if (renderToken !== propertyRegionCountRenderToken) return false;
			clearPropertyRegionCountOverlays();
			console.warn("행정구역 실거래 통계 뱃지 표시 실패", error);
			if (options.throwOnError === true) throw error;
			return false;
		}
	}
	const type = mode === "city-counts" ? "sig" : (mode === "local-counts" ? "local" : "emd");
	try {
		// 네모 뱃지는 전체 매물 배열이 아니라 DB가 계산한 지역별 집계 행만 사용한다.
		const statsByCode = await loadPropertyScaleRegionStats(mode);
		if (renderToken !== propertyRegionCountRenderToken
			|| !shouldUsePropertyMapLevelPresentation()
			|| getPropertyMapPresentationMode() !== mode) return false;
		// 원형→네모 직후 곧바로 더 축소되어 시ㆍ도 네모 단계가 된 경우에는
		// 보류 플래그를 폐기해 나중에 local-counts로 돌아올 때 잘못 재생되지 않게 합니다.
		if (mode !== "local-counts") propertyLocalCountEntryAnimationPending = false;
		if (mode === "province-count") {
			clearPropertyRegionCountOverlays();
			const totalStats = statsByCode.get("50") || { listingCount: 0, brokerCount: 0 };
			const totalCount = Number(totalStats.listingCount || 0);
			const totalBrokerCount = Number(totalStats.brokerCount || 0);
			if (renderToken !== propertyRegionCountRenderToken) return false;
			const content = createPropertyRegionCountLabel(
				"제주도 전체",
				totalCount,
				totalBrokerCount,
				mode,
				JEJU_PROVINCE_REGION_FEATURE
			);
			const overlay = new kakao.maps.CustomOverlay({
				map: state.map,
				position: new kakao.maps.LatLng(33.38, 126.53),
				content,
				xAnchor: 0.5,
				yAnchor: 0.5,
				zIndex: getPropertyRegionCountOverlayZIndex(content)
			});
			overlay.__realjejuRegionCountLabel = content;
			bindPropertyRegionCountOverlayHover(content, overlay);
			propertyRegionCountOverlays.push(overlay);
			if (hasAdminBoundarySelectedPoint() || selectedPropertyRegionBoundaryFeature) {
				void renderAdminBoundaryOverlay();
			}
			return true;
		}
		const data = await loadAdminBoundaryGeoJson(type);
		if (renderToken !== propertyRegionCountRenderToken
			|| !shouldUsePropertyMapLevelPresentation()
			|| getPropertyMapPresentationMode() !== mode) return false;
		const features = Array.isArray(data && data.features) ? data.features : [];
		const projection = typeof state.map.getProjection === "function" ? state.map.getProjection() : null;
		const shouldShowZeroForMode = mode === "city-counts";
		const candidates = features.map((feature) => {
			const stats = statsByCode.get(getAdminBoundaryFeatureCodeValue(feature)) || { listingCount: 0, brokerCount: 0 };
			const count = Number(stats.listingCount || 0);
			const brokerCount = Number(stats.brokerCount || 0);
			const point = (count > 0 || shouldShowZeroForMode) ? getVisibleAdminBoundaryFeatureAnchor(feature) : null;
			if (!point) return null;
			const position = new kakao.maps.LatLng(Number(point[1]), Number(point[0]));
			const screenPoint = projection && typeof projection.containerPointFromCoords === "function"
				? projection.containerPointFromCoords(position)
				: null;
			const hasPreferredAnchor = hasAdminBoundaryFeaturePreferredAnchor(feature);
			return { feature, count, brokerCount, position, screenPoint, hasPreferredAnchor };
		}).filter(Boolean).sort((a, b) => {
			if (a.hasPreferredAnchor !== b.hasPreferredAnchor) return a.hasPreferredAnchor ? -1 : 1;
			return b.count - a.count;
		});

		const visibleCandidates = candidates.slice();

		// 원형→네모 경계에서 준비된 상태는 최종 local-counts 오버레이 생성 때 한 번만 소비한다.
		const animateEntry = mode === "local-counts" && propertyLocalCountEntryAnimationPending;
		if (animateEntry) propertyLocalCountEntryAnimationPending = false;
		clearPropertyRegionCountOverlays();
		visibleCandidates.forEach((candidate) => {
			const content = createPropertyRegionCountLabel(
				getAdminBoundaryFeatureName(candidate.feature),
				candidate.count,
				candidate.brokerCount,
				mode,
				candidate.feature,
				{ animateEntry }
			);
			const overlay = new kakao.maps.CustomOverlay({
				map: state.map,
				position: candidate.position,
				content,
				xAnchor: 0.5,
				yAnchor: 0.5,
				zIndex: getPropertyRegionCountOverlayZIndex(content)
			});
			overlay.__realjejuRegionCountLabel = content;
			bindPropertyRegionCountOverlayHover(content, overlay);
			propertyRegionCountOverlays.push(overlay);
		});
		if (hasAdminBoundarySelectedPoint() || selectedPropertyRegionBoundaryFeature) {
			void renderAdminBoundaryOverlay();
		}
		return true;
	} catch (error) {
		if (renderToken !== propertyRegionCountRenderToken) return false;
		clearPropertyRegionCountOverlays();
		console.warn("축척별 행정구역 매물 수 표시 실패", error);
		if (options.throwOnError === true) throw error;
		return false;
	}
}

function syncPropertyMapPresentationForCurrentLevel()
{
	if (!shouldUsePropertyMapLevelPresentation()) {
		propertyMapPresentationMode = "";
		propertyLocalCountEntryAnimationPending = false;
		propertyRegionCountRenderToken += 1;
		clearPropertyRegionCountOverlays();
		return;
	}
	const mode = getPropertyMapPresentationMode();
	const modeChanged = propertyMapPresentationMode !== mode;
	propertyMapPresentationMode = mode;
	if (isPropertyRegionCountMode(mode)) {
		clearMapObjects();
		renderPropertyRegionCountOverlays(mode);
		return;
	}
	propertyRegionCountRenderToken += 1;
	clearPropertyRegionCountOverlays();
	clearPropertyRegionCountSelection();
	if (modeChanged && Array.isArray(state.filtered) && state.filtered.length) {
		renderMarkers(state.filtered, { preserveViewport: true });
	}
}

function beginPropertyPresentationBoundaryTransition()
{
	if (!shouldUsePropertyMapLevelPresentation()) return false;
	const nextMode = getPropertyMapPresentationMode();
	const previousMode = propertyMapPresentationMode;
	const hasCircleMarkers = Array.isArray(state.markers) && state.markers.length > 0;
	const hasSquareBadges = Array.isArray(propertyRegionCountOverlays) && propertyRegionCountOverlays.length > 0;
	const entersRegionCountModeFromCircles = isPropertyRegionCountMode(nextMode)
		&& (previousMode === "clusters" || hasCircleMarkers);
	const shouldAnimateLocalCountEntry = false;
	const returnsToMarkerMode = (nextMode === "clusters" || nextMode === "individual")
		&& (isPropertyRegionCountMode(previousMode) || hasSquareBadges);
	const markerRestoreVisibleBounds = returnsToMarkerMode ? getPropertyScaleViewportBounds() : null;
	const markerRestoreCoverageKey = returnsToMarkerMode
		? getPropertyScaleViewportCoverageKey("actual-viewport", buildPropertyScaleFilters())
		: "";
	const markerRestoreSnapshot = markerRestoreVisibleBounds
		? readPropertyScaleMarkerSnapshot(markerRestoreCoverageKey, markerRestoreVisibleBounds)
		: null;
	const changesRegionCountLevel = isPropertyRegionCountMode(previousMode)
		&& isPropertyRegionCountMode(nextMode)
		&& previousMode !== nextMode;
	if (!entersRegionCountModeFromCircles && !returnsToMarkerMode && !changesRegionCountLevel) return false;

	// 네모 행정구역 집계 단계가 시작되면 기존 라운드 버튼을 잠깐 비운 뒤
	// 새 모드 상태에서 다시 표시 가능한 데이터가 있으면 즉시 복원한다.
	if (isPropertyRegionCountMode(nextMode) && !selectedPropertyRegionBoundaryFeature && !adminBoundaryBottomPillFeature) {
		hideAdminBoundaryBottomPill();
	}

	// 줌 시작 시 이전 표현과 비동기 렌더를 폐기하고, idle에서 최종 단계만 그린다.
	// 원형 좌표는 화면 객체와 분리된 스냅샷에 보관하므로 네모 단계에 다시 노출되지 않는다.
	if (entersRegionCountModeFromCircles) {
		storePropertyScaleMarkerSnapshot();
		propertyLocalCountEntryAnimationPending = shouldAnimateLocalCountEntry;
	}
	const resetsRegionSelection = returnsToMarkerMode || changesRegionCountLevel;
	if (resetsRegionSelection) propertyLocalCountEntryAnimationPending = false;
	propertyScaleViewportRequestSeq += 1;
	propertyRegionCountRenderToken += 1;
	clearMapObjects();
	// 네모 단계끼리 이동할 때는 새 단계가 준비될 때까지 기존 뱃지를 유지한다.
	if (!isPropertyRegionCountMode(nextMode)) clearPropertyRegionCountOverlays();
	propertyMapPresentationMode = nextMode;
	if (isPropertyRegionCountMode(nextMode)) {
		void renderPropertyRegionCountOverlays(nextMode);
	}
	if (returnsToMarkerMode) hideAdminBoundaryBottomPill();
	if (resetsRegionSelection) {
		const keepsLocalBoundaryInMarkerMode = (nextMode === "clusters" || nextMode === "individual")
			&& (hasAdminBoundarySelectedPoint() || !!selectedPropertyRegionBoundaryFeature);
		clearPropertyRegionCountSelection({
			preserveAdminBoundaryPoint: changesRegionCountLevel || keepsLocalBoundaryInMarkerMode,
			preservePropertyRegionBoundaryFeature: changesRegionCountLevel || keepsLocalBoundaryInMarkerMode
		});
	}
	if (returnsToMarkerMode && markerRestoreSnapshot) {
		propertyScaleViewportCoverage = {
			key: markerRestoreSnapshot.coverage.key,
			bounds: { ...markerRestoreSnapshot.coverage.bounds }
		};
		state.all = markerRestoreSnapshot.items.slice();
		state.filtered = markerRestoreSnapshot.items.slice();
		mapListingsLastLoadedAt = Date.now();
		renderMarkers(state.filtered, { preserveViewport: true });
	}
	return true;
}

function ensureAdminBoundaryBottomPill()
{
	if (adminBoundaryBottomPill) return adminBoundaryBottomPill;
	const mapWrap = document.querySelector(".map-wrap");
	if (!mapWrap) return null;
	adminBoundaryBottomPill = document.createElement("div");
	adminBoundaryBottomPill.className = "admin-boundary-bottom-pill";
	adminBoundaryBottomPill.setAttribute("role", "button");
	adminBoundaryBottomPill.setAttribute("tabindex", "0");
	adminBoundaryBottomPill.setAttribute("aria-live", "polite");
	adminBoundaryBottomPill.setAttribute("aria-label", "현재 행정구역 매물 목록 열기");
	adminBoundaryBottomPill.addEventListener("click", openAdminBoundaryBottomPillRegionMenu);
	adminBoundaryBottomPill.addEventListener("keydown", (event) => {
		if (event.key !== "Enter" && event.key !== " ") return;
		openAdminBoundaryBottomPillRegionMenu(event);
	});
	adminBoundaryBottomPill.hidden = true;
	mapWrap.appendChild(adminBoundaryBottomPill);
	return adminBoundaryBottomPill;
}

function openAdminBoundaryBottomPillRegionMenu(event)
{
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	const feature = adminBoundaryBottomPillFeature;
	if (!feature || typeof openPropertyRegionCountListPanel !== "function") return;
	Promise.resolve(openPropertyRegionCountListPanel(feature, adminBoundaryBottomPillCount))
		.catch((error) => console.warn("행정구역 매물 목록 열기 실패:", error));
}

function hideAdminBoundaryBottomPill(options = {})
{
	const pill = ensureAdminBoundaryBottomPill();
	if (!pill) return;
	pill.hidden = true;
	pill.innerHTML = "";
	if (options.preserveState === true) return;
	adminBoundaryBottomPillFeature = null;
	adminBoundaryBottomPillCount = 0;
}

function shouldShowAdminBoundaryBottomPill()
{
	if (!document.body || !state || !state.map) return false;
	if (state.isPropertyMarkersVisible === false) return false;
	if (document.body.classList.contains("main-landing-page-open")
		|| document.body.classList.contains("presale-page-open")
		|| !!document.querySelector(".terms-full-page.open")
		|| !!document.querySelector(".company-full-page.open")) return false;
	if (distanceMeasureActive || (distanceMeasureToolbar && !distanceMeasureToolbar.hidden)) return false;
	if (typeof isRealjejuWorkspacePageOpen === "function" && isRealjejuWorkspacePageOpen()) return false;
	if (typeof shouldShowGlobalCategoryEmptyMap === "function" && shouldShowGlobalCategoryEmptyMap()) return false;
	// 4.946: 하단 행정구역 매물 개수 버튼은 원형 클러스터 단계(레벨 4~5), 네모 집계 단계,
	// 개별 매물 단계(레벨 1~3)에서도 유지합니다. 지도 숫자ㆍ마커ㆍ좌표 계산은 변경하지 않습니다.
	const presentationMode = getPropertyMapPresentationMode();
	const isMobileViewport = typeof window.matchMedia === "function"
		&& window.matchMedia("(max-width: 850px)").matches;
	if (isMobileViewport && isPropertyRegionCountMode(presentationMode)) return false;
	// 5.270: 도ㆍ시 집계 단계에서는 중앙 하단 매물 수를 표시하지 않습니다.
	if (presentationMode === "province-count" || presentationMode === "city-counts") return false;
	if (presentationMode !== "clusters" && presentationMode !== "individual" && !isPropertyRegionCountMode(presentationMode)) return false;
	const category = document.body.dataset ? String(document.body.dataset.globalCategory || "realestate") : "realestate";
	return typeof isGlobalRealestateCategory === "function" ? isGlobalRealestateCategory(category) : (!category || category === "realestate");
}

function updateAdminBoundaryBottomPill(feature, count)
{
	// 하단 라운드 버튼을 다시 표시하는 모든 비동기 경로의 최종 관문입니다.
	// 행정구역 경계 집계가 늦게 끝나도 도ㆍ시 집계 단계에서는 다시 노출하지 않습니다.
	if (!shouldShowAdminBoundaryBottomPill()) {
		hideAdminBoundaryBottomPill({
			preserveState: state.isPropertyMarkersVisible === false
		});
		return;
	}
	const pill = ensureAdminBoundaryBottomPill();
	if (!pill || !feature) return;
	const name = getAdminBoundaryFeatureName(feature);
	adminBoundaryBottomPillFeature = feature;
	adminBoundaryBottomPillCount = Math.max(0, Number(count) || 0);
	pill.setAttribute("aria-label", name + " 매물 목록 열기");
	pill.innerHTML = '<span class="admin-boundary-bottom-pill-name">' + escapeHtml(name) + '</span>'
		+ '<span class="admin-boundary-bottom-pill-count"><span class="admin-boundary-bottom-pill-count-label">매물</span> <span class="admin-boundary-bottom-pill-count-number">' + Number(count || 0).toLocaleString("ko-KR") + '</span></span>';
	pill.hidden = false;
}

async function refreshAdminBoundaryBottomPill()
{
	if (!shouldShowAdminBoundaryBottomPill()) {
		hideAdminBoundaryBottomPill({
			preserveState: state.isPropertyMarkersVisible === false
		});
		return;
	}
	if (adminBoundaryBottomPillFeature && Number.isFinite(Number(adminBoundaryBottomPillCount))) {
		updateAdminBoundaryBottomPill(adminBoundaryBottomPillFeature, adminBoundaryBottomPillCount);
		return;
	}
	if (selectedPropertyRegionBoundaryFeature) {
		const mode = getPropertyMapPresentationMode();
		const statsByCode = await loadPropertyScaleRegionStats(mode);
		const regionCode = getPropertyScaleRegionCode(selectedPropertyRegionBoundaryFeature);
		const listingCount = statsByCode.get(regionCode || "")?.listingCount;
		if (Number.isFinite(Number(listingCount))) {
			updateAdminBoundaryBottomPill(selectedPropertyRegionBoundaryFeature, listingCount);
			return;
		}
	}
	hideAdminBoundaryBottomPill();
}

async function renderAdminBoundaryOverlay(options = {})
{
	const renderToken = ++adminBoundaryOverlayRenderToken;
	clearAdminBoundaryOverlay();
	const preferredFeature = options?.preferredFeature || null;
	const forceParcelFeature = getCurrentRealjejuGlobalCategoryKey() === "parcel"
		&& !!preferredFeature
		&& (options?.source === "parcel-badge" || options?.source === "parcel-map");
	if (!forceParcelFeature && !shouldShowPropertyScaleAdminBoundaryOverlay()) {
		return;
	}
	try {
		const mode = getPropertyMapPresentationMode();
		const shouldUseParcelFeature = shouldUseParcelAdminBoundaryPresentation();
		const selectedPoint = hasAdminBoundarySelectedPoint()
			? adminBoundarySelectedPoint.slice(0, 2)
			: null;
		let feature = preferredFeature || (shouldUseParcelFeature
			&& selectedPropertyRegionBoundaryFeature
			&& doesParcelRegionTradeFeatureMatchMode(selectedPropertyRegionBoundaryFeature, mode)
			? selectedPropertyRegionBoundaryFeature
			: (selectedPoint
				? await findAdminBoundaryFeatureForPoint(selectedPoint, mode)
				: selectedPropertyRegionBoundaryFeature));
		if (!feature && selectedPropertyRegionBoundaryFeature) {
			feature = selectedPropertyRegionBoundaryFeature;
		}
		if (renderToken !== adminBoundaryOverlayRenderToken || (!forceParcelFeature && !shouldShowPropertyScaleAdminBoundaryOverlay())) return;
		if (!feature) return;
		if (shouldUseParcelFeature) {
			selectedPropertyRegionBoundaryFeature = feature;
			const nextPoint = getParcelRegionTradeFeatureInteriorPoint(feature);
			if (nextPoint) adminBoundarySelectedPoint = nextPoint;
			if (state.leftListDetailMode === "parcel-region-stats" && propertyList?.querySelector(".parcel-region-trade-stats-panel")) {
				const currentCode = String(propertyList.querySelector(".parcel-region-trade-stats-panel")?.dataset.regionCode || "");
				const nextMeta = buildParcelRegionTradeMeta(feature, null);
				if (nextMeta.regionCode && nextMeta.regionCode !== currentCode) {
					void loadParcelRegionTradeStatsPanel(nextMeta, parcelRegionTradeSelection);
				}
			}
		}
		const style = getAdminBoundaryStyle();
		getGeoJsonOuterRings(feature.geometry).forEach((ring) => {
			const path = getAdminBoundaryRingPath(ring);
			if (path.length < 3) return;
			const polygon = new kakao.maps.Polygon({
				path,
				strokeWeight: style.strokeWeight,
				strokeColor: style.strokeColor,
				strokeOpacity: style.strokeOpacity,
				strokeStyle: style.strokeStyle,
				fillColor: style.fillColor,
				fillOpacity: style.fillOpacity,
				zIndex: PARCEL_BOUNDARY_ACTIVE_Z_INDEX
			});
			polygon.setMap(state.map);
			if (typeof polygon.setZIndex === "function") polygon.setZIndex(PARCEL_BOUNDARY_ACTIVE_Z_INDEX);
			adminBoundaryOverlayPolygons.push(polygon);
		});
	} catch (error) {
		if (renderToken !== adminBoundaryOverlayRenderToken) return;
		console.warn("선택 행정구역 경계 표시 실패", error);
		clearAdminBoundaryOverlay();
	}
}

function getFactoryRestrictionDataUrls()
{
	let localUrl = FACTORY_RESTRICTION_GEOJSON_URL;
	try {
		localUrl = resolveRealjejuLocalAssetUrl(FACTORY_RESTRICTION_GEOJSON_URL);
	} catch (error) {}
	const remoteUrl = typeof toRemotePath === "function" ? toRemotePath(FACTORY_RESTRICTION_GEOJSON_URL) : "";
	return [localUrl, remoteUrl].filter((url, index, list) => url && list.indexOf(url) === index);
}

function isFactoryRestrictionGeoJson(data)
{
	return !!(data && data.type === "FeatureCollection" && Array.isArray(data.features));
}

async function loadFactoryRestrictionGeoJson()
{
	if (factoryRestrictionGeoJsonCache) return factoryRestrictionGeoJsonCache;
	if (factoryRestrictionGeoJsonPromise) return factoryRestrictionGeoJsonPromise;
	if (factoryRestrictionGeoJsonFailureUntil > Date.now()) {
		throw new Error("공장설립제한 자료 재시도 대기 중");
	}

	const request = (async () => {
		let responseCache = null;
		if (window.caches && window.isSecureContext) {
			try {
				responseCache = await window.caches.open(FACTORY_RESTRICTION_CACHE_NAME);
			} catch (error) {
				responseCache = null;
			}
		}
		let lastError = null;
		for (const url of getFactoryRestrictionDataUrls()) {
			if (responseCache) {
				try {
					const cachedResponse = await responseCache.match(url);
					if (cachedResponse) {
						const cachedData = await cachedResponse.json();
						if (isFactoryRestrictionGeoJson(cachedData)) return cachedData;
					}
				} catch (error) {
					lastError = error;
				}
			}
			try {
				const response = await fetch(url, { cache: "no-cache" });
				if (!response.ok) throw new Error(`공장설립제한 자료 로드 실패: ${response.status}`);
				if (responseCache) {
					try {
						await responseCache.put(url, response.clone());
					} catch (error) {}
				}
				const data = await response.json();
				if (!isFactoryRestrictionGeoJson(data)) throw new Error("공장설립제한 자료 형식 오류");
				return data;
			} catch (error) {
				lastError = error;
			}
		}
		throw lastError || new Error("공장설립제한 자료를 불러오지 못했습니다.");
	})()
		.then((data) => {
			factoryRestrictionGeoJsonCache = data;
			factoryRestrictionGeoJsonFailureUntil = 0;
			return data;
		})
		.catch((error) => {
			factoryRestrictionGeoJsonFailureUntil = Date.now() + FACTORY_RESTRICTION_FAILURE_COOLDOWN_MS;
			throw error;
		})
		.finally(() => {
			if (factoryRestrictionGeoJsonPromise === request) factoryRestrictionGeoJsonPromise = null;
		});
	factoryRestrictionGeoJsonPromise = request;
	return request;
}

function getFactoryRestrictionPolygonGroups(geometry)
{
	if (!geometry || !Array.isArray(geometry.coordinates)) return [];
	if (geometry.type === "Polygon") return [geometry.coordinates];
	if (geometry.type === "MultiPolygon") return geometry.coordinates;
	return [];
}

function getFactoryRestrictionRingPath(ring)
{
	if (!Array.isArray(ring)) return [];
	return ring
		.map((point) => Array.isArray(point) ? new kakao.maps.LatLng(Number(point[1]), Number(point[0])) : null)
		.filter(Boolean);
}

function clearFactoryRestrictionOverlay()
{
	factoryRestrictionOverlayPolygons.forEach((polygon) => {
		if (polygon && typeof polygon.setMap === "function") polygon.setMap(null);
	});
	factoryRestrictionOverlayPolygons = [];
	isFactoryRestrictionOverlayRenderComplete = false;
	syncFactoryRestrictionLegend();
}

function syncFactoryRestrictionLegend()
{
	if (!factoryRestrictionLegend) return;
	const isAnyFacilityPanelOpen = typeof isAnyFacilityFilterPanelOpen === "function" && isAnyFacilityFilterPanelOpen();
	const shouldShow = !!(isFactoryRestrictionOverlayVisible && isFactoryRestrictionOverlayRenderComplete && !isAnyFacilityPanelOpen);
	factoryRestrictionLegend.classList.toggle("open", shouldShow);
	factoryRestrictionLegend.setAttribute("aria-hidden", shouldShow ? "false" : "true");
}

async function renderFactoryRestrictionOverlay()
{
	if (!isFactoryRestrictionOverlayVisible || !state.map || !window.kakao || !kakao.maps || factoryRestrictionOverlayLoading) return;
	if (factoryRestrictionOverlayPolygons.length) {
		factoryRestrictionOverlayPolygons.forEach((polygon) => polygon.setMap(state.map));
		isFactoryRestrictionOverlayRenderComplete = true;
		if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
		return;
	}
	const renderToken = ++factoryRestrictionOverlayRenderToken;
	factoryRestrictionOverlayLoading = true;
	try {
		const data = await loadFactoryRestrictionGeoJson();
		if (renderToken !== factoryRestrictionOverlayRenderToken || !isFactoryRestrictionOverlayVisible) return;
		const polygons = [];
		(data.features || []).forEach((feature) => {
			getFactoryRestrictionPolygonGroups(feature && feature.geometry).forEach((group) => {
				const paths = (Array.isArray(group) ? group : [])
					.map(getFactoryRestrictionRingPath)
					.filter((path) => path.length >= 3);
				if (!paths.length) return;
				const polygon = new kakao.maps.Polygon({
					path: paths.length === 1 ? paths[0] : paths,
					strokeWeight: 2,
					strokeColor: "#f59e0b",
					strokeOpacity: 0.88,
					fillColor: "#f59e0b",
					fillOpacity: 0.14,
					clickable: false,
					zIndex: 2
				});
				polygon.setMap(state.map);
				polygons.push(polygon);
			});
		});
		if (renderToken !== factoryRestrictionOverlayRenderToken || !isFactoryRestrictionOverlayVisible) {
			polygons.forEach((polygon) => polygon.setMap(null));
			return;
		}
		factoryRestrictionOverlayPolygons = polygons;
		isFactoryRestrictionOverlayRenderComplete = polygons.length > 0;
		if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
	} catch (error) {
		console.warn("공장설립제한 지역 표시 실패:", error);
		isFactoryRestrictionOverlayVisible = false;
		clearFactoryRestrictionOverlay();
		syncDevelopmentFacilityPanelUI();
		updateDevelopmentToolActiveState();
		if (typeof openAuthErrorModal === "function") {
			openAuthErrorModal("공장설립제한 자료를 불러오지 못했습니다.", "공장", mapDevelopmentToolBtn || null);
		}
	} finally {
		factoryRestrictionOverlayLoading = false;
		if (isFactoryRestrictionOverlayVisible
			&& !factoryRestrictionOverlayPolygons.length
			&& renderToken !== factoryRestrictionOverlayRenderToken) {
			Promise.resolve().then(renderFactoryRestrictionOverlay);
		}
	}
}

