async function loadSewerTreatmentAreaGeoJson()
{
	if (sewerTreatmentAreaGeoJsonCache) return sewerTreatmentAreaGeoJsonCache;
	if (sewerTreatmentAreaGeoJsonPromise) return sewerTreatmentAreaGeoJsonPromise;
	if (sewerTreatmentAreaGeoJsonFailureUntil > Date.now()) {
		throw new Error("하수처리구역 자료 재시도 대기 중");
	}

	// 하나의 진행 중 요청을 공유해 빠른 재클릭이나 지도 재렌더가 중복 전송을 만들지 않게 한다.
	const request = loadRealjejuPolygonBinary(
		getSewerTreatmentAreaDataUrls(),
		SEWER_TREATMENT_AREA_CACHE_NAME,
		"하수처리구역"
	)
		.then((data) => {
			sewerTreatmentAreaGeoJsonCache = data;
			sewerTreatmentAreaGeoJsonFailureUntil = 0;
			return data;
		})
		.catch((error) => {
			sewerTreatmentAreaGeoJsonFailureUntil = Date.now() + SEWER_TREATMENT_AREA_FAILURE_COOLDOWN_MS;
			throw error;
		})
		.finally(() => {
			if (sewerTreatmentAreaGeoJsonPromise === request) sewerTreatmentAreaGeoJsonPromise = null;
		});
	sewerTreatmentAreaGeoJsonPromise = request;
	return request;
}

