function getCulturalHeritageProtectionDataUrls()
{
	let localUrl = CULTURAL_HERITAGE_PROTECTION_GEOJSON_URL;
	try {
		localUrl = resolveRealjejuLocalAssetUrl(CULTURAL_HERITAGE_PROTECTION_GEOJSON_URL);
	} catch (error) {}
	const remoteUrl = typeof toRemotePath === "function" ? toRemotePath(CULTURAL_HERITAGE_PROTECTION_GEOJSON_URL) : "";
	return [localUrl, remoteUrl].filter((url, index, list) => url && list.indexOf(url) === index);
}

function isCulturalHeritageProtectionGeoJson(data)
{
	return !!(data && data.type === "FeatureCollection" && Array.isArray(data.features));
}

async function loadCulturalHeritageProtectionGeoJson()
{
	if (culturalHeritageProtectionGeoJsonCache) return culturalHeritageProtectionGeoJsonCache;
	if (culturalHeritageProtectionGeoJsonPromise) return culturalHeritageProtectionGeoJsonPromise;
	if (culturalHeritageProtectionGeoJsonFailureUntil > Date.now()) {
		throw new Error("문화재보호구역 자료 재시도 대기 중");
	}

	const request = (async () => {
		let responseCache = null;
		if (window.caches && window.isSecureContext) {
			try {
				responseCache = await window.caches.open(CULTURAL_HERITAGE_PROTECTION_CACHE_NAME);
			} catch (error) {
				responseCache = null;
			}
		}
		let lastError = null;
		for (const url of getCulturalHeritageProtectionDataUrls()) {
			if (responseCache) {
				try {
					const cachedResponse = await responseCache.match(url);
					if (cachedResponse) {
						const cachedData = await cachedResponse.json();
						if (isCulturalHeritageProtectionGeoJson(cachedData)) return cachedData;
					}
				} catch (error) {
					lastError = error;
				}
			}
			try {
				const response = await fetch(url, { cache: "no-cache" });
				if (!response.ok) throw new Error(`문화재보호구역 자료 로드 실패: ${response.status}`);
				if (responseCache) {
					try {
						await responseCache.put(url, response.clone());
					} catch (error) {}
				}
				const data = await response.json();
				if (!isCulturalHeritageProtectionGeoJson(data)) throw new Error("문화재보호구역 자료 형식 오류");
				return data;
			} catch (error) {
				lastError = error;
			}
		}
		throw lastError || new Error("문화재보호구역 자료를 불러오지 못했습니다.");
	})()
		.then((data) => {
			culturalHeritageProtectionGeoJsonCache = data;
			culturalHeritageProtectionGeoJsonFailureUntil = 0;
			return data;
		})
		.catch((error) => {
			culturalHeritageProtectionGeoJsonFailureUntil = Date.now() + CULTURAL_HERITAGE_PROTECTION_FAILURE_COOLDOWN_MS;
			throw error;
		})
		.finally(() => {
			if (culturalHeritageProtectionGeoJsonPromise === request) culturalHeritageProtectionGeoJsonPromise = null;
		});
	culturalHeritageProtectionGeoJsonPromise = request;
	return request;
}

function clearCulturalHeritageProtectionOverlay()
