function isParcelRegulationToolMode()
{
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "");
	return category === "parcel";
}

function syncParcelRegulationToolActiveState()
{
	const parcelMode = isParcelRegulationToolMode();
	const presentations = parcelMode
		? [
			[mapEducationToolBtn, "하수", "하수처리구역", "fa-droplet"],
			[mapConvenienceToolBtn, "문화재", "문화재보호구역", "fa-landmark"],
			[mapDevelopmentToolBtn, "공장", "공장설립제한지역", "fa-industry"],
			[mapBrokerToolBtn, "가축", "가축사육제한구역", "fa-cow"]
		]
		: [
			[mapEducationToolBtn, "교육", "교육", "fa-graduation-cap"],
			[mapConvenienceToolBtn, "편의", "편의", "fa-heart"],
			[mapDevelopmentToolBtn, "개발", "개발", "fa-road-barrier"],
			[mapBrokerToolBtn, "중개", "중개", "fa-user-tie"]
		];
	presentations.forEach(([button, label, title, iconClass]) => {
		if (!button) return;
		button.setAttribute("aria-label", title);
		button.setAttribute("title", title);
		const labelNode = button.querySelector(".map-tool-label");
		if (labelNode) labelNode.textContent = label;
		const iconNode = button.querySelector(".map-tool-icon i");
		if (iconNode) iconNode.className = `fa-solid ${iconClass}`;
	});
	const group = document.getElementById("mapContextToolGroup");
	if (group) group.setAttribute("aria-label", parcelMode ? "필지 규제구역 도구" : "입지 도구");
	if (!parcelMode) return false;
	[
		[mapEducationToolBtn, isSewerTreatmentAreaOverlayVisible],
		[mapConvenienceToolBtn, isCulturalHeritageProtectionOverlayVisible],
		[mapDevelopmentToolBtn, isFactoryRestrictionOverlayVisible],
		[mapBrokerToolBtn, isLivestockBreedingRestrictionOverlayVisible]
	].forEach(([button, active]) => {
		if (!button) return;
		button.classList.remove("configuring");
		button.classList.toggle("active", !!active);
		button.setAttribute("aria-pressed", active ? "true" : "false");
	});
	return true;
}

function getNationalLandPlanOption(key)
{
	return NATIONAL_LAND_PLAN_DEVELOPMENT_OPTIONS.find((option) => option.key === key) || null;
}

function getNationalLandPlanDataUrls(option)
{
	if (!option || !option.dataUrl) return [];
	let localUrl = option.dataUrl;
	try {
		localUrl = resolveRealjejuLocalAssetUrl(option.dataUrl);
	} catch (error) {}
	const remoteUrl = typeof toRemotePath === "function" ? toRemotePath(option.dataUrl) : "";
	return [localUrl, remoteUrl].filter((url, index, list) => url && list.indexOf(url) === index);
}

function isNationalLandPlanGeoJson(data, key)
{
	if (!data || data.type !== "FeatureCollection" || !Array.isArray(data.features)) return false;
	const savedKey = String(data.metadata && data.metadata.layerKey || "");
	return !savedKey || savedKey === key;
}

async function loadNationalLandPlanGeoJson(key)
{
	const option = getNationalLandPlanOption(key);
	if (!option) throw new Error("알 수 없는 국토계획 레이어");
	if (nationalLandPlanGeoJsonCache.has(key)) return nationalLandPlanGeoJsonCache.get(key);
	if (nationalLandPlanGeoJsonPromiseCache.has(key)) return nationalLandPlanGeoJsonPromiseCache.get(key);
	if (Number(nationalLandPlanGeoJsonFailureUntil.get(key) || 0) > Date.now()) {
		throw new Error(`${option.label} 자료 재시도 대기 중`);
	}

	const request = (async () => {
		// 대용량 국토계획 레이어는 최초 선택 시에만 이진 자료를 해제한다.
		// 생산녹지는 원본 GeoJSON을 유지하므로 기존 JSON 경로를 그대로 사용한다.
		if (option.dataFormat === "binary") {
			return loadRealjejuPolygonBinary(
				getNationalLandPlanDataUrls(option),
				`${NATIONAL_LAND_PLAN_CACHE_NAME}-${key}`,
				option.label
			);
		}
		let responseCache = null;
		if (window.caches && window.isSecureContext) {
			try {
				responseCache = await window.caches.open(NATIONAL_LAND_PLAN_CACHE_NAME);
			} catch (error) {
				responseCache = null;
			}
		}
		let lastError = null;
		for (const url of getNationalLandPlanDataUrls(option)) {
			if (responseCache) {
				try {
					const cachedResponse = await responseCache.match(url);
					if (cachedResponse) {
						const cachedData = await cachedResponse.json();
						if (isNationalLandPlanGeoJson(cachedData, key)) return cachedData;
					}
				} catch (error) {
					lastError = error;
				}
			}
			try {
				const response = await fetch(url, { cache: "no-cache" });
				if (!response.ok) throw new Error(`${option.label} 자료 로드 실패: ${response.status}`);
				if (responseCache) {
					try {
						await responseCache.put(url, response.clone());
					} catch (error) {}
				}
				const data = await response.json();
				if (!isNationalLandPlanGeoJson(data, key)) throw new Error(`${option.label} 자료 형식 오류`);
				return data;
			} catch (error) {
				lastError = error;
			}
		}
		throw lastError || new Error(`${option.label} 자료를 불러오지 못했습니다.`);
	})()
		.then((data) => {
			nationalLandPlanGeoJsonCache.set(key, data);
			nationalLandPlanGeoJsonFailureUntil.delete(key);
			return data;
		})
		.catch((error) => {
			nationalLandPlanGeoJsonFailureUntil.set(key, Date.now() + NATIONAL_LAND_PLAN_FAILURE_COOLDOWN_MS);
			throw error;
		})
		.finally(() => {
			if (nationalLandPlanGeoJsonPromiseCache.get(key) === request) {
				nationalLandPlanGeoJsonPromiseCache.delete(key);
			}
		});
	nationalLandPlanGeoJsonPromiseCache.set(key, request);
	return request;
}

function nextNationalLandPlanRenderToken(key)
{
	const nextToken = Number(nationalLandPlanOverlayRenderTokens.get(key) || 0) + 1;
	nationalLandPlanOverlayRenderTokens.set(key, nextToken);
	return nextToken;
}

function hideNationalLandPlanOverlay(key)
{
	(nationalLandPlanOverlayPolygons.get(key) || []).forEach((polygon) => {
		if (polygon && typeof polygon.setMap === "function") polygon.setMap(null);
	});
	nationalLandPlanOverlayRenderCompleteKeys.delete(key);
}

function discardNationalLandPlanOverlay(key)
{
	hideNationalLandPlanOverlay(key);
	nationalLandPlanOverlayPolygons.delete(key);
}

function clearAllNationalLandPlanOverlays()
{
	NATIONAL_LAND_PLAN_DEVELOPMENT_OPTIONS.forEach((option) => {
		nextNationalLandPlanRenderToken(option.key);
		discardNationalLandPlanOverlay(option.key);
	});
	selectedNationalLandPlanDevelopmentLayers.clear();
	syncNationalLandPlanLegend();
}

function syncNationalLandPlanLegend()
{
	if (!nationalLandPlanLegend) return;
	const visibleOptions = NATIONAL_LAND_PLAN_DEVELOPMENT_OPTIONS.filter((option) => (
		selectedNationalLandPlanDevelopmentLayers.has(option.key)
		&& nationalLandPlanOverlayRenderCompleteKeys.has(option.key)
	));
	if (nationalLandPlanLegendRows) {
		nationalLandPlanLegendRows.innerHTML = visibleOptions.map((option) => (
			'<div class="life-safety-legend-row">'
			+ '<span class="national-land-plan-legend-swatch" data-national-land-plan-key="' + escapeHtml(option.key) + '" aria-hidden="true"></span>'
			+ '<span>' + escapeHtml(option.label) + '</span>'
			+ '</div>'
		)).join("");
	}
	const isAnyFacilityPanelOpen = typeof isAnyFacilityFilterPanelOpen === "function" && isAnyFacilityFilterPanelOpen();
	const shouldShow = visibleOptions.length > 0 && !isAnyFacilityPanelOpen;
	nationalLandPlanLegend.classList.toggle("open", shouldShow);
	nationalLandPlanLegend.setAttribute("aria-hidden", shouldShow ? "false" : "true");
}

async function renderNationalLandPlanOverlay(key)
{
	const option = getNationalLandPlanOption(key);
	if (!option || !selectedNationalLandPlanDevelopmentLayers.has(key) || !state.map || !window.kakao || !kakao.maps) return;
	if (nationalLandPlanOverlayLoadingKeys.has(key)) return;
	const savedPolygons = nationalLandPlanOverlayPolygons.get(key) || [];
	if (savedPolygons.length) {
		savedPolygons.forEach((polygon) => polygon.setMap(state.map));
		nationalLandPlanOverlayRenderCompleteKeys.add(key);
		if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
		return;
	}

	const renderToken = nextNationalLandPlanRenderToken(key);
	nationalLandPlanOverlayLoadingKeys.add(key);
	try {
		const data = await loadNationalLandPlanGeoJson(key);
		if (renderToken !== nationalLandPlanOverlayRenderTokens.get(key) || !selectedNationalLandPlanDevelopmentLayers.has(key)) return;
		const polygons = [];
		(data.features || []).forEach((feature) => {
			getFactoryRestrictionPolygonGroups(feature && feature.geometry).forEach((group) => {
				const paths = (Array.isArray(group) ? group : [])
					.map(getFactoryRestrictionRingPath)
					.filter((path) => path.length >= 3);
				if (!paths.length) return;
				const polygon = new kakao.maps.Polygon({
					path: paths.length === 1 ? paths[0] : paths,
					strokeWeight: 2,
					strokeColor: option.strokeColor,
					strokeOpacity: 0.88,
					fillColor: option.fillColor,
					fillOpacity: 0.18,
					clickable: false,
					zIndex: 1
				});
				polygon.setMap(state.map);
				polygons.push(polygon);
			});
		});
		if (renderToken !== nationalLandPlanOverlayRenderTokens.get(key) || !selectedNationalLandPlanDevelopmentLayers.has(key)) {
			polygons.forEach((polygon) => polygon.setMap(null));
			return;
		}
		nationalLandPlanOverlayPolygons.set(key, polygons);
		if (polygons.length) nationalLandPlanOverlayRenderCompleteKeys.add(key);
		if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
	} catch (error) {
		console.warn(`${option.label} 표시 실패:`, error);
		selectedNationalLandPlanDevelopmentLayers.delete(key);
		discardNationalLandPlanOverlay(key);
		syncDevelopmentFacilityPanelUI();
		updateDevelopmentToolActiveState();
		if (typeof openAuthErrorModal === "function") {
			openAuthErrorModal(`${option.label} 자료를 불러오지 못했습니다.`, "국토계획", mapDevelopmentToolBtn || null);
		}
	} finally {
		nationalLandPlanOverlayLoadingKeys.delete(key);
		const currentPolygons = nationalLandPlanOverlayPolygons.get(key) || [];
		if (selectedNationalLandPlanDevelopmentLayers.has(key)
			&& !currentPolygons.length
			&& renderToken !== nationalLandPlanOverlayRenderTokens.get(key)) {
			Promise.resolve().then(() => renderNationalLandPlanOverlay(key));
		}
	}
}

function clearLifeSafetyOverlay()
{
	lifeSafetyOverlayPolygons.forEach(polygon => {
		if (polygon && typeof polygon.setMap === "function") polygon.setMap(null);
	});
	lifeSafetyOverlayPolygons = [];
}

async function loadLifeSafetyOverlayData()
{
	if (lifeSafetyOverlayData) return lifeSafetyOverlayData;
	const url = resolveRealjejuLocalAssetUrl(LIFE_SAFETY_GRID_URL);
	if (window.caches && window.isSecureContext) {
		try {
			const cache = await caches.open(LIFE_SAFETY_GRID_CACHE_NAME);
			const cachedResponse = await cache.match(url);
			if (cachedResponse) {
				lifeSafetyOverlayData = await cachedResponse.json();
				return lifeSafetyOverlayData;
			}
			const response = await fetch(url, { cache: "no-store" });
			if (!response.ok) throw new Error(`생활안전 참고지표 파일 로드 실패: ${response.status}`);
			await cache.put(url, response.clone());
			lifeSafetyOverlayData = await response.json();
			return lifeSafetyOverlayData;
		} catch (error) {
			console.warn("생활안전 참고지표 로컬 캐시 처리 실패, 일반 요청으로 전환합니다.", error);
		}
	}
	const response = await fetch(url);
	if (!response.ok) throw new Error(`생활안전 참고지표 파일 로드 실패: ${response.status}`);
	lifeSafetyOverlayData = await response.json();
	return lifeSafetyOverlayData;
}

function getLifeSafetyMapBounds()
{
	if (!state.map || typeof state.map.getBounds !== "function") return null;
	const bounds = state.map.getBounds();
	if (!bounds || typeof bounds.getSouthWest !== "function" || typeof bounds.getNorthEast !== "function") return null;
	const sw = bounds.getSouthWest();
	const ne = bounds.getNorthEast();
	if (!sw || !ne) return null;
	return {
		west: sw.getLng(),
		south: sw.getLat(),
		east: ne.getLng(),
		north: ne.getLat()
	};
}

function isLifeSafetyOverlayLevelVisible()
{
	if (!state.map) return false;
	if (typeof state.map.getLevel !== "function") return true;
	return Number(state.map.getLevel()) <= FACILITY_MAP_VISIBLE_LEVEL;
}

function doesLifeSafetyCellIntersectBounds(cell, bounds)
{
	const box = cell && Array.isArray(cell.b) ? cell.b : cell;
	if (!Array.isArray(box) || box.length < 4 || !bounds) return false;
	const west = Number(box[0]);
	const south = Number(box[1]);
	const east = Number(box[2]);
	const north = Number(box[3]);
	if (![west, south, east, north].every(Number.isFinite)) return false;
	return east >= bounds.west && west <= bounds.east && north >= bounds.south && south <= bounds.north;
}

function getLifeSafetyCellScore(cell)
{
	const score = Number(cell && typeof cell === "object" && !Array.isArray(cell) ? cell.s : (Array.isArray(cell) ? cell[4] : 0));
	return Number.isFinite(score) ? score : 0;
}

function getLifeSafetySelectedDongSet()
{
	const selectedDongs = new Set();
	LIFE_SAFETY_REGION_OPTIONS.forEach(option => {
		if (!lifeSafetySelectedRegionKeys.has(option.key)) return;
		(option.dongs || []).forEach(name => selectedDongs.add(name));
	});
	return selectedDongs;
}

function getLifeSafetySelectedRegionScopeText()
{
	const labels = LIFE_SAFETY_REGION_OPTIONS
	.filter(option => lifeSafetySelectedRegionKeys.has(option.key))
	.map(option => option.label);
	return labels.length ? labels.join("ㆍ") : "선택 지역 없음";
}

function isLifeSafetyCellRegionSelected(cell)
{
	const name = String(cell && cell.n ? cell.n : "").trim();
	if (!name) return false;
	return getLifeSafetySelectedDongSet().has(name);
}

function setLifeSafetyRegionSelected(key, selected)
{
	if (!LIFE_SAFETY_REGION_OPTIONS.some(option => option.key === key)) return;
	if (selected) {
		lifeSafetySelectedRegionKeys.add(key);
	} else {
		lifeSafetySelectedRegionKeys.delete(key);
	}
}

function hasLifeSafetySelectedRegions()
{
	return lifeSafetySelectedRegionKeys.size > 0;
}

function getLifeSafetyCellPath(cell)
{
	if (cell && Array.isArray(cell.p)) {
		return cell.p
		.map(point => Array.isArray(point) ? new kakao.maps.LatLng(Number(point[1]), Number(point[0])) : null)
		.filter(Boolean);
	}
	if (!Array.isArray(cell)) return [];
	const west = Number(cell[0]);
	const south = Number(cell[1]);
	const east = Number(cell[2]);
	const north = Number(cell[3]);
	if (![west, south, east, north].every(Number.isFinite)) return [];
	return [
		new kakao.maps.LatLng(south, west),
		new kakao.maps.LatLng(north, west),
		new kakao.maps.LatLng(north, east),
		new kakao.maps.LatLng(south, east)
	];
}

async function renderLifeSafetyOverlay()
{
	if (!state.map || !window.kakao || !kakao.maps || lifeSafetyOverlayLoading) return;
	if (!isLifeSafetyOverlayLevelVisible()) {
		isLifeSafetyOverlayRenderComplete = false;
		clearLifeSafetyOverlay();
		syncLocationAnalysisUI();
		return;
	}
	lifeSafetyOverlayLoading = true;
	try {
		const data = await loadLifeSafetyOverlayData();
		if (!isLifeSafetyOverlayLevelVisible()) {
			clearLifeSafetyOverlay();
			return;
		}
		const mapBounds = getLifeSafetyMapBounds();
		clearLifeSafetyOverlay();
		(data.cells || []).forEach(cell => {
			if (!isLifeSafetyCellRegionSelected(cell)) return;
			if (!doesLifeSafetyCellIntersectBounds(cell, mapBounds)) return;
			const score = getLifeSafetyCellScore(cell);
			const color = getLifeSafetyOverlayColor(score);
			const path = getLifeSafetyCellPath(cell);
			if (path.length < 3) return;
			const polygon = new kakao.maps.Polygon({
				path,
				strokeWeight: 1,
				strokeColor: color,
				strokeOpacity: 0.62,
				fillColor: color,
				fillOpacity: score >= 8 ? 0.42 : 0.32
			});
			polygon.setMap(state.map);
			lifeSafetyOverlayPolygons.push(polygon);
		});
		isLifeSafetyOverlayRenderComplete = true;
		syncLocationAnalysisUI();
	} finally {
		lifeSafetyOverlayLoading = false;
	}
}

function syncLocationAnalysisUI()
{
	if (locationAnalysisDropdown) locationAnalysisDropdown.classList.toggle("has-active", isLifeSafetyOverlayVisible);
	if (locationAnalysisLabel) locationAnalysisLabel.textContent = isLifeSafetyOverlayVisible ? "생활안전 참고지표" : "전체";
	if (lifeSafetyOverlayCheck) lifeSafetyOverlayCheck.checked = !!isLifeSafetyOverlayVisible;
	const sideLifeSafetyCheck = document.getElementById("realjejuSideLifeSafetyCheck");
	if (sideLifeSafetyCheck) sideLifeSafetyCheck.checked = !!isLifeSafetyOverlayVisible;
	const isAnyFacilityPanelOpen = typeof isAnyFacilityFilterPanelOpen === "function" && isAnyFacilityFilterPanelOpen();
	const shouldShowLifeSafetyGuide = !!(isLifeSafetyOverlayVisible && isLifeSafetyOverlayRenderComplete && !isAnyFacilityPanelOpen);
	const shouldShowCleanHouseGuide = !!(state && state.isCleanHouseVisible) && !isAnyFacilityPanelOpen;
	if (lifeSafetyLegend) {
		const scope = lifeSafetyLegend.querySelector(".life-safety-legend-scope");
		if (shouldShowLifeSafetyGuide && scope) scope.textContent = getLifeSafetySelectedRegionScopeText();
		lifeSafetyLegend.classList.toggle("open", shouldShowLifeSafetyGuide);
		lifeSafetyLegend.setAttribute("aria-hidden", shouldShowLifeSafetyGuide ? "false" : "true");
	}
	if (cleanHouseGuideLegend) {
		cleanHouseGuideLegend.classList.toggle("open", shouldShowCleanHouseGuide);
		cleanHouseGuideLegend.setAttribute("aria-hidden", shouldShowCleanHouseGuide ? "false" : "true");
	}
	if (typeof syncFactoryRestrictionLegend === "function") syncFactoryRestrictionLegend();
	if (typeof syncSewerTreatmentAreaLegend === "function") syncSewerTreatmentAreaLegend();
	if (typeof syncCulturalHeritageProtectionLegend === "function") syncCulturalHeritageProtectionLegend();
	if (typeof syncLivestockBreedingRestrictionLegend === "function") syncLivestockBreedingRestrictionLegend();
	if (typeof syncNationalLandPlanLegend === "function") syncNationalLandPlanLegend();
	const shouldShowFactoryRestrictionGuide = !!(factoryRestrictionLegend && factoryRestrictionLegend.classList.contains("open"));
	const shouldShowSewerTreatmentAreaGuide = !!(sewerTreatmentAreaLegend && sewerTreatmentAreaLegend.classList.contains("open"));
	const shouldShowCulturalHeritageProtectionGuide = !!(culturalHeritageProtectionLegend && culturalHeritageProtectionLegend.classList.contains("open"));
	const shouldShowLivestockBreedingRestrictionGuide = !!(livestockBreedingRestrictionLegend && livestockBreedingRestrictionLegend.classList.contains("open"));
	const shouldShowNationalLandPlanGuide = !!(nationalLandPlanLegend && nationalLandPlanLegend.classList.contains("open"));
	if (shouldShowLifeSafetyGuide || shouldShowCleanHouseGuide || shouldShowFactoryRestrictionGuide || shouldShowSewerTreatmentAreaGuide || shouldShowCulturalHeritageProtectionGuide || shouldShowLivestockBreedingRestrictionGuide || shouldShowNationalLandPlanGuide) {
		positionLifeSafetyLegend();
		requestAnimationFrame(positionLifeSafetyLegend);
		setTimeout(positionLifeSafetyLegend, 60);
	}
	if (typeof updateConvenienceToolActiveState === "function") updateConvenienceToolActiveState();
}

function positionLifeSafetyLegend()
{
	const guideBoxes = [lifeSafetyLegend, cleanHouseGuideLegend, culturalHeritageProtectionLegend, sewerTreatmentAreaLegend, factoryRestrictionLegend, livestockBreedingRestrictionLegend, nationalLandPlanLegend].filter(box => box && box.classList.contains("open"));
	if (!guideBoxes.length) return;
	const getVisibleRect = (el) => {
		if (!el || typeof el.getBoundingClientRect !== "function") return null;
		const rect = el.getBoundingClientRect();
		return rect && rect.width && rect.height ? rect : null;
	};
	const anchorRect = getVisibleRect(locationAnalysisTrigger)
		|| getVisibleRect(mapConvenienceToolBtn)
		|| getVisibleRect(areaUnitToggleBtn)
		|| getVisibleRect(areaUnitToolGroup);
	if (!anchorRect) return;
	const firstRect = guideBoxes[0].getBoundingClientRect();
	const guideWidth = firstRect.width || 162;
	const totalHeight = guideBoxes.reduce((sum, box, index) => {
		const rect = box.getBoundingClientRect();
		return sum + (rect.height || 0) + (index ? 10 : 0);
	}, 0);
	const sideTools = document.querySelector(".map-side-tools");
	const sideRect = sideTools && typeof sideTools.getBoundingClientRect === "function" ? sideTools.getBoundingClientRect() : null;
	const areaUnitRect = getVisibleRect(areaUnitToolGroup) || getVisibleRect(areaUnitToggleBtn);
	const gapValue = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--map-tool-stack-gap"));
	const gap = Number.isFinite(gapValue) && gapValue > 0 ? Math.round(gapValue) : 16;
	const safeGap = Math.max(8, Math.min(32, gap));
	const maxLeft = Math.max(8, window.innerWidth - guideWidth - 8);
	const sideAlignedLeft = sideRect && sideRect.width
		? sideRect.left - guideWidth - safeGap
		: anchorRect.left;
	const left = Math.min(Math.max(8, sideAlignedLeft), maxLeft);
	const targetTop = areaUnitRect && areaUnitRect.width && areaUnitRect.height ? areaUnitRect.top : anchorRect.bottom + safeGap;
	let top = Math.min(Math.max(8, targetTop), Math.max(8, window.innerHeight - totalHeight - 8));
	guideBoxes.forEach((box) => {
		const rect = box.getBoundingClientRect();
		box.style.position = "fixed";
		box.style.left = left + "px";
		box.style.top = top + "px";
		box.style.right = "auto";
		top += (rect.height || 0) + 10;
	});
}

function isRealjejuFeatureLoggedIn()
{
	const user = window.realjejuCurrentAuthUser || null;
	return !!(user && user.id);
}

function openRealjejuFeatureLoginRequired(message, title, returnFocusTarget)
{
	const errorModal = typeof window.openAuthErrorModal === "function" ? window.openAuthErrorModal : (typeof openAuthErrorModal === "function" ? openAuthErrorModal : null);
	const loginModal = typeof window.openAuthModal === "function" ? window.openAuthModal : (typeof openAuthModal === "function" ? openAuthModal : null);
	if (errorModal) {
		errorModal(message, title, returnFocusTarget || null, loginModal || null);
		return;
	}
	if (loginModal) {
		loginModal();
		return;
	}
	alert(message);
}

async function setLifeSafetyOverlayVisible(visible)
{
	if (visible && !hasLifeSafetySelectedRegions()) {
		isLifeSafetyOverlayVisible = false;
		isLifeSafetyOverlayRenderComplete = false;
		clearLifeSafetyOverlay();
		syncLocationAnalysisUI();
		return;
	}
	if (visible && !isRealjejuFeatureLoggedIn()) {
		isLifeSafetyOverlayVisible = false;
		isLifeSafetyOverlayRenderComplete = false;
		clearLifeSafetyOverlay();
		syncLocationAnalysisUI();
		closeConvenienceFacilityFilterPanel();
		openRealjejuFeatureLoginRequired("로그인 후 입지 분석을 이용할 수 있습니다.", "생활안전 지표", mapConvenienceToolBtn || locationAnalysisTrigger || null);
		return;
	}
	isLifeSafetyOverlayVisible = !!visible;
	isLifeSafetyOverlayRenderComplete = false;
	syncLocationAnalysisUI();
	if (!isLifeSafetyOverlayVisible) {
		clearLifeSafetyOverlay();
		return;
	}
	try {
		await renderLifeSafetyOverlay();
	} catch (err) {
		console.warn("생활안전 참고지표 표시 실패:", err);
		isLifeSafetyOverlayVisible = false;
		isLifeSafetyOverlayRenderComplete = false;
		clearLifeSafetyOverlay();
		syncLocationAnalysisUI();
		if (typeof openAuthErrorModal === "function") {
			openAuthErrorModal("생활안전 참고지표를 불러오지 못했습니다.", "편의", mapConvenienceToolBtn || locationAnalysisTrigger || null);
		}
	}
}

function closeMapFilterDropdownsExcept(keepId)
{
	function closeRightSideFacilityPanels()
	{
		if (typeof closeEducationFacilityFilterPanel === "function") closeEducationFacilityFilterPanel();
		if (typeof closeConvenienceFacilityFilterPanel === "function") closeConvenienceFacilityFilterPanel();
		if (typeof closeDevelopmentFacilityFilterPanel === "function") closeDevelopmentFacilityFilterPanel();
		if (typeof closeBrokerOfficeFilterPanel === "function") closeBrokerOfficeFilterPanel();
	}
	if (typeof window.closeGlobalTopbarMoreMenu === "function") window.closeGlobalTopbarMoreMenu();

	const filterIds = [
		"typeFilterDropdown",
		"dealFilterDropdown",
		"dealMethodFilterDropdown",
		"priceFilterDropdown",
		"areaFilterDropdown",
		"landTypeFilterDropdown",
		"landUseZoneFilterDropdown",
		"roomBathFilterDropdown",
		"floorDirectionFilterDropdown",
		"approvalYearFilterDropdown",
		"extraFilterDropdown",
		"mapRegionFilterDropdown",
		"allFilterDropdown",
		"locationAnalysisDropdown"
	];
	const filterDropdowns = [
		...filterIds.map(id => document.getElementById(id)),
		...document.querySelectorAll("[data-presale-filter-dropdown]")
	];
	[...new Set(filterDropdowns)]
		.filter(Boolean)
		.forEach(dropdown => {
		if (dropdown.id === keepId) return;
		dropdown.classList.remove("open");
		const trigger = getMapFilterDropdownTrigger(dropdown);
		if (trigger) trigger.setAttribute("aria-expanded", "false");
		const menu = getMapFilterDropdownMenu(dropdown);
		if (menu && menu.hasAttribute("data-presale-filter-menu")) {
			menu.setAttribute("aria-hidden", "true");
		}
	});
	closeRightSideFacilityPanels();
	if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
}

const MAP_FILTER_DELEGATED_TRIGGER_TO_DROPDOWN = {
	typeFilterTrigger: "typeFilterDropdown",
	dealFilterTrigger: "dealFilterDropdown",
	dealMethodFilterTrigger: "dealMethodFilterDropdown",
	priceFilterTrigger: "priceFilterDropdown",
	areaFilterTrigger: "areaFilterDropdown",
	landTypeFilterTrigger: "landTypeFilterDropdown",
	landUseZoneFilterTrigger: "landUseZoneFilterDropdown",
	roomBathFilterTrigger: "roomBathFilterDropdown",
	floorDirectionFilterTrigger: "floorDirectionFilterDropdown",
	approvalYearFilterTrigger: "approvalYearFilterDropdown",
	extraFilterTrigger: "extraFilterDropdown",
	locationAnalysisTrigger: "locationAnalysisDropdown"
};

function lockListToItems(items, options = {})
{
	const sourceItems = Array.isArray(items) ? items.filter(Boolean) : [];
	const ids = sourceItems
	.map(item => normalizeItemId(item?.id))
	.filter(Boolean);
	state.lockedListIds = ids.length ? ids : null;
	state.lockedListItemsSnapshot = ids.length ? sourceItems.slice() : null;
	state.keepLockedListOnMapClick = !!(ids.length && options.keepOnMapClick);
}

function clearListLock()
{
	state.lockedListIds = null;
	state.lockedListItemsSnapshot = null;
	state.keepLockedListOnMapClick = false;
}

function getLockedListItems()
{
	if (!Array.isArray(state.lockedListIds) || !state.lockedListIds.length) return null;
	const lockedIds = state.lockedListIds.map(normalizeItemId).filter(Boolean);
	const itemById = new Map();
	(Array.isArray(state.lockedListItemsSnapshot) ? state.lockedListItemsSnapshot : []).forEach((item) => {
		const id = normalizeItemId(item?.id);
		if (id) itemById.set(id, item);
	});
	(state.filtered || []).forEach((item) => {
		const id = normalizeItemId(item?.id);
		if (id && lockedIds.includes(id)) itemById.set(id, item);
	});
	const lockedItems = lockedIds
	.map(id => itemById.get(id))
	.filter(Boolean)
	.map(mergeCachedLeftListDetailItem);
	return lockedItems.length ? lockedItems : null;
}

let browserFocusLockedListSnapshot = null;

function normalizeAgentOfficeKey(value)
{
	return String(value || "").trim().replace(/\s+/g, " ").toLowerCase();
}

function getItemAgentIdentity(item)
{
	const payload = item && item.payload && typeof item.payload === "object" ? item.payload : {};
	const registrant = payload.registrant && typeof payload.registrant === "object" ? payload.registrant : {};
	return {
		agencyId: normalizeItemId(item?.agencyId || item?.agency_id || payload.agency_id || registrant.agency_id),
		publicId: normalizeRealjejuAgencyPublicId(item?.agencyPublicId || item?.public_id || payload.agency_public_id || registrant.public_id),
		userId: normalizeItemId(item?.userId || item?.user_id || payload.user_id || registrant.agency_user_id || registrant.user_id),
		officeName: normalizeAgentOfficeKey(item?.agentOffice || registrant.office_name || payload.office_name),
		label: String(item?.agentOffice || registrant.office_name || "공인중개사").trim()
	};
}

function buildAgentListFilterFromItem(item)
{
	const identity = getItemAgentIdentity(item);
	return (identity.agencyId || identity.userId || identity.officeName) ? identity : null;
}

function buildAgentListCardFromItem(item)
{
	if (!item || typeof item !== "object") return null;
	const payload = item.payload && typeof item.payload === "object" ? item.payload : {};
	const registrant = payload.registrant && typeof payload.registrant === "object" ? payload.registrant : {};
	const name = String(item.agentName || registrant.name || "").trim();
	const office = String(item.agentOffice || registrant.office_name || payload.office_name || "").trim();
	const phone = formatDisplayPhones(item.phone1, item.phone2, registrant.phone1, registrant.phone2);
	return {
		publicId: normalizeRealjejuAgencyPublicId(item.agencyPublicId || item.public_id || payload.agency_public_id || registrant.public_id || ""),
		name,
		title: getDisplayAgentTitle(item.agentTitle || registrant.title || "", item),
		office,
		phone,
		phoneLink: String(item.phone1 || item.phone2 || registrant.phone1 || registrant.phone2 || phone || "").trim(),
		address: String(item.agentAddress || registrant.address || payload.agentAddress || "").trim(),
		regNo: String(
			item.agentRegNo
			|| item.office_reg_no
			|| item.registration_no
			|| item.reg_no
			|| item.license_no
			|| registrant.office_reg_no
			|| registrant.registration_no
			|| registrant.reg_no
			|| registrant.license_no
			|| payload.office_reg_no
			|| payload.registration_no
			|| payload.reg_no
			|| payload.license_no
			|| payload.agentRegNo
			|| ""
		).trim(),
		image: String(item.agentImage || registrant.profile_image || payload.agentImage || "").trim(),
		kakaoUrl: String(
			item.linkKakaotalk
			|| item.kakao_url
			|| item.kakaoUrl
			|| item.openKakaoUrl
			|| registrant.kakao_url
			|| registrant.kakaoUrl
			|| payload.kakao_url
			|| ""
		).trim()
	};
}

function itemMatchesAgentListFilter(item, filter)
{
	if (!item || !filter) return false;
	const identity = getItemAgentIdentity(item);
	if (filter.agencyId && identity.agencyId) return identity.agencyId === filter.agencyId;
	if (filter.userId && identity.userId) return identity.userId === filter.userId;
	if (filter.officeName && identity.officeName) {
		return identity.officeName === filter.officeName
			|| brokerSpecialtyOfficeNamesMatch(filter.rawOfficeName || filter.label || filter.officeName, identity.rawOfficeName || identity.label || identity.officeName);
	}
	return false;
}

function rememberLeftListDetailItems(items)
{
	(Array.isArray(items) ? items : []).forEach((item) => {
		const id = normalizeItemId(item && item.id);
		if (!id) return;
		setLeftListDetailItemCache(id, item);
		const rawArea = String(item && item.area || "").trim();
		if (rawArea && rawArea !== "-") leftListAreaDisplayRawCache.set(id, rawArea);
	});
}

function sanitizeLeftListDetailCacheItem(item)
{
	const source = item && typeof item === "object" ? item : {};
	const thumbnail = getListingItemThumbnailUrl(source)
		|| String(source.image || "").trim()
		|| (Array.isArray(source.images) ? String(source.images.find(Boolean) || "").trim() : "");
	const photoCount = Math.max(getListingPhotoCount(source), thumbnail ? 1 : 0);
	const cached = { ...source };
	delete cached.photos;
	delete cached.photoRows;
	delete cached.fullPhotos;
	delete cached.fullPhotoRows;
	cached.image = String(cached.image || thumbnail || "").trim();
	cached.thumbnailImage = String(cached.thumbnailImage || cached.thumbnail_image || cached.thumbnailUrl || cached.thumbnail_url || thumbnail || "").trim();
	cached.images = thumbnail ? [thumbnail] : [];
	cached.photoCount = photoCount;
	cached.photo_count = photoCount;
	return cached;
}

function pruneLeftListDetailItemCache()
{
	while (leftListDetailItemCache.size > LEFT_LIST_DETAIL_ITEM_CACHE_LIMIT) {
		const oldestKey = leftListDetailItemCache.keys().next().value;
		if (oldestKey == null) break;
		leftListDetailItemCache.delete(oldestKey);
	}
}

function setLeftListDetailItemCache(id, item)
{
	const key = normalizeItemId(id || (item && item.id));
	if (!key || !item) return;
	if (leftListDetailItemCache.has(key)) leftListDetailItemCache.delete(key);
	leftListDetailItemCache.set(key, sanitizeLeftListDetailCacheItem(item));
	pruneLeftListDetailItemCache();
}

function getLeftListDetailItemCache(id)
{
	const key = normalizeItemId(id);
	if (!key || !leftListDetailItemCache.has(key)) return null;
	const cached = leftListDetailItemCache.get(key);
	leftListDetailItemCache.delete(key);
	leftListDetailItemCache.set(key, cached);
	return cached || null;
}

function hasLeftListDetailItemCache(id)
{
	const key = normalizeItemId(id);
	return !!(key && leftListDetailItemCache.has(key));
}

function rememberVisibleLeftListAreaDisplayRaw()
{
	if (!propertyList) return;
	propertyList.querySelectorAll(".card[data-id] .area-display[data-area-raw]").forEach((areaEl) => {
		const card = areaEl.closest(".card[data-id]");
		const id = normalizeItemId(card && card.dataset.id);
		const raw = String(areaEl.dataset.areaRaw || "").trim();
		if (!id || !raw || raw === "-") return;
		leftListAreaDisplayRawCache.set(id, raw);
	});
}

function getLeftListAreaDisplayRaw(item)
{
	const id = normalizeItemId(item && item.id);
	const rawArea = String(item && item.area || "").trim();
	if (rawArea && rawArea !== "-") {
		if (id) leftListAreaDisplayRawCache.set(id, rawArea);
		return rawArea;
	}
	const cached = id ? leftListAreaDisplayRawCache.get(id) : "";
	return cached || "-";
}

function getCachedLeftListDetailItem(item)
{
	const id = normalizeItemId(item && item.id);
	return id ? getLeftListDetailItemCache(id) : null;
}

function mergeCachedLeftListDetailItem(item)
{
	const cached = getCachedLeftListDetailItem(item);
	return cached ? { ...item, ...cached } : item;
}

function hydrateLeftListRenderItems(items)
{
	return (Array.isArray(items) ? items : []).map((item) => {
		const merged = mergeCachedLeftListDetailItem(item);
		const images = normalizeImageArray(merged);
		if (!images.length) return merged;
		return {
			...merged,
			image: merged.image || images[0] || "",
			images
		};
	});
}

function syncLeftListItemsFromCache()
{
	if (!Array.isArray(state.leftListItems) || !state.leftListItems.length) return false;
	const hydrated = hydrateLeftListRenderItems(state.leftListItems);
	const changed = hydrated.some((item, index) => item !== state.leftListItems[index]);
	if (changed) state.leftListItems = hydrated;
	return changed;
}

function getAgentFilteredBaseItems(filter = state.agentListFilter)
{
	if (!filter) return null;
	const remote = state.leftListRemoteAgent;
	if (remote && remote.filterKey === getPropertyScaleAgentFilterKey(filter)) {
		return Array.isArray(remote.items) ? remote.items : [];
	}
	const source = Array.isArray(state.all) ? state.all : [];
	return (source || []).filter(item => itemMatchesAgentListFilter(item, filter));
}

function getAgentFilteredListItems(filter = state.agentListFilter)
{
	const filteredItems = getAgentFilteredBaseItems(filter);
	if (!filteredItems) return null;
	const mergedItems = filteredItems.map(mergeCachedLeftListDetailItem);
	return mergedItems.length ? sortAgentListItems(mergedItems) : [];
}

async function getHydratedAgentFilteredListItems(filter = state.agentListFilter)
{
	const filteredItems = getAgentFilteredBaseItems(filter);
	if (!filteredItems) return null;
	const ids = filteredItems.map(item => normalizeItemId(item && item.id)).filter(Boolean);
	const missingIds = ids.filter(id => !hasLeftListDetailItemCache(id));
	if (missingIds.length) await fetchLeftListRowsByIds(missingIds);
	const mergedItems = filteredItems.map(mergeCachedLeftListDetailItem);
	return mergedItems.length ? sortAgentListItems(mergedItems) : [];
}

async function refreshSidebarAgentEngagementCounts(items)
{
	if (!state.agentListFilter || engagementCountRpcDisabled) return;
	const sourceItems = Array.isArray(items) ? items : [];
	const ids = [...new Set(sourceItems.map(getItemViewKey).map(getViewCountKey).filter(Boolean))];
	if (!ids.length) return;
	const seq = ++sidebarAgentEngagementSeq;
	try {
		await loadSupabaseScript();
		const client = getMapListingsSupabaseClient();
		if (!client || typeof client.rpc !== "function") return;
		const { data, error } = await client.rpc("get_property_engagement_counts", {
			p_listing_ids: ids
		});
		if (error) throw error;
		if (seq !== sidebarAgentEngagementSeq || !state.agentListFilter) return;
		const fetchedAt = Date.now();
		(Array.isArray(data) ? data : []).forEach((row) => {
			const key = getViewCountKey(row && row.listing_id);
			if (!key) return;
			const views = Number(row.views);
			const favorites = Number(row.favorites);
			const inquiries = Number(row.inquiries);
			if (Number.isFinite(views)) viewMap[key] = views;
			if (Number.isFinite(favorites)) favoriteCountMap[key] = favorites;
			if (Number.isFinite(inquiries)) inquiryCountMap[key] = inquiries;
			detailEngagementFetchedAtMap.set(key, fetchedAt);
		});
		updateCardFavoriteCountElements(sourceItems);
		if ((state.agentListSort || "popular") === "popular") {
			const nextItems = getAgentFilteredListItems();
			if (state.leftListRemoteAgent) {
				// 서버에서 받은 현재 30건 안에서는 실제 조회ㆍ관심 집계값으로 다시 정렬한다.
				state.leftListRemoteAgent.items = Array.isArray(nextItems) ? nextItems.slice() : [];
				state.leftListItems = state.leftListRemoteAgent.items.slice();
				state.leftListSourceIds = state.leftListItems.map((item) => normalizeItemId(item && item.id)).filter(Boolean);
				renderList(state.leftListItems);
				setPagedListInfo(state.leftListRemoteAgent.totalCount, state.leftListItems.length);
				return;
			}
			resetLeftListPagination(nextItems || []);
			if (propertyList) propertyList.scrollTop = 0;
			loadMoreLeftListItems({ sourceItems: nextItems || [] });
		}
	} catch (error) {
		if (isMissingRpcError(error)) {
			engagementCountRpcDisabled = true;
			return;
		}
		console.warn("중개사 매물 관심수 불러오기 실패:", error);
	}
}

