	const singleOfficeRecentKey = offices.length === 1 ? `broker:${getBrokerOfficeOverlayKey(offices[0])}` : "";
	if (singleOfficeRecentKey) el.dataset.categoryRecentKey = singleOfficeRecentKey;
	const offsetPx = Number(office.markerOffsetPx || 0);
	if (Number.isFinite(offsetPx) && offsetPx !== 0) {
		el.style.setProperty("--broker-office-marker-offset-x", offsetPx + "px");
	}
		const primaryProfileImage = offices[0] ? getBrokerOfficeListingProfileImage(offices[0]) : "";
		if (primaryProfileImage) el.classList.add("has-profile-image");
		if (offices.length > 1) el.classList.add("is-grouped");
