function getBrokerOfficeDistanceMeters(first, second)
{
	const firstPosition = normalizeJejuLatLngPair(first && first.lat, first && first.lng);
	const secondPosition = normalizeJejuLatLngPair(second && second.lat, second && second.lng);
	if (!firstPosition || !secondPosition) return Number.POSITIVE_INFINITY;
	const meanLatitudeRadians = ((firstPosition.lat + secondPosition.lat) / 2) * Math.PI / 180;
	const latitudeMeters = (firstPosition.lat - secondPosition.lat) * 111320;
	const longitudeMeters = (firstPosition.lng - secondPosition.lng) * 111320 * Math.cos(meanLatitudeRadians);
	return Math.hypot(latitudeMeters, longitudeMeters);
}

function brokerOfficesShareMapPosition(first, second)
{
	const firstAddressKey = getBrokerOfficeBaseAddressKey(first && first.address);
	const secondAddressKey = getBrokerOfficeBaseAddressKey(second && second.address);
	if (firstAddressKey && secondAddressKey && firstAddressKey === secondAddressKey) return true;
	return getBrokerOfficeDistanceMeters(first, second) <= 12;
}

function getBrokerOfficeSpreadAnchorOffice(group)
{
	const officeWithPosition = (group || []).find(office => normalizeJejuLatLngPair(office && office.lat, office && office.lng));
	return officeWithPosition || (group || [])[0] || null;
}

function spreadBrokerOfficeOverlaysByAddress(offices)
{
	const groups = [];
	(offices || []).forEach((office) => {
		let group = groups.find(items => items.some(item => brokerOfficesShareMapPosition(item, office)));
		if (!group) {
			group = [];
			groups.push(group);
		}
		group.push(office);
	});
	const spreadRows = [];
	groups.forEach((group) => {
		const officesInGroup = rankBrokerOfficesForSharedAddress(group.filter(Boolean));
		const count = officesInGroup.length;
		const anchorOffice = getBrokerOfficeSpreadAnchorOffice(officesInGroup);
		const anchorPosition = normalizeJejuLatLngPair(anchorOffice && anchorOffice.lat, anchorOffice && anchorOffice.lng);
		if (count > 1) {
			spreadRows.push({
				...(anchorOffice || officesInGroup[0]),
				...(anchorPosition ? { lat: anchorPosition.lat, lng: anchorPosition.lng } : {}),
				offices: officesInGroup,
				isBrokerOfficeRowGroup: true,
				markerOffsetPx: 0
			});
			return;
		}
		officesInGroup.forEach((office) => {
			const markerOffsetPx = 0;
			spreadRows.push({
				...office,
				...(anchorPosition ? { lat: anchorPosition.lat, lng: anchorPosition.lng } : {}),
				offices: [office],
				markerOffsetPx
			});
		});
	});
	return spreadRows;
}

function getBrokerOfficeOverlayKey(office)
{
	const offices = getUniqueBrokerOfficeList(Array.isArray(office && office.offices) && office.offices.length ? office.offices : [office]);
	const ids = offices.map(item => normalizeItemId(item && (item.id || item.userId || item.agencyId || item.officeName))).filter(Boolean).sort().join("|");
	const position = normalizeJejuLatLngPair(office && office.lat, office && office.lng);
	const locationKey = position
		? [position.lat.toFixed(5), position.lng.toFixed(5)].join(",")
		: getBrokerOfficeBaseAddressKey(office && office.address);
	return ["broker", locationKey, ids].join(":");
}

function getBrokerOfficeOverlayDataKey(office)
{
	const offices = getUniqueBrokerOfficeList(Array.isArray(office && office.offices) && office.offices.length ? office.offices : [office]);
	return offices.map((item) => [
		normalizeItemId(item && (item.id || item.userId || item.agencyId || item.officeName)),
		getBrokerOfficeProfileImageCandidate(item || {}),
		String(item && item.ownerName || "").trim(),
		String(item && item.phone || "").trim(),
		String(item && item.regNo || "").trim(),
		getBrokerOfficeListingCount(item)
	].join("~")).sort().join("|");
}

function applyBrokerOfficeOverlayEntries(entries)
{
	const previous = state.brokerOfficeOverlayMap instanceof Map ? state.brokerOfficeOverlayMap : new Map();
	const next = new Map();
	const overlays = [];
	(entries || []).forEach((entry) => {
		if (!entry || !entry.key) return;
		let overlay = previous.get(entry.key);
		if (overlay && entry.dataKey && overlay.__realjejuBrokerOfficeDataKey !== entry.dataKey) {
			if (typeof overlay.setMap === "function") overlay.setMap(null);
			overlay = null;
		}
		if (!overlay) overlay = entry.createOverlay();
		if (!overlay) return;
		if (entry.dataKey) overlay.__realjejuBrokerOfficeDataKey = entry.dataKey;
		if (entry.position && typeof overlay.setPosition === "function") {
			overlay.setPosition(new kakao.maps.LatLng(entry.position.lat, entry.position.lng));
		}
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(state.map);
		if (overlay && typeof overlay.setZIndex === "function") overlay.setZIndex(entry.zIndex || getFacilityOverlayZIndex("broker"));
		next.set(entry.key, overlay);
		overlays.push(overlay);
	});
	previous.forEach((overlay, key) => {
		if (!next.has(key) && overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state.brokerOfficeOverlayMap = next;
	state.brokerOfficeOverlays = overlays;
}

function getBrokerOfficeListingFallbackPosition(office)
{
	const filter = buildBrokerOfficeAgentFilter(office);
	if (!filter) return null;
	const sourceItems = Array.isArray(state.all) && state.all.length
		? state.all
		: (Array.isArray(state.filtered) ? state.filtered : []);
	const matches = sourceItems
		.filter(item => itemMatchesAgentListFilter(item, filter))
		.map(item => normalizeJejuLatLngPair(item && item.lat, item && item.lng))
		.filter(Boolean);
	if (!matches.length) return null;
	const sum = matches.reduce((acc, pos) => {
		acc.lat += pos.lat;
		acc.lng += pos.lng;
		return acc;
	}, { lat: 0, lng: 0 });
	return {
		lat: sum.lat / matches.length,
		lng: sum.lng / matches.length
	};
}

async function backfillBrokerOfficeLatLngRows(rows)
{
	if (!window.kakao || !kakao.maps || !kakao.maps.services) return rows || [];
	const client = getRealjejuSupabaseClient();
	const sourceRows = Array.isArray(rows) ? rows : [];
	const missingRows = sourceRows.filter(office => !Number.isFinite(Number(office.lat)) || !Number.isFinite(Number(office.lng)));
	if (!missingRows.length) return sourceRows;
	const geocoder = null;
	const resolvedRows = [];
	for (const office of missingRows) {
		const resolved = await geocodeBrokerOfficeAddress(geocoder, office);
		if (resolved) {
			resolvedRows.push(resolved);
		}
	}
	if (client && resolvedRows.length) {
		await Promise.all(resolvedRows.flatMap(office => [
			saveAgencyLatLngSnapshot(client, {
				agency_id: office.agencyId,
				office_address: office.address,
				lat: office.lat,
				lng: office.lng
			}),
			saveBrokerOfficeLocationSnapshot(client, {
				user_id: office.userId,
				agency_id: office.agencyId,
				broker_name: office.ownerName,
				office_name: office.officeName,
				phone: office.phone,
				office_address: office.address,
				lat: office.lat,
				lng: office.lng
			})
		]));
	}
	const resolvedByKey = new Map(resolvedRows.map(office => [office.id || office.userId || office.officeName, office]));
	return sourceRows.map(office => resolvedByKey.get(office.id || office.userId || office.officeName) || office);
}

