function normalizeEducationFacilityPhoneValue(value)
{
	if (value === null || value === undefined) return "";
	const text = String(value).trim();
	if (!text) return "";
	const compact = text.replace(/\s+/g, "").toLowerCase();
	if (/^(null|undefined|nan|none|-|없음|정보없음|미제공|미입력)$/.test(compact)) return "";
	return text;
}

function normalizeEducationFacilityRow(row)
{
	if (!row) return null;
	const normalized = normalizeJejuLatLngPair(row.lat, row.lng);
	if (!normalized) return null;
	const name = String(row.name || "").trim();
	if (!name) return null;
		return {
			id: normalizeItemId(row.id || row.official_code || name),
			category: String(row.category || "").trim(),
			schoolType: String(row.school_type || "").trim(),
			name,
			address: String(row.address || row.road_address || "").trim(),
			phone: normalizeEducationFacilityPhoneValue(row.phone),
			homepageUrl: String(row.homepage_url || "").trim(),
			lat: normalized.lat,
			lng: normalized.lng,
			raw: row
		};
	}

