function getKindergartenStatusKey(name, address = "")
{
	const nameText = String(name || "").replace(/\s+/g, "");
	const addressText = String(address || "").replace(/\s+/g, "");
	return nameText + "::" + addressText;
}

function getEducationFacilityStatusKey(name, address = "")
{
	return getKindergartenStatusKey(name, address);
}

function buildEducationFacilityStatusMap(payload)
{
	const map = new Map();
	(payload && Array.isArray(payload.items) ? payload.items : []).forEach((item) => {
		const name = item && item.name;
		if (!name) return;
		map.set(getEducationFacilityStatusKey(name, item.address), item);
		map.set(getEducationFacilityStatusKey(name), item);
	});
	return map;
}

async function loadEducationFacilityStatusMap(category)
{
	if (category === "kindergarten") {
		if (kindergartenStatusMap) return kindergartenStatusMap;
		if (kindergartenStatusMapPromise) return kindergartenStatusMapPromise;
		if (kindergartenStatusMapFailureUntil > Date.now()) return new Map();
		const request = fetch(KINDERGARTEN_STATUS_URL, { cache: "no-cache" })
		.then(response => {
			if (!response.ok) throw new Error("유치원 현황 파일 로드 실패: " + response.status);
			return response.json();
		})
		.then(payload => {
			const map = buildEducationFacilityStatusMap(payload);
			kindergartenStatusMap = map;
			kindergartenStatusMapFailureUntil = 0;
			return map;
		})
		.catch(error => {
			console.warn("유치원 현황 로드 실패:", error);
			kindergartenStatusMapFailureUntil = Date.now() + EDUCATION_STATUS_FAILURE_COOLDOWN_MS;
			return new Map();
		})
		.finally(() => {
			if (kindergartenStatusMapPromise === request) kindergartenStatusMapPromise = null;
		});
		kindergartenStatusMapPromise = request;
		return request;
	}
	if (category === "daycare") {
		if (daycareStatusMap) return daycareStatusMap;
		if (daycareStatusMapPromise) return daycareStatusMapPromise;
		if (daycareStatusMapFailureUntil > Date.now()) return new Map();
		const request = fetch(DAYCARE_STATUS_URL, { cache: "no-cache" })
		.then(response => {
			if (!response.ok) throw new Error("어린이집 현황 파일 로드 실패: " + response.status);
			return response.json();
		})
		.then(payload => {
			const map = buildEducationFacilityStatusMap(payload);
			daycareStatusMap = map;
			daycareStatusMapFailureUntil = 0;
			return map;
		})
		.catch(error => {
			console.warn("어린이집 현황 로드 실패:", error);
			daycareStatusMapFailureUntil = Date.now() + EDUCATION_STATUS_FAILURE_COOLDOWN_MS;
			return new Map();
		})
		.finally(() => {
			if (daycareStatusMapPromise === request) daycareStatusMapPromise = null;
		});
		daycareStatusMapPromise = request;
		return request;
	}
	return new Map();
}

async function mergeEducationFacilityStatusRows(rows)
{
	if (!Array.isArray(rows) || !rows.some(row => row && (row.category === "kindergarten" || row.category === "daycare"))) return rows;
	const statusMaps = {};
	if (rows.some(row => row && row.category === "kindergarten")) {
		statusMaps.kindergarten = await loadEducationFacilityStatusMap("kindergarten");
	}
	if (rows.some(row => row && row.category === "daycare")) {
		statusMaps.daycare = await loadEducationFacilityStatusMap("daycare");
	}
	return rows.map((row) => {
		if (!row || (row.category !== "kindergarten" && row.category !== "daycare")) return row;
		const statusMap = statusMaps[row.category];
		if (!statusMap || !statusMap.size) return row;
		const status = statusMap.get(getEducationFacilityStatusKey(row.name, row.address))
			|| statusMap.get(getEducationFacilityStatusKey(row.name));
		if (!status) return row;
		const raw = { ...(row.raw || {}), ...status };
		const phone = normalizeEducationFacilityPhoneValue(row.phone) || normalizeEducationFacilityPhoneValue(status.phone);
		return {
			...row,
			phone,
			homepageUrl: row.homepageUrl || status.homepage_url || "",
			raw
		};
	});
}

async function fetchEducationFacilityRows(options = {})
{
	const selectedCategories = getSelectedEducationFacilityCategories();
	if (!selectedCategories.length) return [];
	const cacheKey = selectedCategories.slice().sort().join(",");
	if (!options.force && Array.isArray(state.educationFacilityRows) && state.educationFacilityRowsCacheKey === cacheKey) return state.educationFacilityRows;
	const client = getRealjejuSupabaseClient();
	if (!client) return [];
	const results = await Promise.all(selectedCategories.map(category => client
		.from("education_facilities")
		.select("*")
		.eq("category", category)
		.not("lat", "is", null)
		.not("lng", "is", null)
		.order("name", { ascending: true })));
	let rows = [];
	results.forEach((result) => {
		if (result.error) {
			console.warn("교육시설 위치 조회 실패:", result.error);
			return;
		}
		rows.push(...(Array.isArray(result.data) ? result.data : []).map(normalizeEducationFacilityRow).filter(Boolean));
	});
	rows = await mergeEducationFacilityStatusRows(rows);
	state.educationFacilityRows = rows;
	state.educationFacilityRowsCacheKey = cacheKey;
	return rows;
}

function getEducationFacilityMarkerLabel(row)
{
	const option = getEducationFacilityCategoryOptions().find(item => item.key === row.category);
	return option && option.markerLabel ? option.markerLabel : "";
}

function getEducationFacilityMarkerIcon(row)
{
	const option = getEducationFacilityCategoryOptions().find(item => item.key === row.category);
	return option && option.icon ? option.icon : "fa-school-flag";
}

function getEducationFacilityMarkerHtml(row)
{
	if (row && row.category === "daycare") {
		return '<span class="education-facility-map-marker-icon daycare-house-heart-marker" aria-hidden="true"><svg viewBox="0 0 28 28" focusable="false"><path d="M5.2 13.2 14 5.6l8.8 7.6-1.65 1.85-1.2-1.03v7.58H8.05v-7.58l-1.2 1.03L5.2 13.2Z" fill="currentColor"/><path d="M14 19.35c-2.15-1.35-3.45-2.55-3.45-4.05 0-1.05.78-1.9 1.82-1.9.63 0 1.24.32 1.63.86.39-.54 1-.86 1.63-.86 1.04 0 1.82.85 1.82 1.9 0 1.5-1.3 2.7-3.45 4.05Z" fill="#ffffff"/></svg></span>';
	}
	if (row && row.category === "kindergarten") {
		return '<span class="education-facility-map-marker-icon kindergarten-smile-marker" aria-hidden="true"><svg viewBox="0 0 28 28" focusable="false"><circle cx="14" cy="14" r="12.8" fill="currentColor" /><circle cx="10" cy="11" r="1.7" fill="#ffffff" /><circle cx="18" cy="11" r="1.7" fill="#ffffff" /><path d="M9 16.2c1.25 2.1 2.95 3.15 5 3.15s3.75-1.05 5-3.15" fill="none" stroke="#ffffff" stroke-width="2" stroke-linecap="round" /></svg></span>';
	}
	return '<span class="education-facility-map-marker-icon"><i class="fa-solid '
		+ escapeHtml(getEducationFacilityMarkerIcon(row))
		+ '" aria-hidden="true"></i><span class="education-facility-map-marker-label">'
		+ escapeHtml(getEducationFacilityMarkerLabel(row))
		+ '</span></span>';
}

function shouldRenderEducationFacilityOverlays()
{
	if (!state.map || typeof state.map.getLevel !== "function") return false;
	const mapLevel = Number(state.map.getLevel());
	const visibleLevel = getMaxSelectedEducationFacilityVisibleLevel();
	return Number.isFinite(mapLevel) && visibleLevel > 0 && mapLevel <= visibleLevel;
}

function shouldShowEducationFacilityRowAtLevel(row, mapLevel)
{
	if (!Number.isFinite(mapLevel) || mapLevel > getEducationFacilityCategoryVisibleLevel(row && row.category)) return false;
	if (row && row.category === "academy" && row.schoolType === "\uAD50\uC2B5\uC18C") return mapLevel <= 5;
	return true;
}

function getEducationFacilityOverlayKey(row, offsetX = 0)
{
	if (!row) return "";
	return [
		"row",
		row.category || "",
		normalizeItemId(row.id || row.name || ""),
		Number(offsetX || 0).toFixed(0)
	].join(":");
}

function syncSelectedEducationFacilityMarkers()
{
	const selectedKey = String(state.selectedEducationFacilityOverlayKey || "");
	const overlays = state.educationFacilityOverlayMap instanceof Map ? state.educationFacilityOverlayMap : new Map();
	overlays.forEach((overlay) => {
		const el = overlay && overlay.__realjejuMarkerElement;
		if (!el || !el.classList) return;
		el.classList.toggle("selected", !!selectedKey && el.dataset.educationFacilityOverlayKey === selectedKey);
	});
}

function setSelectedEducationFacilityMarker(key)
{
	state.selectedEducationFacilityOverlayKey = String(key || "");
	syncSelectedEducationFacilityMarkers();
}

async function syncEducationFacilityOverlaysForMapLevel()
{
	if (!state.isEducationFacilitiesVisible) return;
	if (!shouldRenderEducationFacilityOverlays()) {
		clearEducationFacilityOverlays();
		hideEducationFacilityMapTooltip();
		return;
	}
	await renderEducationFacilityOverlays();
}

let educationFacilityMapTooltipLayer = null;

let educationFacilityMapTooltipHideTimer = null;

let educationFacilityRoadviewRequestToken = 0;

function cancelEducationFacilityMapTooltipHide()
{
	if (!educationFacilityMapTooltipHideTimer) return;
	clearTimeout(educationFacilityMapTooltipHideTimer);
	educationFacilityMapTooltipHideTimer = null;
}

function hideEducationFacilityMapTooltip()
{
	if (!educationFacilityMapTooltipLayer) return;
	educationFacilityMapTooltipLayer.classList.remove("open");
}

function scheduleEducationFacilityMapTooltipHide()
{
	cancelEducationFacilityMapTooltipHide();
	educationFacilityMapTooltipHideTimer = setTimeout(hideEducationFacilityMapTooltip, 120);
}

function stopEducationFacilityTooltipMapEvent(event)
{
	if (!event) return;
	if (typeof event.stopPropagation === "function") event.stopPropagation();
	if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
	if (window.kakao && kakao.maps && kakao.maps.event && typeof kakao.maps.event.preventMap === "function") {
		kakao.maps.event.preventMap();
	}
}

function isParcelMapClickBlockedByFacilityMarker()
{
	return typeof window !== "undefined"
		&& Date.now() < Number(window.__realjejuFacilityMarkerParcelClickBlockedUntil || 0);
}

function blurEducationFacilityPanelFocus(panel)
{
	const activeEl = document.activeElement;
	if (!panel || !activeEl || !panel.contains(activeEl)) return;
	if (typeof activeEl.blur === "function") activeEl.blur();
}

function clearEducationFacilityDetailRoadviewBlocker()
{
	const panel = document.getElementById("educationFacilityDetailPanel");
	if (panel) {
		blurEducationFacilityPanelFocus(panel);
		panel.classList.remove("open");
		panel.setAttribute("aria-hidden", "true");
	}
	document.body.classList.remove("education-facility-detail-open");
	if (typeof restoreRoadviewOverlayForRoadviewOpen === "function") {
		restoreRoadviewOverlayForRoadviewOpen();
	}
}

function openEducationFacilityRoadviewFromTooltip(lat, lng)
{
	educationFacilityRoadviewRequestToken += 1;
	cancelEducationFacilityMapTooltipHide();
	hideEducationFacilityMapTooltip();
	if (typeof closeEducationFacilityDetailPanel === "function") {
		closeEducationFacilityDetailPanel();
	}
	clearEducationFacilityDetailRoadviewBlocker();
	showRoadview(lat, lng, {
		radius: 350,
		clearEducationFacilityDetail: true,
		forceSplitRoadview: true
	});
}

function ensureEducationFacilityMapTooltipLayer()
{
	if (educationFacilityMapTooltipLayer) return educationFacilityMapTooltipLayer;
	educationFacilityMapTooltipLayer = document.createElement("div");
	educationFacilityMapTooltipLayer.className = "education-facility-map-tooltip-layer";
	educationFacilityMapTooltipLayer.addEventListener("mouseenter", cancelEducationFacilityMapTooltipHide);
	educationFacilityMapTooltipLayer.addEventListener("mouseleave", scheduleEducationFacilityMapTooltipHide);
	educationFacilityMapTooltipLayer.addEventListener("pointerdown", stopEducationFacilityTooltipMapEvent, true);
	educationFacilityMapTooltipLayer.addEventListener("mousedown", stopEducationFacilityTooltipMapEvent, true);
	educationFacilityMapTooltipLayer.addEventListener("touchstart", stopEducationFacilityTooltipMapEvent, true);
	educationFacilityMapTooltipLayer.addEventListener("click", async (event) => {
		const roadviewBtn = event.target && event.target.closest ? event.target.closest("[data-public-parking-roadview], [data-large-mart-roadview], [data-convenience-place-roadview], [data-education-facility-roadview], [data-ev-charger-roadview]") : null;
		if (!roadviewBtn) return;
		event.preventDefault();
		stopEducationFacilityTooltipMapEvent(event);
		const lat = Number(roadviewBtn.dataset.lat);
		const lng = Number(roadviewBtn.dataset.lng);
		if (!Number.isFinite(lat) || !Number.isFinite(lng) || typeof showRoadview !== "function") return;
		if (roadviewBtn.hasAttribute("data-education-facility-roadview")) {
			openEducationFacilityRoadviewFromTooltip(lat, lng);
			return;
		}
		const evChargerRecent = roadviewBtn.hasAttribute("data-ev-charger-roadview")
			? {
				id: String(roadviewBtn.dataset.evChargerId || "").trim(),
				title: String(roadviewBtn.dataset.evChargerName || "전기차 충전소").trim(),
				summary: String(roadviewBtn.dataset.evChargerAddress || "").trim(),
				action: "charger-roadview",
				lat,
				lng
			}
			: null;
		showRoadview(lat, lng, evChargerRecent ? { evChargerRecent } : {});
	});
	document.body.appendChild(educationFacilityMapTooltipLayer);
	return educationFacilityMapTooltipLayer;
}

function showEducationFacilityMapTooltip(anchor, row)
{
	if (!anchor || !row) return;
	const layer = ensureEducationFacilityMapTooltipLayer();
	cancelEducationFacilityMapTooltipHide();
	const phone = String(row.phone || "").trim();
	const isPublicParking = row.category === "public-parking";
	const isLargeMart = row.category === "large-mart";
	const isEvCharger = row.category === "ev-charger";
	const isConveniencePlace = row.category === "convenience-store" || row.category === "clean-house" || row.category === "playground-park" || row.category === "bank" || row.category === "public-office" || row.category === "ev-charger";
	const isEducationPlace = !!getEducationFacilityCategoryOptions().some(option => option.key === row.category);
	const lat = Number(row.lat);
	const lng = Number(row.lng);
	const canShowRoadview = (isPublicParking || isLargeMart || isConveniencePlace || isEducationPlace) && Number.isFinite(lat) && Number.isFinite(lng);
	const roadviewAttribute = isEvCharger ? "data-ev-charger-roadview" : (isLargeMart ? "data-large-mart-roadview" : (isConveniencePlace ? "data-convenience-place-roadview" : (isEducationPlace ? "data-education-facility-roadview" : "data-public-parking-roadview")));
	const evChargerRecentAttributes = isEvCharger
		? ' data-ev-charger-id="' + escapeHtml(String(row.id || row.key || row.station_id || row.stationId || `${row.name || "charger"}:${lat},${lng}`))
			+ '" data-ev-charger-name="' + escapeHtml(String(row.name || "전기차 충전소"))
			+ '" data-ev-charger-address="' + escapeHtml(String(row.address || "")) + '"'
		: "";
	const roadviewButton = canShowRoadview
		? '<button type="button" class="education-facility-map-tooltip-roadview" '
			+ roadviewAttribute
			+ ' data-lat="'
			+ escapeHtml(String(lat))
			+ '" data-lng="'
			+ escapeHtml(String(lng))
			+ '"' + evChargerRecentAttributes + '><span>로드뷰</span></button>'
		: "";
	const playgroundParkMeta = row.category === "playground-park"
		? [row.kind, row.safety_inspection_status, row.safety_inspection_year].filter(Boolean).join(" · ")
		: "";
	const evChargerStatusSummary = getEvChargerStatusSummary(row);
	const evChargerSpecAndTimeSummary = getEvChargerSpecAndTimeSummary(row);
	const evChargerParkingSummary = getEvChargerParkingSummary(row);
	layer.innerHTML = '<strong>'
		+ escapeHtml(row.name)
		+ '</strong><small>'
		+ escapeHtml(row.address)
		+ '</small>'
		+ (playgroundParkMeta ? '<small>' + escapeHtml(playgroundParkMeta) + '</small>' : '')
		+ (evChargerStatusSummary ? '<small class="ev-charger-status-line">' + escapeHtml(evChargerStatusSummary) + '</small>' : '')
		+ (evChargerSpecAndTimeSummary ? '<small>' + escapeHtml(evChargerSpecAndTimeSummary) + '</small>' : '')
		+ (evChargerParkingSummary ? '<small>' + escapeHtml(evChargerParkingSummary) + '</small>' : '')
		+ (!isPublicParking && row.category !== "ev-charger" && phone ? '<small>' + escapeHtml(phone) + '</small>' : '')
		+ roadviewButton;
	const rect = anchor.getBoundingClientRect();
	layer.classList.add("open");
	const tooltipRect = layer.getBoundingClientRect();
	const left = Math.min(Math.max(rect.left + rect.width / 2 - tooltipRect.width / 2, 8), window.innerWidth - tooltipRect.width - 8);
	const top = Math.max(rect.top - tooltipRect.height - 10, 8);
	layer.style.left = left + "px";
	layer.style.top = top + "px";
}

function getEducationFacilityCategoryLabel(row)
{
	const option = getEducationFacilityCategoryOptions().find(item => item.key === (row && row.category));
	return option && option.label ? option.label : "교육시설";
}

function getEducationFacilityDetailPanelTitle(row)
{
	const category = row && row.category;
	if (category === "daycare" || category === "kindergarten") return "유치원·어린이집";
	if (category === "academy") return "학원";
	if (category === "elementary" || category === "middle" || category === "high") return "학교";
	return "교육시설";
}

function getEducationFacilityRawValue(row, keys)
{
	const source = row && row.raw ? row.raw : row;
	for (const key of keys || []) {
		const value = source && Object.prototype.hasOwnProperty.call(source, key) ? source[key] : undefined;
		if (value === null || value === undefined) continue;
		const text = String(value).trim();
		if (!text || /^(null|undefined|nan|none)$/i.test(text)) continue;
		if (text) return text;
	}
	return "";
}

function formatEducationFacilityDate(value)
{
	const text = String(value || "").trim();
	if (!text) return "";
	if (/^\d{8}$/.test(text)) return text.replace(/^(\d{4})(\d{2})(\d{2})$/, "$1-$2-$3");
	if (/^\d{4}-\d{2}-\d{2}/.test(text)) return text.slice(0, 10);
	return text;
}

function formatEducationFacilityStatusCount(value, unit)
{
	const text = String(value || "").trim();
	if (!text) return "";
	if (/[가-힣a-zA-Z]/.test(text.replace(/,/g, ""))) return text;
	const numberText = text.replace(/\.0$/, "");
	return numberText ? numberText + unit : "";
}

function formatEducationFacilityBusStatus(value)
{
	const text = String(value || "").trim();
	if (!text) return "정보없음";
	const normalized = text.replace(/\s+/g, "").toLowerCase();
	if (/^(n|no|false|0|미운영|미운용|미운행|없음|무)$/.test(normalized)) return "미운영";
	if (/^(y|yes|true|1|운영|운행|있음|유)$/.test(normalized)) return "운영";
	return text;
}

function formatEducationFacilityOperationHours(value)
{
	const text = String(value || "").trim();
	if (!text) return "";
	const formatPart = (part) => {
		const digits = String(part || "").replace(/[^\d]/g, "");
		if (digits.length === 4) return digits.slice(0, 2) + "시 " + digits.slice(2, 4) + "분";
		return String(part || "").trim();
	};
	const normalizeRepeatedPart = (part) => {
		const repeated = String(part || "").trim().match(/^(\d{2})(\d{2})시\1\2분$/);
		return repeated ? repeated[1] + "시 " + repeated[2] + "분" : formatPart(part);
	};
	const repeatedRange = text.match(/(\d{2}\d{2}시\d{2}\d{2}분)\s*[~-]\s*(\d{2}\d{2}시\d{2}\d{2}분)/);
	if (repeatedRange) return normalizeRepeatedPart(repeatedRange[1]) + "~" + normalizeRepeatedPart(repeatedRange[2]);
	const compactRange = text.match(/(\d{4})\s*[~-]\s*(\d{4})/);
	if (compactRange) return formatPart(compactRange[1]) + "~" + formatPart(compactRange[2]);
	return text
		.replace(/(\d{2})(\d{2})시\1\2분/g, (_, hour, minute) => hour + "시 " + minute + "분")
		.replace(/\b(\d{4})\b/g, (_, digits) => formatPart(digits));
}

function isSchoolEducationFacility(row)
{
	const category = String(row && row.category || "").trim();
	if (/^(elementary|middle|high|school)$/.test(category)) return true;
	const typeText = [row && row.schoolType, getEducationFacilityCategoryLabel(row)].filter(Boolean).join(" ");
	return /초등|중학|고등|학교/.test(typeText);
}

function getEducationFacilityBaseYear(row)
{
	const value = getEducationFacilityRawValue(row, [
		"base_year", "school_year", "statistics_year", "stats_year", "year",
		"기준년도", "기준연도", "학년도", "조사년도"
	]);
	if (value) return value.replace(/년$/, "") + " 기준";
	const updated = formatEducationFacilityDate(getEducationFacilityRawValue(row, ["source_updated_on", "updated_at"]));
	return updated && /^\d{4}/.test(updated) ? updated.slice(0, 4) + " 기준" : "";
}

function parseEducationFacilityNumber(value)
{
	const text = String(value || "").trim();
	if (!text) return null;
	const numeric = Number(text.replace(/,/g, "").replace(/[^\d.-]/g, ""));
	return Number.isFinite(numeric) ? numeric : null;
}

function formatEducationFacilityMetric(value, unit, options = {})
{
	const text = String(value || "").trim();
	if (!text) return "";
	const numeric = parseEducationFacilityNumber(text);
	if (numeric === null) return text;
	const fractionDigits = Number.isFinite(options.fractionDigits) ? options.fractionDigits : (Number.isInteger(numeric) ? 0 : 1);
	return numeric.toLocaleString("ko-KR", {
		maximumFractionDigits: fractionDigits,
		minimumFractionDigits: options.keepDecimal ? fractionDigits : 0
	}) + unit;
}

function getEducationFacilityMetric(row, keys, unit, options = {})
{
	return formatEducationFacilityMetric(getEducationFacilityRawValue(row, keys), unit, options);
}

function formatEducationFacilityBreakdown(row, parts, unit)
{
	const values = (parts || []).map((part) => {
		const rawValue = getEducationFacilityRawValue(row, part.keys || []);
		const numeric = parseEducationFacilityNumber(rawValue);
		if (numeric === null || numeric <= 0) return "";
		return escapeHtml(part.label + " " + formatEducationFacilityMetric(numeric, unit));
	}).filter(Boolean);
	return values.join(" · ");
}

function renderEducationFacilityGradeChart(row)
{
	const gradeKeyGroups = [
		["grade1_students", "students_grade1", "student_grade_1", "first_grade_students", "g1_students", "1학년", "1학년학생수"],
		["grade2_students", "students_grade2", "student_grade_2", "second_grade_students", "g2_students", "2학년", "2학년학생수"],
		["grade3_students", "students_grade3", "student_grade_3", "third_grade_students", "g3_students", "3학년", "3학년학생수"],
		["grade4_students", "students_grade4", "student_grade_4", "fourth_grade_students", "g4_students", "4학년", "4학년학생수"],
		["grade5_students", "students_grade5", "student_grade_5", "fifth_grade_students", "g5_students", "5학년", "5학년학생수"],
		["grade6_students", "students_grade6", "student_grade_6", "sixth_grade_students", "g6_students", "6학년", "6학년학생수"]
	];
	const grades = gradeKeyGroups.map((keys, index) => {
		const rawValue = getEducationFacilityRawValue(row, keys);
		const numeric = parseEducationFacilityNumber(rawValue);
		return { label: (index + 1) + "학년", rawValue, numeric };
	});
	const visibleGrades = grades.filter(item => item.rawValue && item.numeric !== null);
	if (!visibleGrades.length) return "";
	const max = Math.max(...visibleGrades.map(item => item.numeric), 1);
	return grades.map((item) => {
		const hasValue = item.rawValue && item.numeric !== null;
		const height = hasValue ? Math.max(8, Math.round((item.numeric / max) * 100)) : 0;
		return '<div class="education-facility-grade-bar">'
			+ '<span class="education-facility-grade-bar-value">' + (hasValue ? escapeHtml(formatEducationFacilityMetric(item.numeric, "명")) : "") + '</span>'
			+ '<span class="education-facility-grade-bar-fill-wrap"><span class="education-facility-grade-bar-fill" style="height:' + height + '%"></span></span>'
			+ '<span class="education-facility-grade-bar-label">' + escapeHtml(item.label) + '</span>'
			+ '</div>';
	}).join("");
}

function getEducationFacilityDetailHomepage(row)
{
	const rawUrl = getEducationFacilityRawValue(row, ["homepage_url", "homepageUrl", "homepage", "website_url", "url"]);
	if (!rawUrl) return "";
	return /^https?:\/\//i.test(rawUrl) ? rawUrl : "https://" + rawUrl.replace(/^\/+/, "");
}

function renderEducationFacilityDetailRows(rows)
{
	return (rows || [])
		.filter(item => item && String(item.value || "").trim())
		.map(item => '<div class="education-facility-detail-row"><dt>' + escapeHtml(item.label) + '</dt><dd>' + item.value + '</dd></div>')
		.join("");
}

function setEducationFacilityDetailSection(section, html)
{
	if (!section) return;
	section.style.display = html ? "" : "none";
}

function closeEducationFacilityDetailPanel()
{
	const panel = document.getElementById("educationFacilityDetailPanel");
	if (!panel) return;
	if (typeof window.realjejuCloseMobileEducationSummarySheet === "function") {
		window.realjejuCloseMobileEducationSummarySheet();
	}
	blurEducationFacilityPanelFocus(panel);
	panel.classList.remove("open");
	panel.setAttribute("aria-hidden", "true");
	document.body.classList.remove("education-facility-detail-open");
	if (typeof window.realjejuSyncGlobalDetailSurfaceState === "function") {
		window.realjejuSyncGlobalDetailSurfaceState();
	}
	setSelectedEducationFacilityMarker("");
	if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") window.realjejuSyncTopbarFilterSafeLeft();
	if (typeof scheduleMapFilterScrollSyncBurst === "function") scheduleMapFilterScrollSyncBurst();
	else if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
}

