	panel.innerHTML = '<div class="education-facility-filter-grid">'
		+ options.map((option) => '<button type="button" class="education-facility-filter-option '
			+ (selected.has(option.key) ? 'active' : '')
			+ '" data-education-category="'
			+ escapeHtml(option.key)
			+ '" data-category="'
			+ escapeHtml(option.key)
			+ '">'
			+ getEducationFacilityFilterOptionIconHtml(option)
			+ '<span>'
			+ escapeHtml(option.label)
			+ '</span></button>').join("")
		+ '</div><button type="button" class="education-facility-filter-clear '
