	const hasSelected = getSelectedEducationFacilityCategories().length > 0;
	const isConfiguring = isEducationFacilityFilterPanelOpen();
	mapEducationToolBtn.classList.toggle("configuring", isConfiguring);
	mapEducationToolBtn.classList.toggle("active", !isConfiguring && state.isEducationFacilitiesVisible && hasSelected);
