function searchLargeMartPlaces()
{
	const cacheKey = getLocalBusinessPlaceSearchCacheKey("large-mart");
	if (!(state.largeMartSearchCache instanceof Map)) state.largeMartSearchCache = new Map();
	if (!(state.largeMartSearchInflight instanceof Map)) state.largeMartSearchInflight = new Map();
	const cachedRows = getLocalBusinessPlaceSearchCache(state.largeMartSearchCache, cacheKey);
	if (cachedRows) return Promise.resolve(cachedRows);
	if (cacheKey && state.largeMartSearchInflight.has(cacheKey)) {
		return state.largeMartSearchInflight.get(cacheKey).then(cloneLocalBusinessRows);
	}
	const promise = new Promise((resolve) => {
		if (!state.map || !window.kakao || !kakao.maps || !kakao.maps.services || !kakao.maps.services.Places) {
			resolve([]);
			return;
		}
		const places = new kakao.maps.services.Places();
		const bounds = typeof state.map.getBounds === "function" ? state.map.getBounds() : null;
		const options = bounds ? { bounds } : {};
		const rows = [];
		const seen = new Set();
		const callback = (result, status, pagination) => {
			if (status !== kakao.maps.services.Status.OK || !Array.isArray(result)) {
				resolve(rows);
				return;
			}
			result.forEach((place) => {
				const row = normalizeLargeMartPlace(place);
				if (!row) return;
				const key = getLargeMartOverlayKey(row);
				if (seen.has(key)) return;
				seen.add(key);
				rows.push(row);
			});
			if (pagination && pagination.hasNextPage && pagination.current < 3) {
				pagination.nextPage();
				return;
			}
			resolve(rows);
		};
		try {
			if (typeof places.categorySearch === "function") {
				places.categorySearch("MT1", callback, options);
			} else {
				places.keywordSearch("대형마트", callback, options);
			}
		} catch (err) {
			console.warn("대형마트 검색 실패:", err);
			resolve(rows);
		}
	}).then((rows) => {
		setLocalBusinessPlaceSearchCache(state.largeMartSearchCache, cacheKey, rows);
		return cloneLocalBusinessRows(rows);
	}).finally(() => {
		if (cacheKey && state.largeMartSearchInflight instanceof Map) state.largeMartSearchInflight.delete(cacheKey);
	});
	if (cacheKey) state.largeMartSearchInflight.set(cacheKey, promise);
	return promise;
}

