function renderMarkers(data, options = {})
{
	if (isPresaleMapMode()) {
		renderPresaleEmptyMap();
		return;
	}
	if (typeof shouldShowGlobalCategoryEmptyMap === "function" && shouldShowGlobalCategoryEmptyMap()) {
		propertyRegionCountRenderToken += 1;
		clearPropertyRegionCountOverlays();
		clearMapObjects();
		if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
		scheduleWeeklySpecialistBrokerPanelRender(240);
		return;
	}
	if (
		state.isPropertyMarkersVisible === false
		&& !shouldRenderParcelRegionTradeMapBadges(getPropertyMapPresentationMode())
	) {
		propertyRegionCountRenderToken += 1;
		clearPropertyRegionCountOverlays();
		clearMapObjects();
		if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
		scheduleWeeklySpecialistBrokerPanelRender(240);
		return;
	}

	if (shouldUsePropertyMapLevelPresentation()) {
		const presentationMode = getPropertyMapPresentationMode();
		propertyMapPresentationMode = presentationMode;
		if (isPropertyRegionCountMode(presentationMode)) {
			clearMapObjects();
			renderPropertyRegionCountOverlays(presentationMode);
			if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
			scheduleWeeklySpecialistBrokerPanelRender(240);
			return;
		}
	}
	propertyRegionCountRenderToken += 1;
	clearPropertyRegionCountOverlays();

	const sourceMarkerItems = (Array.isArray(data) ? data : []).filter((item) => (
		Number.isFinite(Number(item && item.lat))
		&& Number.isFinite(Number(item && item.lng))
	));
	// 4.930: 레벨 1~3에서도 상세 지번ㆍ도로명 건물번호까지 같은 매물만 실제 개수 한 개로 표시합니다.
	// 지역명ㆍ대표 좌표만 같은 매물은 묶지 않고, 원본 목록은 보존해 숫자 뱃지 클릭 시 실제 매물 목록을 엽니다.
	const markerItems = groupSameAddressPropertyMarkers(sourceMarkerItems);
	if (!markerItems.length) {
		clearMapObjects({ preserveParcelBoundary: true });
		if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
		scheduleWeeklySpecialistBrokerPanelRender(240);
		return;
	}

	const markerSignature = getPropertyMarkerRenderSignature(markerItems);
	if (markerSignature && state.markerRenderSignature === markerSignature && state.markers.length) {
		refreshClusterBadges();
		if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
		scheduleWeeklySpecialistBrokerPanelRender(240);
		return;
	}

	clearMapObjects({ preserveParcelBoundary: true });
	state.markerRenderSignature = markerSignature;

	const bounds = new kakao.maps.LatLngBounds();
	const markerList = [];

	markerItems.forEach(item => {
		const position = new kakao.maps.LatLng(item.lat, item.lng);
		const markerLabel = String(Math.max(1, Number(item.markerGroupCount) || 1));

		const marker = new kakao.maps.Marker({
			position,
			image: createMarkerImage(item, isPropertyMarkerSelected(item), markerLabel),
			clickable: !distanceMeasureActive
		});

	marker.__property = item;

	kakao.maps.event.addListener(marker, "click", async function () {
			if (distanceMeasureActive) return;
			prepareMobilePropertyBadgeListInteraction();
			closeEducationFacilityDetailForPropertyInteraction();
			if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
				await closeRoadviewPanelForPropertyInteraction();
			} else if (typeof hideRoadview === "function") {
				await hideRoadview();
			}
			if (getPropertyMarkerGroupedItems(item).length) {
				await openGroupedPropertyMarkerList(item);
				return;
			}
			allowDetailOpenFromListClick = false;
			currentDetailItem = null;
			hardCloseDetailPanel();
			clearAgentListFilter();
			state.leftListDetailMode = "";

			state.selectedClusterKey = null;
			state.selectedMarkerId = null;
			state.selectedMarkerIds = new Set();
			state.selectionMode = "badge-list";
			lockListToItems([item], { keepOnMapClick: true });

			highlightCard(item.id);
			updateMarkerSelection(item.id, [item.id]);

			setTimeout(() => {
				hardCloseDetailPanel();
				void openPropertyBadgeListPanel([item]);
				setResultInfo("선택 매물 1건");
				setListInfo("총 1개 매물");
				refreshClusterBadges();
			}, 0);
		});

		markerList.push(marker);
		state.markers.push(marker);
		bounds.extend(position);
	});

	if (markerList.length) {
		// 4.932: 4.899와 같이 실제 좌표 마커를 카카오 클러스터러에 한 번만 전달합니다.
		
		state.clusterer.addMarkers(markerList);
		scheduleClusterBadgeRefresh(0);
	}

	// 카카오 내부 오버레이 연결이 늦는 환경도 동일한 최종 레이아웃 커밋 경로만 사용합니다.
	if (typeof refreshAdminBoundaryBottomPill === "function") refreshAdminBoundaryBottomPill();
	scheduleWeeklySpecialistBrokerPanelRender(240);

	return;
}

async function focusProperty(id)
{
	const normalizedId = normalizeItemId(id);
	const findById = (list) => Array.isArray(list)
		? list.find(v => normalizeItemId(v && v.id) === normalizedId)
		: null;
	const item = findById(state.filtered)
		|| findById(state.all)
		|| findById(state.leftListItems)
		|| (currentDetailItem && normalizeItemId(currentDetailItem.id) === normalizedId ? currentDetailItem : null);
	if (!state.map) return;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}

	state.selectionMode = "single";
	state.selectedClusterKey = null;
	updateMarkerSelection(id, [normalizedId]);

	highlightCard(id);
	if (item) await focusRecentViewedListingOnMap(item, normalizedId);

	setTimeout(() => {
		refreshClusterBadges();
	}, 0);
}

