async function loadFavoriteListingStateFromServer(options = {})
{
	if (typeof getRealjejuSupabaseClient !== "function") return false;
	const force = options && options.force === true;
	if (!force && typeof shouldLoadRealjejuRemotePageData === "function" && !shouldLoadRealjejuRemotePageData("favorites")) {
		return false;
	}
	if (realjejuFavoriteLoadPromise && !force) return realjejuFavoriteLoadPromise;

	realjejuFavoriteLoadPromise = (async () => {
		clearLegacyFavoriteLocalStorage();
		const client = getRealjejuSupabaseClient();
		const user = await getFavoriteSupabaseUser();
		const userId = normalizeItemId(user && user.id);
		if (!client || !userId) {
			clearFavoriteListingState();
			return false;
		}
		if (!force && realjejuFavoriteLoaded && realjejuFavoriteUserId === userId) {
			return true;
		}
		await purgeExpiredFavoriteTrashRows(client, userId);
		const { data, error } = await client
			.from(REALJEJU_FAVORITE_TABLE)
			.select("listing_id, status, refreshed_at")
			.eq("user_id", userId)
			.in("status", ["active", "trash"]);
		if (error) throw error;

		realjejuFavoriteUserId = userId;
		realjejuFavoriteListingIds = new Set();
		realjejuFavoriteTrashIds = new Set();
		realjejuFavoriteRefreshedAt = {};

		(Array.isArray(data) ? data : []).forEach((row) => {
			const listingId = normalizeItemId(row && row.listing_id);
			if (!listingId) return;
			if (row.status === "trash") realjejuFavoriteTrashIds.add(listingId);
			else realjejuFavoriteListingIds.add(listingId);
			if (row.refreshed_at) realjejuFavoriteRefreshedAt[listingId] = row.refreshed_at;
		});
		await hydrateFavoriteListingSnapshotsByIds([
			...realjejuFavoriteListingIds,
			...realjejuFavoriteTrashIds
		]);
		realjejuFavoriteLoaded = true;
		refreshFavoriteViewsAfterStateChange();
		return true;
	})().catch((err) => {
		console.warn("관심매물 동기화 실패:", err);
		realjejuFavoriteLoaded = false;
		return false;
	}).finally(() => {
		realjejuFavoriteLoadPromise = null;
	});

	return realjejuFavoriteLoadPromise;
}

let realjejuFavoriteWorkspaceReadyListenerBound = false;

function scheduleFavoriteListingStateLoad()
{
	if (realjejuFavoriteIdleLoadScheduled || realjejuFavoriteLoadPromise || realjejuFavoriteLoaded) return;
	realjejuFavoriteIdleLoadScheduled = true;
	const run = () => {
		realjejuFavoriteIdleLoadScheduled = false;
		if (typeof getRealjejuSupabaseClient !== "function") {
			if (!realjejuFavoriteWorkspaceReadyListenerBound) {
				realjejuFavoriteWorkspaceReadyListenerBound = true;
				document.addEventListener("realjeju:workspace-ready", () => {
					realjejuFavoriteWorkspaceReadyListenerBound = false;
					scheduleFavoriteListingStateLoad();
				}, { once: true });
			}
			return;
		}
		loadFavoriteListingStateFromServer();
	};
	if (typeof window.requestIdleCallback === "function") {
		window.requestIdleCallback(run, { timeout: 3500 });
		return;
	}
	window.setTimeout(run, 2000);
}

async function requireFavoriteSupabaseContext()
{
	const client = getRealjejuSupabaseClient();
	let user = null;
	if (client) {
		try {
			const { data: sessionData, error: sessionError } = await client.auth.getSession();
			const session = !sessionError && sessionData ? sessionData.session : null;
			if (session && session.user && session.user.id && session.access_token) {
				const { data: verifiedData, error: verifiedError } = await client.auth.getUser();
				const verifiedUser = !verifiedError && verifiedData ? verifiedData.user : null;
				if (verifiedUser && verifiedUser.id === session.user.id) user = verifiedUser;
			}
		} catch (err) {}
	}
	if (!client || !user || !user.id) {
		if (typeof openAuthErrorModal === "function") {
			openAuthErrorModal("로그인 후 관심 부동산을 이용할 수 있습니다.", "관심 부동산", null, typeof openAuthModal === "function" ? openAuthModal : null);
		}
		return null;
	}
	const userId = normalizeItemId(user.id);
	setFavoriteCachedAuthUser(user);
	if (realjejuFavoriteUserId && realjejuFavoriteUserId !== userId) clearFavoriteListingState();
	if (!realjejuFavoriteUserId) realjejuFavoriteUserId = userId;
	return { client, user, userId };
}

function parseListingDateToMillis(value)
{
	if (value == null) return Number.NEGATIVE_INFINITY;
	if (value instanceof Date) {
		const dateTime = value.getTime();
		return Number.isNaN(dateTime) ? Number.NEGATIVE_INFINITY : dateTime;
	}
	if (typeof value === "number") {
		if (!Number.isFinite(value)) return Number.NEGATIVE_INFINITY;
		const parsedNumber = new Date(value).getTime();
		return Number.isNaN(parsedNumber) ? Number.NEGATIVE_INFINITY : parsedNumber;
	}

	const candidates = [];
	const addCandidate = (candidate) => {
		const text = String(candidate || "").trim();
		if (!text) return;
		if (!candidates.includes(text)) candidates.push(text);
	};
	const raw = String(value).trim();
	if (!raw) return Number.NEGATIVE_INFINITY;

	addCandidate(raw);
	addCandidate(raw.replace(/\([^)]*\)/g, ""));
	addCandidate(raw.replace(/\s+/g, " "));
	addCandidate(raw.replace(/년/g, "-").replace(/월/g, "-").replace(/일/g, ""));
	addCandidate(raw.replace(/년/g, "-").replace(/월/g, "-").replace(/일/g, "").replace(/\./g, "-"));
	addCandidate(raw.replace(/년/g, "-").replace(/월/g, "-").replace(/일/g, "").replace(/\//g, "-").replace(/\./g, "-"));

	for (const candidate of candidates) {
		const cleaned = candidate.replace(/,/g, "").replace(/\s+/g, " ").trim();
		const num = Number(cleaned);
		if (/^-?\d{10,}(\.\d+)?$/.test(cleaned) && Number.isFinite(num)) {
			const parsedNumber = new Date(num).getTime();
			if (!Number.isNaN(parsedNumber)) return parsedNumber;
		}

		const directDateMatch = cleaned.match(/\b(\d{4}|\d{2})[.\-\/](\d{1,2})[.\-\/](\d{1,2})(?!\d)\b/);
		if (directDateMatch) {
			const year = Number(directDateMatch[1]);
			const normalizedYear = directDateMatch[1].length === 2 ? 2000 + year : year;
			const normalized = `${String(normalizedYear).padStart(4, "0")}-${String(directDateMatch[2]).padStart(2, "0")}-${String(directDateMatch[3]).padStart(2, "0")}`;
			const directParsed = Date.parse(normalized);
			if (!Number.isNaN(directParsed)) return directParsed;
		}

		const parsed = Date.parse(cleaned);
		if (!Number.isNaN(parsed)) return parsed;
	}

	return Number.NEGATIVE_INFINITY;
}

function getListingRegistrationDateSource(item)
{
	const payload = item && item.payload && typeof item.payload === "object" ? item.payload : {};
	const payloadListing = payload.listing && typeof payload.listing === "object" ? payload.listing : {};
	const payloadMetadata = payload.metadata && typeof payload.metadata === "object" ? payload.metadata : {};
	const candidates = [
		payload.last_relisted,
		payload.last_relisted_at,
		payload.created_at,
		payload.createdAt,
		payload.updated_at,
		payload.updatedAt,
		payload.registered_at,
		payload.registeredAt,
		payload.registration_at,
		payload.registrationAt,
		payload.register_date,
		payload.registerDate,
		payload.registration_date,
		payload.registeredDate,
		payload.last_modified_at,
		payload.modified_at,
		payload.modifiedAt,
		payload.created_on,
		payload.updated_on,
		payload.published_at,
		payloadMetadata.created_at,
		payloadMetadata.createdAt,
		payloadMetadata.updated_at,
		payloadMetadata.updatedAt,
		payloadMetadata.created_on,
		payloadMetadata.updated_on,
		payloadListing.created_at,
		payloadListing.createdAt,
		payloadListing.updated_at,
		payloadListing.updatedAt,
		payloadListing.created_on,
		payloadListing.updated_on,
		item?.last_relisted,
		item?.last_relisted_at,
		item?.created,
		item?.updated,
		item?.created_on,
		item?.created_at,
		item?.createdAt,
		item?.date_created,
		item?.date_updated,
		item?.registered_at,
		item?.registeredAt,
		item?.registeredDate,
		item?.registerDate,
		item?.registrationDate,
		item?.register_date,
		item?.registration_date,
		item?.updatedAt,
		item?.updated_at,
		item?.createdOn,
		item?.updatedOn,
		item?.updated_on,
		item?.dateLabel,
		item?.date
	];
	for (const candidate of candidates) {
		const value = parseListingDateToMillis(candidate);
		if (value !== Number.NEGATIVE_INFINITY) return value;
	}
	return Number.NEGATIVE_INFINITY;
}

